INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35407, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "思想", "is_correct": true, "explanation": "見出し語「しそう」そのものです。"}, {"text": "理想", "is_correct": false, "explanation": "「りそう」で、最初の一拍だけが違います。"}, {"text": "思考", "is_correct": false, "explanation": "「しこう」で、二拍目だけが違います。"}, {"text": "悲壮", "is_correct": false, "explanation": "「ひそう」で、最初の一拍だけが違います。"}, {"text": "子孫", "is_correct": false, "explanation": "「しそん」で、最後の一拍だけが違います。"}, {"text": "死闘", "is_correct": false, "explanation": "「しとう」で、二拍目だけが違います。"}], "explanations": {"思想": "見出し語「しそう」そのものです。", "理想": "「りそう」で、最初の一拍だけが違います。", "思考": "「しこう」で、二拍目だけが違います。", "悲壮": "「ひそう」で、最初の一拍だけが違います。", "子孫": "「しそん」で、最後の一拍だけが違います。", "死闘": "「しとう」で、二拍目だけが違います。"}, "sentence_index": null, "correct_answer": "思想"}, "level_3": {"options": [{"text": "思想", "is_correct": true, "explanation": "「ミニマリストの思想に基づき」で、考え方に基づくという意味が合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「天気に基づいて必要な要素を残す」では意味が合わない。"}, {"text": "切符", "is_correct": false, "explanation": "形は合うが、切符に基づいて暮らし方を決めるのは意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、財布に基づいて要素を残すのは意味が合わない。"}], "explanations": {"思想": "「ミニマリストの思想に基づき」で、考え方に基づくという意味が合います。", "天気": "形は合うが、「天気に基づいて必要な要素を残す」では意味が合わない。", "切符": "形は合うが、切符に基づいて暮らし方を決めるのは意味が合わない。", "財布": "形は合うが、財布に基づいて要素を残すのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "思想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夕食に思想を食べた。", "explanation": "思想は考え方であり、食べ物ではないので「食べる」とは使えません。"}, {"text": "思想を机の上に置いて帰った。", "explanation": "思想は目に見えない考えなので、物のように机の上に置けません。"}, {"text": "この思想は重くて持ち上げられない。", "explanation": "思想は抽象的な考えで、重さを持つ物ではないので持ち上げられません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35407, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "思想", "is_correct": true, "explanation": "見出し語「しそう」そのものです。"}, {"text": "位相", "is_correct": false, "explanation": "「いそう」で、最初の一拍だけが違います。"}, {"text": "奇想", "is_correct": false, "explanation": "「きそう」で、最初の一拍だけが違います。"}, {"text": "子息", "is_correct": false, "explanation": "「しそく」で、最後の一拍だけが違います。"}, {"text": "四方", "is_correct": false, "explanation": "「しほう」で、二拍目だけが違います。"}, {"text": "使用", "is_correct": false, "explanation": "「しよう」で、二拍目だけが違います。"}], "explanations": {"思想": "見出し語「しそう」そのものです。", "位相": "「いそう」で、最初の一拍だけが違います。", "奇想": "「きそう」で、最初の一拍だけが違います。", "子息": "「しそく」で、最後の一拍だけが違います。", "四方": "「しほう」で、二拍目だけが違います。", "使用": "「しよう」で、二拍目だけが違います。"}, "sentence_index": null, "correct_answer": "思想"}, "level_3": {"options": [{"text": "思想", "is_correct": true, "explanation": "「彼の思想を知れば行動の理由がわかる」で、考え方を知る意味が合います。"}, {"text": "住所", "is_correct": false, "explanation": "形は合うが、住所を知っても行動の理由はわからず、意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、財布を知ることと行動の理由は結びつかず、意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「彼の天気」は意味が合わない。"}], "explanations": {"思想": "「彼の思想を知れば行動の理由がわかる」で、考え方を知る意味が合います。", "住所": "形は合うが、住所を知っても行動の理由はわからず、意味が合わない。", "財布": "形は合うが、財布を知ることと行動の理由は結びつかず、意味が合わない。", "天気": "形は合うが、「彼の天気」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "思想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅で思想を買って電車に乗った。", "explanation": "思想は売り買いする物ではないので、切符のように「買う」とは使えません。"}, {"text": "思想は雨に降られて濡れてしまった。", "explanation": "思想は考え方で、物のように雨に濡れることはありません。"}, {"text": "料理人が思想をはさみで切って皿に並べた。", "explanation": "思想は形のない考えなので、はさみで切って並べることはできません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35407, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政治家の思想を深く影響された。", "corrected_sentence": "政治家の思想に深く影響された。", "error_description": "「影響される」の対象は「を」ではなく「に」で示します。思想に付く助詞が誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35407, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若いころ、彼はその思想を興味を持った。", "corrected_sentence": "若いころ、彼はその思想に興味を持った。", "error_description": "興味を持つ対象は「を」ではなく「に」で示します。思想に付く助詞が誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35411, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「影響を及ぼす」で、他動詞の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「影響が及ぼす」は他動詞の目的語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「影響の及ぼす」では文が言い切れず不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "「影響で及ぼす」は目的語がなく、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「影響を及ぼす」で、他動詞の目的語を示す。", "が": "「影響が及ぼす」は他動詞の目的語として成り立たない。", "の": "「影響の及ぼす」では文が言い切れず不自然になる。", "で": "「影響で及ぼす」は目的語がなく、文が成り立たない。"}, "error_tags": {"が": "subject_vs_object", "の": "possessive", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35411, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「影響を及ぼす」で、他動詞の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「影響が及ぼして」は他動詞の目的語として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「影響と及ぼして」では目的語にならず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「影響から及ぼして」は目的語がなく、不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「影響を及ぼす」で、他動詞の目的語を示す。", "が": "「影響が及ぼして」は他動詞の目的語として成り立たない。", "と": "「影響と及ぼして」では目的語にならず、文が成り立たない。", "から": "「影響から及ぼして」は目的語がなく、不自然になる。"}, "error_tags": {"が": "subject_vs_object", "と": "comitative", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35411, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "影響や結果を、ほかのものに与えること。", "primary_collocate": null, "pronunciation": "およぼす", "ipa": "ojobosɯ", "syllable_count": 4, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "及ぼし", "complexity_tier": "T6", "furigana": "特[とく]に、住民[じゅうみん]の主体的[しゅたいてき]な参加[さんか]により創出[そうしゅつ]されるガーデンは、生物[せいぶつ]多様性[たようせい]の回復[かいふく]のみならず、微気候[びきこう]の改善[かいぜん]といった側面[そくめん]においても近隣[きんりん]緑地[りょくち]に好影響[こうえいきょう]を及[およ]ぼしている。", "sentence_source": "mined"}, {"text": "睡眠不足は健康に影響を及ぼす。", "target_word": "及ぼす", "complexity_tier": "T3", "furigana": "睡眠不足[すいみんぶそく]は健康[けんこう]に影響[えいきょう]を及[およ]ぼす。", "sentence_source": "generated"}, {"text": "天気は気分に影響を及ぼします。", "target_word": "及ぼします", "complexity_tier": "T2", "furigana": "天気[てんき]は気分[きぶん]に影響[えいきょう]を及[およ]ぼします。", "sentence_source": "generated"}, {"text": "雨は農業に大きな影響を及ぼした。", "target_word": "及ぼした", "complexity_tier": "T3", "furigana": "雨[あめ]は農業[のうぎょう]に大[おお]きな影響[えいきょう]を及[およ]ぼした。", "sentence_source": "generated"}, {"text": "親の言葉は子どもに影響を及ぼしている。", "target_word": "及ぼしている", "complexity_tier": "T3", "furigana": "親[おや]の言葉[ことば]は子[こ]どもに影響[えいきょう]を及[およ]ぼしている。", "sentence_source": "generated"}, {"text": "悪い影響を及ぼさないように、気をつけてください。", "target_word": "及ぼさない", "complexity_tier": "T4", "furigana": "悪[わる]い影響[えいきょう]を及[およ]ぼさないように、気[き]をつけてください。", "sentence_source": "generated"}, {"text": "経済に及ぼす影響は、まだよく分かっていない。", "target_word": "及ぼす", "complexity_tier": "T3", "furigana": "経済[けいざい]に及[およ]ぼす影響[えいきょう]は、まだよく分[わ]かっていない。", "sentence_source": "generated"}, {"text": "新しい法律が社会に影響を及ぼして、生活が変わった。", "target_word": "及ぼして", "complexity_tier": "T4", "furigana": "新[あたら]しい法律[ほうりつ]が社会[しゃかい]に影響[えいきょう]を及[およ]ぼして、生活[せいかつ]が変[か]わった。", "sentence_source": "generated"}, {"text": "工場の排水が川の魚に悪影響を及ぼせば、町全体が困るだろう。", "target_word": "及ぼせば", "complexity_tier": "T4", "furigana": "工場[こうじょう]の排水[はいすい]が川[かわ]の魚[さかな]に悪影響[あくえいきょう]を及[およ]ぼせば、町全体[まちぜんたい]が困[こま]るだろう。", "sentence_source": "generated"}, {"text": "気候変動が世界の食料生産に及ぼす影響について、専門家が報告書をまとめた。", "target_word": "及ぼす", "complexity_tier": "T5", "furigana": "気候変動[きこうへんどう]が世界[せかい]の食料[しょくりょう]生産[せいさん]に及[およ]ぼす影響[えいきょう]について、専門家[せんもんか]が報告書[ほうこくしょ]をまとめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "及ぼした", "label": "活用"}, {"form": "及ぼして", "label": "活用"}, {"form": "及ぼさない", "label": "活用"}, {"form": "及ぼせば", "label": "活用"}, {"form": "及ぼされる", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 影響や結果を他に与えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aab15603-a3e6-49a6-923d-02d2cfa720e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35411, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "及ぼし", "is_correct": true, "explanation": "「好影響を及ぼしている」で、影響を与える意味になり文に合う。"}, {"text": "逃し", "is_correct": false, "explanation": "形は合うが、好影響を逃すでは意味が合わない。"}, {"text": "数え", "is_correct": false, "explanation": "形は合うが、好影響を数えるでは意味が合わない。"}, {"text": "隠し", "is_correct": false, "explanation": "形は合うが、近隣緑地に好影響を隠すでは意味が合わない。"}], "explanations": {"及ぼし": "「好影響を及ぼしている」で、影響を与える意味になり文に合う。", "逃し": "形は合うが、好影響を逃すでは意味が合わない。", "数え": "形は合うが、好影響を数えるでは意味が合わない。", "隠し": "形は合うが、近隣緑地に好影響を隠すでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "及ぼし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は子どもに弁当を及ぼした。", "explanation": "「及ぼす」は影響・結果を与える意味で、弁当のような物を渡す意味では使えない。"}, {"text": "昨日、友達に手紙を及ぼして出した。", "explanation": "手紙のような具体物を「及ぼす」ことはできない。物を送る意味では使えない。"}, {"text": "弟は机の上に本を及ぼした。", "explanation": "「及ぼす」は物を置く意味ではない。影響を与える意味でしか使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35411, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "及ぼす", "is_correct": true, "explanation": "「経済に及ぼす影響」で、経済に与える影響という意味になる。"}, {"text": "譲る", "is_correct": false, "explanation": "形は合うが、経済に譲る影響では意味が合わない。"}, {"text": "混ぜる", "is_correct": false, "explanation": "形は合うが、経済に混ぜる影響では意味が合わない。"}, {"text": "眺める", "is_correct": false, "explanation": "形は合うが、経済に眺める影響では意味が合わない。"}], "explanations": {"及ぼす": "「経済に及ぼす影響」で、経済に与える影響という意味になる。", "譲る": "形は合うが、経済に譲る影響では意味が合わない。", "混ぜる": "形は合うが、経済に混ぜる影響では意味が合わない。", "眺める": "形は合うが、経済に眺める影響では意味が合わない。"}, "sentence_index": 6, "correct_answer": "及ぼす"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は黒板に宿題を及ぼした。", "explanation": "「及ぼす」は影響を与える意味で、字や宿題を書く意味では使えない。"}, {"text": "彼女は財布に小銭を及ぼして買い物をした。", "explanation": "具体物の小銭を「及ぼす」ことはできない。入れる意味では使えない。"}, {"text": "台所で母が野菜を及ぼして料理している。", "explanation": "「及ぼす」に野菜を調理する意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35411, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい薬は患者に効果が及ぼした。", "corrected_sentence": "新しい薬は患者に効果を及ぼした。", "error_description": "「及ぼす」は他動詞なので、目的語には「が」ではなく「を」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "及ぼす", "is_correct": true, "explanation": "文末の終止形で、「影響を及ぼす」と自然に言い切れる。"}, {"text": "及ぼし", "is_correct": false, "explanation": "連用形なので、文を言い切る位置には使えない。"}, {"text": "及ぼして", "is_correct": false, "explanation": "て形なので、ここで文を終えることはできない。"}, {"text": "及ぼさず", "is_correct": false, "explanation": "否定の連用形なので、文末には使えない。"}], "correct_form": "及ぼす", "base_form": "及ぼす", "form_label": "終止形", "sentence_index": 1, "explanations": {"及ぼす": "文末の終止形で、「影響を及ぼす」と自然に言い切れる。", "及ぼし": "連用形なので、文を言い切る位置には使えない。", "及ぼして": "て形なので、ここで文を終えることはできない。", "及ぼさず": "否定の連用形なので、文末には使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35411, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "円安は輸入品の価格で影響を及ぼした。", "corrected_sentence": "円安は輸入品の価格に影響を及ぼした。", "error_description": "影響の及ぶ対象は「で」ではなく「に」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "及ぼして", "is_correct": true, "explanation": "て形で、「影響を及ぼして、生活が変わった」と原因から結果へつなぐ。"}, {"text": "及ぼそう", "is_correct": false, "explanation": "意向形なので、「生活が変わった」への接続に合わない。"}, {"text": "及ぼせ", "is_correct": false, "explanation": "命令形なので、事実を述べる文の途中には使えない。"}, {"text": "及ぼすな", "is_correct": false, "explanation": "禁止の形なので、この文脈には合わない。"}], "correct_form": "及ぼして", "base_form": "及ぼす", "form_label": "て形", "sentence_index": 7, "explanations": {"及ぼして": "て形で、「影響を及ぼして、生活が変わった」と原因から結果へつなぐ。", "及ぼそう": "意向形なので、「生活が変わった」への接続に合わない。", "及ぼせ": "命令形なので、事実を述べる文の途中には使えない。", "及ぼすな": "禁止の形なので、この文脈には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1768b52-5981-44c1-b146-6dfa07616335') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
