INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35413, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の状態や性質が、根本的かつ大幅に変化すること。また、その変化。", "primary_collocate": null, "pronunciation": "へんよう", "ipa": "heɴjoː", "syllable_count": 4, "sentences": [{"text": "その後、長時間にわたる低温発酵を経ることで、グルテンの網目は緻密さを増し、消化吸収にも優れた変容を遂げる。", "target_word": "変容", "complexity_tier": "T4", "furigana": "その後[そのご]、長時間[ちょうじかん]にわたる低温[ていおん]発酵[はっこう]を経[へ]ることで、グルテンの網目[あみめ]は緻密[ちみつ]さを増[ま]し、消化[しょうか]吸収[きゅうしゅう]にも優[すぐ]れた変容[へんよう]を遂[と]げる。", "sentence_source": "mined"}, {"text": "都市は百年のあいだに大きく変容し、昔の面影はほとんど残っていない。", "target_word": "変容", "complexity_tier": "T3", "furigana": "都市[とし]は百年[ひゃくねん]のあいだに大[おお]きく変容[へんよう]し、昔[むかし]の面影[おもかげ]はほとんど残[のこ]っていない。", "sentence_source": "generated"}, {"text": "戦争は人々の価値観を根本から変容させた。", "target_word": "変容", "complexity_tier": "T3", "furigana": "戦争[せんそう]は人々[ひとびと]の価値観[かちかん]を根本[こんぽん]から変容[へんよう]させた。", "sentence_source": "generated"}, {"text": "川の流れが変わったことで、周囲の生態系も変容した。", "target_word": "変容", "complexity_tier": "T3", "furigana": "川[かわ]の流[なが]れが変[か]わったことで、周囲[しゅうい]の生態系[せいたいけい]も変容[へんよう]した。", "sentence_source": "generated"}, {"text": "彼の作風は留学をきっかけに大きな変容を見せた。", "target_word": "変容", "complexity_tier": "T3", "furigana": "彼[かれ]の作風[さくふう]は留学[りゅうがく]をきっかけに大[おお]きな変容[へんよう]を見[み]せた。", "sentence_source": "generated"}, {"text": "インターネットの普及により、働き方は急速に変容している。", "target_word": "変容", "complexity_tier": "T3", "furigana": "インターネットの普及により、働き方は急速に変[へん]容[よう]している。", "sentence_source": "generated"}, {"text": "この小説は、少年が大人へと変容していく過程を描いている。", "target_word": "変容", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、少年[しょうねん]が大人[おとな]へと変容[へんよう]していく過程[かてい]を描[えが]いている。", "sentence_source": "generated"}, {"text": "震災後、町の景色は完全に変容してしまった。", "target_word": "変容", "complexity_tier": "T3", "furigana": "震災後[しんさいご]、町[まち]の景色[けしき]は完全[かんぜん]に変容[へんよう]してしまった。", "sentence_source": "generated"}, {"text": "気候変動が続けば、森の姿は数十年で変容するだろう。", "target_word": "変容", "complexity_tier": "T3", "furigana": "気候[きこう]変動[へんどう]が続[つづ]けば、森[もり]の姿[すがた]は数十年[すうじゅうねん]で変容[へんよう]するだろう。", "sentence_source": "generated"}, {"text": "長い年月をかけて、その言葉の意味は少しずつ変容してきた。", "target_word": "変容", "complexity_tier": "T3", "furigana": "長[なが]い年月[ねんげつ]をかけて、その言葉[ことば]の意味[いみ]は少[すこ]しずつ変容[へんよう]してきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変容する", "label": "辞書形"}, {"form": "変容した", "label": "過去形"}, {"form": "変容して", "label": "て形"}, {"form": "変容しない", "label": "否定形"}], "register": "書き言葉（やや硬い）", "sense_fingerprint": "状態や性質が根本から大きく変わること。サ変動詞「変容する」としても使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a11d6d33-ed8f-4c09-aaf1-468a0c04d56b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35413, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変容", "is_correct": true, "explanation": "名詞で、『優れた変容を遂げる』の形で目的語になる。ここに入る唯一の形。"}, {"text": "変容する", "is_correct": false, "explanation": "サ変動詞の終止形で、『優れた変容する』の形では名詞を修飾できない。"}, {"text": "変容した", "is_correct": false, "explanation": "過去の動詞形で、『優れた変容した』の形では『を遂げる』に続かない。"}, {"text": "変容して", "is_correct": false, "explanation": "て形で、『優れた変容して』の形では『を遂げる』に続かない。"}], "explanations": {"変容": "名詞で、『優れた変容を遂げる』の形で目的語になる。ここに入る唯一の形。", "変容する": "サ変動詞の終止形で、『優れた変容する』の形では名詞を修飾できない。", "変容した": "過去の動詞形で、『優れた変容した』の形では『を遂げる』に続かない。", "変容して": "て形で、『優れた変容して』の形では『を遂げる』に続かない。"}, "sentence_index": 0, "correct_answer": "変容"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "髪型を少しだけ変容させてみた。", "explanation": "ここは〈変化〉の意味。変容は状態や性質が根本から大きく変わることで、少しの変更には使えない。"}, {"text": "引っ越しで、家具を部屋の奥へ変容させた。", "explanation": "ここは〈移動〉の意味。変容は状態や性質の変化を表し、場所を移すことには使わない。"}, {"text": "粘土を指で変容させて、丸く整えた。", "explanation": "ここは〈変形〉の意味。変容は本質や性質の変化で、形を指で整えることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35413, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変容", "is_correct": true, "explanation": "『大人へと変容していく』の語幹にあたり、サ変名詞として正しく入る。"}, {"text": "変容し", "is_correct": false, "explanation": "連用形で、『大人へと変容しし』と重なり、文として続かない。"}, {"text": "変容さ", "is_correct": false, "explanation": "未然形で、『変容さしていく』は成り立たない。"}, {"text": "変容す", "is_correct": false, "explanation": "終止形の語幹で、『変容すしていく』は文法的に成り立たない。"}], "explanations": {"変容": "『大人へと変容していく』の語幹にあたり、サ変名詞として正しく入る。", "変容し": "連用形で、『大人へと変容しし』と重なり、文として続かない。", "変容さ": "未然形で、『変容さしていく』は成り立たない。", "変容す": "終止形の語幹で、『変容すしていく』は文法的に成り立たない。"}, "sentence_index": 6, "correct_answer": "変容"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の日程を少しずつ変容させてきた。", "explanation": "ここは〈変更〉の意味。変容は性質や状態が根本から変わることで、日程の小さな修正には使わない。"}, {"text": "ソフトは毎月、少しずつ変容させている。", "explanation": "ここは〈更新〉の意味。変容は根本的な変化を表すので、版を新しくする意味では使わない。"}, {"text": "箱の容量が変容した。", "explanation": "ここは〈容量が増える〉の意味。変容は状態や性質の変わり方を指し、量の増減には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35413, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海の水位が上がれば、沿岸の町は完全に変容るだろう。", "corrected_sentence": "海の水位が上がれば、沿岸の町は完全に変容するだろう。", "error_description": "『変容』はサ変名詞で、動詞として使うには『変容する』の形にする必要がある。『変容る』は誤った活用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35413, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その言葉の意味は、少しずつ変容てきた。", "corrected_sentence": "その言葉の意味は、少しずつ変容してきた。", "error_description": "「変容」はサ変名詞なので、「変容してきた」の「し」が抜けている。「変容てきた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d112de-9172-419b-b83c-ad1b8ddc501f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
