INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35418, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「軈て」は「やがて」という意味で、少し時間がたつことを表す言葉です。", "primary_collocate": null, "pronunciation": "やがて", "ipa": "jaɡate", "syllable_count": 3, "sentences": [{"text": "雲が広がり、軈て雨が降り出した。", "target_word": "軈て", "complexity_tier": "T3", "furigana": "雲[くも]が広[ひろ]がり、軈[やが]て雨[あめ]が降[ふ]り出[だ]した。", "sentence_source": "generated"}, {"text": "軈て春になれば、この川の岸に桜が咲く。", "target_word": "軈て", "complexity_tier": "T3", "furigana": "軈[やが]て春[はる]になれば、この川[かわ]の岸[きし]に桜[さくら]が咲[さ]く。", "sentence_source": "generated"}, {"text": "子どもは軈て大人になり、親のもとを離れていく。", "target_word": "軈て", "complexity_tier": "T3", "furigana": "子[こ]どもは軈[やが]て大人[おとな]になり、親[おや]のもとを離[はな]れていく。", "sentence_source": "generated"}, {"text": "電車は軈て駅に着いた。", "target_word": "軈て", "complexity_tier": "T3", "furigana": "電車[でんしゃ]は軈[やが]て駅[えき]に着[つ]いた。", "sentence_source": "generated"}, {"text": "日が沈み、軈てあたりは真っ暗になった。", "target_word": "軈て", "complexity_tier": "T3", "furigana": "日[ひ]が沈[しず]み、軈[やが]てあたりは真[ま]っ暗[くら]になった。", "sentence_source": "generated"}, {"text": "彼は修業を重ね、軈て自分の店を持った。", "target_word": "軈て", "complexity_tier": "T3", "furigana": "彼[かれ]は修業[しゅぎょう]を重[かさ]ね、軈[やが]て自分[じぶん]の店[みせ]を持[も]った。", "sentence_source": "generated"}, {"text": "最初は反対していたが、軈て母も賛成してくれた。", "target_word": "軈て", "complexity_tier": "T3", "furigana": "最初[さいしょ]は反対[はんたい]していたが、軈[やが]て母[はは]も賛成[さんせい]してくれた。", "sentence_source": "generated"}, {"text": "軈て、遠くから足音が聞こえてきた。", "target_word": "軈て", "complexity_tier": "T3", "furigana": "軈[やが]て、遠[とお]くから足音[あしおと]が聞[き]こえてきた。", "sentence_source": "generated"}, {"text": "音楽が小さくなり、軈て完全に消えた。", "target_word": "軈て", "complexity_tier": "T3", "furigana": "音楽[おんがく]が小[ちい]さくなり、軈[やが]て完全[かんぜん]に消[き]えた。", "sentence_source": "generated"}, {"text": "今は小さな会社だが、軈て世界に知られるだろう。", "target_word": "軈て", "complexity_tier": "T3", "furigana": "今[いま]は小[ちい]さな会社[かいしゃ]だが、軈[やが]て世界[せかい]に知[し]られるだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "軈て", "label": "基本形"}], "register": "書き言葉", "sense_fingerprint": "しばらくして、時間がたってから", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35418, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "軈て", "is_correct": true, "explanation": "しばらくたってから雨が降り出すという時間の流れに合う正解。"}, {"text": "決して", "is_correct": false, "explanation": "否定と結びつく副詞なので、「決して雨が降り出した」とは続かない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す副詞で、雨が降り出す文には合わない。"}, {"text": "全く", "is_correct": false, "explanation": "程度を強める副詞で、この文の時間の流れと合わない。"}], "explanations": {"軈て": "しばらくたってから雨が降り出すという時間の流れに合う正解。", "決して": "否定と結びつく副詞なので、「決して雨が降り出した」とは続かない。", "ぐっすり": "眠りの深さを表す副詞で、雨が降り出す文には合わない。", "全く": "程度を強める副詞で、この文の時間の流れと合わない。"}, "sentence_index": 0, "correct_answer": "軈て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火事だ！軈て外へ逃げてください。", "explanation": "ここは〈すぐに〉の意味で使っている。軈ては時間がたってからという意味なので、緊急の場面では合わない。"}, {"text": "彼は料理をしながら、軈て同時に電話にも出た。", "explanation": "ここは〈同時に〉の意味。軈ては〈時間がたってから〉の意味なので、同時の動作には合わない。"}, {"text": "軈て昨日、彼から電話があった。", "explanation": "ここは〈以前の出来事を振り返る〉の意味。軈ては〈これから時間がたって〉の意味なので、過去の出来事を述べる文では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35418, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "軈て", "is_correct": true, "explanation": "反対していたが、しばらくして母も賛成したという流れに合う正解。"}, {"text": "一度も", "is_correct": false, "explanation": "一度もないという否定の意味で、「一度も母も賛成してくれた」は文の流れが合わない。"}, {"text": "少しも", "is_correct": false, "explanation": "否定と結びつく副詞で、「少しも母も賛成してくれた」は文の流れが合わない。"}, {"text": "ちっとも", "is_correct": false, "explanation": "否定と結びつく副詞で、「ちっとも母も賛成してくれた」は肯定文として成り立たない。"}], "explanations": {"軈て": "反対していたが、しばらくして母も賛成したという流れに合う正解。", "一度も": "一度もないという否定の意味で、「一度も母も賛成してくれた」は文の流れが合わない。", "少しも": "否定と結びつく副詞で、「少しも母も賛成してくれた」は文の流れが合わない。", "ちっとも": "否定と結びつく副詞で、「ちっとも母も賛成してくれた」は肯定文として成り立たない。"}, "sentence_index": 6, "correct_answer": "軈て"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "軈て最初に名前を書いてください。", "explanation": "ここは〈最初に〉の意味。軈ては〈しばらくして〉の意味なので、順番の最初を示す場面では使わない。"}, {"text": "彼は軈て私より背が低い。", "explanation": "軈ては時間の経過を表す言葉で、今ある状態の比較には使わないので合わない。"}, {"text": "軈て、この部屋には窓がない。", "explanation": "軈ては〈しばらくして起こる変化〉に使うので、今ある状態を述べる文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35418, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "空が暗くなり、軈てに大粒の雨が降り出した。", "corrected_sentence": "空が暗くなり、軈て大粒の雨が降り出した。", "error_description": "誤りは「軈てに」。「軈て」は副詞なので、後ろに「に」を付けるのは誤り。正しくは「軈て大粒の雨が降り出した」と副詞のまま続ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35418, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最初は雨だったが、軈てで晴れてきた。", "corrected_sentence": "最初は雨だったが、軈て晴れてきた。", "error_description": "誤りは「軈てで」。「軈て」は副詞なので、後ろに「で」を付けるのは誤り。正しくは「軈て晴れてきた」と副詞として続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35426, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安定", "is_correct": true, "explanation": "変動の対義語で、変わらず落ち着いている状態。"}, {"text": "記憶", "is_correct": false, "explanation": "覚えて残しておくこと。変動と対になる語ではない。"}, {"text": "工場", "is_correct": false, "explanation": "物を作る施設。変動とは対義関係にない。"}, {"text": "配達", "is_correct": false, "explanation": "物を届けること。変動とは対義関係にない。"}], "correct_answer": "安定", "explanations": {"安定": "変動の対義語で、変わらず落ち着いている状態。", "記憶": "覚えて残しておくこと。変動と対になる語ではない。", "工場": "物を作る施設。変動とは対義関係にない。", "配達": "物を届けること。変動とは対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35426, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不変", "is_correct": true, "explanation": "変わらないこと。変動の対義語で、変わりようと反対の状態を表す。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつけること。変動とは対義関係にない。"}, {"text": "手紙", "is_correct": false, "explanation": "文章で伝える物。変動の反対語ではない。"}, {"text": "相談", "is_correct": false, "explanation": "助言を求めること。変動とは対義関係にない。"}], "correct_answer": "不変", "explanations": {"不変": "変わらないこと。変動の対義語で、変わりようと反対の状態を表す。", "採点": "点数をつけること。変動とは対義関係にない。", "手紙": "文章で伝える物。変動の反対語ではない。", "相談": "助言を求めること。変動とは対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35426, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "価格・気温・数値などが上がったり下がったりして変わること。", "primary_collocate": null, "pronunciation": "へんどう", "ipa": "hendoː", "syllable_count": 4, "sentences": [{"text": "為替の変動が大きいと、輸入品の値段も上がります。", "target_word": "変動", "complexity_tier": "T3", "furigana": "為替[かわせ]の変動[へんどう]が大[おお]きいと、輸入品[ゆにゅうひん]の値段[ねだん]も上[あ]がります。", "sentence_source": "generated"}, {"text": "今年は野菜の価格に大きな変動があった。", "target_word": "変動", "complexity_tier": "T3", "furigana": "今年[ことし]は野菜[やさい]の価格[かかく]に大[おお]きな変動[へんどう]があった。", "sentence_source": "generated"}, {"text": "気温の変動が激しい季節なので、体調に気をつけてください。", "target_word": "変動", "complexity_tier": "T3", "furigana": "気温[きおん]の変動[へんどう]が激[はげ]しい季節[きせつ]なので、体調[たいちょう]に気[き]をつけてください。", "sentence_source": "generated"}, {"text": "株価が変動するたびに、父はニュースを見ている。", "target_word": "変動", "complexity_tier": "T3", "furigana": "株価[かぶか]が変動[へんどう]するたびに、父[ちち]はニュースを見[み]ている。", "sentence_source": "generated"}, {"text": "給料はほとんど変動せず、毎月ほぼ同じ額だ。", "target_word": "変動", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]はほとんど変動[へんどう]せず、毎月[まいつき]ほぼ同[おな]じ額[がく]だ。", "sentence_source": "generated"}, {"text": "地球の気候の変動について、授業で調べた。", "target_word": "変動", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の気候[きこう]の変動[へんどう]について、授業[じゅぎょう]で調[しら]べた。", "sentence_source": "generated"}, {"text": "売り上げは月ごとに変動するので、計画を立てにくい。", "target_word": "変動", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げは月[つき]ごとに変動[へんどう]するので、計画[けいかく]を立[た]てにくい。", "sentence_source": "generated"}, {"text": "人口の変動を表すグラフを、先生が黒板に貼った。", "target_word": "変動", "complexity_tier": "T3", "furigana": "人口[じんこう]の変動[へんどう]を表[あらわ]すグラフを、先生[せんせい]が黒板[こくばん]に貼[は]った。", "sentence_source": "generated"}, {"text": "為替が変動しても、このツアーの料金は変わりません。", "target_word": "変動", "complexity_tier": "T3", "furigana": "為替[かわせ]が変動[へんどう]しても、このツアーの料金[りょうきん]は変[か]わりません。", "sentence_source": "generated"}, {"text": "海水温の変動を、研究者が毎日記録している。", "target_word": "変動", "complexity_tier": "T3", "furigana": "海水温[かいすいおん]の変動[へんどう]を、研究者[けんきゅうしゃ]が毎日[まいにち]記録[きろく]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "変動する", "label": "dictionary form"}, {"form": "変動した", "label": "past"}, {"form": "変動して", "label": "te-form"}, {"form": "変動しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "価格・気温・数値などが上がったり下がったりして変わること。変動する/変動が大きい。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35426, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "変動", "is_correct": true, "explanation": "為替の値段などが上下に動くこと。「変動が大きい」と続く正解。"}, {"text": "安定", "is_correct": false, "explanation": "変わらず落ち着いている状態。「安定が大きい」では文が成り立たない。"}, {"text": "人口", "is_correct": false, "explanation": "人の数を表す語。為替の動きの大きさを言う文には合わない。"}, {"text": "完成", "is_correct": false, "explanation": "出来上がること。為替の動きを表す文には入らない。"}], "explanations": {"変動": "為替の値段などが上下に動くこと。「変動が大きい」と続く正解。", "安定": "変わらず落ち着いている状態。「安定が大きい」では文が成り立たない。", "人口": "人の数を表す語。為替の動きの大きさを言う文には合わない。", "完成": "出来上がること。為替の動きを表す文には入らない。"}, "sentence_index": 0, "correct_answer": "変動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "印象が大きく変動した。", "explanation": "ここは〈変化〉の意味。変動は価格や数値が上下に動くことに使うので、印象の変化には合わない。"}, {"text": "会社は方針を大きく変動させた。", "explanation": "ここは〈転換〉の意味。変動は数値や価格の上下に使い、方針を切り替えることには使わない。"}, {"text": "材料が変動して、食べられなくなった。", "explanation": "ここは〈変質〉の意味。変動は数値などの上下の動きを表し、材料が傷んで性質が変わることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35426, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "変動", "is_correct": true, "explanation": "売り上げが月ごとに上がったり下がったりすること。計画を立てにくい理由になる。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて出かけること。「売り上げは月ごとに散歩する」では文が成り立たない。"}, {"text": "翻訳", "is_correct": false, "explanation": "ある言語の文章を別の言語に置き換えること。売り上げの動きを言う文には合わない。"}, {"text": "工事", "is_correct": false, "explanation": "建物などを造ること。売り上げの話には合わない。"}], "explanations": {"変動": "売り上げが月ごとに上がったり下がったりすること。計画を立てにくい理由になる。", "散歩": "歩いて出かけること。「売り上げは月ごとに散歩する」では文が成り立たない。", "翻訳": "ある言語の文章を別の言語に置き換えること。売り上げの動きを言う文には合わない。", "工事": "建物などを造ること。売り上げの話には合わない。"}, "sentence_index": 6, "correct_answer": "変動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "荷物を変動させて、部屋の模様替えをした。", "explanation": "ここは〈移動〉の意味。変動は数量や価格の上下に使うので、物の場所を動かすことには合わない。"}, {"text": "予定が変動して、旅行は中止になった。", "explanation": "ここは〈変更〉の意味。変動は数値や価格の上下に使い、予定の変更には使わない。"}, {"text": "設計図を変動させ、建物の形を改めた。", "explanation": "ここは〈改変〉の意味。変動は数値や価格の上下に使い、設計を作り直すことには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35426, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "為替の変動が高い時期は、旅行の費用を計画しにくい。", "corrected_sentence": "為替の変動が大きい時期は、旅行の費用を計画しにくい。", "error_description": "「変動」と組む形容詞の誤り。変動の程度は「大きい」で表すので、「高い」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35426, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "株価の変動が、グラフで確かめた。", "corrected_sentence": "株価の変動を、グラフで確かめた。", "error_description": "「変動」に続く格助詞の誤り。「確かめる」の対象は「を」で示すので、「が」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
