INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35429, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「近代」は、西洋ではルネサンスや産業革命以降、日本では明治時代以降の、現代に近い時代を指します。", "primary_collocate": null, "pronunciation": "きんだい", "ipa": "kindai", "syllable_count": 4, "sentences": [{"text": "日本の近代は、明治時代から始まったと考えられている。", "target_word": "近代", "complexity_tier": "T3", "furigana": "日本[にほん]の近代[きんだい]は、明治時代[めいじじだい]から始[はじ]まったと考[かんが]えられている。", "sentence_source": "generated"}, {"text": "西洋の近代は、産業革命のころから大きく進んだ。", "target_word": "近代", "complexity_tier": "T3", "furigana": "西洋[せいよう]の近代[きんだい]は、産業革命[さんぎょうかくめい]のころから大[おお]きく進[すす]んだ。", "sentence_source": "generated"}, {"text": "近代の日本では、鉄道や工場が急に増えた。", "target_word": "近代", "complexity_tier": "T3", "furigana": "近代[きんだい]の日本[にほん]では、鉄道[てつどう]や工場[こうじょう]が急[きゅう]に増[ふ]えた。", "sentence_source": "generated"}, {"text": "歴史の授業で、近代の日本と西洋のちがいを学んだ。", "target_word": "近代", "complexity_tier": "T3", "furigana": "歴史[れきし]の授業[じゅぎょう]で、近代[きんだい]の日本[にほん]と西洋[せいよう]のちがいを学[まな]んだ。", "sentence_source": "generated"}, {"text": "明治政府は、近代の国づくりを目指して学校制度を整えた。", "target_word": "近代", "complexity_tier": "T3", "furigana": "明治政府[めいじせいふ]は、近代[きんだい]の国[くに]づくりを目指[めざ]して学校制度[がっこうせいど]を整[ととの]えた。", "sentence_source": "generated"}, {"text": "近代に入ると、日本でも洋服を着る人が増えた。", "target_word": "近代", "complexity_tier": "T3", "furigana": "近代[きんだい]に入[はい]ると、日本[にほん]でも洋服[ようふく]を着[き]る人[ひと]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "先生は、ルネサンスを近代の始まりと見る考え方を説明した。", "target_word": "近代", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ルネサンスを近代[きんだい]の始[はじ]まりと見[み]る考[かんが]え方[かた]を説明[せつめい]した。", "sentence_source": "generated"}, {"text": "近代の文学には、夏目漱石や森鷗外の作品がある。", "target_word": "近代", "complexity_tier": "T3", "furigana": "近代[きんだい]の文学[ぶんがく]には、夏目漱石[なつめそうせき]や森鷗外[もりおうがい]の作品[さくひん]がある。", "sentence_source": "generated"}, {"text": "近代の産業は、蒸気機関の発明で大きく変わった。", "target_word": "近代", "complexity_tier": "T3", "furigana": "近代[きんだい]の産業[さんぎょう]は、蒸気機関[じょうききかん]の発明[はつめい]で大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "この博物館では、近代の日本の暮らしがわかる。", "target_word": "近代", "complexity_tier": "T3", "furigana": "この博物館[はくぶつかん]では、近代[きんだい]の日本[にほん]の暮[く]らしがわかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "近代", "label": "base form"}, {"form": "近代の", "label": "attributive"}, {"form": "近代に", "label": "adverbial"}], "register": "formal", "sense_fingerprint": "歴史の時代区分としての近代。西洋ではルネサンス・産業革命以降、日本では明治以降を指す。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T3: contains vocabulary far above tier T3: 鷗外 (Zipf 1.89)']::text[], 'fd5ffa41-1131-4a11-8fcb-1ef942369fab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35429, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近代", "is_correct": true, "explanation": "日本の歴史の時代区分で、明治時代以降を指す。正解。"}, {"text": "古代", "is_correct": false, "explanation": "奈良・平安などを指す時代。明治から始まるという文には合わない。"}, {"text": "中世", "is_correct": false, "explanation": "鎌倉・室町などを指す時代。明治から始まるとは言えない。"}, {"text": "現代", "is_correct": false, "explanation": "今に近い時代を指し、明治から始まるという文脈とは合わない。"}], "explanations": {"近代": "日本の歴史の時代区分で、明治時代以降を指す。正解。", "古代": "奈良・平安などを指す時代。明治から始まるという文には合わない。", "中世": "鎌倉・室町などを指す時代。明治から始まるとは言えない。", "現代": "今に近い時代を指し、明治から始まるという文脈とは合わない。"}, "sentence_index": 0, "correct_answer": "近代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "江戸時代は、近代の始まりとされている。", "explanation": "ここは〈近世〉の意味。江戸時代は近世にあたり、明治以降を指す近代とは区別される。"}, {"text": "近代の人々は、昔の土器で煮炊きをしていた。", "explanation": "ここは〈古代〉の意味。土器を使った時代は古代にあたり、明治以降の近代とは合わない。"}, {"text": "近代の村では、人々が狩りをして暮らしていた。", "explanation": "ここは〈先史〉の意味。狩りで暮らした時代は明治以降の近代とは大きく離れる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35429, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近代", "is_correct": true, "explanation": "ルネサンス以降を近代の始まりとする歴史の見方を表す。正解。"}, {"text": "江戸", "is_correct": false, "explanation": "江戸時代は近世にあたり、ルネサンスを近代の始まりとする考えには合わない。"}, {"text": "鎌倉", "is_correct": false, "explanation": "鎌倉時代は中世にあたり、この文脈とは合わない。"}, {"text": "縄文", "is_correct": false, "explanation": "縄文時代は非常に古い時代で、ルネサンスとは結びつかない。"}], "explanations": {"近代": "ルネサンス以降を近代の始まりとする歴史の見方を表す。正解。", "江戸": "江戸時代は近世にあたり、ルネサンスを近代の始まりとする考えには合わない。", "鎌倉": "鎌倉時代は中世にあたり、この文脈とは合わない。", "縄文": "縄文時代は非常に古い時代で、ルネサンスとは結びつかない。"}, "sentence_index": 6, "correct_answer": "近代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "近代の人々は、石器で木の実を集めていた。", "explanation": "ここは〈先史〉の意味。石器の時代は明治以降の近代とは合わない。"}, {"text": "近代の日本は、鎖国を続けていた。", "explanation": "ここは〈江戸時代〉の意味。江戸時代は明治以前で、明治以降を指す近代とは合わない。"}, {"text": "近代の日本では、武士が力を持っていた。", "explanation": "ここは〈中世〉の意味。武士が力を持ったのは中世で、明治以降の近代とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35429, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この国の近代で、明治時代に大きく進んだ。", "corrected_sentence": "この国の近代は、明治時代に大きく進んだ。", "error_description": "「近代」に続く助詞の誤り。主題を示す「は」が正しく、「で」では文の主語と述語が結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35429, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近代に上がると、社会の仕組みが大きく変わった。", "corrected_sentence": "近代に入ると、社会の仕組みが大きく変わった。", "error_description": "「近代に入る」という決まった言い方の誤り。時代の始まりには「入る」を使い、「上がる」とは組まない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c07d00d1-8048-4ad4-beac-311160b5c24e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35430, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「基盤が丈夫だ」の主語を示す格助詞。形容詞「丈夫だ」の主語として正しい。"}, {"text": "を", "is_correct": false, "explanation": "「基盤を丈夫だ」では目的語になるが、「丈夫だ」は状態を表し目的語を取らないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「基盤に丈夫だ」は帰着や場所を示す形で、状態を表す「丈夫だ」とは結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "「基盤で丈夫だ」は手段や場所を示すが、「丈夫だ」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「基盤が丈夫だ」の主語を示す格助詞。形容詞「丈夫だ」の主語として正しい。", "を": "「基盤を丈夫だ」では目的語になるが、「丈夫だ」は状態を表し目的語を取らないので合わない。", "に": "「基盤に丈夫だ」は帰着や場所を示す形で、状態を表す「丈夫だ」とは結びつかない。", "で": "「基盤で丈夫だ」は手段や場所を示すが、「丈夫だ」の主語にはならない。"}, "error_tags": {"を": "目的語の格（対象）", "に": "帰着・方向の格", "で": "手段・場所の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35430, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「基盤になる」の形で、結果や変化の先を示す格助詞。「学力の基盤になる」に合う。"}, {"text": "を", "is_correct": false, "explanation": "「基盤をなる」は成り立たない。「なる」は目的語を取らない自動詞なので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「基盤でなる」は手段や場所を表すが、変化の結果を示す「なる」とは結びつかない。"}, {"text": "へ", "is_correct": false, "explanation": "「基盤へなる」は方向を示すが、「なる」の結果を表す形には使えない。"}], "correct_answer": "に", "explanations": {"に": "「基盤になる」の形で、結果や変化の先を示す格助詞。「学力の基盤になる」に合う。", "を": "「基盤をなる」は成り立たない。「なる」は目的語を取らない自動詞なので合わない。", "で": "「基盤でなる」は手段や場所を表すが、変化の結果を示す「なる」とは結びつかない。", "へ": "「基盤へなる」は方向を示すが、「なる」の結果を表す形には使えない。"}, "error_tags": {"を": "目的語の格（対象）", "で": "手段・場所の格", "へ": "方向の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35430, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをつくるときの、いちばんしたの部分。", "primary_collocate": null, "pronunciation": "きばん", "ipa": "kibaɴ", "syllable_count": 3, "sentences": [{"text": "家を建てる前に、しっかりした基盤を作らなければならない。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "家[いえ]を建[た]てる前[まえ]に、しっかりした基盤[きばん]を作[つく]らなければならない。", "sentence_source": "generated"}, {"text": "地震に強い建物は、基盤が丈夫だ。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "地震[じしん]に強[つよ]い建物[たてもの]は、基盤[きばん]が丈夫[じょうぶ]だ。", "sentence_source": "generated"}, {"text": "信頼は、友情の基盤になる。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "信頼[しんらい]は、友情[ゆうじょう]の基盤[きばん]になる。", "sentence_source": "generated"}, {"text": "この会社は、地域の人々の支えを基盤に成長した。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、地域[ちいき]の人々[ひとびと]の支[ささ]えを基盤[きばん]に成長[せいちょう]した。", "sentence_source": "generated"}, {"text": "健康な体は、毎日の生活の基盤だ。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "健康[けんこう]な体[からだ]は、毎日[まいにち]の生活[せいかつ]の基盤[きばん]だ。", "sentence_source": "generated"}, {"text": "橋の基盤が弱いと、大水が出たときに危ない。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "橋[はし]の基盤[きばん]が弱[よわ]いと、大水[おおみず]が出[で]たときに危[あぶ]ない。", "sentence_source": "generated"}, {"text": "基盤がしっかりしていないと、高い塔は倒れてしまう。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "基盤[きばん]がしっかりしていないと、高[たか]い塔[とう]は倒[たお]れてしまう。", "sentence_source": "generated"}, {"text": "基礎の勉強をしっかりすることが、学力の基盤になる。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "基礎[きそ]の勉強[べんきょう]をしっかりすることが、学力[がくりょく]の基盤[きばん]になる。", "sentence_source": "generated"}, {"text": "彼は十年かけて、店の経営の基盤を固めた。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "彼[かれ]は十年[じゅうねん]かけて、店[みせ]の経営[けいえい]の基盤[きばん]を固[かた]めた。", "sentence_source": "generated"}, {"text": "新しい事業の基盤ができたので、来年は支店を開く予定だ。", "target_word": "基盤", "complexity_tier": "T3", "furigana": "新[あたら]しい事業[じぎょう]の基盤[きばん]ができたので、来年[らいねん]は支店[してん]を開[ひら]く予定[よてい]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "基盤", "label": "base"}, {"form": "基盤を", "label": "object"}], "register": "formal", "sense_fingerprint": "基盤: 物事を成り立たせる土台（建物・生活・事業などの土台）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd0e261-a606-4c8b-a65c-77d92cef559f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35430, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基盤", "is_correct": true, "explanation": "建物などの土台という意味で、「しっかりした〜を作る」に入る唯一の語。"}, {"text": "機嫌", "is_correct": false, "explanation": "機嫌は人の気分の状態で、「しっかりした機嫌を作る」とは言わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は感じるもので作るものではないため、「しっかりした眠気を作る」は不自然。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは空に現れる自然現象で、人が作るものではないので空所に入らない。"}], "explanations": {"基盤": "建物などの土台という意味で、「しっかりした〜を作る」に入る唯一の語。", "機嫌": "機嫌は人の気分の状態で、「しっかりした機嫌を作る」とは言わない。", "眠気": "眠気は感じるもので作るものではないため、「しっかりした眠気を作る」は不自然。", "夕焼け": "夕焼けは空に現れる自然現象で、人が作るものではないので空所に入らない。"}, "sentence_index": 0, "correct_answer": "基盤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝走って、彼は基盤体力を鍛えている。", "explanation": "ここは〈基礎〉の意味。「基礎体力」という決まった言い方の「基礎」を基盤に替えたもので、基盤には体の働きの土台を表す用法がないので不自然。"}, {"text": "この試験の基盤は、七十点だ。", "explanation": "ここは〈基準〉の意味。基盤は物事を支える土台で、合否を判断する目安の点数は指さないので合わない。"}, {"text": "彼の基盤は、来年までに資格を取ることだ。", "explanation": "ここは〈目標〉の意味。基盤は土台で、目指す到達点や達成したいことは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35430, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基盤", "is_correct": true, "explanation": "物事を支える土台の意味で、「基盤がしっかりしていないと塔は倒れる」に合う唯一の語。"}, {"text": "気配", "is_correct": false, "explanation": "気配は様子を感じ取るものなので、「気配がしっかりしていない」では塔が倒れる理由にならない。"}, {"text": "行列", "is_correct": false, "explanation": "行列は人や物が並んだ状態で、「しっかりしていない」と結びつかず、塔の倒壊の理由にならない。"}, {"text": "旋律", "is_correct": false, "explanation": "旋律は音楽の音の流れで、建物の塔を支える役割を持たないので文が成り立たない。"}], "explanations": {"基盤": "物事を支える土台の意味で、「基盤がしっかりしていないと塔は倒れる」に合う唯一の語。", "気配": "気配は様子を感じ取るものなので、「気配がしっかりしていない」では塔が倒れる理由にならない。", "行列": "行列は人や物が並んだ状態で、「しっかりしていない」と結びつかず、塔の倒壊の理由にならない。", "旋律": "旋律は音楽の音の流れで、建物の塔を支える役割を持たないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "基盤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の基盤は、テストで九十点を取った。", "explanation": "ここは〈点数〉の意味。基盤は土台を指すので、テストで取る点数の意味では使えず合わない。"}, {"text": "あの歌手は基盤が高く、若い世代に支持されている。", "explanation": "ここは〈人気〉の意味。基盤は支える土台で、世間の評判の高さを表す用法はないので合わない。"}, {"text": "会社は、この仕事の基盤を十万円に決めた。", "explanation": "ここは〈報酬〉の意味。基盤は土台で、仕事に対して払う金額は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35430, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "親は、子どもの生活の基盤に整えた。", "corrected_sentence": "親は、子どもの生活の基盤を整えた。", "error_description": "「整える」は対象を直接取る他動詞なので、「基盤を」が正しい。「基盤に」は格助詞の誤りで、誤りの箇所は基盤に付く「を」→「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35430, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い家は、基盤が弱くと地震で倒れる。", "corrected_sentence": "古い家は、基盤が弱いと地震で倒れる。", "error_description": "「基盤が」の述語は形容詞「弱い」。条件を表す「弱いと」が正しく、「弱くと」は活用形の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '034c4210-ad68-4bb4-ae2e-8d82f9a50de0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35432, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "谷が形作られる対象なので、目的語を示す「を」が入る。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では、形作る動作の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用の「と」では、形作る対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、この動作の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "谷が形作られる対象なので、目的語を示す「を」が入る。", "へ": "方向を表す「へ」では、形作る動作の対象を示せない。", "と": "共同や引用の「と」では、形作る対象を示せない。", "より": "比較の「より」では、この動作の対象を示せない。"}, "error_tags": {"へ": "方向", "と": "共同・引用", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35432, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "山が形作られる対象なので、目的語を示す「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「に」では、山を作る対象を直接示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」では、形作る対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」では、形作る対象と合わない。"}], "correct_answer": "を", "explanations": {"を": "山が形作られる対象なので、目的語を示す「を」が入る。", "に": "「に」では、山を作る対象を直接示せない。", "で": "手段を表す「で」では、形作る対象を示せない。", "から": "起点を表す「から」では、形作る対象と合わない。"}, "error_tags": {"に": "方向・結果", "で": "手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35432, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを作ること。", "primary_collocate": null, "pronunciation": "かたちづくる", "ipa": "katat͡ɕidzɯkɯɾɯ", "syllable_count": 6, "sentences": [{"text": "粘土で小さな犬を形作りました。", "target_word": "形作り", "complexity_tier": "T3", "furigana": "粘土(ねんど)で小(ちい)さな犬(いぬ)を形作(かたちづく)りました。", "sentence_source": "generated"}, {"text": "長い年月が、この美しい谷を形作った。", "target_word": "形作った", "complexity_tier": "T3", "furigana": "長(なが)い年月(としつき)が、この美(うつく)しい谷(たに)を形作(かたちづく)った。", "sentence_source": "generated"}, {"text": "川の流れが、この土地の地形を形作っています。", "target_word": "形作って", "complexity_tier": "T3", "furigana": "川(かわ)の流(なが)れが、この土地(とち)の地形(ちけい)を形作(かたちづく)っています。", "sentence_source": "generated"}, {"text": "経験の一つ一つが、今の私を形作っている。", "target_word": "形作って", "complexity_tier": "T3", "furigana": "経験(けいけん)の一(ひと)つ一(ひと)つが、今(いま)の私(わたし)を形作(かたちづく)っている。", "sentence_source": "generated"}, {"text": "彼女は手で雪を丸く形作って、雪だるまの頭にした。", "target_word": "形作って", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は手(て)で雪(ゆき)を丸(まる)く形作(かたちづく)って、雪(ゆき)だるまの頭(あたま)にした。", "sentence_source": "generated"}, {"text": "風は砂を動かして、砂漠の美しい模様を形作る。", "target_word": "形作る", "complexity_tier": "T3", "furigana": "風(かぜ)は砂(すな)を動(うご)かして、砂漠(さばく)の美(うつく)しい模様(もよう)を形作(かたちづく)る。", "sentence_source": "generated"}, {"text": "子どものころの環境が、人の性格を形作ると言われる。", "target_word": "形作る", "complexity_tier": "T3", "furigana": "子(こ)どものころの環境(かんきょう)が、人(ひと)の性格(せいかく)を形作(かたちづく)ると言(い)われる。", "sentence_source": "generated"}, {"text": "小さな石が積み重なって、大きな山を形作った。", "target_word": "形作った", "complexity_tier": "T3", "furigana": "小(ちい)さな石(いし)が積(つ)み重(かさ)なって、大(おお)きな山(やま)を形作(かたちづく)った。", "sentence_source": "generated"}, {"text": "昔の人々の考え方が、この国の文化を形作ってきた。", "target_word": "形作って", "complexity_tier": "T3", "furigana": "昔(むかし)の人々(ひとびと)の考(かんが)え方(かた)が、この国(くに)の文化(ぶんか)を形作(かたちづく)ってきた。", "sentence_source": "generated"}, {"text": "職人は熱い鉄をたたいて、一本の刀を形作った。", "target_word": "形作った", "complexity_tier": "T3", "furigana": "職人(しょくにん)は熱(あつ)い鉄(てつ)をたたいて、一本(いっぽん)の刀(かたな)を形作(かたちづく)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "形作る", "label": "終止形"}, {"form": "形作った", "label": "過去形"}, {"form": "形作って", "label": "て形"}, {"form": "形作らない", "label": "否定形"}, {"form": "形作ります", "label": "丁寧形"}, {"form": "形作れば", "label": "仮定形"}, {"form": "形作られる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "粘土や自然の力などが、ある形や姿のものを作り上げる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35432, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形作り", "is_correct": true, "explanation": "粘土で犬の形を作るという意味に合う連用形。"}, {"text": "飲み", "is_correct": false, "explanation": "犬を飲むとは言えず、文が成り立たない。"}, {"text": "眠り", "is_correct": false, "explanation": "犬を眠らせるという動作は、粘土で作る文脈に合わない。"}, {"text": "叫び", "is_correct": false, "explanation": "犬を叫ぶとは言えず、作る行為と合わない。"}], "explanations": {"形作り": "粘土で犬の形を作るという意味に合う連用形。", "飲み": "犬を飲むとは言えず、文が成り立たない。", "眠り": "犬を眠らせるという動作は、粘土で作る文脈に合わない。", "叫び": "犬を叫ぶとは言えず、作る行為と合わない。"}, "sentence_index": 0, "correct_answer": "形作り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は三日かけて、服のしみを形作った。", "explanation": "ここは〈落とす〉の意味。服のしみを落とす場面には形作るは使わない。"}, {"text": "机の上の本を形作って、きれいに並べた。", "explanation": "ここは〈整える〉の意味。本を並べて整える場面では形作るは使わない。"}, {"text": "ガラスを一瞬で割って、その破片を形作った。", "explanation": "ここは〈砕く〉の意味。ガラスを細かく砕く場面には形作るは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35432, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形作る", "is_correct": true, "explanation": "子どもの環境が人の性格を作り出すという意味に合う終止形。"}, {"text": "食べる", "is_correct": false, "explanation": "性格を食べるとは言えず、文が成り立たない。"}, {"text": "笑う", "is_correct": false, "explanation": "性格を笑うという動作は、文の内容に合わない。"}, {"text": "歌う", "is_correct": false, "explanation": "性格を歌うとは言えず、作り出す文脈に合わない。"}], "explanations": {"形作る": "子どもの環境が人の性格を作り出すという意味に合う終止形。", "食べる": "性格を食べるとは言えず、文が成り立たない。", "笑う": "性格を笑うという動作は、文の内容に合わない。", "歌う": "性格を歌うとは言えず、作り出す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "形作る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は黒板の文字を形作って、すぐに拭き取った。", "explanation": "ここは〈消す〉の意味。黒板の文字を消す場面には形作るは使わない。"}, {"text": "彼は雑誌を形作って、かばんに入れた。", "explanation": "ここは〈しまう〉の意味。雑誌をかばんにしまう場面には形作るは使わない。"}, {"text": "夕方、祖母は洗濯物を形作って、たんすにしまった。", "explanation": "ここは〈たたむ〉の意味。洗濯物をたたむ場面には形作るは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35432, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は毎日、粘土で小さな犬を形作りた。", "corrected_sentence": "祖父は毎日、粘土で小さな犬を形作った。", "error_description": "「形作りた」は誤った活用。過去形は「形作った」で、「形作りた」という形はない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "形作った", "is_correct": true, "explanation": "過去の出来事を表す過去形で、谷ができたという文の時制に合う。"}, {"text": "形作って", "is_correct": false, "explanation": "て形で、文を言い切れず「谷を形作って。」は誤り。"}, {"text": "形作られる", "is_correct": false, "explanation": "受身形で、長い年月が谷を作るという能動の文には合わない。"}, {"text": "形作れば", "is_correct": false, "explanation": "仮定形で、主節がなく文を完結できない。"}], "correct_form": "形作った", "base_form": "形作る", "form_label": "過去形", "sentence_index": 1, "explanations": {"形作った": "過去の出来事を表す過去形で、谷ができたという文の時制に合う。", "形作って": "て形で、文を言い切れず「谷を形作って。」は誤り。", "形作られる": "受身形で、長い年月が谷を作るという能動の文には合わない。", "形作れば": "仮定形で、主節がなく文を完結できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35432, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は一日かけて、粘土の器が形作った。", "corrected_sentence": "彼は一日かけて、粘土の器を形作った。", "error_description": "形作るの対象は「を」で示す。「器が」は誤りで、「器を」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "形作った", "is_correct": true, "explanation": "山ができたという過去の出来事を表す過去形で、文の時制に合う。"}, {"text": "形作らず", "is_correct": false, "explanation": "連用形の否定で、文を言い切れず「大きな山を形作らず。」は誤り。"}, {"text": "形作ら", "is_correct": false, "explanation": "未然形で、単独では文を終えられず「大きな山を形作ら。」は誤り。"}, {"text": "形作っ", "is_correct": false, "explanation": "促音で途中が切れた形で、文法的に存在せず誤り。"}], "correct_form": "形作った", "base_form": "形作る", "form_label": "過去形", "sentence_index": 7, "explanations": {"形作った": "山ができたという過去の出来事を表す過去形で、文の時制に合う。", "形作らず": "連用形の否定で、文を言い切れず「大きな山を形作らず。」は誤り。", "形作ら": "未然形で、単独では文を終えられず「大きな山を形作ら。」は誤り。", "形作っ": "促音で途中が切れた形で、文法的に存在せず誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35433, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "機械が形作られる対象なので、目的語を示す「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「に」では、機械を作る対象を直接示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では、形作る対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、形作る対象と合わない。"}], "correct_answer": "を", "explanations": {"を": "機械が形作られる対象なので、目的語を示す「を」が入る。", "に": "「に」では、機械を作る対象を直接示せない。", "で": "手段の「で」では、形作る対象を示せない。", "から": "起点の「から」では、形作る対象と合わない。"}, "error_tags": {"に": "方向・結果", "で": "手段", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35433, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "組織が形作られる対象なので、目的語を示す「を」が入る。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では、形作る対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用の「と」では、形作る対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、この動作の対象と合わない。"}], "correct_answer": "を", "explanations": {"を": "組織が形作られる対象なので、目的語を示す「を」が入る。", "へ": "方向を表す「へ」では、形作る対象を示せない。", "と": "共同や引用の「と」では、形作る対象を示せない。", "より": "比較の「より」では、この動作の対象と合わない。"}, "error_tags": {"へ": "方向", "と": "共同・引用", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35433, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事を組み立てて、新しいものや状態を作り出すこと。", "primary_collocate": null, "pronunciation": "かたちづくる", "ipa": "katat͡ɕidzɯkɯɾɯ", "syllable_count": 6, "sentences": [{"text": "多くの人が協力して、新しい町を形作った。", "target_word": "形作った", "complexity_tier": "T3", "furigana": "多(おお)くの人(ひと)が協力(きょうりょく)して、新(あたら)しい町(まち)を形作(かたちづく)った。", "sentence_source": "generated"}, {"text": "小さな部品が組み合わさって、一つの機械を形作っている。", "target_word": "形作って", "complexity_tier": "T3", "furigana": "小(ちい)さな部品(ぶひん)が組(く)み合(あ)わさって、一(ひと)つの機械(きかい)を形作(かたちづく)っている。", "sentence_source": "generated"}, {"text": "若者たちは自分たちの力で、新しいグループを形作った。", "target_word": "形作った", "complexity_tier": "T3", "furigana": "若者(わかもの)たちは自分(じぶん)たちの力(ちから)で、新(あたら)しいグループを形作(かたちづく)った。", "sentence_source": "generated"}, {"text": "三つの意見をまとめて、一つの計画を形作る。", "target_word": "形作る", "complexity_tier": "T3", "furigana": "三(みっ)つの意見(いけん)をまとめて、一(ひと)つの計画(けいかく)を形作(かたちづく)る。", "sentence_source": "generated"}, {"text": "毎日の小さな習慣が、健康な体を形作る。", "target_word": "形作る", "complexity_tier": "T3", "furigana": "毎日(まいにち)の小(ちい)さな習慣(しゅうかん)が、健康(けんこう)な体(からだ)を形作(かたちづく)る。", "sentence_source": "generated"}, {"text": "家族とは、親と子が一緒に形作る小さな社会だ。", "target_word": "形作る", "complexity_tier": "T3", "furigana": "家族(かぞく)とは、親(おや)と子(こ)が一緒(いっしょ)に形作(かたちづく)る小(ちい)さな社会(しゃかい)だ。", "sentence_source": "generated"}, {"text": "彼は様々な話を集めて、一つの物語を形作った。", "target_word": "形作った", "complexity_tier": "T3", "furigana": "彼(かれ)は様々(さまざま)な話(はなし)を集(あつ)めて、一(ひと)つの物語(ものがたり)を形作(かたちづく)った。", "sentence_source": "generated"}, {"text": "各国の代表が集まって、新しい組織を形作った。", "target_word": "形作った", "complexity_tier": "T3", "furigana": "各国(かっこく)の代表(だいひょう)が集(あつ)まって、新(あたら)しい組織(そしき)を形作(かたちづく)った。", "sentence_source": "generated"}, {"text": "住民の話し合いが、これからの町の姿を形作っていく。", "target_word": "形作って", "complexity_tier": "T3", "furigana": "住民(じゅうみん)の話(はな)し合(あ)いが、これからの町(まち)の姿(すがた)を形作(かたちづく)っていく。", "sentence_source": "generated"}, {"text": "学生たちは意見を出し合い、新しいルールを形作った。", "target_word": "形作った", "complexity_tier": "T3", "furigana": "学生(がくせい)たちは意見(いけん)を出(だ)し合(あ)い、新(あたら)しいルールを形作(かたちづく)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "形作る", "label": "終止形"}, {"form": "形作った", "label": "過去形"}, {"form": "形作って", "label": "て形"}, {"form": "形作らない", "label": "否定形"}, {"form": "形作ります", "label": "丁寧形"}, {"form": "形作れば", "label": "仮定形"}, {"form": "形作られる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "要素を組み合わせて、組織・社会・状態などを新しく作り出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35433, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形作った", "is_correct": true, "explanation": "新しい町を作り上げるという意味に合う過去形。"}, {"text": "飲んだ", "is_correct": false, "explanation": "町を飲むとは言えず、文が成り立たない。"}, {"text": "眠った", "is_correct": false, "explanation": "町を眠らせるという動作は、文の意味に合わない。"}, {"text": "叫んだ", "is_correct": false, "explanation": "町を叫ぶとは言えず、作る行為と合わない。"}], "explanations": {"形作った": "新しい町を作り上げるという意味に合う過去形。", "飲んだ": "町を飲むとは言えず、文が成り立たない。", "眠った": "町を眠らせるという動作は、文の意味に合わない。", "叫んだ": "町を叫ぶとは言えず、作る行為と合わない。"}, "sentence_index": 0, "correct_answer": "形作った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、体重を形作って記録した。", "explanation": "ここは〈計る〉の意味。体重を量る場面には形作るは使わない。"}, {"text": "先生は生徒の名前を一人ずつ形作った。", "explanation": "ここは〈呼ぶ〉の意味。名前を読み上げる場面では形作るは使わない。"}, {"text": "朝から散らかった机を形作った。", "explanation": "ここは〈片付ける〉の意味。散らかったものを整理する場面には形作るは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35433, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形作った", "is_correct": true, "explanation": "話を組み立てて一つの物語を作るという意味に合う過去形。"}, {"text": "食べた", "is_correct": false, "explanation": "物語を食べるとは言えず、文が成り立たない。"}, {"text": "笑った", "is_correct": false, "explanation": "物語を笑うとは言えず、文の流れに合わない。"}, {"text": "歌った", "is_correct": false, "explanation": "物語を歌うとは言えず、作る行為と合わない。"}], "explanations": {"形作った": "話を組み立てて一つの物語を作るという意味に合う過去形。", "食べた": "物語を食べるとは言えず、文が成り立たない。", "笑った": "物語を笑うとは言えず、文の流れに合わない。", "歌った": "物語を歌うとは言えず、作る行為と合わない。"}, "sentence_index": 6, "correct_answer": "形作った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎日、旅行で撮った写真を形作って、アルバムに並べた。", "explanation": "ここは〈貼る〉の意味。写真をアルバムに貼る場面には形作るは使わない。"}, {"text": "店員は笑顔で、客に新しい値段を形作った。", "explanation": "ここは〈伝える〉の意味。情報を相手に知らせる場面には形作るは使わない。"}, {"text": "選手は走り続けて、前の選手を形作った。", "explanation": "ここは〈追い抜く〉の意味。前の選手を追い抜く場面には形作るは使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35433, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友人たちは力を合わせて、新しい学校を形作りた。", "corrected_sentence": "友人たちは力を合わせて、新しい学校を形作った。", "error_description": "「形作りた」は誤った活用。過去形は「形作った」になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "形作って", "is_correct": true, "explanation": "て形で、「ている」に続いて機械ができつつある状態を表すのに合う。"}, {"text": "形作る", "is_correct": false, "explanation": "終止形は「ている」の前に直接続かず、この文の形に合わない。"}, {"text": "形作れば", "is_correct": false, "explanation": "仮定形で、「ている」で状態を述べる文と合わない。"}, {"text": "形作られる", "is_correct": false, "explanation": "受身形では部品が機械を作る主体の文に合わない。"}], "correct_form": "形作って", "base_form": "形作る", "form_label": "て形", "sentence_index": 1, "explanations": {"形作って": "て形で、「ている」に続いて機械ができつつある状態を表すのに合う。", "形作る": "終止形は「ている」の前に直接続かず、この文の形に合わない。", "形作れば": "仮定形で、「ている」で状態を述べる文と合わない。", "形作られる": "受身形では部品が機械を作る主体の文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35433, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地域の人々が協力して、新しい公園が形作った。", "corrected_sentence": "地域の人々が協力して、新しい公園を形作った。", "error_description": "形作るの対象は「を」で示す。「公園が」は誤りで、「公園を」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "形作った", "is_correct": true, "explanation": "新しい組織ができたという過去の出来事を表す過去形で、文の時制に合う。"}, {"text": "形作って", "is_correct": false, "explanation": "て形で、文を言い切れず「組織を形作って。」は誤り。"}, {"text": "形作れば", "is_correct": false, "explanation": "仮定形で、主節がなく文を完結できない。"}, {"text": "形作り", "is_correct": false, "explanation": "連用形で、文を言い切れず「組織を形作り。」は誤り。"}], "correct_form": "形作った", "base_form": "形作る", "form_label": "過去形", "sentence_index": 7, "explanations": {"形作った": "新しい組織ができたという過去の出来事を表す過去形で、文の時制に合う。", "形作って": "て形で、文を言い切れず「組織を形作って。」は誤り。", "形作れば": "仮定形で、主節がなく文を完結できない。", "形作り": "連用形で、文を言い切れず「組織を形作り。」は誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35434, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「原動として」の「と」で、原動を資格として示す形になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では、原動の役割を示せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では、原動としての役割と合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、原動としての役割を表せない。"}], "correct_answer": "と", "explanations": {"と": "「原動として」の「と」で、原動を資格として示す形になる。", "へ": "方向を表す「へ」では、原動の役割を示せない。", "より": "比較の「より」では、原動としての役割と合わない。", "から": "起点の「から」では、原動としての役割を表せない。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35434, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「原動とする」の「と」で、原動を資格として示す形になる。"}, {"text": "で", "is_correct": false, "explanation": "手段の「で」では、原動の役割を示す形にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」では、原動を名詞として続ける形にならず文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」では、原動が動詞に続く形と合わない。"}], "correct_answer": "と", "explanations": {"と": "「原動とする」の「と」で、原動を資格として示す形になる。", "で": "手段の「で」では、原動の役割を示す形にならない。", "の": "連体の「の」では、原動を名詞として続ける形にならず文が成り立たない。", "が": "主語の「が」では、原動が動詞に続く形と合わない。"}, "error_tags": {"で": "手段", "の": "連体修飾", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35434, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを うごかす もとに なること。", "primary_collocate": null, "pronunciation": "げんどう", "ipa": "ɡendoː", "syllable_count": 4, "sentences": [{"text": "水の力が原動となって、古い水車は回り続ける。", "target_word": "原動", "complexity_tier": "T3", "furigana": "水(みず)の力(ちから)が原動(げんどう)となって、古(ふる)い水車(すいしゃ)は回(まわ)り続(つづ)ける。", "sentence_source": "generated"}, {"text": "この船は、蒸気を原動として海を進んだ。", "target_word": "原動", "complexity_tier": "T3", "furigana": "この船(ふね)は、蒸気(じょうき)を原動(げんどう)として海(うみ)を進(すす)んだ。", "sentence_source": "generated"}, {"text": "風を原動にした機械は、燃料がいらない。", "target_word": "原動", "complexity_tier": "T3", "furigana": "風(かぜ)を原動(げんどう)にした機械(きかい)は、燃料(ねんりょう)がいらない。", "sentence_source": "generated"}, {"text": "機械を動かす原動は、地下から送られる水の力だ。", "target_word": "原動", "complexity_tier": "T3", "furigana": "機械(きかい)を動(うご)かす原動(げんどう)は、地下(ちか)から送(おく)られる水(みず)の力(ちから)だ。", "sentence_source": "generated"}, {"text": "この工場では、原動となる水車が止まると、機械はすべて動かなくなる。", "target_word": "原動", "complexity_tier": "T3", "furigana": "この工場(こうじょう)では、原動(げんどう)となる水車(すいしゃ)が止(と)まると、機械(きかい)はすべて動(うご)かなくなる。", "sentence_source": "generated"}, {"text": "昔の工場では、川の流れを原動にして大きな機械を動かした。", "target_word": "原動", "complexity_tier": "T3", "furigana": "昔(むかし)の工場(こうじょう)では、川(かわ)の流(なが)れを原動(げんどう)にして大(おお)きな機械(きかい)を動(うご)かした。", "sentence_source": "generated"}, {"text": "この装置の原動は何かと、先生は生徒に聞いた。", "target_word": "原動", "complexity_tier": "T3", "furigana": "この装置(そうち)の原動(げんどう)は何(なに)かと、先生(せんせい)は生徒(せいと)に聞(き)いた。", "sentence_source": "generated"}, {"text": "電気を原動とするバスが、町の中を静かに走っている。", "target_word": "原動", "complexity_tier": "T3", "furigana": "電気(でんき)を原動(げんどう)とするバスが、町(まち)の中(なか)を静(しず)かに走(はし)っている。", "sentence_source": "generated"}, {"text": "馬の力を原動にした荷車が、昔は荷物を運んでいた。", "target_word": "原動", "complexity_tier": "T3", "furigana": "馬(うま)の力(ちから)を原動(げんどう)にした荷車(にぐるま)が、昔(むかし)は荷物(にもつ)を運(はこ)んでいた。", "sentence_source": "generated"}, {"text": "原動となる力が弱いと、大きな車輪は回らない。", "target_word": "原動", "complexity_tier": "T3", "furigana": "原動(げんどう)となる力(ちから)が弱(よわ)いと、大(おお)きな車輪(しゃりん)は回(まわ)らない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原動", "label": "基本形"}], "register": "formal written", "sense_fingerprint": "機械や乗り物を動かす力の源になるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ef85fb-3faa-4966-9f9e-3c27acf6f4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35434, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原動", "is_correct": true, "explanation": "水の力が機械を動かす動力源になるという意味に合う。"}, {"text": "祝福", "is_correct": false, "explanation": "水の力が祝福となるという文にはならず、意味が通らない。"}, {"text": "教科書", "is_correct": false, "explanation": "水の力が教科書になるとは言えず、文の意味に合わない。"}, {"text": "砂時計", "is_correct": false, "explanation": "水の力が砂時計になるのは不自然で、動かす力の意味に合わない。"}], "explanations": {"原動": "水の力が機械を動かす動力源になるという意味に合う。", "祝福": "水の力が祝福となるという文にはならず、意味が通らない。", "教科書": "水の力が教科書になるとは言えず、文の意味に合わない。", "砂時計": "水の力が砂時計になるのは不自然で、動かす力の意味に合わない。"}, "sentence_index": 0, "correct_answer": "原動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は毎朝、原動を散歩した。", "explanation": "ここは〈原野〉の意味。広い野原を歩く場面に原動は使わない。"}, {"text": "パンの原動は小麦粉だ。", "explanation": "ここは〈原料〉の意味。パンの材料を指す場面には原動は使わない。"}, {"text": "論文の原動を書いた。", "explanation": "ここは〈原稿〉の意味。書いた文章を指す場面には原動は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35434, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原動", "is_correct": true, "explanation": "装置の動力源を尋ねる文の意味に合う。"}, {"text": "献立", "is_correct": false, "explanation": "装置の献立という言い方は成り立たず、文の意味に合わない。"}, {"text": "挨拶", "is_correct": false, "explanation": "装置の挨拶は意味が通らず、動力を尋ねる文と合わない。"}, {"text": "柔道", "is_correct": false, "explanation": "装置の柔道は成り立たず、装置の動力を尋ねる文に合わない。"}], "explanations": {"原動": "装置の動力源を尋ねる文の意味に合う。", "献立": "装置の献立という言い方は成り立たず、文の意味に合わない。", "挨拶": "装置の挨拶は意味が通らず、動力を尋ねる文と合わない。", "柔道": "装置の柔道は成り立たず、装置の動力を尋ねる文に合わない。"}, "sentence_index": 6, "correct_answer": "原動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "企画の原動を提出した。", "explanation": "ここは〈原案〉の意味。提出するのは計画の下書きで、原動ではない。"}, {"text": "原動を精製して、燃料を作る。", "explanation": "ここは〈原油〉の意味。精製して燃料をつくる対象は原油で、原動ではない。"}, {"text": "彼は原動を読んで、旅の計画を立てた。", "explanation": "ここは〈原典〉の意味。読む対象の文献を指すのに原動は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35434, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この列車は、電気を原動して線路を走る。", "corrected_sentence": "この列車は、電気を原動として線路を走る。", "error_description": "原動は名詞なので「として」で受ける。「原動して」は動詞の形にならず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35434, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工場の原動を、地下から送られる水の力だ。", "corrected_sentence": "この工場の原動は、地下から送られる水の力だ。", "error_description": "原動は文の主題なので「は」で示す。「を」にすると目的語になり、「〜だ」で終わる文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38728d3d-6766-4571-9c7c-1f49a64159e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
