INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35437, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「今日の授業」と、名詞「授業」を「今日」で修飾する。"}, {"text": "が", "is_correct": false, "explanation": "「今日が授業で」は不自然。「今日」を主語にすると文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「今日を授業で」は目的語の形として不自然。「授業」を修飾する形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「今日へ授業で」は方向を示す形として不自然で、意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "正解。「今日の授業」と、名詞「授業」を「今日」で修飾する。", "が": "「今日が授業で」は不自然。「今日」を主語にすると文が成り立たない。", "を": "「今日を授業で」は目的語の形として不自然。「授業」を修飾する形にならない。", "へ": "「今日へ授業で」は方向を示す形として不自然で、意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35437, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "話している時点を含む、現在の日や時代。", "primary_collocate": null, "pronunciation": "きょう", "ipa": "kjoː", "syllable_count": 2, "sentences": [{"text": "過酷な自然環境と向き合いながら、彼は今日も黙々と作業を続け、やがて訪れる豊かな実りの季節を心待ちにしている。", "target_word": "今日", "complexity_tier": "T3", "furigana": "過酷[かこく]な自然[しぜん]環境[かんきょう]と向[む]き合[あ]いながら、彼[かれ]は今日[きょう]も黙々[もくもく]と作業[さぎょう]を続[つづ]け、やがて訪[おとず]れる豊[ゆた]かな実[みの]りの季節[きせつ]を心待[こころま]ちにしている。", "sentence_source": "mined"}, {"text": "今日は朝から雨が降っているので、買い物は明日にする。", "target_word": "今日", "complexity_tier": "T3", "furigana": "今日[きょう]は朝[あさ]から雨[あめ]が降[ふ]っているので、買[か]い物[もの]は明日[あした]にする。", "sentence_source": "generated"}, {"text": "今日の夕食は、母が作ったカレーだ。", "target_word": "今日", "complexity_tier": "T3", "furigana": "今日[きょう]の夕食[ゆうしょく]は、母[はは]が作[つく]ったカレーだ。", "sentence_source": "generated"}, {"text": "昨日は忙しかったが、今日は一日ゆっくり休めそうだ。", "target_word": "今日", "complexity_tier": "T3", "furigana": "昨日[きのう]は忙[いそが]しかったが、今日[きょう]は一日[いちにち]ゆっくり休[やす]めそうだ。", "sentence_source": "generated"}, {"text": "今日が締め切りの宿題を、まだ半分しか終わらせていない。", "target_word": "今日", "complexity_tier": "T3", "furigana": "今日[きょう]が締[し]め切[き]りの宿題[しゅくだい]を、まだ半分[はんぶん]しか終[お]わらせていない。", "sentence_source": "generated"}, {"text": "友達と約束があるから、今日は早く帰らなければならない。", "target_word": "今日", "complexity_tier": "T3", "furigana": "友達[ともだち]と約束[やくそく]があるから、今日[きょう]は早[はや]く帰[かえ]らなければならない。", "sentence_source": "generated"}, {"text": "今日は妹の誕生日なので、家族みんなでケーキを食べる。", "target_word": "今日", "complexity_tier": "T3", "furigana": "今日[きょう]は妹[いもうと]の誕生日[たんじょうび]なので、家族[かぞく]みんなでケーキを食[た]べる。", "sentence_source": "generated"}, {"text": "今日の授業で習った漢字を、寝る前にもう一度復習した。", "target_word": "今日", "complexity_tier": "T3", "furigana": "今日[きょう]の授業[じゅぎょう]で習[なら]った漢字[かんじ]を、寝[ね]る前[まえ]にもう一度[いちど]復習[ふくしゅう]した。", "sentence_source": "generated"}, {"text": "今日は祝日で、駅前の店はどこも混んでいた。", "target_word": "今日", "complexity_tier": "T3", "furigana": "今日[きょう]は祝日[しゅくじつ]で、駅前[えきまえ]の店[みせ]はどこも混[こ]んでいた。", "sentence_source": "generated"}, {"text": "今日の試合に勝てば、チームは決勝に進める。", "target_word": "今日", "complexity_tier": "T3", "furigana": "今日[きょう]の試合[しあい]に勝[か]てば、チームは決勝[けっしょう]に進[すす]める。", "sentence_source": "generated"}], "morphological_forms": [{"form": "今日", "label": "基本形"}], "register": "標準語・中立（普通体）", "sense_fingerprint": "話している時点を含む一日、つまり今日（きょう）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 5 words above tier T1 (max 2): 過酷 (Zipf 3.82), 向き合い (Zipf 3.11), 黙々と (Zipf 3.25), 実り (Zipf 3.12), 心待ち (Zipf 3.01)']::text[], '636da3c2-221b-40c9-84b6-330f2c60b543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35437, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今日", "is_correct": true, "explanation": "正解。「今日も」は、話している今日も作業を続けていることを表す。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙も黙々と作業を続け」は成り立たない。手紙は作業の主語にならない。"}, {"text": "病院", "is_correct": false, "explanation": "「病院も黙々と作業を続け」は文の主語として不自然で、意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気も黙々と作業を続け」は成り立たない。天気は人の作業の主体にならない。"}], "explanations": {"今日": "正解。「今日も」は、話している今日も作業を続けていることを表す。", "手紙": "「手紙も黙々と作業を続け」は成り立たない。手紙は作業の主語にならない。", "病院": "「病院も黙々と作業を続け」は文の主語として不自然で、意味が通らない。", "天気": "「天気も黙々と作業を続け」は成り立たない。天気は人の作業の主体にならない。"}, "sentence_index": 0, "correct_answer": "今日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は毎日、朝早く起きて散歩する。", "explanation": "「今日」を「いつも」のような習慣の意味で使っている。今日は特定の一日を指すので、習慣的な散歩とは合わない。"}, {"text": "今日は去年の春、この町に引っ越した。", "explanation": "「今日」は今の日を指すので、去年の出来事には使えない。去年の同じ日なら「去年の今日」と言う。"}, {"text": "今日は一年かけて、庭の木を育てた。", "explanation": "「今日」を「今年」の意味で使っている。「今日」は一日を指すので、「一年かけて」と期間の長さが合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35437, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今日", "is_correct": true, "explanation": "正解。「今日は妹の誕生日なので」の主題として、話している日を示す。"}, {"text": "家族", "is_correct": false, "explanation": "「家族は妹の誕生日なので」は意味が通らない。家族は誕生日そのものではない。"}, {"text": "台風", "is_correct": false, "explanation": "「台風は妹の誕生日なので」は成り立たない。台風は誕生日の主題にならない。"}, {"text": "教室", "is_correct": false, "explanation": "「教室は妹の誕生日なので」は不自然で、場所は誕生日の主題にならない。"}], "explanations": {"今日": "正解。「今日は妹の誕生日なので」の主題として、話している日を示す。", "家族": "「家族は妹の誕生日なので」は意味が通らない。家族は誕生日そのものではない。", "台風": "「台風は妹の誕生日なので」は成り立たない。台風は誕生日の主題にならない。", "教室": "「教室は妹の誕生日なので」は不自然で、場所は誕生日の主題にならない。"}, "sentence_index": 6, "correct_answer": "今日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日の江戸時代には、まだ電話がなかった。", "explanation": "「今日」を「当時」の意味で使っている。今日は話している現在を指すので、江戸時代の話には合わない。"}, {"text": "今日の試合は、先週のうちに終わっていた。", "explanation": "「今日」を「その日」のような過去の日の意味で使っている。今日は現在の日を指すので、先週終わった試合には合わない。"}, {"text": "今日の試合は、去年の秋にもう終わっていた。", "explanation": "「今日」を「去年の秋」のような過去の日の意味で使っている。今日は現在の日を指すので、去年の秋に終わった試合とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35437, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日に雨が降っているので、洗濯は中止だ。", "corrected_sentence": "今日は雨が降っているので、洗濯は中止だ。", "error_description": "「今日」に続く「に」が誤り。主題として「今日は」と示すのが自然。「に」は時点を示す助詞なので、雨の状況を述べる文には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35437, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今日を試合に勝てば、チームは決勝に進めるはずだ。", "corrected_sentence": "今日の試合に勝てば、チームは決勝に進めるはずだ。", "error_description": "「今日」は「試合」を修飾するので「の」が必要。「を」は目的語を示すが、ここは「試合」にかかる名詞句なので合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26f64f78-ef67-4239-8452-c55ac5095b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35438, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「インターネットで調べる」は手段を表す。"}, {"text": "を", "is_correct": false, "explanation": "「天気を」と「を」が重なり、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「インターネットへ天気を調べました」は方向の「へ」が合わず誤り。"}, {"text": "に", "is_correct": false, "explanation": "「インターネットに天気を調べました」は「調べる」と結びつかず誤り。"}], "correct_answer": "で", "explanations": {"で": "「インターネットで調べる」は手段を表す。", "を": "「天気を」と「を」が重なり、文として成り立たない。", "へ": "「インターネットへ天気を調べました」は方向の「へ」が合わず誤り。", "に": "「インターネットに天気を調べました」は「調べる」と結びつかず誤り。"}, "error_tags": {"を": "object_marker_misuse", "へ": "direction", "に": "target_marker_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35438, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「インターネットにつなぐ」は接続先を表す。"}, {"text": "や", "is_correct": false, "explanation": "「インターネットやつなぐには」は並べる「や」の後に名詞がなく、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「インターネットのつなぐには」は文として成り立たない。"}, {"text": "ほど", "is_correct": false, "explanation": "「インターネットほどつなぐには」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「インターネットにつなぐ」は接続先を表す。", "や": "「インターネットやつなぐには」は並べる「や」の後に名詞がなく、文として成り立たない。", "の": "「インターネットのつなぐには」は文として成り立たない。", "ほど": "「インターネットほどつなぐには」は文として成り立たない。"}, "error_tags": {"の": "possessive_misuse", "ほど": "degree_particle_misuse", "や": "enumeration_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35438, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "コンピューターをつなぐしくみ。", "primary_collocate": null, "pronunciation": "いんたーねっと", "ipa": "intaːnetto", "syllable_count": 7, "sentences": [{"text": "インターネットは便利なしくみです。", "target_word": "インターネット", "complexity_tier": "T2", "furigana": "インターネットは便利[べんり]なしくみです。", "sentence_source": "generated"}, {"text": "インターネットで天気を調べました。", "target_word": "インターネット", "complexity_tier": "T2", "furigana": "インターネットで天気[てんき]を調[しら]べました。", "sentence_source": "generated"}, {"text": "インターネットがないと、メールが送れません。", "target_word": "インターネット", "complexity_tier": "T3", "furigana": "インターネットがないと、メールが送[おく]れません。", "sentence_source": "generated"}, {"text": "インターネットを使って、友達に連絡した。", "target_word": "インターネット", "complexity_tier": "T3", "furigana": "インターネットを使[つか]って、友達[ともだち]に連絡[れんらく]した。", "sentence_source": "generated"}, {"text": "学校のコンピューターはインターネットにつながっています。", "target_word": "インターネット", "complexity_tier": "T4", "furigana": "学校[がっこう]のコンピューターはインターネットにつながっています。", "sentence_source": "generated"}, {"text": "インターネットのおかげで、遠い国の友達と話せる。", "target_word": "インターネット", "complexity_tier": "T4", "furigana": "インターネットのおかげで、遠[とお]い国[くに]の友達[ともだち]と話[はな]せる。", "sentence_source": "generated"}, {"text": "家のインターネットが遅くて、動画が止まってしまった。", "target_word": "インターネット", "complexity_tier": "T4", "furigana": "家[いえ]のインターネットが遅[おそ]くて、動画[どうが]が止[と]まってしまった。", "sentence_source": "generated"}, {"text": "インターネットにつなぐには、まず電源を入れてください。", "target_word": "インターネット", "complexity_tier": "T4", "furigana": "インターネットにつなぐには、まず電源[でんげん]を入[い]れてください。", "sentence_source": "generated"}, {"text": "インターネットは、世界中のコンピューターをつなぐ大きなしくみだ。", "target_word": "インターネット", "complexity_tier": "T5", "furigana": "インターネットは、世界中[せかいじゅう]のコンピューターをつなぐ大[おお]きなしくみだ。", "sentence_source": "generated"}, {"text": "インターネットが広まって以来、人々の暮らしや働き方は大きく変わってきた。", "target_word": "インターネット", "complexity_tier": "T5", "furigana": "インターネットが広[ひろ]まって以来[いらい]、人々[ひとびと]の暮[く]らしや働[はたら]き方[かた]は大[おお]きく変[か]わってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ネット", "label": "派生"}, {"form": "インターネット回線", "label": "派生"}, {"form": "インターネットバンキング", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | コンピューターをつなぐしくみ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fadb3909-14e2-49bc-a4d8-0691c24c9708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35438, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インターネット", "is_correct": true, "explanation": "コンピューターをつなぐ便利な仕組みという説明に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は「便利なしくみ」ではない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが意味が合わない。地震は便利なしくみとは言えない。"}, {"text": "砂糖", "is_correct": false, "explanation": "形は合うが意味が合わない。砂糖はしくみではなく物質である。"}], "explanations": {"インターネット": "コンピューターをつなぐ便利な仕組みという説明に合う。", "天気": "形は合うが意味が合わない。天気は「便利なしくみ」ではない。", "地震": "形は合うが意味が合わない。地震は便利なしくみとは言えない。", "砂糖": "形は合うが意味が合わない。砂糖はしくみではなく物質である。"}, "sentence_index": 0, "correct_answer": "インターネット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "インターネットを手でもって、学校へ行った。", "explanation": "インターネットは物ではなく仕組みなので、手で持って行くという使い方は誤り。"}, {"text": "インターネットを冷蔵庫に入れて、冷やした。", "explanation": "インターネットは物ではないので、冷蔵庫に入れて冷やすという使い方は誤り。"}, {"text": "インターネットを朝ごはんに食べた。", "explanation": "インターネットは食べ物ではないので、食べるという使い方は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35438, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インターネット", "is_correct": true, "explanation": "家のネットが遅くて動画が止まるという流れに合う。"}, {"text": "犬", "is_correct": false, "explanation": "形は合うが意味が合わない。犬が遅くて動画が止まるという関係は成り立たない。"}, {"text": "庭", "is_correct": false, "explanation": "形は合うが意味が合わない。庭が遅くて動画が止まることはない。"}, {"text": "椅子", "is_correct": false, "explanation": "形は合うが意味が合わない。椅子が遅くて動画が止まるとは言えない。"}], "explanations": {"インターネット": "家のネットが遅くて動画が止まるという流れに合う。", "犬": "形は合うが意味が合わない。犬が遅くて動画が止まるという関係は成り立たない。", "庭": "形は合うが意味が合わない。庭が遅くて動画が止まることはない。", "椅子": "形は合うが意味が合わない。椅子が遅くて動画が止まるとは言えない。"}, "sentence_index": 6, "correct_answer": "インターネット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "インターネットを着て、寒い外へ出た。", "explanation": "インターネットは衣服ではないので、着るという使い方は誤り。"}, {"text": "インターネットを鉛筆で書いて、先生に出した。", "explanation": "インターネットは仕組みなので、鉛筆で書いて提出するという使い方は誤り。"}, {"text": "インターネットが庭で咲いて、とてもきれいだった。", "explanation": "インターネットは植物ではないので、咲くという使い方は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35438, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校でインターネットを割って、宿題を調べた。", "corrected_sentence": "学校でインターネットを使って、宿題を調べた。", "error_description": "「インターネットを割る」は不自然。調べる手段として「使う」を用いる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
