INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35439, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「インターネットで」は販売の手段・場を表す。"}, {"text": "を", "is_correct": false, "explanation": "「販売を」と「を」が重なり、文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「インターネットが販売を開始しましょう」は意志の文として成り立たない。"}, {"text": "ほど", "is_correct": false, "explanation": "「インターネットほど販売を開始しましょう」は文として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「インターネットで」は販売の手段・場を表す。", "を": "「販売を」と「を」が重なり、文として成り立たない。", "が": "「インターネットが販売を開始しましょう」は意志の文として成り立たない。", "ほど": "「インターネットほど販売を開始しましょう」は文として成り立たない。"}, "error_tags": {"を": "object_marker_misuse", "が": "subject_marker_misuse", "ほど": "degree_particle_misuse"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
