INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35439, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "世界中のコンピューターを相互に接続するネットワークシステム。", "primary_collocate": null, "pronunciation": "いんたーねっと", "ipa": "intaːnetto", "syllable_count": 7, "sentences": [{"text": "まずはインターネットで販売を開始しましょう。", "target_word": "インターネット", "complexity_tier": "T3", "furigana": "まずはインターネットで販売[はんばい]を開始[かいし]しましょう。", "sentence_source": "mined"}, {"text": "インターネットは便利です。", "target_word": "インターネット", "complexity_tier": "T2", "furigana": "インターネットは便利[べんり]です。", "sentence_source": "generated"}, {"text": "インターネットを使う。", "target_word": "インターネット", "complexity_tier": "T2", "furigana": "インターネットを使[つか]う。", "sentence_source": "generated"}, {"text": "家でインターネットに接続しました。", "target_word": "インターネット", "complexity_tier": "T2", "furigana": "家[いえ]でインターネットに接続[せつぞく]しました。", "sentence_source": "generated"}, {"text": "夜はインターネットの動画を見ています。", "target_word": "インターネット", "complexity_tier": "T3", "furigana": "夜[よる]はインターネットの動画[どうが]を見[み]ています。", "sentence_source": "generated"}, {"text": "インターネットがつながらなくて、仕事ができない。", "target_word": "インターネット", "complexity_tier": "T4", "furigana": "インターネットがつながらなくて、仕事[しごと]ができない。", "sentence_source": "generated"}, {"text": "インターネットのおかげで、世界中の人と話せるようになった。", "target_word": "インターネット", "complexity_tier": "T4", "furigana": "インターネットのおかげで、世界中[せかいじゅう]の人[ひと]と話[はな]せるようになった。", "sentence_source": "generated"}, {"text": "インターネットがなければ、現代の生活は成り立たないだろう。", "target_word": "インターネット", "complexity_tier": "T4", "furigana": "インターネットがなければ、現代[げんだい]の生活[せいかつ]は成[な]り立[た]たないだろう。", "sentence_source": "generated"}, {"text": "インターネットで買い物をする人が増えるにつれて、町の小さな店は苦しくなっている。", "target_word": "インターネット", "complexity_tier": "T5", "furigana": "インターネットで買[か]い物[もの]をする人[ひと]が増[ふ]えるにつれて、町[まち]の小[ちい]さな店[みせ]は苦[くる]しくなっている。", "sentence_source": "generated"}, {"text": "インターネットで見た情報が正しいとは限らないので、よく確かめることが大切だ。", "target_word": "インターネット", "complexity_tier": "T5", "furigana": "インターネットで見[み]た情報[じょうほう]が正[ただ]しいとは限[かぎ]らないので、よく確[たし]かめることが大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ネット", "label": "派生"}, {"form": "インターネット回線", "label": "派生"}, {"form": "インターネットバンキング", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 世界中をつなぐ通信網の仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fadb3909-14e2-49bc-a4d8-0691c24c9708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35439, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インターネット", "is_correct": true, "explanation": "「インターネットで販売を開始する」は、ネット上で売り始める意味で自然に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は販売を始める手段や場所にならない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが意味が合わない。地震で販売を始めるという内容は成り立たない。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが意味が合わない。辞書は販売を開始する場や手段として使えない。"}], "explanations": {"インターネット": "「インターネットで販売を開始する」は、ネット上で売り始める意味で自然に合う。", "天気": "形は合うが意味が合わない。天気は販売を始める手段や場所にならない。", "地震": "形は合うが意味が合わない。地震で販売を始めるという内容は成り立たない。", "辞書": "形は合うが意味が合わない。辞書は販売を開始する場や手段として使えない。"}, "sentence_index": 0, "correct_answer": "インターネット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "インターネットを手で持って、家まで運んだ。", "explanation": "インターネットは通信の仕組みで、手で持って運べる物として使うのは誤り。"}, {"text": "インターネットを冷蔵庫に入れておいたので、冷たくなった。", "explanation": "インターネットは物ではないので、冷蔵庫に入れて冷やすという使い方は誤り。"}, {"text": "インターネットに毎朝水をあげたら、花が咲いた。", "explanation": "インターネットは植物ではないので、水をあげて花が咲くという使い方は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35439, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インターネット", "is_correct": true, "explanation": "ネットのおかげで世界中の人と話せるという内容に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気で世界中の人と話せるようにはならない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが意味が合わない。地図は世界中の人と話す手段ではない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "形は合うが意味が合わない。洗濯機のおかげで世界の人と話せるとは言えない。"}], "explanations": {"インターネット": "ネットのおかげで世界中の人と話せるという内容に合う。", "天気": "形は合うが意味が合わない。天気で世界中の人と話せるようにはならない。", "地図": "形は合うが意味が合わない。地図は世界中の人と話す手段ではない。", "洗濯機": "形は合うが意味が合わない。洗濯機のおかげで世界の人と話せるとは言えない。"}, "sentence_index": 6, "correct_answer": "インターネット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "インターネットを鉛筆で書いて、先生に出した。", "explanation": "インターネットは通信の仕組みで、鉛筆で書いて提出できる物ではない。"}, {"text": "インターネットを着て、寒い外へ出た。", "explanation": "インターネットは衣服ではないので、着るという使い方は誤り。"}, {"text": "インターネットがおいしいので、おかわりをした。", "explanation": "インターネットは食べ物ではないので、おいしい・おかわりという使い方は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35439, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎晩、インターネットを歩いて映画を見ます。", "corrected_sentence": "毎晩、インターネットを使って映画を見ます。", "error_description": "「インターネットを歩く」は不自然。手段として「インターネットを使う」と言う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35439, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄はインターネットに買い物を楽しみました。", "corrected_sentence": "兄はインターネットで買い物を楽しみました。", "error_description": "買い物をする場・手段は「インターネットで」と言う。「に」は不適切。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35440, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「例える」は比べる相手に「に」を取る。「広い海に例えた」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「心を」に既に「を」があり、二つ目の「を」は重なって不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示し、「〜より例えた」とは言えない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、動詞「例えた」の前に置くと文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「例える」は比べる相手に「に」を取る。「広い海に例えた」の形になる。", "を": "「心を」に既に「を」があり、二つ目の「を」は重なって不自然になる。", "より": "「より」は比較の基準を示し、「〜より例えた」とは言えない。", "の": "「の」は名詞をつなぐ助詞で、動詞「例えた」の前に置くと文が成り立たない。"}, "error_tags": {"を": "二つ目の目的語の重なり", "より": "比較の基準", "の": "名詞つなぎ"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35440, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「に」は比べる先を示す。「天使の声に例えられる」の形になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「天使の声が例えられる」では比べる先にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示し、「〜より例えられる」とは言わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、動詞の前に置くと不自然になる。"}], "correct_answer": "に", "explanations": {"に": "「に」は比べる先を示す。「天使の声に例えられる」の形になる。", "が": "「が」は主語を示すので、「天使の声が例えられる」では比べる先にならない。", "より": "「より」は比較の基準を示し、「〜より例えられる」とは言わない。", "の": "「の」は名詞をつなぐ助詞で、動詞の前に置くと不自然になる。"}, "error_tags": {"が": "主語", "より": "比較の基準", "の": "名詞つなぎ"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35440, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かと何かをくらべて、同じように考えること。", "primary_collocate": null, "pronunciation": "たとえる", "ipa": "tatoeɾɯ", "syllable_count": 4, "sentences": [{"text": "人生を長い旅に例える人は多い。", "target_word": "例える", "complexity_tier": "T3", "furigana": "人生(じんせい)を長(なが)い旅(たび)に例(たと)える人(ひと)は多(おお)い。", "sentence_source": "generated"}, {"text": "作家は、人の心を広い海に例えた。", "target_word": "例えた", "complexity_tier": "T3", "furigana": "作家(さっか)は、人(ひと)の心(こころ)を広(ひろ)い海(うみ)に例(たと)えた。", "sentence_source": "generated"}, {"text": "先生は、時間をお金に例えて、むだづかいをしないように話した。", "target_word": "例えて", "complexity_tier": "T3", "furigana": "先生(せんせい)は、時間(じかん)をお金(かね)に例(たと)えて、むだづかいをしないように話(はな)した。", "sentence_source": "generated"}, {"text": "彼の走る姿を風に例えるのは、少し大げさだ。", "target_word": "例える", "complexity_tier": "T3", "furigana": "彼(かれ)の走(はし)る姿(すがた)を風(かぜ)に例(たと)えるのは、少(すこ)し大(おお)げさだ。", "sentence_source": "generated"}, {"text": "会社を船に例えるなら、社長は船長にあたる。", "target_word": "例える", "complexity_tier": "T3", "furigana": "会社(かいしゃ)を船(ふね)に例(たと)えるなら、社長(しゃちょう)は船長(せんちょう)にあたる。", "sentence_source": "generated"}, {"text": "祖母は、孫の笑顔を春の日ざしに例えた。", "target_word": "例えた", "complexity_tier": "T3", "furigana": "祖母(そぼ)は、孫(まご)の笑顔(えがお)を春(はる)の日(ひ)ざしに例(たと)えた。", "sentence_source": "generated"}, {"text": "人間の脳をコンピューターに例える研究者もいる。", "target_word": "例える", "complexity_tier": "T3", "furigana": "人間(にんげん)の脳(のう)をコンピューターに例(たと)える研究者(けんきゅうしゃ)もいる。", "sentence_source": "generated"}, {"text": "彼女の歌声は、よく天使の声に例えられる。", "target_word": "例えられる", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の歌声(うたごえ)は、よく天使(てんし)の声(こえ)に例(たと)えられる。", "sentence_source": "generated"}, {"text": "恋を病気に例えた詩は、昔から数多く残っている。", "target_word": "例えた", "complexity_tier": "T3", "furigana": "恋(こい)を病気(びょうき)に例(たと)えた詩(し)は、昔(むかし)から数多(かずおお)く残(のこ)っている。", "sentence_source": "generated"}, {"text": "結婚生活を山登りに例えて、二人は笑った。", "target_word": "例えて", "complexity_tier": "T3", "furigana": "結婚生活(けっこんせいかつ)を山登(やまのぼ)りに例(たと)えて、二人(ふたり)は笑(わら)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "例える", "label": "終止形"}, {"form": "例えた", "label": "た形"}, {"form": "例えて", "label": "て形"}, {"form": "例えない", "label": "否定形"}, {"form": "例えれば", "label": "仮定形"}, {"form": "例えよう", "label": "意志形"}, {"form": "例えられる", "label": "受身形"}], "register": "中立（普通体）", "sense_fingerprint": "ある物事を別の物事と同じようなものとして見なし、くらべて言い表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35440, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "例える", "is_correct": true, "explanation": "終止形で、「例える人」と名詞を修飾でき、「人は多い」と文がつながる。"}, {"text": "例えれば", "is_correct": false, "explanation": "仮定形なので「例えれば人は多い」と続かず、名詞を修飾できない。"}, {"text": "例えよう", "is_correct": false, "explanation": "意志形は「例えよう人」の形で名詞を修飾できず、文が成り立たない。"}, {"text": "例えたら", "is_correct": false, "explanation": "たら形は条件節になり、後ろの名詞「人」を修飾できない。"}], "explanations": {"例える": "終止形で、「例える人」と名詞を修飾でき、「人は多い」と文がつながる。", "例えれば": "仮定形なので「例えれば人は多い」と続かず、名詞を修飾できない。", "例えよう": "意志形は「例えよう人」の形で名詞を修飾できず、文が成り立たない。", "例えたら": "たら形は条件節になり、後ろの名詞「人」を修飾できない。"}, "sentence_index": 0, "correct_answer": "例える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店の入り口の扉を例えて、そっと閉めた。", "explanation": "ここは〈閉める〉の意味。扉を閉める動作で、たとえ話をする例えるとは意味が違う。"}, {"text": "先生は説明のために、具体的な例を三つ例えた。", "explanation": "ここは〈例を挙げる〉の意味。例えるはたとえとして別の物に置き換える語で、具体例を並べて示す場面では使わない。"}, {"text": "彼は記憶を例えて、昔の家を探した。", "explanation": "ここは〈たどる〉の意味。記憶を順にさかのぼる動作で、例える（別の物にたとえる）とは意味が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35440, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "例える", "is_correct": true, "explanation": "終止形で、「例える研究者」と名詞を修飾し、文が成り立つ。"}, {"text": "例えます", "is_correct": false, "explanation": "丁寧形は名詞を修飾できず、「研究者」とつながらない。"}, {"text": "例えました", "is_correct": false, "explanation": "丁寧な過去形は普通体の名詞修飾には使えず、文が崩れる。"}, {"text": "例えなくて", "is_correct": false, "explanation": "て形の否定は文を途中で切るため、後ろの名詞と結びつかない。"}], "explanations": {"例える": "終止形で、「例える研究者」と名詞を修飾し、文が成り立つ。", "例えます": "丁寧形は名詞を修飾できず、「研究者」とつながらない。", "例えました": "丁寧な過去形は普通体の名詞修飾には使えず、文が崩れる。", "例えなくて": "て形の否定は文を途中で切るため、後ろの名詞と結びつかない。"}, "sentence_index": 6, "correct_answer": "例える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの製品の箱を例えて、中身を確かめた。", "explanation": "ここは〈開ける〉の意味。箱を開けて中身を見る動作で、例えるとは意味が違う。"}, {"text": "本の一節を例えて、レポートに書いた。", "explanation": "ここは〈引用する〉の意味。例えるは別の物に置き換えて説明する語で、文章をそのまま示す場面では使わない。"}, {"text": "お手本の文字を例えて、何度も練習した。", "explanation": "ここは〈なぞる〉の意味。線に沿ってたどる動作で、例える（たとえる）とは意味が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35440, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は仕事の苦労を登山に例えるた。", "corrected_sentence": "彼は仕事の苦労を登山に例えた。", "error_description": "「例える」の過去形は「例えた」。「例えるた」は活用の誤りで、「る」は不要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "例えた", "is_correct": true, "explanation": "た形で、過去に比べたという出来事を表し、文が完結する。"}, {"text": "例えて", "is_correct": false, "explanation": "て形は文を途中で止める形で、この文の述語にならない。"}, {"text": "例えれば", "is_correct": false, "explanation": "仮定形は条件で止まり、文が完結しない。"}, {"text": "例えたり", "is_correct": false, "explanation": "たり形は「〜たり〜たり」と並べる形で、一文の述語にはならない。"}], "correct_form": "例えた", "base_form": "例える", "form_label": "た形", "sentence_index": 1, "explanations": {"例えた": "た形で、過去に比べたという出来事を表し、文が完結する。", "例えて": "て形は文を途中で止める形で、この文の述語にならない。", "例えれば": "仮定形は条件で止まり、文が完結しない。", "例えたり": "たり形は「〜たり〜たり」と並べる形で、一文の述語にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35440, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は若い頃の夢を、遠い星に例えて。", "corrected_sentence": "彼女は若い頃の夢を、遠い星に例えた。", "error_description": "文末の「例えて」は中止形で文が終わらない。過去として言い切るには「例えた」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "例えられる", "is_correct": true, "explanation": "受身形。「AをBに例えられる」の形で、歌声が天使の声にたとえられる意味になる。"}, {"text": "例えなくて", "is_correct": false, "explanation": "て形の否定は文を途中で切り、述語として働かない。"}, {"text": "例えます", "is_correct": false, "explanation": "丁寧形は普通体の文の述語として合わない。"}, {"text": "例えず", "is_correct": false, "explanation": "否定の中止形は文末にならず、この文の述語にならない。"}], "correct_form": "例えられる", "base_form": "例える", "form_label": "受身形", "sentence_index": 7, "explanations": {"例えられる": "受身形。「AをBに例えられる」の形で、歌声が天使の声にたとえられる意味になる。", "例えなくて": "て形の否定は文を途中で切り、述語として働かない。", "例えます": "丁寧形は普通体の文の述語として合わない。", "例えず": "否定の中止形は文末にならず、この文の述語にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35441, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「例える」は比べる相手に「に」を取る。「水道の水に例えると」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「流れを」に既に「を」があり、二つ目の「を」は重なって不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、動詞「例える」の前に置くと文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示し、「〜より例える」とは言わない。"}], "correct_answer": "に", "explanations": {"に": "「例える」は比べる相手に「に」を取る。「水道の水に例えると」の形になる。", "を": "「流れを」に既に「を」があり、二つ目の「を」は重なって不自然になる。", "の": "「の」は名詞をつなぐ助詞で、動詞「例える」の前に置くと文が成り立たない。", "より": "「より」は比較の基準を示し、「〜より例える」とは言わない。"}, "error_tags": {"を": "二つ目の目的語の重なり", "の": "名詞つなぎ", "より": "比較の基準"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35441, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「に」は比べる先を示す。「野球に例えて」の形になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「野球が例えて」では比べる先にならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は例える対象だけを示し、比べる先の「に」がなければ文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、動詞「例えて」の前に置くと不自然になる。"}], "correct_answer": "に", "explanations": {"に": "「に」は比べる先を示す。「野球に例えて」の形になる。", "が": "「が」は主語を示すので、「野球が例えて」では比べる先にならない。", "を": "「を」は例える対象だけを示し、比べる先の「に」がなければ文が成り立たない。", "の": "「の」は名詞をつなぐ助詞で、動詞「例えて」の前に置くと不自然になる。"}, "error_tags": {"が": "主語", "を": "比べる先がない", "の": "名詞つなぎ"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35441, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物事を別の物事に置き換えて考えたり、たとえ話をしたりすること。比喩的な表現を用いて、理解しやすくすること。", "primary_collocate": null, "pronunciation": "たとえる", "ipa": "tatoeɾɯ", "syllable_count": 4, "sentences": [{"text": "先生は、むずかしい仕組みを身近な物に例えて説明してくれた。", "target_word": "例えて", "complexity_tier": "T3", "furigana": "先生(せんせい)は、むずかしい仕組(しく)みを身近(みぢか)な物(もの)に例(たと)えて説明(せつめい)してくれた。", "sentence_source": "generated"}, {"text": "電気の流れを水道の水に例えると、子どもでもわかりやすい。", "target_word": "例える", "complexity_tier": "T3", "furigana": "電気(でんき)の流(なが)れを水道(すいどう)の水(みず)に例(たと)えると、子(こ)どもでもわかりやすい。", "sentence_source": "generated"}, {"text": "初めての人にもわかるように、ネットの仕組みを郵便に例えて話した。", "target_word": "例えて", "complexity_tier": "T3", "furigana": "初(はじ)めての人(ひと)にもわかるように、ネットの仕組(しく)みを郵便(ゆうびん)に例(たと)えて話(はな)した。", "sentence_source": "generated"}, {"text": "医者は、血管を道路に例えて、病気の説明をした。", "target_word": "例えて", "complexity_tier": "T3", "furigana": "医者(いしゃ)は、血管(けっかん)を道路(どうろ)に例(たと)えて、病気(びょうき)の説明(せつめい)をした。", "sentence_source": "generated"}, {"text": "銀行の利子の考え方を、植物の成長に例えて教えてくれた。", "target_word": "例えて", "complexity_tier": "T3", "furigana": "銀行(ぎんこう)の利子(りし)の考(かんが)え方(かた)を、植物(しょくぶつ)の成長(せいちょう)に例(たと)えて教(おし)えてくれた。", "sentence_source": "generated"}, {"text": "部長は仕事の流れを料理に例えて、新人に順番を説明した。", "target_word": "例えて", "complexity_tier": "T3", "furigana": "部長(ぶちょう)は仕事(しごと)の流(なが)れを料理(りょうり)に例(たと)えて、新人(しんじん)に順番(じゅんばん)を説明(せつめい)した。", "sentence_source": "generated"}, {"text": "むずかしい数学の考え方を坂道に例えて話すと、みんなうなずいた。", "target_word": "例えて", "complexity_tier": "T3", "furigana": "むずかしい数学(すうがく)の考(かんが)え方(かた)を坂道(さかみち)に例(たと)えて話(はな)すと、みんなうなずいた。", "sentence_source": "generated"}, {"text": "父は何でも野球に例えて話すので、野球好きの弟にはとてもわかりやすい。", "target_word": "例えて", "complexity_tier": "T4", "furigana": "父(ちち)は何(なん)でも野球(やきゅう)に例(たと)えて話(はな)すので、野球好(やきゅうず)きの弟(おとうと)にはとてもわかりやすい。", "sentence_source": "generated"}, {"text": "細胞の働きを工場に例えて説明すると、授業が楽しくなった。", "target_word": "例えて", "complexity_tier": "T3", "furigana": "細胞(さいぼう)の働(はたら)きを工場(こうじょう)に例(たと)えて説明(せつめい)すると、授業(じゅぎょう)が楽(たの)しくなった。", "sentence_source": "generated"}, {"text": "もっとわかりやすく例えてください、と生徒は先生に頼んだ。", "target_word": "例えて", "complexity_tier": "T3", "furigana": "もっとわかりやすく例(たと)えてください、と生徒(せいと)は先生(せんせい)に頼(たの)んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "例える", "label": "終止形"}, {"form": "例えた", "label": "た形"}, {"form": "例えて", "label": "て形"}, {"form": "例えない", "label": "否定形"}, {"form": "例えれば", "label": "仮定形"}, {"form": "例えよう", "label": "意志形"}, {"form": "例えられる", "label": "受身形"}], "register": "中立（普通体）", "sense_fingerprint": "身近な物事に置き換えたたとえ話で、相手に分かりやすく説明する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93788fa0-f2a6-402a-8dac-82f8c6817f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35441, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "例えて", "is_correct": true, "explanation": "て形で、「身近な物に例えて説明した」と続き、文が成り立つ。"}, {"text": "例えれば", "is_correct": false, "explanation": "仮定形は条件で止まり、「説明してくれた」とつながらない。"}, {"text": "例えよう", "is_correct": false, "explanation": "意志形は「例えよう説明」と名詞を修飾できず、文が崩れる。"}, {"text": "例えたら", "is_correct": false, "explanation": "たら形は条件節になり、「説明してくれた」の前に置けない。"}], "explanations": {"例えて": "て形で、「身近な物に例えて説明した」と続き、文が成り立つ。", "例えれば": "仮定形は条件で止まり、「説明してくれた」とつながらない。", "例えよう": "意志形は「例えよう説明」と名詞を修飾できず、文が崩れる。", "例えたら": "たら形は条件節になり、「説明してくれた」の前に置けない。"}, "sentence_index": 0, "correct_answer": "例えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医者は、薬の箱を例えて、棚に戻した。", "explanation": "ここは〈しまう〉の意味。箱を棚に戻す動作で、たとえ話をする例えるとは意味が違う。"}, {"text": "医者は、病気の注意点を三つ例えた。", "explanation": "ここは〈挙げる〉の意味。「例を挙げる」は具体例を示すことで、注意点を並べる場面に例えるは合わない。"}, {"text": "医者は、患者の数を例えて、毎日記録した。", "explanation": "ここは〈数える〉の意味。人数を数える場面で、例える（たとえる）は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35441, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "例えて", "is_correct": true, "explanation": "て形で、「坂道に例えて話すと」と続き、文が成り立つ。"}, {"text": "例えます", "is_correct": false, "explanation": "丁寧形は「坂道に例えます話す」と続かず、文が崩れる。"}, {"text": "例えました", "is_correct": false, "explanation": "丁寧な過去形は「話す」の前に置けず、文が崩れる。"}, {"text": "例えません", "is_correct": false, "explanation": "丁寧な否定形は「話す」の前に置けず、文がつながらない。"}], "explanations": {"例えて": "て形で、「坂道に例えて話すと」と続き、文が成り立つ。", "例えます": "丁寧形は「坂道に例えます話す」と続かず、文が崩れる。", "例えました": "丁寧な過去形は「話す」の前に置けず、文が崩れる。", "例えません": "丁寧な否定形は「話す」の前に置けず、文がつながらない。"}, "sentence_index": 6, "correct_answer": "例えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの地域の地図を例えて、道を調べた。", "explanation": "ここは〈広げて見る〉の意味。地図を広げて道を探す動作で、たとえ話をする例えるとは意味が違う。"}, {"text": "新聞の記事を例えて、レポートに書いた。", "explanation": "ここは〈引用する〉の意味。例えるは別の物に置き換える語で、記事の文章を示す場面では使わない。"}, {"text": "母は朝、窓を例えてから出かけた。", "explanation": "ここは〈拭く〉の意味。窓をふく動作で、例える（たとえる）とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35441, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店長は会社の仕組みを船に例えるて話した。", "corrected_sentence": "店長は会社の仕組みを船に例えて話した。", "error_description": "て形は「例えて」が正しい。「例えるて」は活用の誤りで、「る」は不要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "例える", "is_correct": true, "explanation": "終止形（連体形と同形）。「例えると」の条件の形で、後ろの文につながる。"}, {"text": "例えて", "is_correct": false, "explanation": "て形は「と」に続かず、文が途中で切れる。"}, {"text": "例えた", "is_correct": false, "explanation": "た形は「例えたと」と続かず、条件の「と」の前に置けない。"}, {"text": "例えよう", "is_correct": false, "explanation": "意志形は「例えようと」で意図を表し、「わかりやすい」と続かない。"}], "correct_form": "例える", "base_form": "例える", "form_label": "終止形", "sentence_index": 1, "explanations": {"例える": "終止形（連体形と同形）。「例えると」の条件の形で、後ろの文につながる。", "例えて": "て形は「と」に続かず、文が途中で切れる。", "例えた": "た形は「例えたと」と続かず、条件の「と」の前に置けない。", "例えよう": "意志形は「例えようと」で意図を表し、「わかりやすい」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35441, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は家計のやりくりを、お財布の中身が例えた。", "corrected_sentence": "母は家計のやりくりを、お財布の中身に例えた。", "error_description": "「例える」が比べる先に取るのは「に」。「が」は主語を示すので「中身が例えた」は誤り（正しくは「中身に」）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "例えて", "is_correct": true, "explanation": "て形で、「野球に例えて話す」と続き、文が成り立つ。"}, {"text": "例える", "is_correct": false, "explanation": "終止形は「例える話す」と続かず、文の流れが崩れる。"}, {"text": "例えない", "is_correct": false, "explanation": "否定形は「話す」とつながらず、文が成り立たない。"}, {"text": "例えられる", "is_correct": false, "explanation": "受身形では「野球に例えられる話す」と続かず、動詞の関係が合わない。"}], "correct_form": "例えて", "base_form": "例える", "form_label": "て形", "sentence_index": 7, "explanations": {"例えて": "て形で、「野球に例えて話す」と続き、文が成り立つ。", "例える": "終止形は「例える話す」と続かず、文の流れが崩れる。", "例えない": "否定形は「話す」とつながらず、文が成り立たない。", "例えられる": "受身形では「野球に例えられる話す」と続かず、動詞の関係が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e589b8e-9cc9-489a-8888-642aa7b09f4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35442, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『人間の言葉』で、所属・内容を示す『の』が正しい。"}, {"text": "で", "is_correct": false, "explanation": "『人間で言葉』では手段・場所の関係になり、『言葉を理解できない』と続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』では『人間へ言葉』となり、名詞どうしのつながりが成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "『人間を言葉を』と目的語が二つ並び、文の構造が崩れる。"}], "correct_answer": "の", "explanations": {"の": "『人間の言葉』で、所属・内容を示す『の』が正しい。", "で": "『人間で言葉』では手段・場所の関係になり、『言葉を理解できない』と続かない。", "へ": "方向を示す『へ』では『人間へ言葉』となり、名詞どうしのつながりが成り立たない。", "を": "『人間を言葉を』と目的語が二つ並び、文の構造が崩れる。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35442, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35442, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "にんげんは、ひとのことです。", "primary_collocate": null, "pronunciation": "にんげん", "ipa": "ɲiŋɡeɴ", "syllable_count": 4, "sentences": [{"text": "人間は道具を使って、少しずつ生活を便利にしてきた。", "target_word": "人間", "complexity_tier": "T3", "furigana": "人間[にんげん]は道具[どうぐ]を使[つか]って、少[すこ]しずつ生活[せいかつ]を便利[べんり]にしてきた。", "sentence_source": "generated"}, {"text": "犬は人間の言葉を完全には理解できないが、声の調子はよくわかる。", "target_word": "人間", "complexity_tier": "T3", "furigana": "犬[いぬ]は人間[にんげん]の言葉[ことば]を完全[かんぜん]には理解[りかい]できないが、声[こえ]の調子[ちょうし]はよくわかる。", "sentence_source": "generated"}, {"text": "人間はだれでも失敗するものだから、一度の失敗で落ち込みすぎることはない。", "target_word": "人間", "complexity_tier": "T3", "furigana": "人間[にんげん]はだれでも失敗[しっぱい]するものだから、一度[いちど]の失敗[しっぱい]で落[お]ち込[こ]みすぎることはない。", "sentence_source": "generated"}, {"text": "宇宙には、まだ人間が行ったことのない星がたくさんある。", "target_word": "人間", "complexity_tier": "T3", "furigana": "宇宙[うちゅう]には、まだ人間[にんげん]が行[い]ったことのない星[ほし]がたくさんある。", "sentence_source": "generated"}, {"text": "ロボットは疲れないが、人間は長く働くと疲れてしまう。", "target_word": "人間", "complexity_tier": "T3", "furigana": "ロボットは疲[つか]れないが、人間[にんげん]は長[なが]く働[はたら]くと疲[つか]れてしまう。", "sentence_source": "generated"}, {"text": "人間は水がなければ、数日しか生きられない。", "target_word": "人間", "complexity_tier": "T3", "furigana": "人間[にんげん]は水[みず]がなければ、数日[すうじつ]しか生[い]きられない。", "sentence_source": "generated"}, {"text": "この動物は人間をおそれず、すぐ近くまで寄ってくる。", "target_word": "人間", "complexity_tier": "T3", "furigana": "この動物[どうぶつ]は人間[にんげん]をおそれず、すぐ近[ちか]くまで寄[よ]ってくる。", "sentence_source": "generated"}, {"text": "彼は優しくて正直な人間なので、みんなに信頼されている。", "target_word": "人間", "complexity_tier": "T3", "furigana": "彼[かれ]は優[やさ]しくて正直[しょうじき]な人間[にんげん]なので、みんなに信頼[しんらい]されている。", "sentence_source": "generated"}, {"text": "人間と自然がうまく共に生きる方法を、この町は考えている。", "target_word": "人間", "complexity_tier": "T3", "furigana": "人間[にんげん]と自然[しぜん]がうまく共[とも]に生[い]きる方法[ほうほう]を、この町[まち]は考[かんが]えている。", "sentence_source": "generated"}, {"text": "人間の体の約六割は水でできていると言われる。", "target_word": "人間", "complexity_tier": "T3", "furigana": "人間[にんげん]の体[からだ]の約六割[やくろくわり]は水[みず]でできていると言[い]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人間", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "動物や機械に対する、ひと(人類・一人の人)としての人間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e5da86-1411-4fd5-9f5f-e54c321bb1e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35442, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人間", "is_correct": true, "explanation": "主語として、道具を使って生活を便利にしてきた主体に当たる。"}, {"text": "地震", "is_correct": false, "explanation": "地震は道具を使う主体にならず、生活を便利にしてきたという文の主語として成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は道具を使えず、生活を便利にしてきた主体にならないので、文が成り立たない。"}, {"text": "言葉", "is_correct": false, "explanation": "言葉は道具を使う主体ではなく、主語として置くと『言葉が生活を便利にしてきた』という意味になり不自然。"}], "explanations": {"人間": "主語として、道具を使って生活を便利にしてきた主体に当たる。", "地震": "地震は道具を使う主体にならず、生活を便利にしてきたという文の主語として成り立たない。", "天気": "天気は道具を使えず、生活を便利にしてきた主体にならないので、文が成り立たない。", "言葉": "言葉は道具を使う主体ではなく、主語として置くと『言葉が生活を便利にしてきた』という意味になり不自然。"}, "sentence_index": 0, "correct_answer": "人間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小説は人間の登場が多すぎて、誰が主人公かわからない。", "explanation": "ここは〈人物〉（作品に出てくる人）の意味。『登場人物』の『人物』に当たる語で、『人間』は人そのものを指すので、作品の登場人物は言い表せない。"}, {"text": "妹は部屋で人間の着せ替えを楽しんでいる。", "explanation": "ここは〈人形〉の意味。着せ替えて遊ぶものは『人形』と言い、『人間』は人そのものを指すので、おもちゃの意味では使わない。"}, {"text": "この国では、人間差別が今も一部に残っていると報告された。", "explanation": "ここは〈人種〉（肌の色などで分けた人の種類）の意味。『人種差別』の『人種』に当たる語で、『人間』は人類全体を指すので、この言い方は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35442, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人間", "is_correct": true, "explanation": "『おそれず』の対象となり、近づいてくる動物との関係が自然に成り立つ。"}, {"text": "宝石", "is_correct": false, "explanation": "宝石は動物がおそれたり寄ってきたりする対象ではないので、文が成り立たない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は動物が恐れるかどうかを問題にする対象にならず、意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は『おそれる』対象として不自然で、近づいてくるという文脈とも合わない。"}], "explanations": {"人間": "『おそれず』の対象となり、近づいてくる動物との関係が自然に成り立つ。", "宝石": "宝石は動物がおそれたり寄ってきたりする対象ではないので、文が成り立たない。", "教室": "教室は動物が恐れるかどうかを問題にする対象にならず、意味が通らない。", "季節": "季節は『おそれる』対象として不自然で、近づいてくるという文脈とも合わない。"}, "sentence_index": 6, "correct_answer": "人間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は押し入れから古い人間を出して、ひな段に飾った。", "explanation": "ここは〈人形〉の意味。『ひな人形を飾る』の『人形』に当たる語で、『人間』は人そのものを指すので、雛人形には使わない。"}, {"text": "工事は人間が足りず、来月まで延びることになった。", "explanation": "ここは〈人手（働き手）〉の意味。働く人の数を指す語で、『人間（人そのもの）』とは違う。"}, {"text": "店長は新しい人間を三人雇って、接客を任せた。", "explanation": "ここは〈社員・人員〉を数える感覚。『人間』は人数を数える語として使わないので、三人と組み合わせると不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35442, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人間を犬は、長い間よい関係を築いてきた。", "corrected_sentence": "人間と犬は、長い間よい関係を築いてきた。", "error_description": "『関係を築く』は相手を示す『と』で結ぶ。『を』にすると『人間を』が目的語になり、『犬は』との関係が崩れる。正しくは『人間と』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35442, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ロボットは人間を代わりに重い荷物を運ぶ。", "corrected_sentence": "ロボットは人間の代わりに重い荷物を運ぶ。", "error_description": "『代わり』の前は『の』で結ぶ。『を』にすると『人間を』が目的語になり、『代わりに』との関係が崩れる。正しくは『人間の』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35444, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『問題の認識がちがっていた』と、主語として認識のずれを述べる。"}, {"text": "を", "is_correct": false, "explanation": "『違う』は目的語を取らないので、『認識を違っていた』は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『違う』は『と』で比べる相手を示すので、『認識に違っていた』は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『問題の認識の違っていた』と続けると、名詞修飾が崩れ、述語が立たない。"}], "correct_answer": "が", "explanations": {"が": "『問題の認識がちがっていた』と、主語として認識のずれを述べる。", "を": "『違う』は目的語を取らないので、『認識を違っていた』は成り立たない。", "に": "『違う』は『と』で比べる相手を示すので、『認識に違っていた』は成り立たない。", "の": "『問題の認識の違っていた』と続けると、名詞修飾が崩れ、述語が立たない。"}, "error_tags": {"を": "目的語", "に": "方向・相手", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35444, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35444, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを知ったり、理解したりすること。", "primary_collocate": null, "pronunciation": "にんしき", "ipa": "ɲiɴɕiki", "syllable_count": 4, "sentences": [{"text": "事故の危険について、私たちは認識が甘かったと反省している。", "target_word": "認識", "complexity_tier": "T3", "furigana": "事故[じこ]の危険[きけん]について、私[わたし]たちは認識[にんしき]が甘[あま]かったと反省[はんせい]している。", "sentence_source": "generated"}, {"text": "母と私では問題の認識がちがっていたので、話が合わなかった。", "target_word": "認識", "complexity_tier": "T3", "furigana": "母[はは]と私[わたし]では問題[もんだい]の認識[にんしき]がちがっていたので、話[はなし]が合[あ]わなかった。", "sentence_source": "generated"}, {"text": "彼は自分の弱点を正しく認識しているから、練習に力を入れている。", "target_word": "認識", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の弱点[じゃくてん]を正[ただ]しく認識[にんしき]しているから、練習[れんしゅう]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "この写真を見て、事件への認識を改めた人も多い。", "target_word": "認識", "complexity_tier": "T3", "furigana": "この写真[しゃしん]を見[み]て、事件[じけん]への認識[にんしき]を改[あらた]めた人[ひと]も多[おお]い。", "sentence_source": "generated"}, {"text": "子どもは三歳ごろになると、鏡の中の姿を自分だと認識できるようになる。", "target_word": "認識", "complexity_tier": "T3", "furigana": "子[こ]どもは三歳[さんさい]ごろになると、鏡[かがみ]の中[なか]の姿[すがた]を自分[じぶん]だと認識[にんしき]できるようになる。", "sentence_source": "generated"}, {"text": "会議では、全員が同じ認識を持つことが大切だと言われた。", "target_word": "認識", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、全員[ぜんいん]が同[おな]じ認識[にんしき]を持[も]つことが大切[たいせつ]だと言[い]われた。", "sentence_source": "generated"}, {"text": "新しい機械は、人の顔を認識して自動でドアを開ける。", "target_word": "認識", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]は、人[ひと]の顔[かお]を認識[にんしき]して自動[じどう]でドアを開[あ]ける。", "sentence_source": "generated"}, {"text": "環境問題が深刻だという認識は、多くの国で広がっている。", "target_word": "認識", "complexity_tier": "T3", "furigana": "環境問題[かんきょうもんだい]が深刻[しんこく]だという認識[にんしき]は、多[おお]くの国[くに]で広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "私の認識では、会議は明日のはずだったが、実は今日だった。", "target_word": "認識", "complexity_tier": "T3", "furigana": "私[わたし]の認識[にんしき]では、会議[かいぎ]は明日[あした]のはずだったが、実[じつ]は今日[きょう]だった。", "sentence_source": "generated"}, {"text": "相手を知らなかったので、危険だという認識がなく、近づいてしまった。", "target_word": "認識", "complexity_tier": "T3", "furigana": "相手[あいて]を知[し]らなかったので、危険[きけん]だという認識[にんしき]がなく、近[ちか]づいてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "認識", "label": "基本形"}, {"form": "認識する", "label": "サ変動詞"}, {"form": "認識した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "物事を知り、その意味や状況を理解・判断すること。見方や理解の内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e5da86-1411-4fd5-9f5f-e54c321bb1e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35444, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "認識", "is_correct": true, "explanation": "『事故の危険について、私たちは認識が甘かった』と、理解の程度を述べる文に合う。"}, {"text": "味", "is_correct": false, "explanation": "『味が甘い』は味覚の意味で、『私たちは味が甘かった』では主語として意味が通らない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は『甘い』という評価の対象にならず、この文脈では成り立たない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は危険への理解の甘さを表す主語にならず、文が不自然になる。"}], "explanations": {"認識": "『事故の危険について、私たちは認識が甘かった』と、理解の程度を述べる文に合う。", "味": "『味が甘い』は味覚の意味で、『私たちは味が甘かった』では主語として意味が通らない。", "地図": "地図は『甘い』という評価の対象にならず、この文脈では成り立たない。", "天井": "天井は危険への理解の甘さを表す主語にならず、文が不自然になる。"}, "sentence_index": 0, "correct_answer": "認識"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "危険に認識を向けて、慎重に歩いた。", "explanation": "ここは〈注意〉（気をつける）の意味。『注意を向ける』の『注意』に当たる語で、『認識』は知る・理解する働きを指すので『向ける』とは組まない。"}, {"text": "業者に工事費の認識を頼んだ。", "explanation": "ここは〈見積もり〉（費用の額をあらかじめ算出すること）の意味。『見積もりを頼む』の『見積もり』に当たる語で、『認識』は知る働きを指すので工事費には使わない。"}, {"text": "役所で正式な認識を踏んで、書類を出した。", "explanation": "ここは〈手続き〉（決まった順序で進める事務）の意味。『手続きを踏む』の『手続き』に当たる語で、『認識』は知る働きを指すので『踏む』とは組まない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35444, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "認識", "is_correct": true, "explanation": "『人の顔を認識して、ドアを開ける』という機械の働きを表す語として自然。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は文章や言葉を別の言語にする行為で、顔に対して使うと意味が通らない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物を頼む行為で、顔を対象にすると文が成り立たない。"}, {"text": "抽選", "is_correct": false, "explanation": "抽選はくじで選ぶ行為で、顔を対象にして自動でドアを開ける文脈に合わない。"}], "explanations": {"認識": "『人の顔を認識して、ドアを開ける』という機械の働きを表す語として自然。", "翻訳": "翻訳は文章や言葉を別の言語にする行為で、顔に対して使うと意味が通らない。", "注文": "注文は品物を頼む行為で、顔を対象にすると文が成り立たない。", "抽選": "抽選はくじで選ぶ行為で、顔を対象にして自動でドアを開ける文脈に合わない。"}, "sentence_index": 6, "correct_answer": "認識"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故で頭を打った彼は、しばらく認識を失っていた。", "explanation": "ここは〈意識〉の意味。『意識を失う』の『意識』に当たる語で、『認識』は知る・理解する働きを指すので『失う』とは組まない。"}, {"text": "祖母は認識症と診断され、家族で介護を始めた。", "explanation": "ここは〈認知症〉（認知機能が衰える病気）の意味。病名の『認知症』に当たる語で、『認識』は知る働きを指すので、この病名には使わない。"}, {"text": "工事の認識を役所に申請した。", "explanation": "ここは〈認可〉（行政が許可すること）の意味。『認可を申請する』の『認可』に当たる語で、『認識』は知る・理解する働きを指すので申請には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35444, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は危険を正しく認識に、慎重に行動した。", "corrected_sentence": "彼は危険を正しく認識して、慎重に行動した。", "error_description": "サ変動詞『認識する』の連用形は『認識して』。『認識に』では動詞として働かず、文の述語にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35444, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "相手の気持ちが認識していれば、トラブルは避けられる。", "corrected_sentence": "相手の気持ちを認識していれば、トラブルは避けられる。", "error_description": "『認識する』の目的語は『を』で示す。『が』にすると『気持ちが認識する』となり、認識する主体と対象の関係が崩れる。正しくは『を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35446, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「このコーヒーは」の主題。「苦すぎて」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「苦すぎて」は形容詞で目的語を取らないので、「を」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「苦い」は「に」を取らないので、「コーヒーに苦すぎて」は文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・引用で、「苦すぎて」と結びつかないので文が崩れる。"}], "correct_answer": "は", "explanations": {"は": "「このコーヒーは」の主題。「苦すぎて」と自然につながる。", "を": "「苦すぎて」は形容詞で目的語を取らないので、「を」は不自然。", "に": "「苦い」は「に」を取らないので、「コーヒーに苦すぎて」は文が崩れる。", "と": "「と」は並列・引用で、「苦すぎて」と結びつかないので文が崩れる。"}, "error_tags": {"を": "目的語（形容詞と合わない）", "に": "方向・結果（形容詞と合わない）", "と": "並列・引用（文が崩れる）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35446, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「母がコーヒーを入れてくれた」の目的語を示す助詞。「入れてくれた」と自然につながる。"}, {"text": "が", "is_correct": false, "explanation": "「コーヒーが入れてくれた」は目的語の位置に主語を置くことになり、主語が二つ並んで不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・相手を示すが、「入れてくれた」と結びつかず文が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞修飾にしかならず、「入れてくれた」の目的語にならないので文が崩れる。"}], "correct_answer": "を", "explanations": {"を": "「母がコーヒーを入れてくれた」の目的語を示す助詞。「入れてくれた」と自然につながる。", "が": "「コーヒーが入れてくれた」は目的語の位置に主語を置くことになり、主語が二つ並んで不自然。", "と": "「と」は並列・相手を示すが、「入れてくれた」と結びつかず文が崩れる。", "の": "「の」は名詞修飾にしかならず、「入れてくれた」の目的語にならないので文が崩れる。"}, "error_tags": {"が": "目的語の位置（主語が重複）", "と": "並列・引用（文が崩れる）", "の": "連体修飾（目的語にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35446, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "のみもののなまえです。くろいみずで、にがいあじがします。", "primary_collocate": null, "pronunciation": "こーひー", "ipa": "koːçiː", "syllable_count": 4, "sentences": [{"text": "朝はいつも熱いコーヒーを一杯飲む。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "朝[あさ]はいつも熱[あつ]いコーヒーを一杯[いっぱい]飲[の]む。", "sentence_source": "generated"}, {"text": "このコーヒーは苦すぎて、砂糖を入れないと飲めない。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "このコーヒーは苦[にが]すぎて、砂糖[さとう]を入[い]れないと飲[の]めない。", "sentence_source": "generated"}, {"text": "父は仕事の前に、黒いコーヒーをゆっくり飲む。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]の前[まえ]に、黒[くろ]いコーヒーをゆっくり飲[の]む。", "sentence_source": "generated"}, {"text": "喫茶店で、ミルクの入ったコーヒーを注文した。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "喫茶店[きっさてん]で、ミルクの入[はい]ったコーヒーを注文[ちゅうもん]した。", "sentence_source": "generated"}, {"text": "コーヒーをこぼして、白いシャツが茶色になった。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "コーヒーをこぼして、白[しろ]いシャツが茶色[ちゃいろ]になった。", "sentence_source": "generated"}, {"text": "夜にコーヒーを飲むと、目がさえて眠れなくなる。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "夜[よる]にコーヒーを飲[の]むと、目[め]がさえて眠[ねむ]れなくなる。", "sentence_source": "generated"}, {"text": "寒い日は、温かいコーヒーがおいしく感じる。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、温[あたた]かいコーヒーがおいしく感[かん]じる。", "sentence_source": "generated"}, {"text": "母がコーヒーを入れてくれたので、みんなで飲んだ。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "母[はは]がコーヒーを入[い]れてくれたので、みんなで飲[の]んだ。", "sentence_source": "generated"}, {"text": "甘いお菓子には、苦いコーヒーがよく合う。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "甘[あま]いお菓子[かし]には、苦[にが]いコーヒーがよく合[あ]う。", "sentence_source": "generated"}, {"text": "友だちと話しながら、コーヒーを二杯も飲んでしまった。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "友[とも]だちと話[はな]しながら、コーヒーを二杯[にはい]も飲[の]んでしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コーヒー", "label": "基本形"}], "register": "中立", "sense_fingerprint": "黒くて苦い味の、毎日の飲み物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35446, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コーヒー", "is_correct": true, "explanation": "「朝はいつも熱い〜を一杯飲む」に入る、熱くして朝に飲む飲み物。文脈に合う唯一の語。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は飲み物ではなく、「熱い砂糖を一杯飲む」は成り立たない。"}, {"text": "氷", "is_correct": false, "explanation": "氷は熱くできず飲むものでもないので、文が成り立たない。"}, {"text": "醤油", "is_correct": false, "explanation": "醤油は飲み物ではないので、「一杯飲む」と続かない。"}], "explanations": {"コーヒー": "「朝はいつも熱い〜を一杯飲む」に入る、熱くして朝に飲む飲み物。文脈に合う唯一の語。", "砂糖": "砂糖は飲み物ではなく、「熱い砂糖を一杯飲む」は成り立たない。", "氷": "氷は熱くできず飲むものでもないので、文が成り立たない。", "醤油": "醤油は飲み物ではないので、「一杯飲む」と続かない。"}, "sentence_index": 0, "correct_answer": "コーヒー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このコーヒーの茶葉は、蒸らす時間で味が変わる。", "explanation": "ここは〈紅茶〉の意味。茶葉は紅茶の材料で、コーヒーには使わない語なので合わない。"}, {"text": "このコーヒーは、しょうゆで煮詰めて、甘辛い味に仕上げる。", "explanation": "ここは〈煮物のたれ〉の意味。しょうゆで煮詰めて味を整える調理は料理の話で、飲み物のコーヒーには当てはまらない。"}, {"text": "このコーヒーは豆腐とわかめの具が入っていて、体が温まる。", "explanation": "ここは〈味噌汁〉の意味。具は汁物の話で、コーヒーには具がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35446, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コーヒー", "is_correct": true, "explanation": "「温かい〜がおいしく感じる」に入る、寒い日に温めて飲む飲み物。文脈に合う唯一の語。"}, {"text": "角砂糖", "is_correct": false, "explanation": "角砂糖は温かくして飲む対象ではなく、「温かい角砂糖がおいしく感じる」は不自然。"}, {"text": "石けん", "is_correct": false, "explanation": "石けんは食べ物ではなく、おいしく感じる対象にはならない。"}, {"text": "雪", "is_correct": false, "explanation": "雪は冷たいもので、「温かい雪がおいしく感じる」は成り立たない。"}], "explanations": {"コーヒー": "「温かい〜がおいしく感じる」に入る、寒い日に温めて飲む飲み物。文脈に合う唯一の語。", "角砂糖": "角砂糖は温かくして飲む対象ではなく、「温かい角砂糖がおいしく感じる」は不自然。", "石けん": "石けんは食べ物ではなく、おいしく感じる対象にはならない。", "雪": "雪は冷たいもので、「温かい雪がおいしく感じる」は成り立たない。"}, "sentence_index": 6, "correct_answer": "コーヒー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このコーヒーで手を洗うと、肌がさっぱりする。", "explanation": "ここは〈石けん〉の意味。コーヒーは洗う道具ではないので、手を洗う使い方は合わない。"}, {"text": "このコーヒーは、麹を混ぜて三日寝かせると、香りが増す。", "explanation": "ここは〈甘酒〉の意味。麹を混ぜて寝かせる仕込みは甘酒の話で、コーヒーには当てはまらない。"}, {"text": "このコーヒーは朝しぼったばかりで、とても濃厚だ。", "explanation": "ここは〈牛乳〉の意味。しぼるのは乳の話で、コーヒーにはその工程がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35446, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜はコーヒーに飲まないようにしている。", "corrected_sentence": "夜はコーヒーを飲まないようにしている。", "error_description": "「飲む」は目的語に「を」を取る。「に」は誤りで、正しくは「コーヒーを飲まない」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35446, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は毎朝、コーヒーが淹れてくれる。", "corrected_sentence": "母は毎朝、コーヒーを淹れてくれる。", "error_description": "「淹れる」の目的語は「を」。「が」は誤りで、正しくは「コーヒーを淹れてくれる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35447, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35447, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「豆を細かくひくほど、コーヒーは濃く出る」の主題。「濃く出る」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「出る」は自動詞で目的語を取らないので、「コーヒーを濃く出る」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「コーヒーに濃く出る」は場所や相手を示す形として成り立たず、文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列・引用で、「濃く出る」と続かないので文が崩れる。"}], "correct_answer": "は", "explanations": {"は": "「豆を細かくひくほど、コーヒーは濃く出る」の主題。「濃く出る」と自然につながる。", "を": "「出る」は自動詞で目的語を取らないので、「コーヒーを濃く出る」は不自然。", "に": "「コーヒーに濃く出る」は場所や相手を示す形として成り立たず、文が崩れる。", "と": "「と」は並列・引用で、「濃く出る」と続かないので文が崩れる。"}, "error_tags": {"を": "目的語（出るは自動詞）", "に": "位置（出るの場所にならない）", "と": "並列（文が崩れる）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35447, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "コーヒーは、コーヒー豆から作られる飲み物で、苦みと香りが特徴です。", "primary_collocate": null, "pronunciation": "こーひー", "ipa": "koːçiː", "syllable_count": 4, "sentences": [{"text": "この店のコーヒーは、豆をひいた直後の香りがすばらしい。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "この店[みせ]のコーヒーは、豆[まめ]をひいた直後[ちょくご]の香[かお]りがすばらしい。", "sentence_source": "generated"}, {"text": "焙煎の仕方によって、コーヒーの苦みは大きく変わる。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "焙煎[ばいせん]の仕方[しかた]によって、コーヒーの苦[にが]みは大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "彼は産地ごとのコーヒーの味の違いを楽しんでいる。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "彼[かれ]は産地[さんち]ごとのコーヒーの味[あじ]の違[ちが]いを楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "会議の前に、同僚がいれたコーヒーの香りで気持ちが落ち着いた。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "会議[かいぎ]の前[まえ]に、同僚[どうりょう]がいれたコーヒーの香[かお]りで気持[きも]ちが落[お]ち着[つ]いた。", "sentence_source": "generated"}, {"text": "コーヒーの苦みが苦手な人には、牛乳を入れる飲み方がすすめられる。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "コーヒーの苦[にが]みが苦手[にがて]な人[ひと]には、牛乳[ぎゅうにゅう]を入[い]れる飲[の]み方[かた]がすすめられる。", "sentence_source": "generated"}, {"text": "ブラジルは、世界で最もコーヒーを多く生産する国の一つだ。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "ブラジルは、世界[せかい]で最[もっと]もコーヒーを多[おお]く生産[せいさん]する国[くに]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "祖父は毎朝、ひきたてのコーヒーの香りで目を覚ます。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "祖父[そふ]は毎朝[まいあさ]、ひきたてのコーヒーの香[かお]りで目[め]を覚[さ]ます。", "sentence_source": "generated"}, {"text": "豆を細かくひくほど、コーヒーは濃く出る。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "豆[まめ]を細[こま]かくひくほど、コーヒーは濃[こ]く出[で]る。", "sentence_source": "generated"}, {"text": "彼女は休日、ゆっくりとコーヒーを味わいながら本を読む。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は休日[きゅうじつ]、ゆっくりとコーヒーを味[あじ]わいながら本[ほん]を読[よ]む。", "sentence_source": "generated"}, {"text": "浅い焙煎のコーヒーは、酸味が強くて軽い味になる。", "target_word": "コーヒー", "complexity_tier": "T3", "furigana": "浅[あさ]い焙煎[ばいせん]のコーヒーは、酸味[さんみ]が強[つよ]くて軽[かる]い味[あじ]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "コーヒー", "label": "基本形"}], "register": "中立", "sense_fingerprint": "コーヒー豆から作る、苦みと香りが特徴の飲み物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f06b4680-4fa3-4940-ae92-665bd01dff19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35447, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "コーヒー", "is_correct": true, "explanation": "「この店の〜は、豆をひいた直後の香りがすばらしい」に入る、豆から作る飲み物。文脈に合う唯一の語。"}, {"text": "寿司", "is_correct": false, "explanation": "寿司は豆をひいて香りを楽しむものではないので、「この店の寿司」は文脈に合わない。"}, {"text": "漬物", "is_correct": false, "explanation": "漬物は豆をひく工程とは無関係で、「豆をひいた直後の香り」とは結びつかない。"}, {"text": "焼き鳥", "is_correct": false, "explanation": "焼き鳥は豆を扱う店の品物ではないので、香りの説明として文が成り立たない。"}], "explanations": {"コーヒー": "「この店の〜は、豆をひいた直後の香りがすばらしい」に入る、豆から作る飲み物。文脈に合う唯一の語。", "寿司": "寿司は豆をひいて香りを楽しむものではないので、「この店の寿司」は文脈に合わない。", "漬物": "漬物は豆をひく工程とは無関係で、「豆をひいた直後の香り」とは結びつかない。", "焼き鳥": "焼き鳥は豆を扱う店の品物ではないので、香りの説明として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "コーヒー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このコーヒーは、蒸した茶葉の香りが爽やかだ。", "explanation": "ここは〈緑茶〉の意味。茶葉を蒸す製法の話で、豆から作る飲み物には当てはまらない。"}, {"text": "このコーヒーは、乾燥させた花をお湯で煮出して飲む。", "explanation": "ここは〈ハーブティー〉の意味。花を煮出す飲み物で、コーヒーの材料は豆なので合わない。"}, {"text": "このコーヒーは、豆腐とわかめの具が入っていて体が温まる。", "explanation": "ここは〈味噌汁〉の意味。具は汁物の話で、コーヒーには具がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35447, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "コーヒー", "is_correct": true, "explanation": "「ひきたての〜の香りで目を覚ます」に入る、ひいて淹れる飲み物。文脈に合う唯一の語。"}, {"text": "氷", "is_correct": false, "explanation": "氷はひきたてるものではなく、香りで目を覚ますことにはならない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は香りで目を覚ます対象ではなく、「ひきたての石鹸の香り」は不自然。"}, {"text": "牛乳", "is_correct": false, "explanation": "牛乳はひいて香りを立てるものではないので、「ひきたての牛乳の香り」は意味が通らない。"}], "explanations": {"コーヒー": "「ひきたての〜の香りで目を覚ます」に入る、ひいて淹れる飲み物。文脈に合う唯一の語。", "氷": "氷はひきたてるものではなく、香りで目を覚ますことにはならない。", "石鹸": "石鹸は香りで目を覚ます対象ではなく、「ひきたての石鹸の香り」は不自然。", "牛乳": "牛乳はひいて香りを立てるものではないので、「ひきたての牛乳の香り」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "コーヒー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このコーヒーは、ぶどうの果皮と一緒に発酵させるので色が濃い。", "explanation": "ここは〈ワイン〉の意味。果皮と一緒に発酵させる製法はワインの話で、コーヒーには当てはまらない。"}, {"text": "このコーヒーは、塩と唐辛子に漬けて三日おくと、ぴりっと辛くなる。", "explanation": "ここは〈漬物〉の意味。塩と唐辛子に漬けて味を移す工程は漬物の話で、コーヒーには当てはまらない。"}, {"text": "このコーヒーは、お湯を注ぐだけで具が戻る。", "explanation": "ここは〈粉末スープ〉の意味。具が戻るのは乾燥具材の話で、コーヒーには具がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35447, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は毎朝、コーヒーが飲んでいる。", "corrected_sentence": "父は毎朝、コーヒーを飲んでいる。", "error_description": "「飲む」の目的語は「を」。「が」は誤りで、正しくは「コーヒーを飲んでいる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35447, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、砂糖をコーヒーを入れて飲む。", "corrected_sentence": "彼は、砂糖をコーヒーに入れて飲む。", "error_description": "「入れる」の相手は「に」で示す。「を」を重ねると目的語が二つ並び誤り（正しくは「コーヒーに入れて」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f14b35-1271-4760-b951-b1670908809b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35451, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「昨日は」と、「昨日」を文の主題として示すので入る。"}, {"text": "を", "is_correct": false, "explanation": "「昨日」を目的語にする文として不自然で、「昨日を朝から忙しくて」とは続かない。"}, {"text": "に", "is_correct": false, "explanation": "「昨日に」は主題として続かず、文の出だしとして不自然。"}, {"text": "で", "is_correct": false, "explanation": "「昨日」を場所や手段として扱えないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「昨日は」と、「昨日」を文の主題として示すので入る。", "を": "「昨日」を目的語にする文として不自然で、「昨日を朝から忙しくて」とは続かない。", "に": "「昨日に」は主題として続かず、文の出だしとして不自然。", "で": "「昨日」を場所や手段として扱えないので合わない。"}, "error_tags": {"を": "目的格（「昨日」を目的語にする文として不自然）", "に": "時点（「昨日に」は主題として続かない）", "で": "場所・手段（「昨日」を場所や手段として扱えない）"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明日", "is_correct": true, "explanation": "「今日の一日前」の反対で、「今日の一日後」を表すので対義語。"}, {"text": "今朝", "is_correct": false, "explanation": "今日の中の時間帯で、昨日の対義語ではない。"}, {"text": "先週", "is_correct": false, "explanation": "過去の期間で、昨日の反対の意味関係にはならない。"}, {"text": "週末", "is_correct": false, "explanation": "特定の期間で、昨日の対義語ではない。"}], "correct_answer": "明日", "explanations": {"明日": "「今日の一日前」の反対で、「今日の一日後」を表すので対義語。", "今朝": "今日の中の時間帯で、昨日の対義語ではない。", "先週": "過去の期間で、昨日の反対の意味関係にはならない。", "週末": "特定の期間で、昨日の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35451, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明日", "is_correct": true, "explanation": "「今日の一日前」の反対で、「今日の一日後」を表すので対義語。"}, {"text": "今日", "is_correct": false, "explanation": "昨日を数えるときの基準になる日で、反対語ではない。"}, {"text": "一昨日", "is_correct": false, "explanation": "昨日のさらに前の日で、昨日の反対の意味関係にはならない。"}, {"text": "来週", "is_correct": false, "explanation": "未来の期間で、昨日の対義語ではない。"}], "correct_answer": "明日", "explanations": {"明日": "「今日の一日前」の反対で、「今日の一日後」を表すので対義語。", "今日": "昨日を数えるときの基準になる日で、反対語ではない。", "一昨日": "昨日のさらに前の日で、昨日の反対の意味関係にはならない。", "来週": "未来の期間で、昨日の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35451, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "今日の前の日。過去のある一日を指します。", "primary_collocate": null, "pronunciation": "きのう", "ipa": "kinoː", "syllable_count": 3, "sentences": [{"text": "今日は水曜日ですから、昨日は火曜日でした。", "target_word": "昨日", "complexity_tier": "T3", "furigana": "今日[きょう]は水曜日[すいようび]ですから、昨日[きのう]は火曜日[かようび]でした。", "sentence_source": "generated"}, {"text": "昨日は朝から忙しくて、昼ご飯を食べる時間もなかった。", "target_word": "昨日", "complexity_tier": "T3", "furigana": "昨日[きのう]は朝[あさ]から忙[いそが]しくて、昼[ひる]ご飯[はん]を食[た]べる時間[じかん]もなかった。", "sentence_source": "generated"}, {"text": "昨日の会議で決まったことを、先生に伝えます。", "target_word": "昨日", "complexity_tier": "T3", "furigana": "昨日[きのう]の会議[かいぎ]で決[き]まったことを、先生[せんせい]に伝[つた]えます。", "sentence_source": "generated"}, {"text": "昨日は寒かったが、今日は暖かい。", "target_word": "昨日", "complexity_tier": "T3", "furigana": "昨日[きのう]は寒[さむ]かったが、今日[きょう]は暖[あたた]かい。", "sentence_source": "generated"}, {"text": "昨日の試合は、三対二で私たちが勝った。", "target_word": "昨日", "complexity_tier": "T3", "furigana": "昨日[きのう]の試合[しあい]は、三対[さんたい]二[に]で私[わたし]たちが勝[か]った。", "sentence_source": "generated"}, {"text": "昨日、図書館で借りた本をもう読み終えた。", "target_word": "昨日", "complexity_tier": "T3", "furigana": "昨日[きのう]、図書館[としょかん]で借[か]りた本[ほん]をもう読[よ]み終[お]えた。", "sentence_source": "generated"}, {"text": "妹は昨日、新しい自転車を買ってもらった。", "target_word": "昨日", "complexity_tier": "T3", "furigana": "妹[いもうと]は昨日[きのう]、新[あたら]しい自転車[じてんしゃ]を買[か]ってもらった。", "sentence_source": "generated"}, {"text": "昨日あった出来事を、日記に書いた。", "target_word": "昨日", "complexity_tier": "T3", "furigana": "昨日[きのう]あった出来事[できごと]を、日記[にっき]に書[か]いた。", "sentence_source": "generated"}, {"text": "昨日は休みだったので、公園を散歩した。", "target_word": "昨日", "complexity_tier": "T3", "furigana": "昨日[きのう]は休[やす]みだったので、公園[こうえん]を散歩[さんぽ]した。", "sentence_source": "generated"}, {"text": "昨日の天気予報では、今日は晴れると言っていた。", "target_word": "昨日", "complexity_tier": "T3", "furigana": "昨日[きのう]の天気[てんき]予報[よほう]では、今日[きょう]は晴[は]れると言[い]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "昨日", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "今日の前の日として指す過去の一日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd66e20-49ac-4d90-a0b0-2856280ca87e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35451, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨日", "is_correct": true, "explanation": "今日の前の日を指し、「火曜日でした」と過去の一日として続く。"}, {"text": "明日", "is_correct": false, "explanation": "未来の日なので、「火曜日でした」という過去の話と合わない。"}, {"text": "明後日", "is_correct": false, "explanation": "未来の日で、過去の曜日の文脈と合わない。"}, {"text": "来週", "is_correct": false, "explanation": "未来の期間で、「火曜日でした」という過去の話と合わない。"}], "explanations": {"昨日": "今日の前の日を指し、「火曜日でした」と過去の一日として続く。", "明日": "未来の日なので、「火曜日でした」という過去の話と合わない。", "明後日": "未来の日で、過去の曜日の文脈と合わない。", "来週": "未来の期間で、「火曜日でした」という過去の話と合わない。"}, "sentence_index": 0, "correct_answer": "昨日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大会の昨日は、なかなか眠れなかった。", "explanation": "ここは〈前夜〉（前の晩）の意味。昨日は今日を基準にした一日前なので、大会を基準にした言い方には合わない。"}, {"text": "昨日、次の試合で会いましょう。", "explanation": "ここは〈次回〉の意味。昨日は過去の日を指すので、これから先の約束には使えない。"}, {"text": "昨日の朝は、いつもパンを食べる。", "explanation": "ここは〈毎日〉の意味。特定の一日を指す昨日は、「いつも」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35451, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨日", "is_correct": true, "explanation": "今日の前の日を指し、「買ってもらった」と過去の出来事として続く。"}, {"text": "来月", "is_correct": false, "explanation": "未来の期間で、過去の出来事の文脈と合わない。"}, {"text": "再来週", "is_correct": false, "explanation": "未来の期間で、「買ってもらった」という過去の話と合わない。"}, {"text": "将来", "is_correct": false, "explanation": "未来を指す語で、過去の出来事とは合わない。"}], "explanations": {"昨日": "今日の前の日を指し、「買ってもらった」と過去の出来事として続く。", "来月": "未来の期間で、過去の出来事の文脈と合わない。", "再来週": "未来の期間で、「買ってもらった」という過去の話と合わない。", "将来": "未来を指す語で、過去の出来事とは合わない。"}, "sentence_index": 6, "correct_answer": "昨日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の約束は、いつだったか分からない。", "explanation": "ここは〈先日〉（はっきりしない最近の日）の意味。昨日は日付が決まっているので、「いつだったか分からない」とは合わない。"}, {"text": "授業の昨日に、小テストがあった。", "explanation": "「授業の昨日」は授業を基準にした言い方で、「昨日」は今日を基準にした前の日なので、授業の日程とは結びつかない。"}, {"text": "昨日の夏休みに、家族で旅行した。", "explanation": "「昨日」は直前の一日を指すので、「夏休み」の期間や一年前の出来事とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35451, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日で朝、駅で財布を落とした。", "corrected_sentence": "昨日の朝、駅で財布を落とした。", "error_description": "正しくは「昨日の朝」。「昨日」が「朝」を修飾するので「の」が必要で、「で」では文が続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35451, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日に、友だちに電話をかけた。", "corrected_sentence": "昨日、友だちに電話をかけた。", "error_description": "正しくは「昨日、」。「昨日」は特定の日を表す副詞なので、「に」はつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a6f964-f2a0-4fd2-8b98-0afe1beeede2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35456, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「泣き出した」の主語は赤ちゃんなので主格の「が」。"}, {"text": "を", "is_correct": false, "explanation": "「泣き出す」は目的語を取らない自動詞なので「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表すので、主語を示す位置には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、主語の位置には使えない。"}], "correct_answer": "が", "explanations": {"が": "正解。「泣き出した」の主語は赤ちゃんなので主格の「が」。", "を": "「泣き出す」は目的語を取らない自動詞なので「を」は合わない。", "で": "場所や手段を表すので、主語を示す位置には入らない。", "へ": "方向を表す助詞で、主語の位置には使えない。"}, "error_tags": {"を": "目的語の格（他動詞用）", "で": "場所・手段の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35456, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。文の主題として「赤ちゃんは」で文が成り立つ。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、「赤ちゃんの泣いて」と文の骨組みが続かない。"}, {"text": "に", "is_correct": false, "explanation": "「赤ちゃんに泣いて」では動作の主体が示せず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「赤ちゃんより泣いて」は意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "正解。文の主題として「赤ちゃんは」で文が成り立つ。", "の": "連体修飾の「の」で、「赤ちゃんの泣いて」と文の骨組みが続かない。", "に": "「赤ちゃんに泣いて」では動作の主体が示せず、文が成り立たない。", "より": "比較の助詞で、「赤ちゃんより泣いて」は意味が通らない。"}, "error_tags": {"の": "連体修飾の格", "に": "与格・到達点の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35456, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "うまれたばかりの、とてもちいさいこども。", "primary_collocate": null, "pronunciation": "あかちゃん", "ipa": "akat͡ɕaɴ", "syllable_count": 4, "sentences": [{"text": "赤ちゃんがベッドでぐっすり眠っています。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんがベッドでぐっすり眠[ねむ]っています。", "sentence_source": "generated"}, {"text": "赤ちゃんが急に泣き出したので、お母さんがだっこしました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが急[きゅう]に泣[な]き出[だ]したので、お母[かあ]さんがだっこしました。", "sentence_source": "generated"}, {"text": "隣の家に赤ちゃんが生まれました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]に赤[あか]ちゃんが生[う]まれました。", "sentence_source": "generated"}, {"text": "赤ちゃんの手はとても小さくてかわいいです。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの手[て]はとても小[ちい]さくてかわいいです。", "sentence_source": "generated"}, {"text": "赤ちゃんはミルクを飲むと、すぐに眠くなります。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんはミルクを飲[の]むと、すぐに眠[ねむ]くなります。", "sentence_source": "generated"}, {"text": "姉は赤ちゃんの世話をするために、早く帰りました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "姉[あね]は赤[あか]ちゃんの世話[せわ]をするために、早[はや]く帰[かえ]りました。", "sentence_source": "generated"}, {"text": "電車で赤ちゃんが笑っていて、みんなが笑顔になりました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "電車[でんしゃ]で赤[あか]ちゃんが笑[わら]っていて、みんなが笑顔[えがお]になりました。", "sentence_source": "generated"}, {"text": "赤ちゃんは泣いて、お母さんにおなかがすいたことを知らせます。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは泣[な]いて、お母[かあ]さんにおなかがすいたことを知[し]らせます。", "sentence_source": "generated"}, {"text": "病院で、生まれたばかりの赤ちゃんに会いました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "病院[びょういん]で、生[う]まれたばかりの赤[あか]ちゃんに会[あ]いました。", "sentence_source": "generated"}, {"text": "うちの赤ちゃんは夜中に何度も起きるので、母は寝不足です。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "うちの赤[あか]ちゃんは夜中[よなか]に何度[なんど]も起[お]きるので、母[はは]は寝不足[ねぶそく]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "赤ちゃん", "label": "基本形"}], "register": "neutral (everyday spoken)", "sense_fingerprint": "newborn or very young baby, everyday plain-explanation sense", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35456, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赤ちゃん", "is_correct": true, "explanation": "正解。「ベッドでぐっすり眠る」主語として文が成り立つ。"}, {"text": "台所", "is_correct": false, "explanation": "場所を表す名詞で、ベッドで眠る主語にはならない。"}, {"text": "郵便局", "is_correct": false, "explanation": "建物の名前で、ベッドで眠ることはできないので文に合わない。"}, {"text": "消防車", "is_correct": false, "explanation": "乗り物で、ベッドで眠る主語にはならないので文に合わない。"}], "explanations": {"赤ちゃん": "正解。「ベッドでぐっすり眠る」主語として文が成り立つ。", "台所": "場所を表す名詞で、ベッドで眠る主語にはならない。", "郵便局": "建物の名前で、ベッドで眠ることはできないので文に合わない。", "消防車": "乗り物で、ベッドで眠る主語にはならないので文に合わない。"}, "sentence_index": 0, "correct_answer": "赤ちゃん"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月小学校に入る赤ちゃんと、ランドセルを買いに行きました。", "explanation": "ここは〈子ども〉の意味。赤ちゃんは生まれて間もない乳児を指すので、小学生には使わない。"}, {"text": "幼稚園に通う赤ちゃんが、運動会でダンスをしました。", "explanation": "ここは〈幼児〉の意味。赤ちゃんは乳児を指すので、幼稚園児には使わない。"}, {"text": "教室で赤ちゃんたちが、先生の話を熱心に聞いています。", "explanation": "ここは〈生徒〉の意味。赤ちゃんは乳児なので、授業を受ける生徒には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35456, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赤ちゃん", "is_correct": true, "explanation": "正解。電車の中で笑っている人の主語として自然。"}, {"text": "教室", "is_correct": false, "explanation": "場所の名詞で、笑っている主語にはならないので文に合わない。"}, {"text": "飛行機", "is_correct": false, "explanation": "乗り物で、電車の中で笑うことはできないので文に合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、笑う主語にはならないので文に合わない。"}], "explanations": {"赤ちゃん": "正解。電車の中で笑っている人の主語として自然。", "教室": "場所の名詞で、笑っている主語にはならないので文に合わない。", "飛行機": "乗り物で、電車の中で笑うことはできないので文に合わない。", "冷蔵庫": "家電で、笑う主語にはならないので文に合わない。"}, "sentence_index": 6, "correct_answer": "赤ちゃん"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学の赤ちゃんは、夜遅くまで図書館で勉強します。", "explanation": "ここは〈学生〉の意味。赤ちゃんは乳児を指すので、大学生には使わない。"}, {"text": "赤ちゃんは、毎朝大型トラックを運転して配達します。", "explanation": "ここは〈運転手〉の意味。赤ちゃんは乳児を指すので、トラックを運転して配達する大人には使わない。"}, {"text": "赤ちゃんは、毎朝部活の準備をします。", "explanation": "ここは〈高校生〉の意味。赤ちゃんは乳児なので、部活をする高校生には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35456, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "赤ちゃんを夜中に何度も起きるので、母は寝不足です。", "corrected_sentence": "赤ちゃんが夜中に何度も起きるので、母は寝不足です。", "error_description": "主語の「赤ちゃん」には「が」が必要。「を」だと目的語になり、自動詞「起きる」と合わない。正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35456, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公園で赤ちゃんが笑いていて、みんなが笑顔になりました。", "corrected_sentence": "公園で赤ちゃんが笑っていて、みんなが笑顔になりました。", "error_description": "「笑う」のて形は「笑って」「笑っていて」。「笑いて」は誤った活用形なので、正しくは「笑っていて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35457, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「赤ちゃんの体重」と所属を示す連体修飾の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「体重を」の後に「を」が重なり、「赤ちゃんを体重を測って」は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「赤ちゃんに体重」では所属が示せず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すので、「赤ちゃんで体重」とは続かない。"}], "correct_answer": "の", "explanations": {"の": "正解。「赤ちゃんの体重」と所属を示す連体修飾の「の」。", "を": "「体重を」の後に「を」が重なり、「赤ちゃんを体重を測って」は不自然。", "に": "「赤ちゃんに体重」では所属が示せず、文が成り立たない。", "で": "場所や手段を示すので、「赤ちゃんで体重」とは続かない。"}, "error_tags": {"を": "目的語の格（二重の「を」）", "に": "与格・到達点の格", "で": "場所・手段の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35457, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。文の主題として「赤ちゃんは」で、「敏感なので」と続く。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「赤ちゃんへ敏感」とは続かない。"}, {"text": "を", "is_correct": false, "explanation": "「敏感」は「に」を取る状態語で、「赤ちゃんを敏感なので」は目的語の形が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す助詞で、「赤ちゃんから敏感」の形では文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "正解。文の主題として「赤ちゃんは」で、「敏感なので」と続く。", "へ": "方向を表す助詞で、「赤ちゃんへ敏感」とは続かない。", "を": "「敏感」は「に」を取る状態語で、「赤ちゃんを敏感なので」は目的語の形が成り立たない。", "から": "起点を表す助詞で、「赤ちゃんから敏感」の形では文が成り立たない。"}, "error_tags": {"へ": "方向の格", "から": "起点の格", "を": "目的語の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35457, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生まれて間もない、非常に幼い子ども。", "primary_collocate": null, "pronunciation": "あかちゃん", "ipa": "akat͡ɕaɴ", "syllable_count": 4, "sentences": [{"text": "赤ちゃんは生後三か月になり、首がすわってきました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは生後[せいご]三[さん]か月[げつ]になり、首[くび]がすわってきました。", "sentence_source": "generated"}, {"text": "医者は赤ちゃんの体重を測って、順調だと言いました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "医者[いしゃ]は赤[あか]ちゃんの体重[たいじゅう]を測[はか]って、順調[じゅんちょう]だと言[い]いました。", "sentence_source": "generated"}, {"text": "赤ちゃんが泣くのは、おなかがすいたり眠かったりするからです。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが泣[な]くのは、おなかがすいたり眠[ねむ]かったりするからです。", "sentence_source": "generated"}, {"text": "友達の赤ちゃんを初めて抱かせてもらいました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "友達[ともだち]の赤[あか]ちゃんを初[はじ]めて抱[だ]かせてもらいました。", "sentence_source": "generated"}, {"text": "赤ちゃんの声が聞こえて、私は目を覚ましました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの声[こえ]が聞[き]こえて、私[わたし]は目[め]を覚[さ]ましました。", "sentence_source": "generated"}, {"text": "生まれたばかりの赤ちゃんは、一日の大部分を眠って過ごします。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "生[う]まれたばかりの赤[あか]ちゃんは、一日[いちにち]の大部分[だいぶぶん]を眠[ねむ]って過[す]ごします。", "sentence_source": "generated"}, {"text": "公園で、赤ちゃんを乗せたベビーカーを押す人を見ました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "公園[こうえん]で、赤[あか]ちゃんを乗[の]せたベビーカーを押[お]す人[ひと]を見[み]ました。", "sentence_source": "generated"}, {"text": "赤ちゃんは周りの音にとても敏感なので、静かにしてください。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは周[まわ]りの音[おと]にとても敏感[びんかん]なので、静[しず]かにしてください。", "sentence_source": "generated"}, {"text": "赤ちゃんがお母さんの顔を見て、にっこり笑いました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんがお母[かあ]さんの顔[かお]を見[み]て、にっこり笑[わら]いました。", "sentence_source": "generated"}, {"text": "兄に赤ちゃんが生まれて、私は叔母になりました。", "target_word": "赤ちゃん", "complexity_tier": "T3", "furigana": "兄[あに]に赤[あか]ちゃんが生[う]まれて、私[わたし]は叔母[おば]になりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "赤ちゃん", "label": "基本形"}], "register": "neutral (slightly formal explanatory)", "sense_fingerprint": "infant shortly after birth, dictionary-style sense focusing on very young age", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 眠かっ (Zipf 2.26)']::text[], '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35457, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赤ちゃん", "is_correct": true, "explanation": "正解。生後三か月の子どもが主語になり、首がすわる話と合う。"}, {"text": "台所", "is_correct": false, "explanation": "場所の名詞で、生後三か月になることはないので文に合わない。"}, {"text": "郵便局", "is_correct": false, "explanation": "建物の名前で、月齢を重ねる主語にはならないので文に合わない。"}, {"text": "教室", "is_correct": false, "explanation": "場所の名詞で、生後三か月になる主語にはならないので文に合わない。"}], "explanations": {"赤ちゃん": "正解。生後三か月の子どもが主語になり、首がすわる話と合う。", "台所": "場所の名詞で、生後三か月になることはないので文に合わない。", "郵便局": "建物の名前で、月齢を重ねる主語にはならないので文に合わない。", "教室": "場所の名詞で、生後三か月になる主語にはならないので文に合わない。"}, "sentence_index": 0, "correct_answer": "赤ちゃん"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "幼稚園に通う赤ちゃんが、お遊戯の練習をしています。", "explanation": "ここは〈幼児〉の意味。赤ちゃんは乳児を指すので、幼稚園児には使わない。"}, {"text": "赤ちゃんが、校庭でサッカーの練習をしています。", "explanation": "ここは〈小学生〉の意味。赤ちゃんは乳児なので、校庭で練習する小学生には使わない。"}, {"text": "赤ちゃんは、部活で毎日走っています。", "explanation": "ここは〈中学生〉の意味。赤ちゃんは乳児なので、部活で走る中学生には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35457, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赤ちゃん", "is_correct": true, "explanation": "正解。ベビーカーに乗せる対象として自然。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、ベビーカーに乗せることはないので文に合わない。"}, {"text": "飛行機", "is_correct": false, "explanation": "乗り物で、ベビーカーに乗せる対象にはならないので文に合わない。"}, {"text": "消防車", "is_correct": false, "explanation": "乗り物で、ベビーカーに乗せる対象にはならないので文に合わない。"}], "explanations": {"赤ちゃん": "正解。ベビーカーに乗せる対象として自然。", "冷蔵庫": "家電で、ベビーカーに乗せることはないので文に合わない。", "飛行機": "乗り物で、ベビーカーに乗せる対象にはならないので文に合わない。", "消防車": "乗り物で、ベビーカーに乗せる対象にはならないので文に合わない。"}, "sentence_index": 6, "correct_answer": "赤ちゃん"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "赤ちゃんは、毎朝電車で通勤します。", "explanation": "ここは〈会社員〉の意味。赤ちゃんは乳児なので、通勤する会社員には使わない。"}, {"text": "赤ちゃんは、工場で一日中、部品を組み立てています。", "explanation": "ここは〈工員〉の意味。赤ちゃんは乳児を指すので、工場で部品を組み立てる大人には使わない。"}, {"text": "赤ちゃんが、サークルの合宿に行きます。", "explanation": "ここは〈大学生〉の意味。赤ちゃんは乳児を指すので、サークルの合宿に行く大学生には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35457, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "赤ちゃんを生後三か月になって、首がすわってきました。", "corrected_sentence": "赤ちゃんは生後三か月になって、首がすわってきました。", "error_description": "主語の「赤ちゃん」には「は」が必要。「を」では「なる」の主語にならず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35457, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "帰り道で、赤ちゃんを乗ったベビーカーを押す人を見ました。", "corrected_sentence": "帰り道で、赤ちゃんを乗せたベビーカーを押す人を見ました。", "error_description": "赤ちゃんを「乗せる」のが正しい。「乗った」では赤ちゃんが自分で乗る意味になり、「を」と動詞が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
