INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35458, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "おどろいたときに、その気もちをあらわすことばです。", "primary_collocate": null, "pronunciation": "びっくり", "ipa": "bikkɯɾi", "syllable_count": 4, "sentences": [{"text": "急に大きな音がして、とてもびっくりしました。", "target_word": "びっくり", "complexity_tier": "T3", "furigana": "急[きゅう]に大[おお]きな音[おと]がして、とてもびっくりしました。", "sentence_source": "generated"}, {"text": "友だちが誕生日会を開いてくれて、びっくりしました。", "target_word": "びっくり", "complexity_tier": "T3", "furigana": "友[とも]だちが誕生日会[たんじょうびかい]を開[ひら]いてくれて、びっくりしました。", "sentence_source": "generated"}, {"text": "道でむかしの先生に会って、びっくりしました。", "target_word": "びっくり", "complexity_tier": "T3", "furigana": "道[みち]でむかしの先生[せんせい]に会[あ]って、びっくりしました。", "sentence_source": "generated"}, {"text": "テストで百点をとったので、母もびっくりしていました。", "target_word": "びっくり", "complexity_tier": "T3", "furigana": "テストで百点[ひゃくてん]をとったので、母[はは]もびっくりしていました。", "sentence_source": "generated"}, {"text": "部屋の電気が突然消えて、みんなびっくりしました。", "target_word": "びっくり", "complexity_tier": "T3", "furigana": "部屋[へや]の電気[でんき]が突然[とつぜん]消[き]えて、みんなびっくりしました。", "sentence_source": "generated"}, {"text": "知らない人に名前を呼ばれて、びっくりしました。", "target_word": "びっくり", "complexity_tier": "T3", "furigana": "知[し]らない人[ひと]に名前[なまえ]を呼[よ]ばれて、びっくりしました。", "sentence_source": "generated"}, {"text": "値段が思ったより安くて、びっくりしました。", "target_word": "びっくり", "complexity_tier": "T3", "furigana": "値段[ねだん]が思[おも]ったより安[やす]くて、びっくりしました。", "sentence_source": "generated"}, {"text": "犬が急に走り出したので、私はびっくりしました。", "target_word": "びっくり", "complexity_tier": "T3", "furigana": "犬[いぬ]が急[きゅう]に走[はし]り出[だ]したので、私[わたし]はびっくりしました。", "sentence_source": "generated"}, {"text": "雪が一晩で一メートルも積もっていて、びっくりしました。", "target_word": "びっくり", "complexity_tier": "T3", "furigana": "雪[ゆき]が一晩[ひとばん]で一[いち]メートルも積[つ]もっていて、びっくりしました。", "sentence_source": "generated"}, {"text": "後ろから急に声をかけて、びっくりさせないでください。", "target_word": "びっくり", "complexity_tier": "T3", "furigana": "後[うし]ろから急[きゅう]に声[こえ]をかけて、びっくりさせないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "びっくりする", "label": "辞書形"}, {"form": "びっくりします", "label": "丁寧形"}, {"form": "びっくりしました", "label": "丁寧過去形"}, {"form": "びっくりして", "label": "て形"}, {"form": "びっくりしない", "label": "否定形"}], "register": "polite (です・ます体)", "sense_fingerprint": "びっくり: the feeling of being startled or surprised by something sudden or unexpected; used as びっくりする / びっくりしました", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e19b2205-6e13-41a2-a86e-2a42bff0feea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35458, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "びっくり", "is_correct": true, "explanation": "感情を表す語で、「とてもびっくりしました」と「しました」に続く形。"}, {"text": "怒り", "is_correct": false, "explanation": "名詞の「怒り」は「とても怒りしました」と「しました」にうまく続かない。"}, {"text": "喜び", "is_correct": false, "explanation": "「とても喜びしました」は成り立たない。感情名詞をそのまま「しました」に続けられない。"}, {"text": "寂しさ", "is_correct": false, "explanation": "「寂しさしました」と続かず、ここでは文が成り立たない。"}], "explanations": {"びっくり": "感情を表す語で、「とてもびっくりしました」と「しました」に続く形。", "怒り": "名詞の「怒り」は「とても怒りしました」と「しました」にうまく続かない。", "喜び": "「とても喜びしました」は成り立たない。感情名詞をそのまま「しました」に続けられない。", "寂しさ": "「寂しさしました」と続かず、ここでは文が成り立たない。"}, "sentence_index": 0, "correct_answer": "びっくり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達の家で、びっくりを開けた。", "explanation": "ここは〈びっくり箱〉（驚かせる仕掛けの箱）の意味。〈びっくり〉は感情を表す語で、箱のように開けることはできない。"}, {"text": "昨日の強い雨で、道がびっくりしていた。", "explanation": "ここは〈驚く〉を、感じる主体のない道に当てはめた使い方。〈びっくり〉は人の感情を表すので、道が驚くとは言わない。"}, {"text": "その知らせに、彼は冷たくびっくりした。", "explanation": "ここは〈驚く〉の意味。〈冷たく〉は感情がないことを表すので、感情の動きである〈びっくり〉とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35458, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "びっくり", "is_correct": true, "explanation": "感情を表す語で、「びっくりしました」と「しました」に続く形。"}, {"text": "悲しみ", "is_correct": false, "explanation": "「悲しみしました」は成り立たず、感情名詞を「しました」に続けられない。"}, {"text": "憤り", "is_correct": false, "explanation": "「憤りしました」と続かないので、ここでは文が成り立たない。"}, {"text": "切なさ", "is_correct": false, "explanation": "「切なさしました」は成り立たず、文の述語として使えない。"}], "explanations": {"びっくり": "感情を表す語で、「びっくりしました」と「しました」に続く形。", "悲しみ": "「悲しみしました」は成り立たず、感情名詞を「しました」に続けられない。", "憤り": "「憤りしました」と続かないので、ここでは文が成り立たない。", "切なさ": "「切なさしました」は成り立たず、文の述語として使えない。"}, "sentence_index": 6, "correct_answer": "びっくり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週の発表を、今のうちにびっくりしておこう。", "explanation": "ここは〈予想して備える〉の意味。びっくりは急に起きる感情なので、前もって準備はできず、「今のうちに」とは合わない。"}, {"text": "問題の答えを、びっくりで書いて提出した。", "explanation": "ここは〈驚いた様子で〉の意味。〈びっくり〉は感情そのもので、答えを書く手段にはならない。"}, {"text": "その絵のびっくりは、とても静かな色だ。", "explanation": "ここは〈驚き〉を〈色〉の性質と取り違えた使い方。〈びっくり〉は感情なので、絵の色の性質を表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35458, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中に電話が鳴って、家族はみんなびっくりさせました。", "corrected_sentence": "夜中に電話が鳴って、家族はみんなびっくりしました。", "error_description": "正しくは「びっくりしました」。「びっくりさせました」は誰かを驚かせる意味で、「家族は」が驚いた側なら自動詞の形が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35458, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜道で足音がして、私はびっくりました。", "corrected_sentence": "夜道で足音がして、私はびっくりしました。", "error_description": "「びっくりしました」の「し」が抜けている。「びっくりました」は活用形として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35460, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『確かめる』の目的語を示す『を』で、『不思議を実験で確かめる』と自然につながる。"}, {"text": "が", "is_correct": false, "explanation": "『確かめる』は目的語を取る動詞なので、主語の『が』では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『確かめる』は『に』で対象を取らず、『不思議に確かめる』は不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す『で』は、確かめる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "『確かめる』の目的語を示す『を』で、『不思議を実験で確かめる』と自然につながる。", "が": "『確かめる』は目的語を取る動詞なので、主語の『が』では文が成り立たない。", "に": "『確かめる』は『に』で対象を取らず、『不思議に確かめる』は不自然。", "で": "手段を表す『で』は、確かめる対象を示せない。"}, "error_tags": {"が": "主語", "に": "目標", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35460, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35460, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ふしぎは、どうしてそうなるのか、わからないことです。", "primary_collocate": null, "pronunciation": "ふしぎ", "ipa": "ɸɯɕiɡi", "syllable_count": 3, "sentences": [{"text": "子どもは星空を見上げて、宇宙の不思議について質問した。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "子[こ]どもは星空[ほしぞら]を見上[みあ]げて、宇宙[うちゅう]の不思議[ふしぎ]について質問[しつもん]した。", "sentence_source": "generated"}, {"text": "理科の授業では、身近な自然の不思議を実験で確かめる。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]では、身近[みぢか]な自然[しぜん]の不思議[ふしぎ]を実験[じっけん]で確[たし]かめる。", "sentence_source": "generated"}, {"text": "なぜ鳥は迷わず帰れるのか、その不思議の理由はまだわかっていない。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "なぜ鳥[とり]は迷[まよ]わず帰[かえ]れるのか、その不思議[ふしぎ]の理由[りゆう]はまだわかっていない。", "sentence_source": "generated"}, {"text": "不思議を感じたら、すぐに図書館で調べるようにしている。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "不思議[ふしぎ]を感[かん]じたら、すぐに図書館[としょかん]で調[しら]べるようにしている。", "sentence_source": "generated"}, {"text": "虹ができる不思議を、先生が水と光で説明してくれた。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "虹[にじ]ができる不思議[ふしぎ]を、先生[せんせい]が水[みず]と光[ひかり]で説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "この湖には、夏でも水が冷たいままという不思議がある。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "この湖[みずうみ]には、夏[なつ]でも水[みず]が冷[つめ]たいままという不思議[ふしぎ]がある。", "sentence_source": "generated"}, {"text": "人間の記憶の不思議に、科学者たちは長く取り組んできた。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "人間[にんげん]の記憶[きおく]の不思議[ふしぎ]に、科学者[かがくしゃ]たちは長[なが]く取[と]り組[く]んできた。", "sentence_source": "generated"}, {"text": "雨上がりの空を見ると、色の不思議に心が引かれる。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "雨上[あめあ]がりの空[そら]を見[み]ると、色[いろ]の不思議[ふしぎ]に心[こころ]が引[ひ]かれる。", "sentence_source": "generated"}, {"text": "毎日の生活にも、よく考えると不思議がたくさん隠れている。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "毎日[まいにち]の生活[せいかつ]にも、よく考[かんが]えると不思議[ふしぎ]がたくさん隠[かく]れている。", "sentence_source": "generated"}, {"text": "磁石が鉄を引きつける不思議を、兄は何度も試して楽しんだ。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "磁石[じしゃく]が鉄[てつ]を引[ひ]きつける不思議[ふしぎ]を、兄[あに]は何度[なんど]も試[ため]して楽[たの]しんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不思議", "label": "基本形"}, {"form": "不思議さ", "label": "名詞化"}], "register": "neutral", "sense_fingerprint": "理由がわからず心を引く物事（名詞としての不思議）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35460, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不思議", "is_correct": true, "explanation": "宇宙について、理由のわからない事柄を質問する文脈に合う。"}, {"text": "方言", "is_correct": false, "explanation": "宇宙の方言という話は成り立たず、質問の対象にならない。"}, {"text": "包丁", "is_correct": false, "explanation": "台所の道具で、宇宙について質問する対象にはならない。"}, {"text": "砂糖", "is_correct": false, "explanation": "食べ物で、宇宙の話題として質問する内容にはならない。"}], "explanations": {"不思議": "宇宙について、理由のわからない事柄を質問する文脈に合う。", "方言": "宇宙の方言という話は成り立たず、質問の対象にならない。", "包丁": "台所の道具で、宇宙について質問する対象にはならない。", "砂糖": "食べ物で、宇宙の話題として質問する内容にはならない。"}, "sentence_index": 0, "correct_answer": "不思議"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "売り場で、珍しい不思議を一つ買った。", "explanation": "ここは〈商品〉の意味。不思議は理由のわからない事柄で、買える物は指さない。"}, {"text": "祖母は台所で不思議を作ってくれた。", "explanation": "ここは〈食べ物〉の意味。不思議は食べ物を指さない。"}, {"text": "犯人の不思議を探して、警察が捜査した。", "explanation": "ここは〈証拠〉の意味。不思議は理由のわからない事柄で、物的な証拠の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35460, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不思議", "is_correct": true, "explanation": "人間の記憶にある、理由のわからない事柄を指し、取り組む対象と合う。"}, {"text": "天ぷら", "is_correct": false, "explanation": "食べ物で、人間の記憶に取り組む対象にはならない。"}, {"text": "座布団", "is_correct": false, "explanation": "敷物で、記憶の研究の対象にはならない。"}, {"text": "郵便", "is_correct": false, "explanation": "手紙を届ける仕組みで、記憶に取り組む対象とは合わない。"}], "explanations": {"不思議": "人間の記憶にある、理由のわからない事柄を指し、取り組む対象と合う。", "天ぷら": "食べ物で、人間の記憶に取り組む対象にはならない。", "座布団": "敷物で、記憶の研究の対象にはならない。", "郵便": "手紙を届ける仕組みで、記憶に取り組む対象とは合わない。"}, "sentence_index": 6, "correct_answer": "不思議"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テストの不思議を生徒全員に配った。", "explanation": "ここは〈答案〉の意味。不思議は紙の答案ではないので、配ることはできない。"}, {"text": "工場の不思議を修理した。", "explanation": "ここは〈機械〉の意味。不思議は機械ではなく、修理の対象にはならない。"}, {"text": "大きな荷物の不思議を、トラックで運んだ。", "explanation": "ここは〈荷物〉の意味。不思議は物ではないので、運ぶことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
