INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35461, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "普通ではない、なぜそうなるのか説明できない様子。", "primary_collocate": null, "pronunciation": "ふしぎ", "ipa": "ɸɯɕiɡi", "syllable_count": 3, "sentences": [{"text": "夜の森で、不思議な光がゆらゆらと動いていた。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "夜[よる]の森[もり]で、不思議[ふしぎ]な光[ひかり]がゆらゆらと動[うご]いていた。", "sentence_source": "generated"}, {"text": "あの小さなチームが優勝したのは不思議だ。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "あの小[ちい]さなチームが優勝[ゆうしょう]したのは不思議[ふしぎ]だ。", "sentence_source": "generated"}, {"text": "昨日なくした鍵が机の上にあって、不思議でならない。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "昨日[きのう]なくした鍵[かぎ]が机[つくえ]の上[うえ]にあって、不思議[ふしぎ]でならない。", "sentence_source": "generated"}, {"text": "不思議なことに、その薬は子どもにだけよく効いた。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "不思議[ふしぎ]なことに、その薬[くすり]は子[こ]どもにだけよく効[き]いた。", "sentence_source": "generated"}, {"text": "祖母の古い時計は、不思議なことに毎年同じ日に止まる。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "祖母[そぼ]の古[ふる]い時計[とけい]は、不思議[ふしぎ]なことに毎年[まいとし]同[おな]じ日[ひ]に止[と]まる。", "sentence_source": "generated"}, {"text": "誰も触れていないのにドアが開くなんて、不思議な話だ。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "誰[だれ]も触[ふ]れていないのにドアが開[あ]くなんて、不思議[ふしぎ]な話[はなし]だ。", "sentence_source": "generated"}, {"text": "この町には不思議な言い伝えが多く残っている。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "この町[まち]には不思議[ふしぎ]な言[い]い伝[つた]えが多[おお]く残[のこ]っている。", "sentence_source": "generated"}, {"text": "何も食べないのに元気なのは不思議だ。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "何[なに]も食[た]べないのに元気[げんき]なのは不思議[ふしぎ]だ。", "sentence_source": "generated"}, {"text": "初めて来た場所なのに、不思議と懐かしい気持ちになった。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "初[はじ]めて来[き]た場所[ばしょ]なのに、不思議[ふしぎ]と懐[なつ]かしい気持[きも]ちになった。", "sentence_source": "generated"}, {"text": "手品師が帽子から花を出す様子は、本当に不思議だった。", "target_word": "不思議", "complexity_tier": "T3", "furigana": "手品師[てじなし]が帽子[ぼうし]から花[はな]を出[だ]す様子[ようす]は、本当[ほんとう]に不思議[ふしぎ]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "不思議だ", "label": "終止形"}, {"form": "不思議な", "label": "連体形"}, {"form": "不思議に", "label": "連用形"}, {"form": "不思議で", "label": "連用形（て形相当）"}, {"form": "不思議ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "普通と違い、理由を説明できない様子（形容動詞的な不思議）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 夜の森 (Zipf 1.81)']::text[], '8040d734-164f-4fc0-809e-36d9f39f3334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35461, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不思議", "is_correct": true, "explanation": "夜の森で光が動く、理由のわからない様子に合う。"}, {"text": "便利", "is_correct": false, "explanation": "役立つ様子を表し、夜の森の光の描写には合わない。"}, {"text": "丁寧", "is_correct": false, "explanation": "念入りな様子を表し、光の動きの描写には合わない。"}, {"text": "乱暴", "is_correct": false, "explanation": "荒っぽい様子を表し、ゆらゆら動く光とは合わない。"}], "explanations": {"不思議": "夜の森で光が動く、理由のわからない様子に合う。", "便利": "役立つ様子を表し、夜の森の光の描写には合わない。", "丁寧": "念入りな様子を表し、光の動きの描写には合わない。", "乱暴": "荒っぽい様子を表し、ゆらゆら動く光とは合わない。"}, "sentence_index": 0, "correct_answer": "不思議"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は、孫に誕生日の不思議を贈った。", "explanation": "ここは〈贈り物〉の意味。不思議は様子や事柄を表す語で、人に贈る品の名前ではない。"}, {"text": "学生でも買えるように、不思議を半額で売り出した。", "explanation": "ここは〈商品〉の意味。不思議は様子を表す語で、売り出せる品物ではない。"}, {"text": "彼は会議用の不思議を三枚配って、話を始めた。", "explanation": "ここは〈用紙〉の意味。不思議は紙の名前ではないので、配る資料にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35461, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不思議", "is_correct": true, "explanation": "町に残る言い伝えの性質として、理由のわからない様子に合う。"}, {"text": "器用", "is_correct": false, "explanation": "手先が巧みな様子を表し、言い伝えの説明には合わない。"}, {"text": "無作法", "is_correct": false, "explanation": "礼儀に欠ける様子を表し、言い伝えには使えない。"}, {"text": "頑丈", "is_correct": false, "explanation": "壊れにくい様子を表し、言い伝えの描写には合わない。"}], "explanations": {"不思議": "町に残る言い伝えの性質として、理由のわからない様子に合う。", "器用": "手先が巧みな様子を表し、言い伝えの説明には合わない。", "無作法": "礼儀に欠ける様子を表し、言い伝えには使えない。", "頑丈": "壊れにくい様子を表し、言い伝えの描写には合わない。"}, "sentence_index": 6, "correct_answer": "不思議"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この地図の不思議を、駅員が広げて道を教えてくれた。", "explanation": "ここは〈地図〉の意味。不思議は様子を表す語で、紙の地図を指すことはない。"}, {"text": "明日の不思議は雨だと、天気予報が伝えた。", "explanation": "ここは〈天気〉の意味。不思議は様子や事柄を表す語で、天候そのものは指さない。"}, {"text": "彼女は来月の不思議を決めるため、会議を開いた。", "explanation": "ここは〈予定〉の意味。不思議は予定や計画を指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35461, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜の森で、不思議声が聞こえた。", "corrected_sentence": "夜の森で、不思議な声が聞こえた。", "error_description": "形容動詞型の『不思議』は名詞の前で『な』を付ける。『な』が抜けていて誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "不思議", "is_correct": true, "explanation": "文末の『だ』の前に置く語形で、『優勝したのは不思議だ』と合う。"}, {"text": "不思議な", "is_correct": false, "explanation": "連体形で名詞を修飾する形。文末に置くと『不思議なだ』となり成り立たない。"}, {"text": "不思議に", "is_correct": false, "explanation": "連用形で用言を修飾する形。文末の『だ』には続かない。"}, {"text": "不思議がる", "is_correct": false, "explanation": "動詞の形。「だ」の前には続かず、「優勝したのは不思議がるだ」は成り立たない。"}], "correct_form": "不思議", "base_form": "不思議", "form_label": "終止形", "sentence_index": 1, "explanations": {"不思議": "文末の『だ』の前に置く語形で、『優勝したのは不思議だ』と合う。", "不思議な": "連体形で名詞を修飾する形。文末に置くと『不思議なだ』となり成り立たない。", "不思議に": "連用形で用言を修飾する形。文末の『だ』には続かない。", "不思議がる": "動詞の形。「だ」の前には続かず、「優勝したのは不思議がるだ」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35461, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不思議にことに、雨が止んだ。", "corrected_sentence": "不思議なことに、雨が止んだ。", "error_description": "『不思議なこと』は名詞を修飾する形なので『な』が必要。『に』は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "不思議", "is_correct": true, "explanation": "文末の『だ』の前に置く語形で、「なのは不思議だ」と合う。"}, {"text": "不思議で", "is_correct": false, "explanation": "て形。後ろに文を続ける形で、文末の『だ』の位置には入らない。"}, {"text": "不思議く", "is_correct": false, "explanation": "形容動詞の語幹に『く』は付かず、「元気なのは不思議く。」は成り立たない。"}, {"text": "不思議がって", "is_correct": false, "explanation": "て形の動詞。不思議に感じてという動作になり、文末の名詞述語の位置には入らない。"}], "correct_form": "不思議", "base_form": "不思議", "form_label": "終止形", "sentence_index": 7, "explanations": {"不思議": "文末の『だ』の前に置く語形で、「なのは不思議だ」と合う。", "不思議で": "て形。後ろに文を続ける形で、文末の『だ』の位置には入らない。", "不思議く": "形容動詞の語幹に『く』は付かず、「元気なのは不思議く。」は成り立たない。", "不思議がって": "て形の動詞。不思議に感じてという動作になり、文末の名詞述語の位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '837edd75-6153-4d7b-968d-441fc71dea40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
