INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35462, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "においがして、鼻でかぎます。", "primary_collocate": null, "pronunciation": "においがする", "ipa": "nioiɡasɯɾɯ", "syllable_count": 6, "sentences": [{"text": "台所からカレーの匂いがします。", "target_word": "匂いがします", "complexity_tier": "T3", "furigana": "台所[だいどころ]からカレーの匂[にお]いがします。", "sentence_source": "generated"}, {"text": "この花は、いい匂いがするので大好きです。", "target_word": "匂いがする", "complexity_tier": "T3", "furigana": "この花[はな]は、いい匂[にお]いがするので大好[だいす]きです。", "sentence_source": "generated"}, {"text": "雨が降る前は、土の匂いがする。", "target_word": "匂いがする", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]る前[まえ]は、土[つち]の匂[にお]いがする。", "sentence_source": "generated"}, {"text": "部屋に入ると、コーヒーの匂いがしました。", "target_word": "匂いがしました", "complexity_tier": "T3", "furigana": "部屋[へや]に入[はい]ると、コーヒーの匂[にお]いがしました。", "sentence_source": "generated"}, {"text": "焼いたパンの匂いがして、急におなかがすいた。", "target_word": "匂いがして", "complexity_tier": "T3", "furigana": "焼[や]いたパンの匂[にお]いがして、急[きゅう]におなかがすいた。", "sentence_source": "generated"}, {"text": "このせっけんは、レモンの匂いがします。", "target_word": "匂いがします", "complexity_tier": "T3", "furigana": "このせっけんは、レモンの匂[にお]いがします。", "sentence_source": "generated"}, {"text": "窓を開けたら、海の匂いがした。", "target_word": "匂いがした", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けたら、海[うみ]の匂[にお]いがした。", "sentence_source": "generated"}, {"text": "冷蔵庫の中から変な匂いがするので、中を見てみた。", "target_word": "匂いがする", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]の中[なか]から変[へん]な匂[にお]いがするので、中[なか]を見[み]てみた。", "sentence_source": "generated"}, {"text": "古い本は、紙の匂いがして落ち着く。", "target_word": "匂いがして", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]は、紙[かみ]の匂[にお]いがして落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "新しい車は、独特の匂いがするけれど、すぐに慣れます。", "target_word": "匂いがする", "complexity_tier": "T3", "furigana": "新[あたら]しい車[くるま]は、独特[どくとく]の匂[にお]いがするけれど、すぐに慣[な]れます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "匂いがする", "label": "終止形"}, {"form": "匂いがした", "label": "過去形"}, {"form": "匂いがして", "label": "て形"}, {"form": "匂いがしない", "label": "否定形"}, {"form": "匂いがします", "label": "丁寧形"}], "register": "neutral", "sense_fingerprint": "鼻で感じるにおいが存在する意味の「匂いがする（します）」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b06b0e63-ab55-4198-b9e1-1c42010908cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35462, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "匂いがします", "is_correct": true, "explanation": "丁寧な終止形。台所のカレーの匂いを丁寧に伝える文末として正しい。"}, {"text": "匂いがすると", "is_correct": false, "explanation": "条件形「〜と」。後ろに続く文が必要で、文末には置けない。"}, {"text": "匂いがしたら", "is_correct": false, "explanation": "仮定形「〜たら」。ここで文を終えられず、続きの文が必要になる。"}, {"text": "匂いがして", "is_correct": false, "explanation": "て形。文の途中で止まる形で、文末に置くと文が完結しない。"}], "explanations": {"匂いがします": "丁寧な終止形。台所のカレーの匂いを丁寧に伝える文末として正しい。", "匂いがすると": "条件形「〜と」。後ろに続く文が必要で、文末には置けない。", "匂いがしたら": "仮定形「〜たら」。ここで文を終えられず、続きの文が必要になる。", "匂いがして": "て形。文の途中で止まる形で、文末に置くと文が完結しない。"}, "sentence_index": 0, "correct_answer": "匂いがします"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この布は、ざらざらした匂いがする。", "explanation": "ここは〈手ざわり〉の話。ざらざらは触って感じる感覚で、においを表す「匂い」とは合わない。"}, {"text": "ドアの向こうから、足音の匂いがした。", "explanation": "ここは〈音〉の話。足音は耳で聞くもので、匂いとしては言わない。"}, {"text": "この花は、赤い匂いがする。", "explanation": "ここは〈色〉の話。赤いのは見た目なので、においを表す「匂いがする」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35462, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "匂いがした", "is_correct": true, "explanation": "過去形。「窓を開けたら」の結果として海の匂いがしたと述べる文末として正しい。"}, {"text": "匂いがしたので", "is_correct": false, "explanation": "理由を表す「ので」で止まる形。文末には置けず、続きの文が必要になる。"}, {"text": "匂いがしなければ", "is_correct": false, "explanation": "仮定形「〜ば」。文末に置くと文が完結せず、成り立たない。"}, {"text": "匂いがしたり", "is_correct": false, "explanation": "並列の「〜たり」。「〜たりする」と続けないと文末にならない。"}], "explanations": {"匂いがした": "過去形。「窓を開けたら」の結果として海の匂いがしたと述べる文末として正しい。", "匂いがしたので": "理由を表す「ので」で止まる形。文末には置けず、続きの文が必要になる。", "匂いがしなければ": "仮定形「〜ば」。文末に置くと文が完結せず、成り立たない。", "匂いがしたり": "並列の「〜たり」。「〜たりする」と続けないと文末にならない。"}, "sentence_index": 6, "correct_answer": "匂いがした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空に、星の匂いがする。", "explanation": "ここは〈見る〉の感覚の話。星は見るもので、においは感じない。「匂い」は鼻で感じる語なので視覚には合わない。"}, {"text": "遠くで、歌の匂いがした。", "explanation": "ここは〈音〉の話。歌は耳で聞くもので、においとしては言わない。"}, {"text": "この電車は、速い匂いがした。", "explanation": "ここは〈速さ〉の話。速いのは動きの特徴で、においの性質を表す語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35462, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台所から焼き魚の匂いをします。", "corrected_sentence": "台所から焼き魚の匂いがします。", "error_description": "助詞の誤り。「匂いがする」は「が」を使う形で、「匂いを」とすると誤り。正しくは「匂いが」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "匂いがする", "is_correct": true, "explanation": "辞書形。「〜ので」の前は普通形で続くので、ここでは辞書形が正しい。"}, {"text": "匂いがしたら", "is_correct": false, "explanation": "仮定形「〜たら」。「〜ので」の前には続かず、文法的に成り立たない。"}, {"text": "匂いがして", "is_correct": false, "explanation": "て形。「〜ので」の前では文が続かず、文法的に成り立たない。"}, {"text": "匂いがすれば", "is_correct": false, "explanation": "仮定形「〜ば」。「〜ので」の前には続かず、文法的に成り立たない。"}], "correct_form": "匂いがする", "base_form": "匂いがする", "form_label": "辞書形", "sentence_index": 1, "explanations": {"匂いがする": "辞書形。「〜ので」の前は普通形で続くので、ここでは辞書形が正しい。", "匂いがしたら": "仮定形「〜たら」。「〜ので」の前には続かず、文法的に成り立たない。", "匂いがして": "て形。「〜ので」の前では文が続かず、文法的に成り立たない。", "匂いがすれば": "仮定形「〜ば」。「〜ので」の前には続かず、文法的に成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35462, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓を開けたら、山の匂いがいた。", "corrected_sentence": "窓を開けたら、山の匂いがした。", "error_description": "動詞の誤り。「匂いがする」の過去形は「した」。「いた」は存在の動詞「いる」の過去形で、匂いには使わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "匂いがする", "is_correct": true, "explanation": "辞書形。「〜ので」の前は普通形で続くので正しい。"}, {"text": "匂いがしろ", "is_correct": false, "explanation": "命令形。「〜ので」の前には続かず、文法的に成り立たない。"}, {"text": "匂いがしそう", "is_correct": false, "explanation": "様態の「そう」。「〜ので」の前では「しそうなので」の形が必要で、このままでは成り立たない。"}, {"text": "匂いがしなくて", "is_correct": false, "explanation": "否定のて形。「ので」の前で文が完結せず、変な匂いがしないという意味にもなり合わない。"}], "correct_form": "匂いがする", "base_form": "匂いがする", "form_label": "辞書形", "sentence_index": 7, "explanations": {"匂いがする": "辞書形。「〜ので」の前は普通形で続くので正しい。", "匂いがしろ": "命令形。「〜ので」の前には続かず、文法的に成り立たない。", "匂いがしそう": "様態の「そう」。「〜ので」の前では「しそうなので」の形が必要で、このままでは成り立たない。", "匂いがしなくて": "否定のて形。「ので」の前で文が完結せず、変な匂いがしないという意味にもなり合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e650c5-eafd-44e9-9635-5b0ea38fdd98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35464, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「薬を飲まず」で、飲む対象を表す。"}, {"text": "の", "is_correct": false, "explanation": "「薬の飲まず」では所属の関係になり、動詞の目的語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「薬に飲まず」は相手や場所を示し、飲む対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「薬へ飲まず」は方向を示すが、飲む対象は方向ではないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「薬を飲まず」で、飲む対象を表す。", "の": "「薬の飲まず」では所属の関係になり、動詞の目的語を示せない。", "に": "「薬に飲まず」は相手や場所を示し、飲む対象にはならない。", "へ": "「薬へ飲まず」は方向を示すが、飲む対象は方向ではないので合わない。"}, "error_tags": {"の": "連体・所有", "に": "相手・帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35464, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ジュースを飲みすぎて」で、飲む対象を表す。"}, {"text": "で", "is_correct": false, "explanation": "「ジュースで飲みすぎて」は手段を示し、飲む対象にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「ジュースから飲みすぎて」は起点を示し、飲む対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「ジュースより飲みすぎて」は比較の意味になり、文の流れに合わない。"}], "correct_answer": "を", "explanations": {"を": "「ジュースを飲みすぎて」で、飲む対象を表す。", "で": "「ジュースで飲みすぎて」は手段を示し、飲む対象にはならない。", "から": "「ジュースから飲みすぎて」は起点を示し、飲む対象を表せない。", "より": "「ジュースより飲みすぎて」は比較の意味になり、文の流れに合わない。"}, "error_tags": {"で": "手段", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35464, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "くちにいれて、おなかのなかにおくること。", "primary_collocate": null, "pronunciation": "のむ", "ipa": "nomɯ", "syllable_count": 2, "sentences": [{"text": "毎朝、牛乳を一杯飲みます。", "target_word": "飲みます", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、牛乳[ぎゅうにゅう]を一杯[いっぱい]飲[の]みます。", "sentence_source": "generated"}, {"text": "薬を飲まずに寝たので、朝になっても熱が下がらなかった。", "target_word": "飲まず", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]まずに寝[ね]たので、朝[あさ]になっても熱[ねつ]が下[さ]がらなかった。", "sentence_source": "generated"}, {"text": "のどがかわいたので、冷たい水を飲んだ。", "target_word": "飲んだ", "complexity_tier": "T3", "furigana": "のどがかわいたので、冷[つめ]たい水[みず]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "夜は眠れなくなるので、コーヒーは飲みません。", "target_word": "飲みません", "complexity_tier": "T3", "furigana": "夜[よる]は眠[ねむ]れなくなるので、コーヒーは飲[の]みません。", "sentence_source": "generated"}, {"text": "風邪をひいたときは、薬を飲んで早く寝ます。", "target_word": "飲んで", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいたときは、薬[くすり]を飲[の]んで早[はや]く寝[ね]ます。", "sentence_source": "generated"}, {"text": "水も飲まずに走りつづけて、気分が悪くなった。", "target_word": "飲まず", "complexity_tier": "T3", "furigana": "水[みず]も飲[の]まずに走[はし]りつづけて、気分[きぶん]が悪[わる]くなった。", "sentence_source": "generated"}, {"text": "熱いお茶をゆっくり飲むと、体があたたまる。", "target_word": "飲む", "complexity_tier": "T3", "furigana": "熱[あつ]いお茶[ちゃ]をゆっくり飲[の]むと、体[からだ]があたたまる。", "sentence_source": "generated"}, {"text": "子どもはジュースを飲みすぎて、ごはんを食べられなかった。", "target_word": "飲みすぎて", "complexity_tier": "T3", "furigana": "子[こ]どもはジュースを飲[の]みすぎて、ごはんを食[た]べられなかった。", "sentence_source": "generated"}, {"text": "この水は安全なので、そのまま飲めます。", "target_word": "飲めます", "complexity_tier": "T3", "furigana": "この水[みず]は安全[あんぜん]なので、そのまま飲[の]めます。", "sentence_source": "generated"}, {"text": "食事の前に一錠飲むように、医者に言われました。", "target_word": "飲む", "complexity_tier": "T3", "furigana": "食事[しょくじ]の前[まえ]に一錠[いちじょう]飲[の]むように、医者[いしゃ]に言[い]われました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲む", "label": "終止形"}, {"form": "飲み", "label": "連用形"}, {"form": "飲ま", "label": "未然形"}, {"form": "飲んで", "label": "て形"}, {"form": "飲んだ", "label": "過去形"}, {"form": "飲めます", "label": "可能・丁寧形"}, {"form": "飲みます", "label": "丁寧形"}, {"form": "飲まず", "label": "否定連用形"}], "register": "neutral", "sense_fingerprint": "水や薬などを口に入れ、のみこんで腹に入れる動作。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: あたたまる (Zipf 2.17)']::text[], '01b68666-ebe4-44b0-8208-b74bdbb1eb7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35464, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飲みます", "is_correct": true, "explanation": "「牛乳を一杯飲みます」は毎朝の習慣として自然に入る。"}, {"text": "食べます", "is_correct": false, "explanation": "牛乳は食べるものではなく飲むものなので、「一杯食べます」は不自然。"}, {"text": "洗います", "is_correct": false, "explanation": "洗うは物を清潔にする動作で、牛乳を一杯取る文には合わない。"}, {"text": "噛みます", "is_correct": false, "explanation": "噛むは歯でかみくだく動作で、液体の牛乳には使わない。"}], "explanations": {"飲みます": "「牛乳を一杯飲みます」は毎朝の習慣として自然に入る。", "食べます": "牛乳は食べるものではなく飲むものなので、「一杯食べます」は不自然。", "洗います": "洗うは物を清潔にする動作で、牛乳を一杯取る文には合わない。", "噛みます": "噛むは歯でかみくだく動作で、液体の牛乳には使わない。"}, "sentence_index": 0, "correct_answer": "飲みます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝は食パンを飲んで、ゆっくり出かけます。", "explanation": "ここは〈食べる〉の意味。固形のパンは食べると言い、飲むは液体や薬に使うので合わない。"}, {"text": "たばこを飲んで、一息ついた。", "explanation": "ここは〈吸う〉の意味。煙を口から取り込むのは吸うで、飲むは液体を飲み込む動作なので合わない。"}, {"text": "そばを飲んで、ずるずると音を立てた。", "explanation": "ここは〈すする〉の意味。麺を口に吸い込むように食べる動作で、飲むは液体を口から送る動作なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35464, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飲む", "is_correct": true, "explanation": "「お茶をゆっくり飲む」は飲む動作として自然。"}, {"text": "踏む", "is_correct": false, "explanation": "お茶は踏むものではないので、「お茶をゆっくり踏む」は成り立たない。"}, {"text": "切る", "is_correct": false, "explanation": "切るは固体を分ける動作で、液体のお茶には合わない。"}, {"text": "磨く", "is_correct": false, "explanation": "磨くは表面をみがく動作で、お茶には使わない。"}], "explanations": {"飲む": "「お茶をゆっくり飲む」は飲む動作として自然。", "踏む": "お茶は踏むものではないので、「お茶をゆっくり踏む」は成り立たない。", "切る": "切るは固体を分ける動作で、液体のお茶には合わない。", "磨く": "磨くは表面をみがく動作で、お茶には使わない。"}, "sentence_index": 6, "correct_answer": "飲む"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "硬いお肉は、飲んで細かくしてから食べてください。", "explanation": "ここは〈噛む〉の意味。肉を歯で細かく砕くのは噛むで、飲むは口から胃へ送る動作なので合わない。"}, {"text": "飴を飲んで、口の中で小さくしていた。", "explanation": "ここは〈舐める〉の意味。飴は口の中で溶かすので舐めると言い、飲むは液体や薬に使うので合わない。"}, {"text": "ペンを飲んで、机に向かった。", "explanation": "ここは〈くわえる〉の意味。ペンを歯や唇で口にくわえるのは、飲むは液体や薬を胃へ送る動作なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35464, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方、お茶を一杯飲むます。", "corrected_sentence": "夕方、お茶を一杯飲みます。", "error_description": "「ます」の前は動詞の連用形「飲み」にする。「飲むます」は誤りで、「飲みます」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "飲まず", "is_correct": true, "explanation": "「薬を飲まずに寝た」で、否定の連用形として前後をつなぐ。"}, {"text": "飲め", "is_correct": false, "explanation": "命令形なので、「寝たので」と続く過去の文には合わない。"}, {"text": "飲もう", "is_correct": false, "explanation": "意志形なので、過去の出来事として「寝た」と続かない。"}, {"text": "飲み", "is_correct": false, "explanation": "肯定の連用形なので、「飲み寝た」では否定の意味にならない。"}], "correct_form": "飲まず", "base_form": "飲む", "form_label": "否定連用形", "sentence_index": 1, "explanations": {"飲まず": "「薬を飲まずに寝た」で、否定の連用形として前後をつなぐ。", "飲め": "命令形なので、「寝たので」と続く過去の文には合わない。", "飲もう": "意志形なので、過去の出来事として「寝た」と続かない。", "飲み": "肯定の連用形なので、「飲み寝た」では否定の意味にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35464, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い日は、熱いスープで飲むと体が温まる。", "corrected_sentence": "寒い日は、熱いスープを飲むと体が温まる。", "error_description": "「飲む」は目的語に「を」を取るので、「で」は誤り。「熱いスープを飲む」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "飲みすぎて", "is_correct": true, "explanation": "「飲みすぎて」はて形で、後ろの「ごはんを食べられなかった」へつなげる。"}, {"text": "飲みすぎる", "is_correct": false, "explanation": "終止・連体形なので、後ろの文へ接続できない。"}, {"text": "飲みすぎた", "is_correct": false, "explanation": "過去形なので、原因を述べて後ろへつなぐ役割は持たない。"}, {"text": "飲みすぎよう", "is_correct": false, "explanation": "意志形なので、後ろの過去の結果「食べられなかった」とはつながらない。"}], "correct_form": "飲みすぎて", "base_form": "飲む", "form_label": "て形", "sentence_index": 7, "explanations": {"飲みすぎて": "「飲みすぎて」はて形で、後ろの「ごはんを食べられなかった」へつなげる。", "飲みすぎる": "終止・連体形なので、後ろの文へ接続できない。", "飲みすぎた": "過去形なので、原因を述べて後ろへつなぐ役割は持たない。", "飲みすぎよう": "意志形なので、後ろの過去の結果「食べられなかった」とはつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35466, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35466, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「絵の先生に」で、教えてもらう相手を表す。"}, {"text": "で", "is_correct": false, "explanation": "「絵の先生で」は場所や手段を示し、教えてもらう相手にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「絵の先生より」は比較の意味になり、教えてもらう相手を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「絵の先生の」は所属を示すだけで、「教えてもらいました」の相手を表せない。"}], "correct_answer": "に", "explanations": {"に": "「絵の先生に」で、教えてもらう相手を表す。", "で": "「絵の先生で」は場所や手段を示し、教えてもらう相手にはならない。", "より": "「絵の先生より」は比較の意味になり、教えてもらう相手を示せない。", "の": "「絵の先生の」は所属を示すだけで、「教えてもらいました」の相手を表せない。"}, "error_tags": {"で": "手段・場所", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35466, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "おしえるひと。", "primary_collocate": null, "pronunciation": "せんせい", "ipa": "seɴseː", "syllable_count": 4, "sentences": [{"text": "ピアノの先生は、毎週きびしく教えてくれます。", "target_word": "先生", "complexity_tier": "T3", "furigana": "ピアノの先生[せんせい]は、毎週[まいしゅう]きびしく教[おし]えてくれます。", "sentence_source": "generated"}, {"text": "私の水泳の先生は、とても泳ぐのが速いです。", "target_word": "先生", "complexity_tier": "T3", "furigana": "私[わたし]の水泳[すいえい]の先生[せんせい]は、とても泳[およ]ぐのが速[はや]いです。", "sentence_source": "generated"}, {"text": "先生に習ったので、料理が上手になりました。", "target_word": "先生", "complexity_tier": "T3", "furigana": "先生[せんせい]に習[なら]ったので、料理[りょうり]が上手[じょうず]になりました。", "sentence_source": "generated"}, {"text": "書道の先生が、筆の持ち方を直してくれた。", "target_word": "先生", "complexity_tier": "T3", "furigana": "書道[しょどう]の先生[せんせい]が、筆[ふで]の持[も]ち方[かた]を直[なお]してくれた。", "sentence_source": "generated"}, {"text": "英会話の先生は外国の人で、発音がきれいです。", "target_word": "先生", "complexity_tier": "T3", "furigana": "英会話[えいかいわ]の先生[せんせい]は外国[がいこく]の人[ひと]で、発音[はつおん]がきれいです。", "sentence_source": "generated"}, {"text": "先生のおかげで、歌が歌えるようになった。", "target_word": "先生", "complexity_tier": "T3", "furigana": "先生[せんせい]のおかげで、歌[うた]が歌[うた]えるようになった。", "sentence_source": "generated"}, {"text": "ギターの先生は優しいので、練習が楽しいです。", "target_word": "先生", "complexity_tier": "T3", "furigana": "ギターの先生[せんせい]は優[やさ]しいので、練習[れんしゅう]が楽[たの]しいです。", "sentence_source": "generated"}, {"text": "絵の先生に、色の使い方を教えてもらいました。", "target_word": "先生", "complexity_tier": "T3", "furigana": "絵[え]の先生[せんせい]に、色[いろ]の使[つか]い方[かた]を教[おし]えてもらいました。", "sentence_source": "generated"}, {"text": "先生が忙しい日は、レッスンがお休みになります。", "target_word": "先生", "complexity_tier": "T3", "furigana": "先生[せんせい]が忙[いそが]しい日[ひ]は、レッスンがお休[やす]みになります。", "sentence_source": "generated"}, {"text": "子どものころ、ダンスの先生にほめられてうれしかった。", "target_word": "先生", "complexity_tier": "T3", "furigana": "子[こ]どものころ、ダンスの先生[せんせい]にほめられてうれしかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "先生", "label": "基本形"}, {"form": "先生たち", "label": "複数形"}, {"form": "先生方", "label": "敬称複数形"}], "register": "neutral", "sense_fingerprint": "習い事や技能を教える人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: きびしく (Zipf 2.15)']::text[], '01b68666-ebe4-44b0-8208-b74bdbb1eb7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35466, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "先生", "is_correct": true, "explanation": "「ピアノの先生は」は、毎週きびしく教える人として主語に入る。"}, {"text": "楽譜", "is_correct": false, "explanation": "楽譜は教えてくれる人ではないので、主語にすると文が成り立たない。"}, {"text": "鍵盤", "is_correct": false, "explanation": "鍵盤は楽器の一部で、毎週きびしく教える主語にはならない。"}, {"text": "録音", "is_correct": false, "explanation": "録音は音を記録したもので、人のように教える主語にはならない。"}], "explanations": {"先生": "「ピアノの先生は」は、毎週きびしく教える人として主語に入る。", "楽譜": "楽譜は教えてくれる人ではないので、主語にすると文が成り立たない。", "鍵盤": "鍵盤は楽器の一部で、毎週きびしく教える主語にはならない。", "録音": "録音は音を記録したもので、人のように教える主語にはならない。"}, "sentence_index": 0, "correct_answer": "先生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この先生は、一袋百円で売っている。", "explanation": "先生は人を指すので、値段がついて売られる物の主語にはならない。"}, {"text": "今日の先生は、午後から雨になるそうだ。", "explanation": "先生は人を指すので、天気の話の主語にはならない。"}, {"text": "この先生は、駅の近くに三年前に建った。", "explanation": "先生は人を指すので、駅前に建つ建物の主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35466, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先生", "is_correct": true, "explanation": "「ギターの先生は優しいので」は、教える人として主語に入る。"}, {"text": "弦", "is_correct": false, "explanation": "弦は教える主体ではないので、「弦は優しいので」は文として成り立たない。"}, {"text": "指板", "is_correct": false, "explanation": "指板はギターの部品で、人のように優しいと言えない。"}, {"text": "音程", "is_correct": false, "explanation": "音程は音の高さで、人物評の主語にはならない。"}], "explanations": {"先生": "「ギターの先生は優しいので」は、教える人として主語に入る。", "弦": "弦は教える主体ではないので、「弦は優しいので」は文として成り立たない。", "指板": "指板はギターの部品で、人のように優しいと言えない。", "音程": "音程は音の高さで、人物評の主語にはならない。"}, "sentence_index": 6, "correct_answer": "先生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の先生が、選手の反則を取った。", "explanation": "先生は教える人を指すので、試合で反則を判定する人の意味では使えない。"}, {"text": "選挙の応援に来た先生は、道の角に立てられていた。", "explanation": "先生は人を指すので、道の角に立てられる看板の主語にはならない。"}, {"text": "港の先生が、大きな船を沖へ出した。", "explanation": "先生は教える人を指すので、港から船を出す人の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35466, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "英会話の先生を習ったので、会話が上手になりました。", "corrected_sentence": "英会話の先生に習ったので、会話が上手になりました。", "error_description": "「先生に習う」は相手を表す「に」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35466, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小学生のころ、体操の先生だにほめられてうれしかった。", "corrected_sentence": "小学生のころ、体操の先生にほめられてうれしかった。", "error_description": "「先生」の直後に「だ」が余計に入っている。「先生」の後は「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35467, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「先生が」で、黒板に書く動作の主語を表す。"}, {"text": "に", "is_correct": false, "explanation": "「先生に黒板に」では相手を示すが、書く動作の主語にはならない。"}, {"text": "を", "is_correct": false, "explanation": "「先生を黒板に」では目的語になり、書く動作の主語として合わない。"}, {"text": "で", "is_correct": false, "explanation": "「先生で黒板に」は手段や場所を示すが、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「先生が」で、黒板に書く動作の主語を表す。", "に": "「先生に黒板に」では相手を示すが、書く動作の主語にはならない。", "を": "「先生を黒板に」では目的語になり、書く動作の主語として合わない。", "で": "「先生で黒板に」は手段や場所を示すが、主語にはならない。"}, "error_tags": {"に": "相手", "を": "対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35467, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「先生に質問」で、質問する相手を表す。"}, {"text": "の", "is_correct": false, "explanation": "「先生の質問」は所属や持ち主を示し、質問の相手を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「先生を質問したら」は質問の相手を示せず、目的語の形にもならない。"}, {"text": "より", "is_correct": false, "explanation": "「先生より質問」は比較の意味になり、質問の相手にならない。"}], "correct_answer": "に", "explanations": {"に": "「先生に質問」で、質問する相手を表す。", "の": "「先生の質問」は所属や持ち主を示し、質問の相手を示せない。", "を": "「先生を質問したら」は質問の相手を示せず、目的語の形にもならない。", "より": "「先生より質問」は比較の意味になり、質問の相手にならない。"}, "error_tags": {"の": "連体修飾", "を": "目的語", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35467, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "学校や塾などで、生徒に学問や技術を教える人。", "primary_collocate": null, "pronunciation": "せんせい", "ipa": "seɴseː", "syllable_count": 4, "sentences": [{"text": "田中先生は、学校で数学を教えています。", "target_word": "先生", "complexity_tier": "T3", "furigana": "田中[たなか]先生[せんせい]は、学校[がっこう]で数学[すうがく]を教[おし]えています。", "sentence_source": "generated"}, {"text": "先生が黒板に問題を書きました。", "target_word": "先生", "complexity_tier": "T3", "furigana": "先生[せんせい]が黒板[こくばん]に問題[もんだい]を書[か]きました。", "sentence_source": "generated"}, {"text": "宿題を忘れたので、先生に謝りました。", "target_word": "先生", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]を忘[わす]れたので、先生[せんせい]に謝[あやま]りました。", "sentence_source": "generated"}, {"text": "塾の先生は、わからないところを何度も説明してくれる。", "target_word": "先生", "complexity_tier": "T3", "furigana": "塾[じゅく]の先生[せんせい]は、わからないところを何度[なんど]も説明[せつめい]してくれる。", "sentence_source": "generated"}, {"text": "担任の先生から、明日の持ち物を聞きました。", "target_word": "先生", "complexity_tier": "T3", "furigana": "担任[たんにん]の先生[せんせい]から、明日[あした]の持[も]ち物[もの]を聞[き]きました。", "sentence_source": "generated"}, {"text": "先生が教室に入ると、みんな静かになった。", "target_word": "先生", "complexity_tier": "T3", "furigana": "先生[せんせい]が教室[きょうしつ]に入[はい]ると、みんな静[しず]かになった。", "sentence_source": "generated"}, {"text": "理科の先生は、実験が好きな人です。", "target_word": "先生", "complexity_tier": "T3", "furigana": "理科[りか]の先生[せんせい]は、実験[じっけん]が好[す]きな人[ひと]です。", "sentence_source": "generated"}, {"text": "先生に質問したら、やさしく答えてくれました。", "target_word": "先生", "complexity_tier": "T3", "furigana": "先生[せんせい]に質問[しつもん]したら、やさしく答[こた]えてくれました。", "sentence_source": "generated"}, {"text": "卒業式の日、先生は生徒一人ひとりに声をかけた。", "target_word": "先生", "complexity_tier": "T3", "furigana": "卒業式[そつぎょうしき]の日[ひ]、先生[せんせい]は生徒[せいと]一人[ひとり]ひとりに声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "中学の先生のおかげで、英語が好きになりました。", "target_word": "先生", "complexity_tier": "T3", "furigana": "中学[ちゅうがく]の先生[せんせい]のおかげで、英語[えいご]が好[す]きになりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "先生", "label": "基本形"}, {"form": "先生たち", "label": "複数形"}, {"form": "先生方", "label": "敬称複数形"}], "register": "neutral", "sense_fingerprint": "学校や塾で生徒に教える職業の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b68666-ebe4-44b0-8208-b74bdbb1eb7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35467, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "先生", "is_correct": true, "explanation": "「田中先生は」は、学校で数学を教える人として主語に入る。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所で、数学を教える人の主語にすると成り立たない。"}, {"text": "黒板", "is_correct": false, "explanation": "黒板は道具で、教える人の主語にはならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は教材で、主語となる人物としては文が合わない。"}], "explanations": {"先生": "「田中先生は」は、学校で数学を教える人として主語に入る。", "教室": "教室は場所で、数学を教える人の主語にすると成り立たない。", "黒板": "黒板は道具で、教える人の主語にはならない。", "教科書": "教科書は教材で、主語となる人物としては文が合わない。"}, "sentence_index": 0, "correct_answer": "先生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この先生は、ボタンを押すと三時間で書類を仕上げる。", "explanation": "先生は人を指すので、ボタンで書類を仕上げる機械の主語にはならない。"}, {"text": "来週の先生は範囲が広い。", "explanation": "先生は人を指すので、範囲の広さを言う主語にはならない。"}, {"text": "この先生は、一冊千円で売られている。", "explanation": "先生は人を指すので、値段がついて売られる物の主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35467, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先生", "is_correct": true, "explanation": "「理科の先生は」は、実験が好きな人として主語に入る。"}, {"text": "試験管", "is_correct": false, "explanation": "試験管は実験器具で、実験が好きな人の主語にはならない。"}, {"text": "顕微鏡", "is_correct": false, "explanation": "顕微鏡は観察の道具で、人物の説明の主語にはならない。"}, {"text": "薬品", "is_correct": false, "explanation": "薬品は実験に使う物質で、好きな人として主語にはならない。"}], "explanations": {"先生": "「理科の先生は」は、実験が好きな人として主語に入る。", "試験管": "試験管は実験器具で、実験が好きな人の主語にはならない。", "顕微鏡": "顕微鏡は観察の道具で、人物の説明の主語にはならない。", "薬品": "薬品は実験に使う物質で、好きな人として主語にはならない。"}, "sentence_index": 6, "correct_answer": "先生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい先生の使い方が分かり、作業が速くなった。", "explanation": "先生は人を指すので、機械の使い方の対象にはならない。"}, {"text": "この先生の表紙は派手で、目立つ。", "explanation": "先生は人を指すので、本の表紙の主語にはならない。"}, {"text": "駅前の先生は、雨に濡れて色があせた。", "explanation": "先生は人を指すので、雨に濡れて色があせる物の主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35467, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "担任の先生を、黒板に明日の宿題を書いた。", "corrected_sentence": "担任の先生が、黒板に明日の宿題を書いた。", "error_description": "主語の「先生」には「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35467, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小学校の先生を教えてもらって、漢字が書けるようになりました。", "corrected_sentence": "小学校の先生に教えてもらって、漢字が書けるようになりました。", "error_description": "「教えてもらう」で教えてくれる人は「に」で示す。「先生を」は先生を教える対象にしてしまうので誤り。「先生に教えてもらって」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37a00a04-4613-4ed0-8714-b43ebbccdc29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
