INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35476, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "「とても」という意味の言葉です。", "primary_collocate": null, "pronunciation": "とびきり", "ipa": "tobikiɾi", "syllable_count": 4, "sentences": [{"text": "今日は飛び切り寒いので、手袋をして出かけます。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "今日[きょう]は飛[と]び切[き]り寒[さむ]いので、手袋[てぶくろ]をして出[で]かけます。", "sentence_source": "generated"}, {"text": "祖母が作る煮物は、飛び切りおいしいです。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "祖母[そぼ]が作[つく]る煮物[にもの]は、飛[と]び切[き]りおいしいです。", "sentence_source": "generated"}, {"text": "彼女は飛び切り明るい笑顔で、みんなを迎えてくれました。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は飛[と]び切[き]り明[あか]るい笑顔[えがお]で、みんなを迎[むか]えてくれました。", "sentence_source": "generated"}, {"text": "誕生日に、飛び切り高いケーキを買いました。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]に、飛[と]び切[き]り高[たか]いケーキを買[か]いました。", "sentence_source": "generated"}, {"text": "飛び切り速い電車に乗ったので、予定より早く着きました。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "飛[と]び切[き]り速[はや]い電車[でんしゃ]に乗[の]ったので、予定[よてい]より早[はや]く着[つ]きました。", "sentence_source": "generated"}, {"text": "昨日は飛び切り楽しい一日で、思い出すと今も笑ってしまいます。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "昨日[きのう]は飛[と]び切[き]り楽[たの]しい一日[いちにち]で、思[おも]い出[だ]すと今[いま]も笑[わら]ってしまいます。", "sentence_source": "generated"}, {"text": "母は、お客さんが来る日は飛び切り豪華なごちそうを用意します。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "母[はは]は、お客[きゃく]さんが来[く]る日[ひ]は飛[と]び切[き]り豪華[ごうか]なごちそうを用意[ようい]します。", "sentence_source": "generated"}, {"text": "夏の海は飛び切りきれいで、写真をたくさん撮りました。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "夏[なつ]の海[うみ]は飛[と]び切[き]りきれいで、写真[しゃしん]をたくさん撮[と]りました。", "sentence_source": "generated"}, {"text": "この店では、飛び切り新鮮な魚が食べられます。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "この店[みせ]では、飛[と]び切[き]り新鮮[しんせん]な魚[さかな]が食[た]べられます。", "sentence_source": "generated"}, {"text": "彼は飛び切り頭がいいのに、運動はあまり得意ではありません。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "彼[かれ]は飛[と]び切[き]り頭[あたま]がいいのに、運動[うんどう]はあまり得意[とくい]ではありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛び切り", "label": "基本形（副詞）"}, {"form": "飛び切りの", "label": "連体形（の）"}], "register": "口語", "sense_fingerprint": "ふつうの程度をはるかに超えて「とても」「ずば抜けて」という意味を表す程度の言葉。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76303e4f-8772-4b0c-a318-4b641521f4da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35476, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飛び切り", "is_correct": true, "explanation": "正解。「とても寒い」という程度を強める副詞で、「今日は飛び切り寒い」が成り立つ。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "ゆっくりは動作の速さを表す語で、程度を表す形容詞「寒い」の前には入らない。"}, {"text": "さっと", "is_correct": false, "explanation": "さっとは素早い動作を表すので、「さっと寒い」は成り立たない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "ぐっすりは眠りの深さを表す語で、寒さの程度には使えない。"}], "explanations": {"飛び切り": "正解。「とても寒い」という程度を強める副詞で、「今日は飛び切り寒い」が成り立つ。", "ゆっくり": "ゆっくりは動作の速さを表す語で、程度を表す形容詞「寒い」の前には入らない。", "さっと": "さっとは素早い動作を表すので、「さっと寒い」は成り立たない。", "ぐっすり": "ぐっすりは眠りの深さを表す語で、寒さの程度には使えない。"}, "sentence_index": 0, "correct_answer": "飛び切り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宿題は飛び切り終わったので、もう寝よう。", "explanation": "飛び切りは程度を強める副詞で、「終わった」という完了の動作は修飾できないので不自然。"}, {"text": "飛び切り行ってください。", "explanation": "飛び切りは程度を強める副詞で、「行ってください」という行為の順序は表せないので不自然。"}, {"text": "飛び切り、駅で旧友に会った。", "explanation": "飛び切りは程度を強める副詞で、「旧友に会った」という偶然の出来事は表せないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35476, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飛び切り", "is_correct": true, "explanation": "正解。「豪華な」を強める副詞で、「飛び切り豪華な」が自然に成り立つ。"}, {"text": "黙って", "is_correct": false, "explanation": "黙っては話さないことを表すので、「黙って豪華な」は成り立たない。"}, {"text": "こっそり", "is_correct": false, "explanation": "こっそりは人目を避けて行う動作を表すので、「こっそり豪華な」は意味をなさない。"}, {"text": "しきりに", "is_correct": false, "explanation": "しきりには繰り返し行うさまを表すので、「しきりに豪華な」は成り立たない。"}], "explanations": {"飛び切り": "正解。「豪華な」を強める副詞で、「飛び切り豪華な」が自然に成り立つ。", "黙って": "黙っては話さないことを表すので、「黙って豪華な」は成り立たない。", "こっそり": "こっそりは人目を避けて行う動作を表すので、「こっそり豪華な」は意味をなさない。", "しきりに": "しきりには繰り返し行うさまを表すので、「しきりに豪華な」は成り立たない。"}, "sentence_index": 6, "correct_answer": "飛び切り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飛び切り出かけないと間に合わない。", "explanation": "飛び切りは程度を強める副詞で、「間に合わない」という時間の切迫は表せないので不自然。"}, {"text": "飛び切り電話があった。", "explanation": "飛び切りは程度を強める副詞で、「電話があった」という時点は表せないので不自然。"}, {"text": "飛び切り駅に向かった。", "explanation": "飛び切りは程度を強める副詞で、「駅に向かった」という動作の速さは表せないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35476, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は飛び切りに暑いので、帽子をかぶって出かけた。", "corrected_sentence": "今日は飛び切り暑いので、帽子をかぶって出かけた。", "error_description": "「飛び切り」は副詞なので「に」を付けず、そのまま「暑い」を直接修飾する。「飛び切りに暑い」は誤りで、正しくは「飛び切り暑い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35476, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちが作ってくれた料理は、飛び切りで美味しかった。", "corrected_sentence": "友だちが作ってくれた料理は、飛び切り美味しかった。", "error_description": "「飛び切り」は副詞なので「で」は付かない。「飛び切りで美味しい」は誤りで、正しくは「飛び切り美味しい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
