INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35477, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "程度がはなはだしいさまを表す副詞。たいへん。非常に。", "primary_collocate": null, "pronunciation": "とびきり", "ipa": "tobikiɾi", "syllable_count": 4, "sentences": [{"text": "今日は誕生日なので、飛び切りおいしいケーキを買って帰った。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "今日[きょう]は誕生日[たんじょうび]なので、飛[と]び切[き]りおいしいケーキを買[か]って帰[かえ]った。", "sentence_source": "generated"}, {"text": "彼女は飛び切り元気な声で、みんなに挨拶した。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は飛[と]び切[き]り元気[げんき]な声[こえ]で、みんなに挨拶[あいさつ]した。", "sentence_source": "generated"}, {"text": "この店のコーヒーは飛び切り安いのに、味はとても良い。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "この店[みせ]のコーヒーは飛[と]び切[き]り安[やす]いのに、味[あじ]はとても良[よ]い。", "sentence_source": "generated"}, {"text": "祖父は大切な客のために、飛び切り上等な酒を出してくれた。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "祖父[そふ]は大切[たいせつ]な客[きゃく]のために、飛[と]び切[き]り上等[じょうとう]な酒[さけ]を出[だ]してくれた。", "sentence_source": "generated"}, {"text": "市場で、飛び切り新鮮な魚を安く買うことができた。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "市場[いちば]で、飛[と]び切[き]り新鮮[しんせん]な魚[さかな]を安[やす]く買[か]うことができた。", "sentence_source": "generated"}, {"text": "優勝したお祝いに、飛び切り豪華な食事を用意した。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]したお祝[いわ]いに、飛[と]び切[き]り豪華[ごうか]な食事[しょくじ]を用意[ようい]した。", "sentence_source": "generated"}, {"text": "彼は飛び切り腕がいい料理人で、予約が三か月先まで埋まっている。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "彼[かれ]は飛[と]び切[き]り腕[うで]がいい料理人[りょうりにん]で、予約[よやく]が三[さん]か月[げつ]先[さき]まで埋[う]まっている。", "sentence_source": "generated"}, {"text": "山の上で見た星空は、飛び切りきれいだった。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]で見[み]た星空[ほしぞら]は、飛[と]び切[き]りきれいだった。", "sentence_source": "generated"}, {"text": "兄は飛び切り足が速くて、学校の大会ではいつも一位だ。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "兄[あに]は飛[と]び切[き]り足[あし]が速[はや]くて、学校[がっこう]の大会[たいかい]ではいつも一位[いちい]だ。", "sentence_source": "generated"}, {"text": "友だちに、飛び切りいい知らせがあると言われて、わくわくした。", "target_word": "飛び切り", "complexity_tier": "T3", "furigana": "友[とも]だちに、飛[と]び切[き]りいい知[し]らせがあると言[い]われて、わくわくした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛び切り", "label": "基本形"}, {"form": "飛び切りの", "label": "連体形"}], "register": "口語", "sense_fingerprint": "他と比べて抜きん出て程度が高いことを表す。飛び切りおいしい、飛び切りの笑顔など", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76303e4f-8772-4b0c-a318-4b641521f4da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35477, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飛び切り", "is_correct": true, "explanation": "正解。「おいしい」の程度を強める副詞で、「飛び切りおいしい」が自然に成り立つ。"}, {"text": "黙って", "is_correct": false, "explanation": "黙っては話さないことを表すので、「黙っておいしい」は成り立たない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "ぐっすりは眠りの深さを表す語で、味の程度には使えない。"}, {"text": "ゆっくり", "is_correct": false, "explanation": "ゆっくりは動作の速さを表す語で、「ゆっくりおいしい」は成り立たない。"}], "explanations": {"飛び切り": "正解。「おいしい」の程度を強める副詞で、「飛び切りおいしい」が自然に成り立つ。", "黙って": "黙っては話さないことを表すので、「黙っておいしい」は成り立たない。", "ぐっすり": "ぐっすりは眠りの深さを表す語で、味の程度には使えない。", "ゆっくり": "ゆっくりは動作の速さを表す語で、「ゆっくりおいしい」は成り立たない。"}, "sentence_index": 0, "correct_answer": "飛び切り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飛び切り、ここで休もう。", "explanation": "飛び切りは程度を強める副詞で、「ここで休もう」という判断は表せないので不自然。"}, {"text": "飛び切り、もう一度ここに来ます。", "explanation": "飛び切りは程度を強める副詞で、「もう一度来る」という時間の順序は表せないので不自然。"}, {"text": "友だちと飛び切り行く。", "explanation": "飛び切りは程度を強める副詞で、「友だちと行く」という同行は表せないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35477, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飛び切り", "is_correct": true, "explanation": "正解。「腕がいい」の程度を強める副詞で、「飛び切り腕がいい」が自然に成り立つ。"}, {"text": "さっと", "is_correct": false, "explanation": "さっとは素早い動作を表すので、「さっと腕がいい」は成り立たない。"}, {"text": "そっと", "is_correct": false, "explanation": "そっとは静かに行う動作を表すので、「そっと腕がいい」は意味をなさない。"}, {"text": "きっぱり", "is_correct": false, "explanation": "きっぱりは態度がはっきりしていることを表すので、「きっぱり腕がいい」は成り立たない。"}], "explanations": {"飛び切り": "正解。「腕がいい」の程度を強める副詞で、「飛び切り腕がいい」が自然に成り立つ。", "さっと": "さっとは素早い動作を表すので、「さっと腕がいい」は成り立たない。", "そっと": "そっとは静かに行う動作を表すので、「そっと腕がいい」は意味をなさない。", "きっぱり": "きっぱりは態度がはっきりしていることを表すので、「きっぱり腕がいい」は成り立たない。"}, "sentence_index": 6, "correct_answer": "飛び切り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飛び切り一言、言わせてください。", "explanation": "飛び切りは程度を強める副詞で、「一言」の位置や順序は表せないので不自然。"}, {"text": "その光は飛び切り消えた。", "explanation": "飛び切りは程度を強める副詞で、「消えた」という瞬間性は表せないので不自然。"}, {"text": "飛び切り来てね。", "explanation": "飛び切りは程度を強める副詞で、「来てね」という確実さは表せないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35477, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちの家で、飛び切りな楽しい時間を過ごした。", "corrected_sentence": "友だちの家で、飛び切り楽しい時間を過ごした。", "error_description": "「飛び切り」は副詞なので「な」を付けず、そのまま「楽しい」を修飾する。「飛び切りな」は誤りで、正しくは「飛び切り楽しい」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35477, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家族で訪ねたその店は、料理が飛び切りでおいしかった。", "corrected_sentence": "家族で訪ねたその店は、料理が飛び切りおいしかった。", "error_description": "「飛び切り」は副詞なので「で」は付かない。「飛び切りでおいしい」は誤りで、正しくは「飛び切りおいしい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35478, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黒い", "is_correct": true, "explanation": "「白」の対義語で、色の反対を表す。"}, {"text": "青い", "is_correct": false, "explanation": "別の色であり、白の対義語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す形容詞で、色の対義語ではない。"}, {"text": "辛い", "is_correct": false, "explanation": "味を表す形容詞で、色の対義語ではない。"}], "correct_answer": "黒い", "explanations": {"黒い": "「白」の対義語で、色の反対を表す。", "青い": "別の色であり、白の対義語ではない。", "重い": "重さを表す形容詞で、色の対義語ではない。", "辛い": "味を表す形容詞で、色の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
