INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35478, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "雪の色です。明るい色です。", "primary_collocate": null, "pronunciation": "しろい", "ipa": "ɕiɾoi", "syllable_count": 3, "sentences": [{"text": "白い雪の上に、小さな足あとがついています。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]い雪[ゆき]の上[うえ]に、小[ちい]さな足[あし]あとがついています。", "sentence_source": "generated"}, {"text": "冬の朝、息が白いので、寒さがよくわかります。", "target_word": "白い", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]、息[いき]が白[しろ]いので、寒[さむ]さがよくわかります。", "sentence_source": "generated"}, {"text": "白いくつは、雨の日によごれやすいです。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]いくつは、雨[あめ]の日[ひ]によごれやすいです。", "sentence_source": "generated"}, {"text": "妹は白いワンピースを着て、結婚式に行きました。", "target_word": "白い", "complexity_tier": "T3", "furigana": "妹[いもうと]は白[しろ]いワンピースを着[き]て、結婚式[けっこんしき]に行[い]きました。", "sentence_source": "generated"}, {"text": "白い紙に、赤いペンで名前を書いてください。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]い紙[かみ]に、赤[あか]いペンで名前[なまえ]を書[か]いてください。", "sentence_source": "generated"}, {"text": "山の上は雪で白いので、遠くからでもよく見えます。", "target_word": "白い", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は雪[ゆき]で白[しろ]いので、遠[とお]くからでもよく見[み]えます。", "sentence_source": "generated"}, {"text": "白い光が部屋に入って、とても明るい朝でした。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]い光[ひかり]が部屋[へや]に入[はい]って、とても明[あか]るい朝[あさ]でした。", "sentence_source": "generated"}, {"text": "白い帽子をかぶると、夏の日ざしがやわらぎます。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]い帽子[ぼうし]をかぶると、夏[なつ]の日[ひ]ざしがやわらぎます。", "sentence_source": "generated"}, {"text": "白いタオルで顔をふいたら、すっきりしました。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]いタオルで顔[かお]をふいたら、すっきりしました。", "sentence_source": "generated"}, {"text": "白い犬と黒い猫が、庭でならんで寝ています。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]い犬[いぬ]と黒[くろ]い猫[ねこ]が、庭[にわ]でならんで寝[ね]ています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "白い", "label": "基本形"}, {"form": "白く", "label": "連用形"}, {"form": "白くて", "label": "て形"}, {"form": "白かった", "label": "過去形"}, {"form": "白くない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "雪のような明るい色を表す基本的な色の形容詞(しろい)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: よごれ (Zipf 2.32)','sentence 7 above tier T2: contains vocabulary far above tier T2: やわらぎ (Zipf 1.78)']::text[], 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35478, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白い", "is_correct": true, "explanation": "連体形。後ろの名詞「雪」を修飾し、文の意味に合う。"}, {"text": "白く", "is_correct": false, "explanation": "連用形。名詞「雪」を直接修飾できない。"}, {"text": "白さ", "is_correct": false, "explanation": "名詞形。「白さ雪」とはつながらず、「の」が必要になる。"}, {"text": "白かろう", "is_correct": false, "explanation": "推量形。名詞を修飾する形ではなく、文が成り立たない。"}], "explanations": {"白い": "連体形。後ろの名詞「雪」を修飾し、文の意味に合う。", "白く": "連用形。名詞「雪」を直接修飾できない。", "白さ": "名詞形。「白さ雪」とはつながらず、「の」が必要になる。", "白かろう": "推量形。名詞を修飾する形ではなく、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "白い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この煮物は白い味つけで、ごはんによく合う。", "explanation": "ここは〈淡白〉（味があっさりしている）の意味。味の性質は〈白い〉では表せないので合わない。"}, {"text": "白い水が、川底までよく見えた。", "explanation": "ここは〈澄んだ〉の意味（透き通っている）。白い水では川底が見えないので、合わない。"}, {"text": "白い声で返事をした。", "explanation": "ここは〈明るい〉の意味（声が晴れやかな）。声には色がないので、〈白い〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35478, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白い", "is_correct": true, "explanation": "連体形。後ろの名詞「光」を修飾し、文の意味に合う。"}, {"text": "白くて", "is_correct": false, "explanation": "て形。名詞「光」の前に置けず、文が続かない。"}, {"text": "白めに", "is_correct": false, "explanation": "副詞的な形で、名詞「光」を修飾できない。"}, {"text": "白みを", "is_correct": false, "explanation": "名詞に助詞「を」が付いた形で、「光」に続く文にならない。"}], "explanations": {"白い": "連体形。後ろの名詞「光」を修飾し、文の意味に合う。", "白くて": "て形。名詞「光」の前に置けず、文が続かない。", "白めに": "副詞的な形で、名詞「光」を修飾できない。", "白みを": "名詞に助詞「を」が付いた形で、「光」に続く文にならない。"}, "sentence_index": 6, "correct_answer": "白い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "白いピンクのリボンを、髪につけた。", "explanation": "ここは〈淡い〉の意味（色がうすい）。ピンクは白色ではないので、〈白い〉では色が合わない。"}, {"text": "白い熱気に包まれ、議論は夜遅くまで続いた。", "explanation": "ここは〈白熱〉（議論の熱気が高まる）の意味。色の白さは熱気を表さないので、〈白い〉では合わない。"}, {"text": "そんな白い態度では、誰も信じてくれない。", "explanation": "ここは〈白々しい〉（見え透いてわざとらしい）の意味。態度の性質は〈白い〉では表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35478, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬の朝、白さ雪の上に、小さな足あとが残っていた。", "corrected_sentence": "冬の朝、白い雪の上に、小さな足あとが残っていた。", "error_description": "「白さ」は名詞なので、「雪」を直接修飾できない。連体修飾では「白い雪」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "白い", "is_correct": true, "explanation": "基本形。「ので」に続く述語として文の意味に合う。"}, {"text": "白く", "is_correct": false, "explanation": "連用形。「ので」の前に置けず、文が成り立たない。"}, {"text": "白かろう", "is_correct": false, "explanation": "推量形。理由を述べる「ので」の文に続かない。"}, {"text": "白ければ", "is_correct": false, "explanation": "仮定形。「ので」と続けられず、文が成り立たない。"}], "correct_form": "白い", "base_form": "白い", "form_label": "基本形", "sentence_index": 1, "explanations": {"白い": "基本形。「ので」に続く述語として文の意味に合う。", "白く": "連用形。「ので」の前に置けず、文が成り立たない。", "白かろう": "推量形。理由を述べる「ので」の文に続かない。", "白ければ": "仮定形。「ので」と続けられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35478, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝の公園で、白いの鳥が水を飲んでいた。", "corrected_sentence": "朝の公園で、白い鳥が水を飲んでいた。", "error_description": "「白いの」は名詞扱いになり、「鳥」を直接修飾できない。連体修飾では「白い鳥」とする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "白い", "is_correct": true, "explanation": "連体形。後ろの名詞「帽子」を修飾し、文の意味に合う。"}, {"text": "白くて", "is_correct": false, "explanation": "て形。名詞「帽子」の前に置けず、文が続かない。"}, {"text": "白んで", "is_correct": false, "explanation": "て形。名詞「帽子」の前に置けず、文が続かない。"}, {"text": "白かったら", "is_correct": false, "explanation": "仮定形。名詞「帽子」を修飾できず、文が成り立たない。"}], "correct_form": "白い", "base_form": "白い", "form_label": "連体形", "sentence_index": 7, "explanations": {"白い": "連体形。後ろの名詞「帽子」を修飾し、文の意味に合う。", "白くて": "て形。名詞「帽子」の前に置けず、文が続かない。", "白んで": "て形。名詞「帽子」の前に置けず、文が続かない。", "白かったら": "仮定形。名詞「帽子」を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35479, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黒い", "is_correct": true, "explanation": "「白」の対義語で、色の反対を表す。"}, {"text": "赤い", "is_correct": false, "explanation": "別の色であり、白の対義語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す形容詞で、色の対義語ではない。"}, {"text": "甘い", "is_correct": false, "explanation": "味を表す形容詞で、色の対義語ではない。"}], "correct_answer": "黒い", "explanations": {"黒い": "「白」の対義語で、色の反対を表す。", "赤い": "別の色であり、白の対義語ではない。", "重い": "重さを表す形容詞で、色の対義語ではない。", "甘い": "味を表す形容詞で、色の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35479, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黒い", "is_correct": true, "explanation": "「白」の対義語で、色の反対を表す。"}, {"text": "遅い", "is_correct": false, "explanation": "速さを表す形容詞で、色の対義語ではない。"}, {"text": "硬い", "is_correct": false, "explanation": "硬さを表す形容詞で、色の対義語ではない。"}, {"text": "太い", "is_correct": false, "explanation": "太さを表す形容詞で、色の対義語ではない。"}], "correct_answer": "黒い", "explanations": {"黒い": "「白」の対義語で、色の反対を表す。", "遅い": "速さを表す形容詞で、色の対義語ではない。", "硬い": "硬さを表す形容詞で、色の対義語ではない。", "太い": "太さを表す形容詞で、色の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35479, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "色の一つ。光をすべて反射するときの色。雪や牛乳のような色。", "primary_collocate": null, "pronunciation": "しろい", "ipa": "ɕiɾoi", "syllable_count": 3, "sentences": [{"text": "放課後の美術室で、私は白い画用紙に向き合っている。", "target_word": "白い", "complexity_tier": "T3", "furigana": "放課後[ほうかご]の美術室[びじゅつしつ]で、私[わたし]は白[しろ]い画用紙[がようし]に向[む]き合[あ]っている。", "sentence_source": "mined"}, {"text": "夜のうちに雪がふって、町じゅうが白い景色に変わりました。", "target_word": "白い", "complexity_tier": "T3", "furigana": "夜[よ]のうちに雪[ゆき]がふって、町[まち]じゅうが白[しろ]い景色[けしき]に変[か]わりました。", "sentence_source": "generated"}, {"text": "白いシャツはよごれやすいので、気をつけて着ています。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]いシャツはよごれやすいので、気[き]をつけて着[き]ています。", "sentence_source": "generated"}, {"text": "犬は白い毛をしていて、雪の中では見えにくいです。", "target_word": "白い", "complexity_tier": "T3", "furigana": "犬[いぬ]は白[しろ]い毛[け]をしていて、雪[ゆき]の中[なか]では見[み]えにくいです。", "sentence_source": "generated"}, {"text": "白いカップに、あたたかい牛乳を入れました。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]いカップに、あたたかい牛乳[ぎゅうにゅう]を入[い]れました。", "sentence_source": "generated"}, {"text": "病院の部屋は白いかべで、とても明るかったです。", "target_word": "白い", "complexity_tier": "T3", "furigana": "病院[びょういん]の部屋[へや]は白[しろ]いかべで、とても明[あか]るかったです。", "sentence_source": "generated"}, {"text": "白い雲がゆっくり動いて、空はおだやかでした。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]い雲[くも]がゆっくり動[うご]いて、空[そら]はおだやかでした。", "sentence_source": "generated"}, {"text": "白い花がさく春になると、公園に人があつまります。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]い花[はな]がさく春[はる]になると、公園[こうえん]に人[ひと]があつまります。", "sentence_source": "generated"}, {"text": "白いごはんに、梅ぼしをのせて食べます。", "target_word": "白い", "complexity_tier": "T3", "furigana": "白[しろ]いごはんに、梅[うめ]ぼしをのせて食[た]べます。", "sentence_source": "generated"}, {"text": "母がアイロンをかけた白いハンカチを、かばんに入れた。", "target_word": "白い", "complexity_tier": "T3", "furigana": "母[はは]がアイロンをかけた白[しろ]いハンカチを、かばんに入[い]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "白い", "label": "基本形"}, {"form": "白く", "label": "連用形"}, {"form": "白くて", "label": "て形"}, {"form": "白かった", "label": "過去形"}, {"form": "白くない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "雪や牛乳のような、光をすべて反射する色を表す形容詞(しろい)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: よごれ (Zipf 2.32)','sentence 8 above tier T2: contains vocabulary far above tier T2: 梅ぼし (Zipf 1.16)']::text[], 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35479, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白い", "is_correct": true, "explanation": "連体形。後ろの名詞「画用紙」を修飾でき、文の意味に合う。"}, {"text": "白く", "is_correct": false, "explanation": "連用形。名詞を直接修飾できず、「白く画用紙」は成り立たない。"}, {"text": "白くて", "is_correct": false, "explanation": "て形。名詞の前には置けず、「白くて画用紙」は続かない。"}, {"text": "白かろう", "is_correct": false, "explanation": "推量形。名詞を修飾する形ではなく、この文の流れに合わない。"}], "explanations": {"白い": "連体形。後ろの名詞「画用紙」を修飾でき、文の意味に合う。", "白く": "連用形。名詞を直接修飾できず、「白く画用紙」は成り立たない。", "白くて": "て形。名詞の前には置けず、「白くて画用紙」は続かない。", "白かろう": "推量形。名詞を修飾する形ではなく、この文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "白い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の白い言い訳は、誰も信じなかった。", "explanation": "ここは〈白々しい〉（見え透いてわざとらしい）の意味。言い訳の性質は〈白い〉では表せないので合わない。"}, {"text": "白いピンクのリボンを、髪につけた。", "explanation": "ここは〈淡い〉の意味（色がうすい）。ピンクは白色ではないので、〈白い〉では色が合わない。"}, {"text": "白い熱気に包まれ、議論は夜遅くまで続いた。", "explanation": "ここは〈白熱〉（議論の熱気が高まる）の意味。色の白さは熱気を表さないので、〈白い〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35479, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白い", "is_correct": true, "explanation": "連体形。後ろの名詞「雲」を修飾でき、文の意味に合う。"}, {"text": "白んで", "is_correct": false, "explanation": "て形。名詞「雲」を修飾できず、文が続かない。"}, {"text": "白めに", "is_correct": false, "explanation": "副詞的な形で、名詞「雲」を直接修飾できない。"}, {"text": "白さに", "is_correct": false, "explanation": "名詞形に助詞「に」が付いた形で、「雲」に続く文にならない。"}], "explanations": {"白い": "連体形。後ろの名詞「雲」を修飾でき、文の意味に合う。", "白んで": "て形。名詞「雲」を修飾できず、文が続かない。", "白めに": "副詞的な形で、名詞「雲」を直接修飾できない。", "白さに": "名詞形に助詞「に」が付いた形で、「雲」に続く文にならない。"}, "sentence_index": 6, "correct_answer": "白い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "白い味のスープを、ゆっくり飲んだ。", "explanation": "ここは〈淡白〉（味があっさりしている）の意味。味の性質は〈白い〉では表せないので合わない。"}, {"text": "白い水が、川底までよく見えた。", "explanation": "ここは〈透明〉の意味（澄んで向こうが見える）。白い水では川底が見えないので合わない。"}, {"text": "白い声で、みんなに挨拶した。", "explanation": "ここは〈明るい〉の意味（声が晴れやかな）。声には色がないので、〈白い〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35479, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜明けの空に、白な雲が浮かんでいた。", "corrected_sentence": "夜明けの空に、白い雲が浮かんでいた。", "error_description": "「白」は形容詞「白い」なので、「な」は付けられない。名詞「雲」の前では「白い雲」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "白い", "is_correct": true, "explanation": "連体形。「景色」を直接修飾し、文の意味に合う。"}, {"text": "白く", "is_correct": false, "explanation": "連用形。名詞「景色」を直接修飾できない。"}, {"text": "白くて", "is_correct": false, "explanation": "て形。名詞の前に置けず、「白くて景色」は続かない。"}, {"text": "白んで", "is_correct": false, "explanation": "て形。名詞「景色」の前に置けず、文が続かない。"}], "correct_form": "白い", "base_form": "白い", "form_label": "連体形", "sentence_index": 1, "explanations": {"白い": "連体形。「景色」を直接修飾し、文の意味に合う。", "白く": "連用形。名詞「景色」を直接修飾できない。", "白くて": "て形。名詞の前に置けず、「白くて景色」は続かない。", "白んで": "て形。名詞「景色」の前に置けず、文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35479, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "駅前の白いの花が咲いた木の下で、待ち合わせました。", "corrected_sentence": "駅前の白い花が咲いた木の下で、待ち合わせました。", "error_description": "「白いの」と「の」を付けると名詞扱いになり、「花」を直接修飾できない。連体修飾では「白い花」とする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "白い", "is_correct": true, "explanation": "連体形。後ろの名詞「花」を修飾し、文の意味に合う。"}, {"text": "白かったら", "is_correct": false, "explanation": "仮定形。名詞を修飾できず、「白かったら花」は続かない。"}, {"text": "白ければ", "is_correct": false, "explanation": "仮定形。名詞の前に置けず、文が成り立たない。"}, {"text": "白んで", "is_correct": false, "explanation": "て形。名詞「花」の前に置けず、文が続かない。"}], "correct_form": "白い", "base_form": "白い", "form_label": "連体形", "sentence_index": 7, "explanations": {"白い": "連体形。後ろの名詞「花」を修飾し、文の意味に合う。", "白かったら": "仮定形。名詞を修飾できず、「白かったら花」は続かない。", "白ければ": "仮定形。名詞の前に置けず、文が成り立たない。", "白んで": "て形。名詞「花」の前に置けず、文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35480, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「大きな船が港に入ってきた」の「が」は、船を主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "対象を示すが、「入る」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、船を主語にはできない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を表すので、文の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「大きな船が港に入ってきた」の「が」は、船を主語として示す。", "を": "対象を示すが、「入る」の主語にはならない。", "へ": "方向を表すが、船を主語にはできない。", "の": "所属や修飾を表すので、文の主語にはならない。"}, "error_tags": {"を": "対象", "へ": "方向", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35480, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「船は出ませんでした」の「は」は、船を話題として示す。"}, {"text": "に", "is_correct": false, "explanation": "「船に出ませんでした」は不自然で、「出る」と結びつかない。"}, {"text": "と", "is_correct": false, "explanation": "「船と出ませんでした」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示すので、「出る」とは結びつかない。"}], "correct_answer": "は", "explanations": {"は": "「船は出ませんでした」の「は」は、船を話題として示す。", "に": "「船に出ませんでした」は不自然で、「出る」と結びつかない。", "と": "「船と出ませんでした」は意味が通らない。", "より": "比較の基準を示すので、「出る」とは結びつかない。"}, "error_tags": {"に": "場所", "と": "相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35480, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がのったり、ものをつんだりして、水のうえをうごくのりものです。", "primary_collocate": null, "pronunciation": "ふね", "ipa": "ɸɯne", "syllable_count": 2, "sentences": [{"text": "船に乗って島へ行きました。", "target_word": "船", "complexity_tier": "T3", "furigana": "船[ふね]に乗[の]って島[しま]へ行[い]きました。", "sentence_source": "generated"}, {"text": "大きな船が港に入ってきました。", "target_word": "船", "complexity_tier": "T3", "furigana": "大[おお]きな船[ふね]が港[みなと]に入[はい]ってきました。", "sentence_source": "generated"}, {"text": "川に小さな船が浮かんでいます。", "target_word": "船", "complexity_tier": "T3", "furigana": "川[かわ]に小[ちい]さな船[ふね]が浮[う]かんでいます。", "sentence_source": "generated"}, {"text": "船は水の上を走るので、車では行けない島にも行けます。", "target_word": "船", "complexity_tier": "T3", "furigana": "船[ふね]は水[みず]の上[うえ]を走[はし]るので、車[くるま]では行[い]けない島[しま]にも行[い]けます。", "sentence_source": "generated"}, {"text": "魚をとるために、朝早く船で海に出ます。", "target_word": "船", "complexity_tier": "T3", "furigana": "魚[さかな]をとるために、朝早[あさはや]く船[ふね]で海[うみ]に出[で]ます。", "sentence_source": "generated"}, {"text": "この船には、五十人まで乗ることができます。", "target_word": "船", "complexity_tier": "T3", "furigana": "この船[ふね]には、五十人[ごじゅうにん]まで乗[の]ることができます。", "sentence_source": "generated"}, {"text": "船が大きくゆれて、少し気持ちが悪くなりました。", "target_word": "船", "complexity_tier": "T3", "furigana": "船[ふね]が大[おお]きくゆれて、少[すこ]し気持[きも]ちが悪[わる]くなりました。", "sentence_source": "generated"}, {"text": "雨が強かったので、船は出ませんでした。", "target_word": "船", "complexity_tier": "T3", "furigana": "雨[あめ]が強[つよ]かったので、船[ふね]は出[で]ませんでした。", "sentence_source": "generated"}, {"text": "父は船の絵をかくのが好きです。", "target_word": "船", "complexity_tier": "T3", "furigana": "父[ちち]は船[ふね]の絵[え]をかくのが好[す]きです。", "sentence_source": "generated"}, {"text": "荷物を船に積んで、遠い国へ送ります。", "target_word": "船", "complexity_tier": "T3", "furigana": "荷物[にもつ]を船[ふね]に積[つ]んで、遠[とお]い国[くに]へ送[おく]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "船", "label": "基本形"}], "register": "中立（丁寧体）", "sense_fingerprint": "人や荷物をのせて水の上を行く乗り物（ふね）。子ども向けのやさしい説明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d77c36-1221-46e8-9ca1-e98c3b3fa4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35480, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "船", "is_correct": true, "explanation": "「船に乗って島へ行きました」が自然に成り立つ。"}, {"text": "切符", "is_correct": false, "explanation": "「切符に乗って」は不自然で、乗り物にはならない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓に乗って」は意味が通らない。"}, {"text": "皿", "is_correct": false, "explanation": "「皿に乗って島へ行く」は意味が通らない。"}], "explanations": {"船": "「船に乗って島へ行きました」が自然に成り立つ。", "切符": "「切符に乗って」は不自然で、乗り物にはならない。", "窓": "「窓に乗って」は意味が通らない。", "皿": "「皿に乗って島へ行く」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "船"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議中、彼はずっと船を漕いでいた。", "explanation": "ここは〈居眠りする〉の意味（「船を漕ぐ」という慣用句）。乗り物の船の意味ではないので、ここは合わない。"}, {"text": "新しい計画の船に乗ることに決めた。", "explanation": "ここは〈参加する〉の意味（「船に乗る」という慣用句）。乗り物の船としては、計画に乗るとは言わない。"}, {"text": "彼はチームの船を降りた。", "explanation": "ここは〈脱退する〉の意味（「船を降りる」という慣用句）。乗り物の船の意味とは別で、ここには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35480, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "船", "is_correct": true, "explanation": "船が大きく揺れる、という文として自然に成り立つ。"}, {"text": "石", "is_correct": false, "explanation": "石が大きく揺れるのは不自然で、文が成り立たない。"}, {"text": "本", "is_correct": false, "explanation": "本が大きく揺れるのは不自然で、文が成り立たない。"}, {"text": "切手", "is_correct": false, "explanation": "切手が大きく揺れるのは不自然で、文が成り立たない。"}], "explanations": {"船": "船が大きく揺れる、という文として自然に成り立つ。", "石": "石が大きく揺れるのは不自然で、文が成り立たない。", "本": "本が大きく揺れるのは不自然で、文が成り立たない。", "切手": "切手が大きく揺れるのは不自然で、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "船"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "思わぬ提案は、まさに渡りに船だった。", "explanation": "ここは〈好都合〉の意味（「渡りに船」という慣用句）。乗り物の船の意味ではないので、ここでは船を乗り物として使う文にはならない。"}, {"text": "寒い日は、船につかってあたたまった。", "explanation": "ここは〈湯船〉の意味（ふろの湯おけ）。「湯船」と言い、「船」だけではふろの意味にはならない。乗り物の船とは別の使い方。"}, {"text": "チャンスの船に乗り遅れた。", "explanation": "ここは〈好機〉の意味（「船に乗り遅れる」という慣用句）。乗り物の船として乗り遅れる話ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35480, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "港で船が止めて、荷物をおろした。", "corrected_sentence": "港で船を止めて、荷物をおろした。", "error_description": "「止める」の目的語には助詞「を」が必要。「船が」だと船が主語になり、「止める」と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35480, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝、船を釣りに出かけた。", "corrected_sentence": "朝、船で釣りに出かけた。", "error_description": "「出かける」は自動詞で、「を」の目的語を取れない。手段を表すのは「で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35481, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「船で渡る」と、手段を表す。"}, {"text": "に", "is_correct": false, "explanation": "「船に渡る」は不自然。「に」では、船で渡るという手段の意味が出せない。"}, {"text": "を", "is_correct": false, "explanation": "「船を渡る」は、船を通過地点にできないので不自然。"}, {"text": "の", "is_correct": false, "explanation": "「船の渡る」では、文として成立しない。"}], "correct_answer": "で", "explanations": {"で": "正解。「船で渡る」と、手段を表す。", "に": "「船に渡る」は不自然。「に」では、船で渡るという手段の意味が出せない。", "を": "「船を渡る」は、船を通過地点にできないので不自然。", "の": "「船の渡る」では、文として成立しない。"}, "error_tags": {"に": "方向・場所の誤用", "を": "目的語の誤用", "の": "連体修飾の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35481, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「船が岸から離れる」と、船を主語にする。"}, {"text": "へ", "is_correct": false, "explanation": "「船へ岸から離れる」は不自然。「へ」は方向を表すが、離れる主体には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「船より岸から離れる」は、比較の意味になり文が成立しない。"}, {"text": "から", "is_correct": false, "explanation": "「船から岸から離れる」は、起点が二重になり不自然。"}], "correct_answer": "が", "explanations": {"が": "正解。「船が岸から離れる」と、船を主語にする。", "へ": "「船へ岸から離れる」は不自然。「へ」は方向を表すが、離れる主体には合わない。", "より": "「船より岸から離れる」は、比較の意味になり文が成立しない。", "から": "「船から岸から離れる」は、起点が二重になり不自然。"}, "error_tags": {"へ": "方向の誤用", "より": "比較の誤用", "から": "起点の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35481, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "水上を移動するための乗り物。水に浮かぶ構造を持ち、人や貨物を運ぶために使われる。", "primary_collocate": null, "pronunciation": "ふね", "ipa": "ɸɯne", "syllable_count": 2, "sentences": [{"text": "貨物を積んだ船が、ゆっくりと港を出ていった。", "target_word": "船", "complexity_tier": "T3", "furigana": "貨物[かもつ]を積[つ]んだ船[ふね]が、ゆっくりと港[みなと]を出[で]ていった。", "sentence_source": "generated"}, {"text": "この島へは橋がないので、船で渡るしかない。", "target_word": "船", "complexity_tier": "T3", "furigana": "この島[しま]へは橋[はし]がないので、船[ふね]で渡[わた]るしかない。", "sentence_source": "generated"}, {"text": "台風が近づいているため、今日は船の運航が中止になった。", "target_word": "船", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいているため、今日[きょう]は船[ふね]の運航[うんこう]が中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "フェリーのような大きな船は、車ごと乗客を運ぶことができる。", "target_word": "船", "complexity_tier": "T3", "furigana": "フェリーのような大[おお]きな船[ふね]は、車[くるま]ごと乗客[じょうきゃく]を運[はこ]ぶことができる。", "sentence_source": "generated"}, {"text": "昔は、船で海を渡って外国の品物が運ばれてきた。", "target_word": "船", "complexity_tier": "T3", "furigana": "昔[むかし]は、船[ふね]で海[うみ]を渡[わた]って外国[がいこく]の品物[しなもの]が運[はこ]ばれてきた。", "sentence_source": "generated"}, {"text": "古い船を修理して、観光客を乗せる計画が進んでいる。", "target_word": "船", "complexity_tier": "T3", "furigana": "古[ふる]い船[ふね]を修理[しゅうり]して、観光客[かんこうきゃく]を乗[の]せる計画[けいかく]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "荷物が多いときは、飛行機より船のほうが安く送れる。", "target_word": "船", "complexity_tier": "T3", "furigana": "荷物[にもつ]が多[おお]いときは、飛行機[ひこうき]より船[ふね]のほうが安[やす]く送[おく]れる。", "sentence_source": "generated"}, {"text": "船が岸から離れると、見送りの人たちが手を振った。", "target_word": "船", "complexity_tier": "T3", "furigana": "船[ふね]が岸[きし]から離[はな]れると、見送[みおく]りの人[ひと]たちが手[て]を振[ふ]った。", "sentence_source": "generated"}, {"text": "氷の海を進む船は、特別に厚い鉄板で造られている。", "target_word": "船", "complexity_tier": "T3", "furigana": "氷[こおり]の海[うみ]を進[すす]む船[ふね]は、特別[とくべつ]に厚[あつ]い鉄板[てっぱん]で造[つく]られている。", "sentence_source": "generated"}, {"text": "海が荒れると、船は港で出発を待つことになる。", "target_word": "船", "complexity_tier": "T3", "furigana": "海[うみ]が荒[あ]れると、船[ふね]は港[みなと]で出発[しゅっぱつ]を待[ま]つことになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "船", "label": "基本形"}], "register": "中立（常体）", "sense_fingerprint": "人や貨物を運ぶ水上の乗り物（ふね）。輸送・運航の文脈で使う説明的な語義", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d77c36-1221-46e8-9ca1-e98c3b3fa4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35481, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "船", "is_correct": true, "explanation": "正解。貨物を積んで港を出ていく乗り物として、船が入る。"}, {"text": "地図", "is_correct": false, "explanation": "地図は貨物を積めず、港を出ていくこともないので、主語として合わない。"}, {"text": "電話", "is_correct": false, "explanation": "電話は貨物を積まず、港を出ていかないので、この文の主語にはならない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は貨物を積めず、港を出ていく動きもしないので、文が成立しない。"}], "explanations": {"船": "正解。貨物を積んで港を出ていく乗り物として、船が入る。", "地図": "地図は貨物を積めず、港を出ていくこともないので、主語として合わない。", "電話": "電話は貨物を積まず、港を出ていかないので、この文の主語にはならない。", "雲": "雲は貨物を積めず、港を出ていく動きもしないので、文が成立しない。"}, "sentence_index": 0, "correct_answer": "船"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "満員の飛行機で、乗客は船の座席を探していた。", "explanation": "ここは〈飛行機〉の意味。機内の座席を探す場面なので、飛行機の座席と言い、船の座席とは言わないため合わない。"}, {"text": "駅のホームで、船が来るのを待った。", "explanation": "ここは〈電車〉の意味。駅で来るのを待つのは電車で、船は線路を走らないので合わない。"}, {"text": "試合の終盤、船が鮮やかなゴールを決めた。", "explanation": "ここは〈選手〉の意味。ゴールを決めるのは人の選手で、船は人を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35481, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "船", "is_correct": true, "explanation": "正解。「飛行機より」と比べる乗り物として、船が入る。"}, {"text": "歌", "is_correct": false, "explanation": "歌は送る対象として比べる文脈に入らず、「安く送れる」という意味も成立しない。"}, {"text": "足", "is_correct": false, "explanation": "足は荷物の輸送と比べられる対象ではないので、文が成立しない。"}, {"text": "影", "is_correct": false, "explanation": "影は送ることができず、料金を比べる文脈に合わない。"}], "explanations": {"船": "正解。「飛行機より」と比べる乗り物として、船が入る。", "歌": "歌は送る対象として比べる文脈に入らず、「安く送れる」という意味も成立しない。", "足": "足は荷物の輸送と比べられる対象ではないので、文が成立しない。", "影": "影は送ることができず、料金を比べる文脈に合わない。"}, "sentence_index": 6, "correct_answer": "船"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "通学には、この船のペダルを毎朝こいでいる。", "explanation": "ここは〈自転車〉の意味。ペダルをこぐのは自転車で、船はペダルを持たないので合わない。"}, {"text": "病院で、患者は船のベッドに寝かされた。", "explanation": "ここは〈ベッド〉の意味。寝かせる台はベッドを指し、船は病室の寝台を指さないので合わない。"}, {"text": "お風呂の船に、ゆっくり浸かった。", "explanation": "ここは〈湯船〉の意味。湯船（ゆぶね）と取り違えた言い方で、船は浴槽のことではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35481, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この村へは道がないので、船を渡るしかない。", "corrected_sentence": "この村へは道がないので、船で渡るしかない。", "error_description": "誤りは「船を渡る」の「を」。手段を表す「で」が正しい形。「を」は目的語の印なので、船を渡る対象にはできず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35481, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "霧の深い朝、船を静かに湾から出ていった。", "corrected_sentence": "霧の深い朝、船が静かに湾から出ていった。", "error_description": "誤りは「船を」。船は出ていく主体なので「が」で主語を示す必要がある。「を」だと船が出る場所のようになり、「湾から」と重なって不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35482, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「倉庫に送る」と、届け先を表す。"}, {"text": "を", "is_correct": false, "explanation": "「米を」がすでにあり、「倉庫を送ります」は誤り。"}, {"text": "の", "is_correct": false, "explanation": "「倉庫の送ります」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「倉庫と送ります」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「倉庫に送る」と、届け先を表す。", "を": "「米を」がすでにあり、「倉庫を送ります」は誤り。", "の": "「倉庫の送ります」は文として成り立たない。", "と": "「倉庫と送ります」は文として成り立たない。"}, "error_tags": {"を": "object_vs_destination", "の": "possessive_vs_destination", "と": "companion_vs_destination"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受け取る", "is_correct": true, "explanation": "送られた物を受ける意味で、「送る」の反対。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「運ぶ」は送るに近い意味で、反対ではない。"}, {"text": "届ける", "is_correct": false, "explanation": "「届ける」は送るに近い意味で、反対ではない。"}, {"text": "置く", "is_correct": false, "explanation": "「置く」は物を置く意味で、反対ではない。"}], "correct_answer": "受け取る", "explanations": {"受け取る": "送られた物を受ける意味で、「送る」の反対。", "運ぶ": "「運ぶ」は送るに近い意味で、反対ではない。", "届ける": "「届ける」は送るに近い意味で、反対ではない。", "置く": "「置く」は物を置く意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
