INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35482, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを どこかに はこぶ こと。", "primary_collocate": null, "pronunciation": "おくる", "ipa": "okɯɾɯ", "syllable_count": 3, "sentences": [{"text": "工場から店へ品物を送る。", "target_word": "送る", "complexity_tier": "T2", "furigana": "工場[こうじょう]から店[みせ]へ品物[しなもの]を送[おく]る。", "sentence_source": "generated"}, {"text": "米を畑から倉庫に送ります。", "target_word": "送ります", "complexity_tier": "T2", "furigana": "米[こめ]を畑[はたけ]から倉庫[そうこ]に送[おく]ります。", "sentence_source": "generated"}, {"text": "船で車を海外に送っている。", "target_word": "送っている", "complexity_tier": "T3", "furigana": "船[ふね]で車[くるま]を海外[かいがい]に送[おく]っている。", "sentence_source": "generated"}, {"text": "重い荷物はトラックで送った。", "target_word": "送った", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]はトラックで送[おく]った。", "sentence_source": "generated"}, {"text": "水を山の上まで送る管がある。", "target_word": "送る", "complexity_tier": "T3", "furigana": "水[みず]を山[やま]の上[うえ]まで送[おく]る管[くだ]がある。", "sentence_source": "generated"}, {"text": "部品が各地へ送られていく。", "target_word": "送られて", "complexity_tier": "T4", "furigana": "部品[ぶひん]が各地[かくち]へ送[おく]られていく。", "sentence_source": "generated"}, {"text": "野菜を冷蔵で送ってください。", "target_word": "送って", "complexity_tier": "T3", "furigana": "野菜[やさい]を冷蔵[れいぞう]で送[おく]ってください。", "sentence_source": "generated"}, {"text": "荷物を送れば、今日中に着く。", "target_word": "送れ", "complexity_tier": "T4", "furigana": "荷物[にもつ]を送[おく]れば、今日中[きょうじゅう]に着[つ]く。", "sentence_source": "generated"}, {"text": "家具を新居に送りたいです。", "target_word": "送り", "complexity_tier": "T3", "furigana": "家具[かぐ]を新居[しんきょ]に送[おく]りたいです。", "sentence_source": "generated"}, {"text": "本を図書館に送りました。", "target_word": "送りました", "complexity_tier": "T2", "furigana": "本[ほん]を図書館[としょかん]に送[おく]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "送った", "label": "活用"}, {"form": "送って", "label": "活用"}, {"form": "送られる", "label": "活用"}, {"form": "送り", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物をどこかへ運んで移す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be06c00-e07b-4845-a5a1-5b9d6c46fb56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35482, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "送る", "is_correct": true, "explanation": "正解。「おくる」は物をどこかへ運ぶという意味。"}, {"text": "おこる", "is_correct": false, "explanation": "「おこる」は二つ目の音が「こ」で、「く」と違う。"}, {"text": "おとる", "is_correct": false, "explanation": "「おとる」は二つ目の音が「と」で、「く」と違う。"}, {"text": "つくる", "is_correct": false, "explanation": "「つくる」は最初の音が「つ」で、「お」と違う。"}, {"text": "めくる", "is_correct": false, "explanation": "「めくる」は最初の音が「め」で、「お」と違う。"}], "explanations": {"送る": "正解。「おくる」は物をどこかへ運ぶという意味。", "おこる": "「おこる」は二つ目の音が「こ」で、「く」と違う。", "おとる": "「おとる」は二つ目の音が「と」で、「く」と違う。", "つくる": "「つくる」は最初の音が「つ」で、「お」と違う。", "めくる": "「めくる」は最初の音が「め」で、「お」と違う。"}, "sentence_index": null, "correct_answer": "送る"}, "level_3": {"options": [{"text": "送る", "is_correct": true, "explanation": "工場から店へ品物を運ぶ意味で、文脈に合う。"}, {"text": "作る", "is_correct": false, "explanation": "形は合うが、工場から店へ品物を作るという意味が合わない。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが、工場から店へ品物を洗うという意味が合わない。"}, {"text": "読む", "is_correct": false, "explanation": "形は合うが、工場から店へ品物を読むという意味が合わない。"}], "explanations": {"送る": "工場から店へ品物を運ぶ意味で、文脈に合う。", "作る": "形は合うが、工場から店へ品物を作るという意味が合わない。", "洗う": "形は合うが、工場から店へ品物を洗うという意味が合わない。", "読む": "形は合うが、工場から店へ品物を読むという意味が合わない。"}, "sentence_index": 0, "correct_answer": "送る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "忙しい毎日をトラックで送った。", "explanation": "「毎日を送る」は日々を過ごす別の意味で、トラックで荷物を運ぶ意味に合わない。"}, {"text": "重い荷物がトラックで送って、倉庫に着いた。", "explanation": "「送る」は他動詞なので「荷物が送って」は誤り。「荷物を送って」が正しい。"}, {"text": "重い荷物を自分の部屋の中で送った。", "explanation": "「送る」は物を別の場所へ移す意味で、部屋の中で動かすだけなら「運ぶ」「動かす」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35482, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "送る", "is_correct": true, "explanation": "正解。「おくる」は物をどこかへ運ぶという意味。"}, {"text": "おどる", "is_correct": false, "explanation": "「おどる」は二つ目の音が「ど」で、「く」と違う。"}, {"text": "おきる", "is_correct": false, "explanation": "「おきる」は二つ目の音が「き」で、「く」と違う。"}, {"text": "おちる", "is_correct": false, "explanation": "「おちる」は二つ目の音が「ち」で、「く」と違う。"}, {"text": "おりる", "is_correct": false, "explanation": "「おりる」は二つ目の音が「り」で、「く」と違う。"}], "explanations": {"送る": "正解。「おくる」は物をどこかへ運ぶという意味。", "おどる": "「おどる」は二つ目の音が「ど」で、「く」と違う。", "おきる": "「おきる」は二つ目の音が「き」で、「く」と違う。", "おちる": "「おちる」は二つ目の音が「ち」で、「く」と違う。", "おりる": "「おりる」は二つ目の音が「り」で、「く」と違う。"}, "sentence_index": null, "correct_answer": "送る"}, "level_3": {"options": [{"text": "送って", "is_correct": true, "explanation": "野菜を冷蔵で運んでほしい、という依頼の意味で文脈に合う。"}, {"text": "書いて", "is_correct": false, "explanation": "形は合うが、野菜を冷蔵で書くという意味が合わない。"}, {"text": "育てて", "is_correct": false, "explanation": "形は合うが、冷蔵で育てるという意味が合わない。"}, {"text": "切って", "is_correct": false, "explanation": "形は合うが、冷蔵で切るという意味が合わない。"}], "explanations": {"送って": "野菜を冷蔵で運んでほしい、という依頼の意味で文脈に合う。", "書いて": "形は合うが、野菜を冷蔵で書くという意味が合わない。", "育てて": "形は合うが、冷蔵で育てるという意味が合わない。", "切って": "形は合うが、冷蔵で切るという意味が合わない。"}, "sentence_index": 6, "correct_answer": "送って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本が図書館に送りました。", "explanation": "「送る」は他動詞なので「本が送りました」は誤り。「本を送りました」が正しい。"}, {"text": "楽しい休日を図書館に送りました。", "explanation": "「休日を送る」は日々を過ごす別の意味で、物を運ぶ意味に合わない。"}, {"text": "図書館を本に送りました。", "explanation": "運ぶ物は「を」、届け先は「に」。助詞が逆で、意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EX