INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35482, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "果物をトラックを工場から店へ送った。", "corrected_sentence": "果物をトラックで工場から店へ送った。", "error_description": "手段は「で」で表す。「トラックを」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "送ります", "is_correct": true, "explanation": "文末の丁寧形で、「倉庫に送ります」と正しい。"}, {"text": "送ら", "is_correct": false, "explanation": "未然形のままでは文が終わらない。"}, {"text": "送り", "is_correct": false, "explanation": "連用形のままでは文が終わらない。"}, {"text": "送られ", "is_correct": false, "explanation": "受け身の連用形のままでは文が終わらない。"}], "correct_form": "送ります", "base_form": "送る", "form_label": "丁寧形（ます形）", "sentence_index": 1, "explanations": {"送ります": "文末の丁寧形で、「倉庫に送ります」と正しい。", "送ら": "未然形のままでは文が終わらない。", "送り": "連用形のままでは文が終わらない。", "送られ": "受け身の連用形のままでは文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35482, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部品が工場から店へ送った。", "corrected_sentence": "部品を工場から店へ送った。", "error_description": "他動詞「送る」の対象は「を」で表す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "送れ", "is_correct": true, "explanation": "「ば」に続く仮定形で、正しい。"}, {"text": "送る", "is_correct": false, "explanation": "終止形に「ば」は直接つかない。"}, {"text": "送って", "is_correct": false, "explanation": "て形に「ば」は続かない。"}, {"text": "送った", "is_correct": false, "explanation": "過去形に「ば」は続かない。"}], "correct_form": "送れ", "base_form": "送る", "form_label": "仮定形（ば形）", "sentence_index": 7, "explanations": {"送れ": "「ば」に続く仮定形で、正しい。", "送る": "終止形に「ば」は直接つかない。", "送って": "て形に「ば」は続かない。", "送った": "過去形に「ば」は続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b982e327-9a99-4c05-941a-7fa6bf794c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35486, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「靴の裏に付いて」と、くっつく場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "「靴の裏を付いて」は不自然。付く場所は「に」で示す。"}, {"text": "と", "is_correct": false, "explanation": "「靴の裏と付いて」は、くっつく場所の表現として成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「靴の裏の付いて」は文として成立しない。"}], "correct_answer": "に", "explanations": {"に": "正解。「靴の裏に付いて」と、くっつく場所を表す。", "を": "「靴の裏を付いて」は不自然。付く場所は「に」で示す。", "と": "「靴の裏と付いて」は、くっつく場所の表現として成立しない。", "の": "「靴の裏の付いて」は文として成立しない。"}, "error_tags": {"を": "目的語の誤用", "と": "共同の誤用", "の": "連体修飾の誤用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "離れる", "is_correct": true, "explanation": "正解。くっついた状態の反対で、「付いた」の対義語。"}, {"text": "光る", "is_correct": false, "explanation": "光るは輝く意味で、くっつくことの対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは休む動作で、くっつく状態と関係がない。"}, {"text": "歌う", "is_correct": false, "explanation": "歌うは声を出す動作で、くっつくことの対義語ではない。"}], "correct_answer": "離れる", "explanations": {"離れる": "正解。くっついた状態の反対で、「付いた」の対義語。", "光る": "光るは輝く意味で、くっつくことの対義語ではない。", "眠る": "眠るは休む動作で、くっつく状態と関係がない。", "歌う": "歌うは声を出す動作で、くっつくことの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35486, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「ズボンに付いて」と、くっつく場所を表す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を表すので、くっつく場所には合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、くっつく場所を示す文脈に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の意味なので、場所を示す文として成立しない。"}], "correct_answer": "に", "explanations": {"に": "正解。「ズボンに付いて」と、くっつく場所を表す。", "へ": "「へ」は移動の方向を表すので、くっつく場所には合わない。", "から": "「から」は起点を表すので、くっつく場所を示す文脈に合わない。", "より": "「より」は比較の意味なので、場所を示す文として成立しない。"}, "error_tags": {"へ": "方向の誤用", "から": "起点の誤用", "より": "比較の誤用"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取れる", "is_correct": true, "explanation": "正解。泥がくっついた状態の反対で、取れるという意味。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "叫ぶは大きな声を出す動作で、くっつくことの対義語ではない。"}, {"text": "踊る", "is_correct": false, "explanation": "踊るは体を動かす動作で、くっつく状態と関係がない。"}, {"text": "数える", "is_correct": false, "explanation": "数えるは数を確かめる動作で、くっつくことの対義語ではない。"}], "correct_answer": "取れる", "explanations": {"取れる": "正解。泥がくっついた状態の反対で、取れるという意味。", "叫ぶ": "叫ぶは大きな声を出す動作で、くっつくことの対義語ではない。", "踊る": "踊るは体を動かす動作で、くっつく状態と関係がない。", "数える": "数えるは数を確かめる動作で、くっつくことの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35486, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが、他のものにくっつく。", "primary_collocate": null, "pronunciation": "つく", "ipa": "tsɯkɯ", "syllable_count": 2, "sentences": [{"text": "服に泥が付いてしまった。", "target_word": "付いて", "complexity_tier": "T3", "furigana": "服[ふく]に泥[どろ]が付[つ]いてしまった。", "sentence_source": "generated"}, {"text": "ガムが靴の裏に付いて、なかなか取れない。", "target_word": "付いて", "complexity_tier": "T3", "furigana": "ガムが靴[くつ]の裏[うら]に付[つ]いて、なかなか取[と]れない。", "sentence_source": "generated"}, {"text": "顔にご飯粒が付いている。", "target_word": "付いて", "complexity_tier": "T3", "furigana": "顔[かお]にご飯粒[はんつぶ]が付[つ]いている。", "sentence_source": "generated"}, {"text": "ペンキが乾いていなかったので、手に付いた。", "target_word": "付いた", "complexity_tier": "T3", "furigana": "ペンキが乾[かわ]いていなかったので、手[て]に付[つ]いた。", "sentence_source": "generated"}, {"text": "白いシャツにコーヒーのしみが付くと、落とすのが大変だ。", "target_word": "付く", "complexity_tier": "T3", "furigana": "白[しろ]いシャツにコーヒーのしみが付[つ]くと、落[お]とすのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "磁石には鉄のくぎが付くが、木のくぎは付かない。", "target_word": "付く", "complexity_tier": "T3", "furigana": "磁石[じしゃく]には鉄[てつ]のくぎが付[つ]くが、木[き]のくぎは付[つ]かない。", "sentence_source": "generated"}, {"text": "セロハンテープは、紙にもガラスにもよく付く。", "target_word": "付く", "complexity_tier": "T3", "furigana": "セロハンテープは、紙[かみ]にもガラスにもよく付[つ]く。", "sentence_source": "generated"}, {"text": "犬の毛が黒いズボンに付いて、目立っている。", "target_word": "付いて", "complexity_tier": "T3", "furigana": "犬[いぬ]の毛[け]が黒[くろ]いズボンに付[つ]いて、目立[めだ]っている。", "sentence_source": "generated"}, {"text": "のりが十分に付いていなかったため、封筒が開いてしまった。", "target_word": "付いて", "complexity_tier": "T3", "furigana": "のりが十分[じゅうぶん]に付[つ]いていなかったため、封筒[ふうとう]が開[ひら]いてしまった。", "sentence_source": "generated"}, {"text": "雨の日は、靴に泥が付いて玄関が汚れる。", "target_word": "付いて", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、靴[くつ]に泥[どろ]が付[つ]いて玄関[げんかん]が汚[よご]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "付く", "label": "基本形"}, {"form": "付きます", "label": "ます形"}, {"form": "付いて", "label": "て形"}, {"form": "付いた", "label": "た形"}, {"form": "付かない", "label": "ない形"}], "register": "中立（常体）", "sense_fingerprint": "汚れ・のり・毛などが他のものの表面にくっついて離れない（自動詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: 飯粒 (Zipf 1.72)']::text[], '55d77c36-1221-46e8-9ca1-e98c3b3fa4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35486, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付いて", "is_correct": true, "explanation": "正解。「服に泥が付いてしまった」と、汚れがくっつく意味で合う。"}, {"text": "作って", "is_correct": false, "explanation": "「服に泥が作ってしまった」は、泥を作る意味になり、文として不自然。"}, {"text": "笑って", "is_correct": false, "explanation": "泥は笑わないので、「服に泥が笑ってしまった」は成立しない。"}, {"text": "眠って", "is_correct": false, "explanation": "泥は眠らないので、「服に泥が眠ってしまった」は成立しない。"}], "explanations": {"付いて": "正解。「服に泥が付いてしまった」と、汚れがくっつく意味で合う。", "作って": "「服に泥が作ってしまった」は、泥を作る意味になり、文として不自然。", "笑って": "泥は笑わないので、「服に泥が笑ってしまった」は成立しない。", "眠って": "泥は眠らないので、「服に泥が眠ってしまった」は成立しない。"}, "sentence_index": 0, "correct_answer": "付いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その試合で、ついに勝負が付いた。", "explanation": "ここは〈決着がつく〉の意味（「勝負が付く」）。くっつくの意味の付くとは別。"}, {"text": "ストーブに火が付いた。", "explanation": "ここは〈点火される〉の意味（「火が付く」）。くっつくの意味の付くとは別。"}, {"text": "父は三年前、教師の職に付いた。", "explanation": "ここは〈就く〉の意味（「職に付く」）。くっつくの意味の付くとは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35486, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付く", "is_correct": true, "explanation": "正解。「紙にもガラスにもよく付く」と、セロハンテープのくっつく性質を表す。"}, {"text": "泣く", "is_correct": false, "explanation": "テープは泣かないので、「よく泣く」は成立しない。"}, {"text": "歌う", "is_correct": false, "explanation": "テープは歌わないので、文が成立しない。"}, {"text": "踊る", "is_correct": false, "explanation": "テープは踊らないので、文が成立しない。"}], "explanations": {"付く": "正解。「紙にもガラスにもよく付く」と、セロハンテープのくっつく性質を表す。", "泣く": "テープは泣かないので、「よく泣く」は成立しない。", "歌う": "テープは歌わないので、文が成立しない。", "踊る": "テープは踊らないので、文が成立しない。"}, "sentence_index": 6, "correct_answer": "付く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その件は、ついに片が付いた。", "explanation": "ここは〈解決する〉の意味（「片が付く」）。くっつくの意味の付くとは別。"}, {"text": "この絵に、高い値が付いた。", "explanation": "ここは〈値段がつく〉の意味（「値が付く」）。くっつくの意味の付くとは別。"}, {"text": "彼はすぐに嘘を付いた。", "explanation": "ここは〈嘘をつく〉の意味（「嘘を付く」）。くっつくの意味の付くとは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35486, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "白い服にインクが付けると、落ちにくい。", "corrected_sentence": "白い服にインクが付くと、落ちにくい。", "error_description": "誤りは「付けると」。インクが自分からくっつく場合は自動詞の「付く」が正しい。「付ける」は人が何かを取り付ける他動詞なので、主語がインクだと不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "付いて", "is_correct": true, "explanation": "正解。「て形」で、「、なかなか取れない」へとつなげる形。"}, {"text": "付く", "is_correct": false, "explanation": "基本形では、文を切ってしまい「、なかなか取れない」へつながらない。"}, {"text": "付きます", "is_correct": false, "explanation": "丁寧形なので、この文の普通体の流れに合わない。"}, {"text": "付かない", "is_correct": false, "explanation": "否定形になると、くっつかないという逆の意味になり、取れないという文脈と合わない。"}], "correct_form": "付いて", "base_form": "付く", "form_label": "て形", "sentence_index": 1, "explanations": {"付いて": "正解。「て形」で、「、なかなか取れない」へとつなげる形。", "付く": "基本形では、文を切ってしまい「、なかなか取れない」へつながらない。", "付きます": "丁寧形なので、この文の普通体の流れに合わない。", "付かない": "否定形になると、くっつかないという逆の意味になり、取れないという文脈と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35486, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "糊がしっかり付くたので、封筒は開かなかった。", "corrected_sentence": "糊がしっかり付いたので、封筒は開かなかった。", "error_description": "誤りは「付くた」。過去の「付いた」が正しい形。「付くた」は活用の誤りで、語形として存在しない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "付いて", "is_correct": true, "explanation": "正解。「て形」で、「、目立っている」へつながる形。"}, {"text": "付きません", "is_correct": false, "explanation": "丁寧形の否定で、「、目立っている」へ続かない。"}, {"text": "付けろ", "is_correct": false, "explanation": "「付ける」の命令形で、状態を述べる文に合わない。"}, {"text": "付こう", "is_correct": false, "explanation": "意志形になると、くっつけようという意味になり、状況説明として合わない。"}], "correct_form": "付いて", "base_form": "付く", "form_label": "て形", "sentence_index": 7, "explanations": {"付いて": "正解。「て形」で、「、目立っている」へつながる形。", "付きません": "丁寧形の否定で、「、目立っている」へ続かない。", "付けろ": "「付ける」の命令形で、状態を述べる文に合わない。", "付こう": "意志形になると、くっつけようという意味になり、状況説明として合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35487, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「スープが付く」と、付くものを主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「スープを付く」は、付くの目的語にできないので不自然。"}, {"text": "で", "is_correct": false, "explanation": "「スープで付く」は、手段の意味になり文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「スープの付く」では、文として成立しない。"}], "correct_answer": "が", "explanations": {"が": "正解。「スープが付く」と、付くものを主語として示す。", "を": "「スープを付く」は、付くの目的語にできないので不自然。", "で": "「スープで付く」は、手段の意味になり文が成立しない。", "の": "「スープの付く」では、文として成立しない。"}, "error_tags": {"を": "目的語の誤用", "で": "手段の誤用", "の": "連体修飾の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35487, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「製氷機が付いている」と、備わっているものを主語として示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、備わっているものを示す文に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の意味なので、備わっている状態の文として成立しない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、備わっている状態を示す文に合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「製氷機が付いている」と、備わっているものを主語として示す。", "へ": "「へ」は方向を表すので、備わっているものを示す文に合わない。", "より": "「より」は比較の意味なので、備わっている状態の文として成立しない。", "から": "「から」は起点を表すので、備わっている状態を示す文に合わない。"}, "error_tags": {"へ": "方向の誤用", "より": "比較の誤用", "から": "起点の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35487, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "機能や設備、おまけなどが、本体に備わっている（付属している）。", "primary_collocate": null, "pronunciation": "つく", "ipa": "tsɯkɯ", "syllable_count": 2, "sentences": [{"text": "この部屋にはバスルームが付いている。", "target_word": "付いている", "complexity_tier": "T3", "furigana": "この部屋[へや]にはバスルームが付[つ]いている。", "sentence_source": "generated"}, {"text": "セットメニューにはサラダとスープが付く。", "target_word": "付く", "complexity_tier": "T3", "furigana": "セットメニューにはサラダとスープが付[つ]く。", "sentence_source": "generated"}, {"text": "このカメラには、ケースが付いている。", "target_word": "付いている", "complexity_tier": "T3", "furigana": "このカメラには、ケースが付[つ]いている。", "sentence_source": "generated"}, {"text": "ホテルの料金には朝食が付いている。", "target_word": "付いている", "complexity_tier": "T3", "furigana": "ホテルの料金[りょうきん]には朝食[ちょうしょく]が付[つ]いている。", "sentence_source": "generated"}, {"text": "この電話には留守番機能が付いている。", "target_word": "付いている", "complexity_tier": "T3", "furigana": "この電話[でんわ]には留守番機能[るすばんきのう]が付[つ]いている。", "sentence_source": "generated"}, {"text": "新しい洗濯機には、三年間の保証が付く。", "target_word": "付く", "complexity_tier": "T3", "furigana": "新[あたら]しい洗濯機[せんたくき]には、三年間[さんねんかん]の保証[ほしょう]が付[つ]く。", "sentence_source": "generated"}, {"text": "この辞書にはCDが付いていて、発音も聞ける。", "target_word": "付いて", "complexity_tier": "T3", "furigana": "この辞書[じしょ]にはCDが付[つ]いていて、発音[はつおん]も聞[き]ける。", "sentence_source": "generated"}, {"text": "この冷蔵庫には、製氷機が付いている。", "target_word": "付いている", "complexity_tier": "T3", "furigana": "この冷蔵庫[れいぞうこ]には、製氷機[せいひょうき]が付[つ]いている。", "sentence_source": "generated"}, {"text": "チケットに座席指定が付いているので、安心だ。", "target_word": "付いている", "complexity_tier": "T3", "furigana": "チケットに座席指定[ざせきしてい]が付[つ]いているので、安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "この家には小さな庭が付いていて、家賃は少し高い。", "target_word": "付いて", "complexity_tier": "T3", "furigana": "この家[いえ]には小[ちい]さな庭[にわ]が付[つ]いていて、家賃[やちん]は少[すこ]し高[たか]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "付く", "label": "基本形"}, {"form": "付きます", "label": "ます形"}, {"form": "付いて", "label": "て形"}, {"form": "付いた", "label": "た形"}, {"form": "付かない", "label": "ない形"}], "register": "中立（常体）", "sense_fingerprint": "部屋・機能・おまけなどが本体に備わっている、付属する（自動詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d77c36-1221-46e8-9ca1-e98c3b3fa4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35487, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付いている", "is_correct": true, "explanation": "正解。「この部屋にはバスルームが付いている」と、備わっている意味で合う。"}, {"text": "笑っている", "is_correct": false, "explanation": "部屋は笑わないので、「バスルームが笑っている」は成立しない。"}, {"text": "歌っている", "is_correct": false, "explanation": "部屋は歌わないので、文が成立しない。"}, {"text": "眠っている", "is_correct": false, "explanation": "バスルームは眠らないので、文が成立しない。"}], "explanations": {"付いている": "正解。「この部屋にはバスルームが付いている」と、備わっている意味で合う。", "笑っている": "部屋は笑わないので、「バスルームが笑っている」は成立しない。", "歌っている": "部屋は歌わないので、文が成立しない。", "眠っている": "バスルームは眠らないので、文が成立しない。"}, "sentence_index": 0, "correct_answer": "付いている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ストーブに火が付いた。", "explanation": "ここは〈点火される〉の意味（「火が付く」）。備わる・付属の意味の付くとは別。"}, {"text": "父は三年前、教師の職に付いた。", "explanation": "ここは〈就く〉の意味（「職に付く」）。備わる・付属の意味の付くとは別。"}, {"text": "彼はすぐに嘘を付いた。", "explanation": "ここは〈嘘をつく〉の意味（「嘘を付く」）。備わる・付属の意味の付くとは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35487, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付いて", "is_correct": true, "explanation": "正解。「CDが付いていて」と、付属の意味で合う。"}, {"text": "泣いて", "is_correct": false, "explanation": "CDは泣かないので、「CDが泣いて」は成立しない。"}, {"text": "踊って", "is_correct": false, "explanation": "CDは踊らないので、文が成立しない。"}, {"text": "寝て", "is_correct": false, "explanation": "CDは寝ないので、「CDが寝て」は成立しない。"}], "explanations": {"付いて": "正解。「CDが付いていて」と、付属の意味で合う。", "泣いて": "CDは泣かないので、「CDが泣いて」は成立しない。", "踊って": "CDは踊らないので、文が成立しない。", "寝て": "CDは寝ないので、「CDが寝て」は成立しない。"}, "sentence_index": 6, "correct_answer": "付いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その件は、ついに片が付いた。", "explanation": "ここは〈解決する〉の意味（「片が付く」）。付属の意味の付くとは別。"}, {"text": "この絵に、高い値が付いた。", "explanation": "ここは〈値段がつく〉の意味（「値が付く」）。付属の意味の付くとは別。"}, {"text": "この企画には、批判が付いた。", "explanation": "ここは〈批判される〉の意味（「批判が付く」）。付属の意味の付くとは別。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35487, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この自転車には、ライトが付けている。", "corrected_sentence": "この自転車には、ライトが付いている。", "error_description": "誤りは「付けている」。ライトが備わっている状態は自動詞の「付いている」が正しい。「付けている」は人が取り付けている意味になり、主語のライトと合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "付く", "is_correct": true, "explanation": "正解。基本形で、「セットメニューにはサラダとスープが付く」と文を終える形。"}, {"text": "付き", "is_correct": false, "explanation": "連用形で、文を終えられない。"}, {"text": "付いて", "is_correct": false, "explanation": "て形で止まり、文が完結しない。"}, {"text": "付か", "is_correct": false, "explanation": "未然形で、文を終えられない。"}], "correct_form": "付く", "base_form": "付く", "form_label": "基本形", "sentence_index": 1, "explanations": {"付く": "正解。基本形で、「セットメニューにはサラダとスープが付く」と文を終える形。", "付き": "連用形で、文を終えられない。", "付いて": "て形で止まり、文が完結しない。", "付か": "未然形で、文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35487, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このカードには、ポイントが付くている。", "corrected_sentence": "このカードには、ポイントが付いている。", "error_description": "誤りは「付くている」。状態を表す「付いている」が正しい形。「付くている」は活用の誤りで、語形として不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "付いている", "is_correct": true, "explanation": "正解。「ている形」で、冷蔵庫に備わっている状態を表す。"}, {"text": "付かない", "is_correct": false, "explanation": "ない形で否定になり、備わっていないという意味になるため、この文の状態説明と合わない。"}, {"text": "付いた", "is_correct": false, "explanation": "た形は過去の出来事を表し、現在の備わっている状態を述べる文と合わない。"}, {"text": "付こう", "is_correct": false, "explanation": "意志形になると、付けようという意味になり、備わっている状態と合わない。"}], "correct_form": "付いている", "base_form": "付く", "form_label": "ている形", "sentence_index": 7, "explanations": {"付いている": "正解。「ている形」で、冷蔵庫に備わっている状態を表す。", "付かない": "ない形で否定になり、備わっていないという意味になるため、この文の状態説明と合わない。", "付いた": "た形は過去の出来事を表し、現在の備わっている状態を述べる文と合わない。", "付こう": "意志形になると、付けようという意味になり、備わっている状態と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35488, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「水で手を洗う」と、手段として水を使うことを表す。"}, {"text": "に", "is_correct": false, "explanation": "「水に手を洗う」は、手段の意味にならず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「水を手を洗う」は、目的語が二つになり不自然。"}, {"text": "の", "is_correct": false, "explanation": "「水の手を洗う」は、文として成立しない。"}], "correct_answer": "で", "explanations": {"で": "正解。「水で手を洗う」と、手段として水を使うことを表す。", "に": "「水に手を洗う」は、手段の意味にならず不自然。", "を": "「水を手を洗う」は、目的語が二つになり不自然。", "の": "「水の手を洗う」は、文として成立しない。"}, "error_tags": {"に": "方向・場所の誤用", "を": "目的語の重複", "の": "連体修飾の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
