INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35488, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "みずは、のむものや、あらうものに つかう、とうめいな ものです。", "primary_collocate": null, "pronunciation": "みず", "ipa": "mizɯ", "syllable_count": 2, "sentences": [{"text": "のどがかわいたので、水を飲みました。", "target_word": "水", "complexity_tier": "T3", "furigana": "のどがかわいたので、水[みず]を飲[の]みました。", "sentence_source": "generated"}, {"text": "食べる前に、水で手を洗いましょう。", "target_word": "水", "complexity_tier": "T3", "furigana": "食[た]べる前[まえ]に、水[みず]で手[て]を洗[あら]いましょう。", "sentence_source": "generated"}, {"text": "花に水をやるのは、わたしの仕事です。", "target_word": "水", "complexity_tier": "T3", "furigana": "花[はな]に水[みず]をやるのは、わたしの仕事[しごと]です。", "sentence_source": "generated"}, {"text": "川の水は冷たくて、気持ちがいいです。", "target_word": "水", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]は冷[つめ]たくて、気持[きも]ちがいいです。", "sentence_source": "generated"}, {"text": "水を火にかけると、お湯になります。", "target_word": "水", "complexity_tier": "T3", "furigana": "水[みず]を火[ひ]にかけると、お湯[ゆ]になります。", "sentence_source": "generated"}, {"text": "コップに水を入れて、花を飾りました。", "target_word": "水", "complexity_tier": "T3", "furigana": "コップに水[みず]を入[い]れて、花[はな]を飾[かざ]りました。", "sentence_source": "generated"}, {"text": "雨が降って、道に水がたまっています。", "target_word": "水", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]って、道[みち]に水[みず]がたまっています。", "sentence_source": "generated"}, {"text": "プールの水は、夏でも少し冷たいです。", "target_word": "水", "complexity_tier": "T3", "furigana": "プールの水[みず]は、夏[なつ]でも少[すこ]し冷[つめ]たいです。", "sentence_source": "generated"}, {"text": "水をこぼして、机がぬれてしまいました。", "target_word": "水", "complexity_tier": "T3", "furigana": "水[みず]をこぼして、机[つくえ]がぬれてしまいました。", "sentence_source": "generated"}, {"text": "水がなければ、人も動物も生きていけません。", "target_word": "水", "complexity_tier": "T3", "furigana": "水[みず]がなければ、人[ひと]も動物[どうぶつ]も生[い]きていけません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "水", "label": "基本形"}], "register": "中立（丁寧体）", "sense_fingerprint": "飲んだり洗ったりするのに使う、透明な液体の水（冷たい水）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d77c36-1221-46e8-9ca1-e98c3b3fa4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35488, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水", "is_correct": true, "explanation": "正解。のどが渇いたときに飲むものとして、水が入る。"}, {"text": "紙", "is_correct": false, "explanation": "紙は飲めないので、「紙を飲みました」は成立しない。"}, {"text": "石", "is_correct": false, "explanation": "石は飲めないので、「石を飲みました」は成立しない。"}, {"text": "花", "is_correct": false, "explanation": "花は飲めないので、「花を飲みました」は成立しない。"}], "explanations": {"水": "正解。のどが渇いたときに飲むものとして、水が入る。", "紙": "紙は飲めないので、「紙を飲みました」は成立しない。", "石": "石は飲めないので、「石を飲みました」は成立しない。", "花": "花は飲めないので、「花を飲みました」は成立しない。"}, "sentence_index": 0, "correct_answer": "水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二年間の努力が、水の泡になった。", "explanation": "ここは〈無駄になる〉の意味（水の泡）。慣用句で、液体の水の義項とは別の意味。"}, {"text": "彼の一言が、楽しい会の雰囲気に水を差した。", "explanation": "ここは〈邪魔をする〉の意味（水を差す）。慣用句で、液体の水の義項とは別の意味。"}, {"text": "朝から水が降って、道がぬれている。", "explanation": "ここは〈雨〉の意味。雨と取り違えた言い方で、水は空から降るものとして使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35488, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水", "is_correct": true, "explanation": "正解。道にたまるものとして、水が入る。"}, {"text": "鳥", "is_correct": false, "explanation": "鳥は道にたまらないので、文が成立しない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は道にたまらないので、文が成立しない。"}, {"text": "足", "is_correct": false, "explanation": "足は道にたまらないので、文が成立しない。"}], "explanations": {"水": "正解。道にたまるものとして、水が入る。", "鳥": "鳥は道にたまらないので、文が成立しない。", "歌": "歌は道にたまらないので、文が成立しない。", "足": "足は道にたまらないので、文が成立しない。"}, "sentence_index": 6, "correct_answer": "水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その話は、水に流して忘れよう。", "explanation": "ここは〈なかったことにする〉の意味（水に流す）。慣用句で、液体の水の義項とは別の意味。"}, {"text": "この土地は水が合って、住みやすい。", "explanation": "ここは〈体質や環境が合う〉の意味（水が合う）。慣用句で、液体の水の義項とは別の意味。"}, {"text": "最終ラップで、一位が二位に大きく水をあけた。", "explanation": "ここは〈大きく差をつける〉の意味（水をあける）。慣用句で、液体の水の義項とは別の意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35488, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喉が渇いた時は、水が一杯飲むとよい。", "corrected_sentence": "喉が渇いた時は、水を一杯飲むとよい。", "error_description": "誤りは「水が」の「が」。飲む対象は目的語なので「を」が正しい。「が」は主語の印なので、飲む動作の対象には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35488, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ペットボトルの水が一本買った。", "corrected_sentence": "ペットボトルの水を一本買った。", "error_description": "誤りは「水が」の「が」。買う対象は目的語なので「を」が正しい。「が」は主語を示すため、買う動作の対象には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35490, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「濃いコーヒーを」の「を」。入れる（淹れる）の目的語を示す格助詞で、文中に実際にある。"}, {"text": "が", "is_correct": false, "explanation": "「コーヒーが入れます」ではコーヒーが動作主になり、人が淹れるという意味にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は動詞の前に立たず、「コーヒーの入れます」は成立しない。"}, {"text": "から", "is_correct": false, "explanation": "「コーヒーから入れます」は起点を表し、淹れる対象として成立しない。"}], "correct_answer": "を", "explanations": {"を": "「濃いコーヒーを」の「を」。入れる（淹れる）の目的語を示す格助詞で、文中に実際にある。", "が": "「コーヒーが入れます」ではコーヒーが動作主になり、人が淹れるという意味にならない。", "の": "連体修飾の「の」は動詞の前に立たず、「コーヒーの入れます」は成立しない。", "から": "「コーヒーから入れます」は起点を表し、淹れる対象として成立しない。"}, "error_tags": {"が": "主語の格助詞の誤用", "の": "連体修飾の誤用", "から": "起点の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35490, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35490, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "お茶やコーヒーを、お湯を使って作ることです。", "primary_collocate": null, "pronunciation": "いれる", "ipa": "iɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "お客さんが来たので、母は温かいお茶を入れました。", "target_word": "入れました", "complexity_tier": "T3", "furigana": "お客[きゃく]さんが来[き]たので、母[はは]は温[あたた]かいお茶[ちゃ]を入[い]れました。", "sentence_source": "generated"}, {"text": "朝は眠いので、濃いコーヒーを入れます。", "target_word": "入れます", "complexity_tier": "T3", "furigana": "朝[あさ]は眠[ねむ]いので、濃[こ]いコーヒーを入[い]れます。", "sentence_source": "generated"}, {"text": "急須でお茶を入れると、いい香りがします。", "target_word": "入れる", "complexity_tier": "T3", "furigana": "急須[きゅうす]でお茶[ちゃ]を入[い]れると、いい香[かお]りがします。", "sentence_source": "generated"}, {"text": "父のために、おいしいコーヒーを入れてあげました。", "target_word": "入れて", "complexity_tier": "T3", "furigana": "父[ちち]のために、おいしいコーヒーを入[い]れてあげました。", "sentence_source": "generated"}, {"text": "熱いお湯でお茶を入れてから、少し待ちます。", "target_word": "入れて", "complexity_tier": "T3", "furigana": "熱[あつ]いお湯[ゆ]でお茶[ちゃ]を入[い]れてから、少[すこ]し待[ま]ちます。", "sentence_source": "generated"}, {"text": "妹がお茶を入れてくれたので、みんなで休みました。", "target_word": "入れて", "complexity_tier": "T3", "furigana": "妹[いもうと]がお茶[ちゃ]を入[い]れてくれたので、みんなで休[やす]みました。", "sentence_source": "generated"}, {"text": "私は毎日、会社でみんなにコーヒーを入れます。", "target_word": "入れます", "complexity_tier": "T3", "furigana": "私[わたし]は毎日[まいにち]、会社[かいしゃ]でみんなにコーヒーを入[い]れます。", "sentence_source": "generated"}, {"text": "お湯を沸かしてから、お茶を入れます。", "target_word": "入れます", "complexity_tier": "T3", "furigana": "お湯[ゆ]を沸[わ]かしてから、お茶[ちゃ]を入[い]れます。", "sentence_source": "generated"}, {"text": "ゆっくり入れたお茶は、とてもおいしいです。", "target_word": "入れた", "complexity_tier": "T3", "furigana": "ゆっくり入[い]れたお茶[ちゃ]は、とてもおいしいです。", "sentence_source": "generated"}, {"text": "寒い日は、温かい紅茶を入れて飲みます。", "target_word": "入れて", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、温[あたた]かい紅茶[こうちゃ]を入[い]れて飲[の]みます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "入れる", "label": "辞書形"}, {"form": "入れます", "label": "丁寧形"}, {"form": "入れた", "label": "過去形"}, {"form": "入れて", "label": "て形"}, {"form": "入れない", "label": "否定形"}, {"form": "入れれば", "label": "仮定形"}, {"form": "入れよう", "label": "意向形"}], "register": "丁寧", "sense_fingerprint": "お茶やコーヒーを、お湯などを使って作る(淹れる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa355574-9e18-4c72-a592-28e39dbf69ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35490, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "入れました", "is_correct": true, "explanation": "「温かいお茶を入れました」は、湯で茶を淹れるという意味で、この文脈に自然に収まる。"}, {"text": "笑いました", "is_correct": false, "explanation": "笑うは自動詞で、「お茶を」を目的語に取れないので、空欄に入らない。"}, {"text": "走りました", "is_correct": false, "explanation": "走るは移動を表す自動詞で、「温かいお茶を」の後に続かない。"}, {"text": "歌いました", "is_correct": false, "explanation": "歌うは歌を対象とする動詞で、お茶を目的語にできない。"}], "explanations": {"入れました": "「温かいお茶を入れました」は、湯で茶を淹れるという意味で、この文脈に自然に収まる。", "笑いました": "笑うは自動詞で、「お茶を」を目的語に取れないので、空欄に入らない。", "走りました": "走るは移動を表す自動詞で、「温かいお茶を」の後に続かない。", "歌いました": "歌うは歌を対象とする動詞で、お茶を目的語にできない。"}, "sentence_index": 0, "correct_answer": "入れました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父のために、大事な書類を封筒に入れてあげました。", "explanation": "ここは〈中に収める〉の意味。淹れる（湯でお茶やコーヒーを作る）とは別の使い方なので、この定義には合わない。"}, {"text": "父のために、来週の予定を入れてあげました。", "explanation": "ここは〈予定に組み込む〉の意味。淹れる（湯でお茶やコーヒーを作る）とは別なので、この定義には合わない。"}, {"text": "父のために、ホームページに写真を入れてあげました。", "explanation": "ここは〈中に組み込む・掲載する〉の意味。淹れる（湯で飲み物を作る）とは別なので、この定義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35490, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入れます", "is_correct": true, "explanation": "「みんなにコーヒーを入れます」で、会社でコーヒーを淹れて配るという意味に合う。"}, {"text": "踊ります", "is_correct": false, "explanation": "踊るは自動詞で、コーヒーを目的語にできない。"}, {"text": "寝ます", "is_correct": false, "explanation": "寝るは自動詞で、ものを目的語に取らないので空欄に入らない。"}, {"text": "吠えます", "is_correct": false, "explanation": "吠えるは動物の鳴き声を表す動詞で、コーヒーに続かない。"}], "explanations": {"入れます": "「みんなにコーヒーを入れます」で、会社でコーヒーを淹れて配るという意味に合う。", "踊ります": "踊るは自動詞で、コーヒーを目的語にできない。", "寝ます": "寝るは自動詞で、ものを目的語に取らないので空欄に入らない。", "吠えます": "吠えるは動物の鳴き声を表す動詞で、コーヒーに続かない。"}, "sentence_index": 6, "correct_answer": "入れます"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもをお風呂に入れてから、寝かせました。", "explanation": "ここは〈風呂に入らせる〉の意味。淹れるは湯で飲み物を作る意味なので、子どもを風呂に入れる場面では使わない。"}, {"text": "子どもを保育園に入れることにしました。", "explanation": "ここは〈入園させる〉の意味。淹れるは湯で飲み物を作る意味なので、この定義には合わない。"}, {"text": "玄関のポストに手紙を入れました。", "explanation": "ここは〈差し込む・投函する〉の意味。淹れるは湯で飲み物を作る意味なので、この定義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35490, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母が寒い日に、温かいお茶が入れました。", "corrected_sentence": "祖母が寒い日に、温かいお茶を入れました。", "error_description": "目的語の助詞が誤り。誤り：「お茶が入れました」、正しい形：「お茶を入れました」。「入れる（淹れる）」は人が作る動作で、お茶は「を」で示す目的語になるため、「が」にすると文が成立しない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "入れます", "is_correct": true, "explanation": "丁寧形の非過去。毎朝の習慣を述べる文に合う。"}, {"text": "入れて", "is_correct": false, "explanation": "て形は文末にならず、「濃いコーヒーを入れて。」では文が完結しない。"}, {"text": "入れたら", "is_correct": false, "explanation": "条件の「たら」で終わり、文が完結しない。"}, {"text": "入れれば", "is_correct": false, "explanation": "仮定形で条件を表す。ここは単なる習慣の叙述なので合わない。"}], "correct_form": "入れます", "base_form": "入れる", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"入れます": "丁寧形の非過去。毎朝の習慣を述べる文に合う。", "入れて": "て形は文末にならず、「濃いコーヒーを入れて。」では文が完結しない。", "入れたら": "条件の「たら」で終わり、文が完結しない。", "入れれば": "仮定形で条件を表す。ここは単なる習慣の叙述なので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35490, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎朝、家族のためにコーヒーを入れれます。", "corrected_sentence": "毎朝、家族のためにコーヒーを入れます。", "error_description": "動詞の活用形が誤り。誤り：「入れれます」、正しい形：「入れます」。「入れる」は一段動詞なので、「れ」を重ねた「入れれます」は誤りになる。習慣と丁寧さを表すには「入れます」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "入れます", "is_correct": true, "explanation": "丁寧形。手順を丁寧に説明する文の述語として合う。"}, {"text": "入れながら", "is_correct": false, "explanation": "ながら形は「〜しながら」の意で、「お茶を入れながら。」では文が完結しない。"}, {"text": "入れたり", "is_correct": false, "explanation": "たり形は動作の列挙を表し、「お茶を入れたり。」では文が完結しない。"}, {"text": "入れなければ", "is_correct": false, "explanation": "条件の「なければ」で終わり、「お茶を入れなければ。」では文が完結しない。"}], "correct_form": "入れます", "base_form": "入れる", "form_label": "丁寧形", "sentence_index": 7, "explanations": {"入れます": "丁寧形。手順を丁寧に説明する文の述語として合う。", "入れながら": "ながら形は「〜しながら」の意で、「お茶を入れながら。」では文が完結しない。", "入れたり": "たり形は動作の列挙を表し、「お茶を入れたり。」では文が完結しない。", "入れなければ": "条件の「なければ」で終わり、「お茶を入れなければ。」では文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35492, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "甘い", "is_correct": true, "explanation": "味覚の対義語。苦い味の反対である甘い味を表す。"}, {"text": "暗い", "is_correct": false, "explanation": "明るさの反対で、味覚の対義語ではない。"}, {"text": "遠い", "is_correct": false, "explanation": "距離を表す形容詞で、苦味とは対をなさない。"}, {"text": "太い", "is_correct": false, "explanation": "太さを表す形容詞で、味覚の対義語ではない。"}], "correct_answer": "甘い", "explanations": {"甘い": "味覚の対義語。苦い味の反対である甘い味を表す。", "暗い": "明るさの反対で、味覚の対義語ではない。", "遠い": "距離を表す形容詞で、苦味とは対をなさない。", "太い": "太さを表す形容詞で、味覚の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35492, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "甘い", "is_correct": true, "explanation": "味覚の対義語。苦い味と反対の味を表す。"}, {"text": "低い", "is_correct": false, "explanation": "高さを表す形容詞で、味覚の対義語ではない。"}, {"text": "軽い", "is_correct": false, "explanation": "重さを表す形容詞で、味覚の対義語ではない。"}, {"text": "広い", "is_correct": false, "explanation": "面積を表す形容詞で、味覚の対義語ではない。"}], "correct_answer": "甘い", "explanations": {"甘い": "味覚の対義語。苦い味と反対の味を表す。", "低い": "高さを表す形容詞で、味覚の対義語ではない。", "軽い": "重さを表す形容詞で、味覚の対義語ではない。", "広い": "面積を表す形容詞で、味覚の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35492, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "この食べ物や飲み物の味が、好きではない人がいるくらい、はっきりと悪い味のことです。", "primary_collocate": null, "pronunciation": "にがい", "ipa": "ɲiɡai", "syllable_count": 3, "sentences": [{"text": "ゴーヤは苦いので、子どもはあまり食べません。", "target_word": "苦い", "complexity_tier": "T3", "furigana": "ゴーヤは苦[にが]いので、子[こ]どもはあまり食[た]べません。", "sentence_source": "generated"}, {"text": "このコーヒーは砂糖を入れていないから、とても苦いです。", "target_word": "苦い", "complexity_tier": "T3", "furigana": "このコーヒーは砂糖[さとう]を入[い]れていないから、とても苦[にが]いです。", "sentence_source": "generated"}, {"text": "苦いお茶が苦手なので、私は牛乳を入れて飲みます。", "target_word": "苦い", "complexity_tier": "T3", "furigana": "苦[にが]いお茶[ちゃ]が苦手[にがて]なので、私[わたし]は牛乳[ぎゅうにゅう]を入[い]れて飲[の]みます。", "sentence_source": "generated"}, {"text": "昨日のコーヒーは苦かったですが、今日のはおいしいです。", "target_word": "苦かった", "complexity_tier": "T3", "furigana": "昨日[きのう]のコーヒーは苦[にが]かったですが、今日[きょう]のはおいしいです。", "sentence_source": "generated"}, {"text": "このチョコレートは苦くなくて、子どもでも食べられます。", "target_word": "苦くなくて", "complexity_tier": "T3", "furigana": "このチョコレートは苦[にが]くなくて、子[こ]どもでも食[た]べられます。", "sentence_source": "generated"}, {"text": "野菜が苦くて、弟は残してしまいました。", "target_word": "苦くて", "complexity_tier": "T3", "furigana": "野菜[やさい]が苦[にが]くて、弟[おとうと]は残[のこ]してしまいました。", "sentence_source": "generated"}, {"text": "ビールは苦い飲み物なので、私は好きではありません。", "target_word": "苦い", "complexity_tier": "T3", "furigana": "ビールは苦[にが]い飲[の]み物[もの]なので、私[わたし]は好[す]きではありません。", "sentence_source": "generated"}, {"text": "お茶を長く置きすぎて、苦くなりました。", "target_word": "苦く", "complexity_tier": "T3", "furigana": "お茶[ちゃ]を長[なが]く置[お]きすぎて、苦[にが]くなりました。", "sentence_source": "generated"}, {"text": "ピーマンが苦いと言って、娘は食べませんでした。", "target_word": "苦い", "complexity_tier": "T3", "furigana": "ピーマンが苦[にが]いと言[い]って、娘[むすめ]は食[た]べませんでした。", "sentence_source": "generated"}, {"text": "苦ければ、はちみつを入れてもいいですよ。", "target_word": "苦ければ", "complexity_tier": "T3", "furigana": "苦[にが]ければ、はちみつを入[い]れてもいいですよ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "苦い", "label": "辞書形"}, {"form": "苦くない", "label": "否定形"}, {"form": "苦かった", "label": "過去形"}, {"form": "苦くて", "label": "て形"}, {"form": "苦く", "label": "連用形"}, {"form": "苦ければ", "label": "仮定形"}], "register": "丁寧", "sense_fingerprint": "食べ物や飲み物の、好き嫌いが分かれる苦い味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa355574-9e18-4c72-a592-28e39dbf69ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35492, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苦い", "is_correct": true, "explanation": "食べ物の味が苦く、子どもが避けるという理由が成立する。"}, {"text": "丸い", "is_correct": false, "explanation": "形を表す形容詞で、味が理由で子どもが食べない文には合わない。"}, {"text": "速い", "is_correct": false, "explanation": "速さを表す形容詞で、味が理由で子どもが食べない文には合わない。"}, {"text": "細い", "is_correct": false, "explanation": "形状を表す形容詞で、ゴーヤの味と結びつかない。"}], "explanations": {"苦い": "食べ物の味が苦く、子どもが避けるという理由が成立する。", "丸い": "形を表す形容詞で、味が理由で子どもが食べない文には合わない。", "速い": "速さを表す形容詞で、味が理由で子どもが食べない文には合わない。", "細い": "形状を表す形容詞で、ゴーヤの味と結びつかない。"}, "sentence_index": 0, "correct_answer": "苦い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この梅干しは苦くて、子どもは食べられません。", "explanation": "ここは〈酸っぱい・塩辛い〉の場面。梅干しの味は酸味や塩気と言い、苦味とは言わない。"}, {"text": "このレモンは苦いので、そのまま食べられません。", "explanation": "ここは〈酸っぱい〉の場面。レモンの味は酸味であり、苦味とは言わない。"}, {"text": "この柿は苦いので、まだ食べられません。", "explanation": "ここは〈渋い〉の場面。舌がきゅっとする未熟な柿の味は渋いと言い、苦いとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35492, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苦い", "is_correct": true, "explanation": "味が苦いので好きではない、という理由として成立する。"}, {"text": "眠い", "is_correct": false, "explanation": "眠気を表す形容詞で、飲み物を修飾できない。"}, {"text": "固い", "is_correct": false, "explanation": "硬さを表す形容詞で、飲み物の味を表さない。"}, {"text": "早い", "is_correct": false, "explanation": "速さや時間を表す形容詞で、味の性質を表さない。"}], "explanations": {"苦い": "味が苦いので好きではない、という理由として成立する。", "眠い": "眠気を表す形容詞で、飲み物を修飾できない。", "固い": "硬さを表す形容詞で、飲み物の味を表さない。", "早い": "速さや時間を表す形容詞で、味の性質を表さない。"}, "sentence_index": 6, "correct_answer": "苦い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家計が苦いので、外食を控えています。", "explanation": "ここは〈経済的に余裕がない〉の意味で、苦しいと言う場面。味の苦いはお金の状況には使わない。"}, {"text": "このカレーは苦くて、子どもには食べられません。", "explanation": "ここは〈辛い〉の場面。カレーの刺激は辛いと言い、苦いとは言わない。"}, {"text": "このスープは苦いので、塩を足します。", "explanation": "ここは〈薄い〉の場面。味が弱いので塩を足すという文脈で、苦味の話ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35492, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ピーマンは苦いくて、子どもは食べません。", "corrected_sentence": "ピーマンは苦くて、子どもは食べません。", "error_description": "形容詞の活用形が誤り。誤り：「苦いくて」、正しい形：「苦くて」。「い」形容詞は語幹に「く」を付けてから「て」を続ける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "苦い", "is_correct": true, "explanation": "辞書形（非過去）。現在の味の状態を述べる文に合う。"}, {"text": "苦くない", "is_correct": false, "explanation": "否定形で「苦くない」となり、文の肯定の内容と逆になる。"}, {"text": "苦かろう", "is_correct": false, "explanation": "推量形は「です」に続かず、「とても苦かろうです」は文が成立しない。"}, {"text": "苦くて", "is_correct": false, "explanation": "て形は文末にならず、「とても苦くて。」では文が完結しない。"}], "correct_form": "苦い", "base_form": "苦い", "form_label": "辞書形", "sentence_index": 1, "explanations": {"苦い": "辞書形（非過去）。現在の味の状態を述べる文に合う。", "苦くない": "否定形で「苦くない」となり、文の肯定の内容と逆になる。", "苦かろう": "推量形は「です」に続かず、「とても苦かろうです」は文が成立しない。", "苦くて": "て形は文末にならず、「とても苦くて。」では文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35492, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このお茶は苦いに、子どもは飲みません。", "corrected_sentence": "このお茶は苦いので、子どもは飲みません。", "error_description": "理由を表す接続の誤り。誤り：「苦いに」、正しい形：「苦いので」。形容詞の後に「に」は続かず、理由は「ので」で示す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "苦く", "is_correct": true, "explanation": "連用形。「苦くなりました」のように変化を表す形になる。"}, {"text": "苦ければ", "is_correct": false, "explanation": "仮定形で条件を表す。実際に起きた変化には続かない。"}, {"text": "苦かろう", "is_correct": false, "explanation": "推量形で、確かな事実として述べる文に合わない。"}, {"text": "苦くなかった", "is_correct": false, "explanation": "否定の過去形で、変化の結果を述べる文の内容と逆になる。"}], "correct_form": "苦く", "base_form": "苦い", "form_label": "連用形", "sentence_index": 7, "explanations": {"苦く": "連用形。「苦くなりました」のように変化を表す形になる。", "苦ければ": "仮定形で条件を表す。実際に起きた変化には続かない。", "苦かろう": "推量形で、確かな事実として述べる文に合わない。", "苦くなかった": "否定の過去形で、変化の結果を述べる文の内容と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
