INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35493, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "口に入れたときに、舌が嫌がるような、強い不快な味を感じること。", "primary_collocate": null, "pronunciation": "にがい", "ipa": "ɲiɡai", "syllable_count": 3, "sentences": [{"text": "粉薬を飲んだら、口の中がとても苦かったです。", "target_word": "苦かった", "complexity_tier": "T3", "furigana": "粉薬[こなぐすり]を飲[の]んだら、口[くち]の中[なか]がとても苦[にが]かったです。", "sentence_source": "generated"}, {"text": "薬が苦くて、子どもは泣いてしまいました。", "target_word": "苦くて", "complexity_tier": "T3", "furigana": "薬[くすり]が苦[にが]くて、子[こ]どもは泣[な]いてしまいました。", "sentence_source": "generated"}, {"text": "口に入れた瞬間、苦い味が広がりました。", "target_word": "苦い", "complexity_tier": "T3", "furigana": "口[くち]に入[い]れた瞬間[しゅんかん]、苦[にが]い味[あじ]が広[ひろ]がりました。", "sentence_source": "generated"}, {"text": "このお茶は舌が痛くなるほど苦いです。", "target_word": "苦い", "complexity_tier": "T3", "furigana": "このお茶[ちゃ]は舌[した]が痛[いた]くなるほど苦[にが]いです。", "sentence_source": "generated"}, {"text": "焦げたパンは、口に入れると苦いです。", "target_word": "苦い", "complexity_tier": "T3", "furigana": "焦[こ]げたパンは、口[くち]に入[い]れると苦[にが]いです。", "sentence_source": "generated"}, {"text": "苦い薬を飲むとき、いつも水を多めに用意します。", "target_word": "苦い", "complexity_tier": "T3", "furigana": "苦[にが]い薬[くすり]を飲[の]むとき、いつも水[みず]を多[おお]めに用意[ようい]します。", "sentence_source": "generated"}, {"text": "冷めたコーヒーは苦く感じます。", "target_word": "苦く", "complexity_tier": "T3", "furigana": "冷[さ]めたコーヒーは苦[にが]く感[かん]じます。", "sentence_source": "generated"}, {"text": "この野菜のジュースは苦くないので、飲みやすいです。", "target_word": "苦くない", "complexity_tier": "T3", "furigana": "この野菜[やさい]のジュースは苦[にが]くないので、飲[の]みやすいです。", "sentence_source": "generated"}, {"text": "魚の内臓は苦いので、私は食べられません。", "target_word": "苦い", "complexity_tier": "T3", "furigana": "魚[さかな]の内臓[ないぞう]は苦[にが]いので、私[わたし]は食[た]べられません。", "sentence_source": "generated"}, {"text": "苦かったら、無理に飲まなくてもいいですよ。", "target_word": "苦かったら", "complexity_tier": "T3", "furigana": "苦[にが]かったら、無理[むり]に飲[の]まなくてもいいですよ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "苦い", "label": "辞書形"}, {"form": "苦くない", "label": "否定形"}, {"form": "苦かった", "label": "過去形"}, {"form": "苦くて", "label": "て形"}, {"form": "苦く", "label": "連用形"}, {"form": "苦かったら", "label": "たら形"}], "register": "丁寧", "sense_fingerprint": "口に入れた瞬間に舌が感じる、強くて不快な苦味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa355574-9e18-4c72-a592-28e39dbf69ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35493, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苦かった", "is_correct": true, "explanation": "口の中の強い不快な苦味を表す過去形で、「とても苦かったです」と自然に続く。"}, {"text": "丸かった", "is_correct": false, "explanation": "形状を表す形容詞で、口の中の味の状態には合わない。"}, {"text": "眠かった", "is_correct": false, "explanation": "眠気を表す形容詞で、口の中の味の状態には合わない。"}, {"text": "細かった", "is_correct": false, "explanation": "細さを表す形容詞で、口の中の状態として意味が通らない。"}], "explanations": {"苦かった": "口の中の強い不快な苦味を表す過去形で、「とても苦かったです」と自然に続く。", "丸かった": "形状を表す形容詞で、口の中の味の状態には合わない。", "眠かった": "眠気を表す形容詞で、口の中の味の状態には合わない。", "細かった": "細さを表す形容詞で、口の中の状態として意味が通らない。"}, "sentence_index": 0, "correct_answer": "苦かった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このレモンは苦くて、そのまま食べられません。", "explanation": "ここは〈酸っぱい〉の場面。レモンの酸味は酸っぱいと言い、苦味とは言わない。"}, {"text": "このスープは苦くて、塩気が強すぎます。", "explanation": "ここは〈塩辛い〉の場面。塩気が強いことは塩辛いと言い、苦味とは言わない。"}, {"text": "この柿は舌がきゅっとするほど苦いです。", "explanation": "ここは〈渋い〉の場面。舌がきゅっとする収斂味は渋いと言い、苦いとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35493, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苦く", "is_correct": true, "explanation": "「苦く感じます」の連用形。冷めたコーヒーの味を感じる文に合う。"}, {"text": "遠く", "is_correct": false, "explanation": "距離を表す形容詞の連用形で、味の感じ方には合わない。"}, {"text": "痛く", "is_correct": false, "explanation": "痛みを表す形容詞の連用形で、味の感覚表現には合わない。"}, {"text": "早く", "is_correct": false, "explanation": "時間や速さを表す形容詞で、味の感覚を表さない。"}], "explanations": {"苦く": "「苦く感じます」の連用形。冷めたコーヒーの味を感じる文に合う。", "遠く": "距離を表す形容詞の連用形で、味の感じ方には合わない。", "痛く": "痛みを表す形容詞の連用形で、味の感覚表現には合わない。", "早く": "時間や速さを表す形容詞で、味の感覚を表さない。"}, "sentence_index": 6, "correct_answer": "苦く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この仕事は苦かったら、無理に続けなくてもいいですよ。", "explanation": "ここは〈つらくて大変だ〉の意味で、苦しいと言う場面。味の苦いは仕事の大変さには使わない。"}, {"text": "このお湯は苦かったら、もっと沸かしてください。", "explanation": "ここは〈ぬるい〉の場面。温度はぬるいと言い、苦味とは言わない。"}, {"text": "この部屋は苦かったら、窓を開けてください。", "explanation": "ここは〈臭い〉の場面。においは臭いと言い、苦味とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35493, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "口に含んだ瞬間、苦かい味が広がりました。", "corrected_sentence": "口に含んだ瞬間、苦い味が広がりました。", "error_description": "形容詞の形が誤り。誤り：「苦かい」は存在しない形、正しい形：「苦い」。「苦い」は連体形で名詞「味」を修飾する。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "苦くて", "is_correct": true, "explanation": "て形で、後ろの「子どもは泣いてしまいました」に原因として続く。"}, {"text": "苦い", "is_correct": false, "explanation": "連体形のままでは「薬が苦い、」と続けても原因を示す接続にならず、文の流れが成立しない。"}, {"text": "苦かった", "is_correct": false, "explanation": "過去形で文を切るため、「薬が苦かった、」の後に原因の流れが続かず不自然。"}, {"text": "苦くなかった", "is_correct": false, "explanation": "否定の過去形で、「薬が苦くなかった」となり泣いた原因と意味が合わない。"}], "correct_form": "苦くて", "base_form": "苦い", "form_label": "て形", "sentence_index": 1, "explanations": {"苦くて": "て形で、後ろの「子どもは泣いてしまいました」に原因として続く。", "苦い": "連体形のままでは「薬が苦い、」と続けても原因を示す接続にならず、文の流れが成立しない。", "苦かった": "過去形で文を切るため、「薬が苦かった、」の後に原因の流れが続かず不自然。", "苦くなかった": "否定の過去形で、「薬が苦くなかった」となり泣いた原因と意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35493, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飲んでみて苦かったたら、水で薄めてください。", "corrected_sentence": "飲んでみて苦かったら、水で薄めてください。", "error_description": "条件の形が誤り。誤り：「苦かったたら」（「た」の重複）、正しい形：「苦かったら」。「たら」は過去形の後に一度だけ付ける。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "苦くない", "is_correct": true, "explanation": "否定形。「この野菜のジュースは苦くないので」と、味の否定を理由として述べる文に合う。"}, {"text": "苦く", "is_correct": false, "explanation": "連用形は「ので」に続かず、「苦くので」は文が成立しない。"}, {"text": "苦かったら", "is_correct": false, "explanation": "過去の仮定形で、現在の事実を述べる文には合わない。"}, {"text": "苦かろう", "is_correct": false, "explanation": "推量形で、確かな事実として述べる文に合わない。"}], "correct_form": "苦くない", "base_form": "苦い", "form_label": "否定形", "sentence_index": 7, "explanations": {"苦くない": "否定形。「この野菜のジュースは苦くないので」と、味の否定を理由として述べる文に合う。", "苦く": "連用形は「ので」に続かず、「苦くので」は文が成立しない。", "苦かったら": "過去の仮定形で、現在の事実を述べる文には合わない。", "苦かろう": "推量形で、確かな事実として述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35494, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「このスーパーは夜十時まで開いている」で、話題として示す。正解。"}, {"text": "に", "is_correct": false, "explanation": "「このスーパーに夜十時まで開いている」は、開いている主体として文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「このスーパーへ夜十時まで開いている」は方向を示し、主題にならない。"}, {"text": "と", "is_correct": false, "explanation": "「このスーパーと夜十時まで開いている」は並列の相手を示し、主題にならない。"}], "correct_answer": "は", "explanations": {"は": "「このスーパーは夜十時まで開いている」で、話題として示す。正解。", "に": "「このスーパーに夜十時まで開いている」は、開いている主体として文が成り立たない。", "へ": "「このスーパーへ夜十時まで開いている」は方向を示し、主題にならない。", "と": "「このスーパーと夜十時まで開いている」は並列の相手を示し、主題にならない。"}, "error_tags": {"に": "位置・帰着の格", "へ": "方向の格", "と": "並列・相手の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35494, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "「スーパーまで歩いて行く」で、移動の到達点を表す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「スーパーが歩いて行く」は、スーパーを主語にできないので不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」で、「スーパーと歩いて行く」は歩く相手が立たず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「スーパーで歩いて行く」は場所や手段を示し、到達点の意味にならない。"}], "correct_answer": "まで", "explanations": {"まで": "「スーパーまで歩いて行く」で、移動の到達点を表す。正解。", "が": "「スーパーが歩いて行く」は、スーパーを主語にできないので不自然。", "と": "並列や相手を示す「と」で、「スーパーと歩いて行く」は歩く相手が立たず文が成り立たない。", "で": "「スーパーで歩いて行く」は場所や手段を示し、到達点の意味にならない。"}, "error_tags": {"が": "主格", "で": "場所・手段の格", "と": "並列・相手の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35494, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べものや飲みものを売っているお店", "primary_collocate": null, "pronunciation": "すーぱー", "ipa": "sɯːpaː", "syllable_count": 4, "sentences": [{"text": "仕事のあとで、近くのスーパーに寄って野菜を買った。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "仕事[しごと]のあとで、近[ちか]くのスーパーに寄[よ]って野菜[やさい]を買[か]った。", "sentence_source": "generated"}, {"text": "このスーパーは夜十時まで開いているので、とても便利だ。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "このスーパーは夜[よる]十時[じゅうじ]まで開[あ]いているので、とても便利[べんり]だ。", "sentence_source": "generated"}, {"text": "スーパーで牛乳とパンを買ってから、家に帰った。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "スーパーで牛乳[ぎゅうにゅう]とパンを買[か]ってから、家[いえ]に帰[かえ]った。", "sentence_source": "generated"}, {"text": "駅の近くにスーパーがないから、買い物は少し大変だ。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くにスーパーがないから、買[か]い物[もの]は少[すこ]し大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "今日は卵が安かったので、スーパーで二つ買った。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "今日[きょう]は卵[たまご]が安[やす]かったので、スーパーで二[ふた]つ買[か]った。", "sentence_source": "generated"}, {"text": "母は毎週土曜日に、スーパーでまとめて食べ物を買う。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "母[はは]は毎週[まいしゅう]土曜日[どようび]に、スーパーでまとめて食[た]べ物[もの]を買[か]う。", "sentence_source": "generated"}, {"text": "スーパーのお茶は、コンビニより少し安いことが多い。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "スーパーのお茶[ちゃ]は、コンビニより少[すこ]し安[やす]いことが多[おお]い。", "sentence_source": "generated"}, {"text": "雨がひどかったので、スーパーまで歩いて行くのをやめた。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "雨[あめ]がひどかったので、スーパーまで歩[ある]いて行[い]くのをやめた。", "sentence_source": "generated"}, {"text": "新しいスーパーができて、町の人たちが大勢集まった。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "新[あたら]しいスーパーができて、町[まち]の人[ひと]たちが大勢[おおぜい]集[あつ]まった。", "sentence_source": "generated"}, {"text": "冷蔵庫が空だったから、夕食の前にスーパーへ走った。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]が空[から]だったから、夕食[ゆうしょく]の前[まえ]にスーパーへ走[はし]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スーパー", "label": "基本形"}, {"form": "すーぱー", "label": "ひらがな表記"}], "register": "普通体（口語・中立）", "sense_fingerprint": "食品や飲みものを買う町の店としての「スーパー」（スーパーマーケットの略）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35494, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スーパー", "is_correct": true, "explanation": "「近くのスーパーに寄る」で、食品を買う店を表す。正解。"}, {"text": "砂浜", "is_correct": false, "explanation": "「近くの砂浜に寄って野菜を買った」は、砂浜で野菜を買う意味になり不自然。"}, {"text": "博物館", "is_correct": false, "explanation": "「近くの博物館に寄って野菜を買った」は、博物館で野菜を買う意味になり不自然。"}, {"text": "公園", "is_correct": false, "explanation": "「近くの公園に寄って野菜を買った」は、公園で野菜を買う意味になり不自然。"}], "explanations": {"スーパー": "「近くのスーパーに寄る」で、食品を買う店を表す。正解。", "砂浜": "「近くの砂浜に寄って野菜を買った」は、砂浜で野菜を買う意味になり不自然。", "博物館": "「近くの博物館に寄って野菜を買った」は、博物館で野菜を買う意味になり不自然。", "公園": "「近くの公園に寄って野菜を買った」は、公園で野菜を買う意味になり不自然。"}, "sentence_index": 0, "correct_answer": "スーパー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "読みたい本を、スーパーで借りた。", "explanation": "ここは〈図書館〉の意味。スーパーでは本を借りられないので合わない。"}, {"text": "車にガソリンを、スーパーで入れた。", "explanation": "ここは〈ガソリンスタンド〉の意味。スーパーでは給油できないので合わない。"}, {"text": "給料をスーパーで預けた。", "explanation": "ここは〈銀行〉の意味。スーパーでは給料を預けることはできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35494, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スーパー", "is_correct": true, "explanation": "「スーパーのお茶」は、食品を売る店で売られている品物を指す。正解。"}, {"text": "消防車", "is_correct": false, "explanation": "乗り物で、お茶を売る場所ではないので「消防車のお茶」は成り立たない。"}, {"text": "美術館", "is_correct": false, "explanation": "「美術館のお茶」は、お茶を売る場所として不自然。"}, {"text": "動物園", "is_correct": false, "explanation": "「動物園のお茶」は、お茶を売る場所として不自然。"}], "explanations": {"スーパー": "「スーパーのお茶」は、食品を売る店で売られている品物を指す。正解。", "消防車": "乗り物で、お茶を売る場所ではないので「消防車のお茶」は成り立たない。", "美術館": "「美術館のお茶」は、お茶を売る場所として不自然。", "動物園": "「動物園のお茶」は、お茶を売る場所として不自然。"}, "sentence_index": 6, "correct_answer": "スーパー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "髪を切ってもらうため、近くのスーパーで予約した。", "explanation": "ここは〈美容院〉の意味。スーパーは髪を切る店ではないので、ここには合わない。"}, {"text": "熱が出たので、スーパーで診てもらった。", "explanation": "ここは〈病院〉の意味。スーパーでは診察は受けられないので合わない。"}, {"text": "住民票を、スーパーで取った。", "explanation": "ここは〈役所〉の意味。住民票はスーパーでは取れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35494, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仕事の帰りに、近くのスーパーを寄って野菜を買った。", "corrected_sentence": "仕事の帰りに、近くのスーパーに寄って野菜を買った。", "error_description": "正しくは「スーパーに寄る」。「寄る」は移動先に「に」を取る。「を」は目的語の格で、移動の動詞とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35494, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷蔵庫が空だったから、夕食の前にスーパーへ走って行かった。", "corrected_sentence": "冷蔵庫が空だったから、夕食の前にスーパーへ走って行った。", "error_description": "正しくは「行った」。「行く」の過去形は「行った」で、「行かった」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35495, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「買い出しに行く」の行き先を表すので、「へ」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を表すが、「行く」の行き先にはならないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すが、この文の主語は父と私なので、スーパーに付けると不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は一緒に行く相手を表すが、スーパーは相手ではないので、文の意味が通らない。"}], "correct_answer": "へ", "explanations": {"へ": "「買い出しに行く」の行き先を表すので、「へ」が正しい。", "を": "「を」は動作の対象を表すが、「行く」の行き先にはならないので合わない。", "が": "「が」は主語を表すが、この文の主語は父と私なので、スーパーに付けると不自然。", "と": "「と」は一緒に行く相手を表すが、スーパーは相手ではないので、文の意味が通らない。"}, "error_tags": {"を": "目的語の格", "が": "主格", "と": "並列・相手の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35495, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「三つある」の主語になるので、スーパーに続く「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すが、「ある」は目的語を取らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すが、存在を述べる文の主語にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「ある」の文では方向は使わないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「三つある」の主語になるので、スーパーに続く「が」が正しい。", "を": "「を」は目的語を表すが、「ある」は目的語を取らないので合わない。", "で": "「で」は場所や手段を表すが、存在を述べる文の主語にはならないので合わない。", "へ": "「へ」は方向を表すが、「ある」の文では方向は使わないので合わない。"}, "error_tags": {"を": "目的語の格", "で": "場所・手段の格", "へ": "方向の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35495, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "スーパーマーケットのこと。食料品や日用品を売っている店。", "primary_collocate": null, "pronunciation": "すーぱー", "ipa": "sɯːpaː", "syllable_count": 4, "sentences": [{"text": "洗剤やトイレットペーパーは、スーパーでまとめて買っている。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "洗剤[せんざい]やトイレットペーパーは、スーパーでまとめて買[か]っている。", "sentence_source": "generated"}, {"text": "日曜日の朝、父と一緒にスーパーへ買い出しに行った。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の朝[あさ]、父[ちち]と一緒[いっしょ]にスーパーへ買[か]い出[だ]しに行[い]った。", "sentence_source": "generated"}, {"text": "家の前のスーパーは、閉店の前に弁当が安くなる。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "家[いえ]の前[まえ]のスーパーは、閉店[へいてん]の前[まえ]に弁当[べんとう]が安[やす]くなる。", "sentence_source": "generated"}, {"text": "スーパーのレジが込んでいたので、少し待たされた。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "スーパーのレジが込[こ]んでいたので、少[すこ]し待[ま]たされた。", "sentence_source": "generated"}, {"text": "私はスーパーで働いていて、毎日野菜を棚に並べている。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "私[わたし]はスーパーで働[はたら]いていて、毎日[まいにち]野菜[やさい]を棚[たな]に並[なら]べている。", "sentence_source": "generated"}, {"text": "大きなスーパーには、食料品のほかに日用品もそろっている。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "大[おお]きなスーパーには、食料品[しょくりょうひん]のほかに日用品[にちようひん]もそろっている。", "sentence_source": "generated"}, {"text": "姉はスーパーの袋を持って、ゆっくり坂を上ってきた。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "姉[あね]はスーパーの袋[ふくろ]を持[も]って、ゆっくり坂[さか]を上[のぼ]ってきた。", "sentence_source": "generated"}, {"text": "この町には、肉も魚も安く買えるスーパーが三つある。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "この町[まち]には、肉[にく]も魚[さかな]も安[やす]く買[か]えるスーパーが三[みっ]つある。", "sentence_source": "generated"}, {"text": "買い忘れたものを思い出して、もう一度スーパーに戻った。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "買[か]い忘[わす]れたものを思[おも]い出[だ]して、もう一度[いちど]スーパーに戻[もど]った。", "sentence_source": "generated"}, {"text": "スーパーのチラシを見て、安い日を選んで買い物に行く。", "target_word": "スーパー", "complexity_tier": "T3", "furigana": "スーパーのチラシを見[み]て、安[やす]い日[ひ]を選[えら]んで買[か]い物[もの]に行[い]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スーパー", "label": "基本形"}, {"form": "すーぱー", "label": "ひらがな表記"}], "register": "普通体（口語・中立）", "sense_fingerprint": "食料品と日用品をそろえた大きな店、スーパーマーケットの略としての「スーパー」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35495, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スーパー", "is_correct": true, "explanation": "「洗剤やトイレットペーパーをまとめて買う」場所として、スーパーマーケットが自然に入る。"}, {"text": "電車", "is_correct": false, "explanation": "電車は買い物をする場所ではないので、「電車でまとめて買っている」は成り立たない。"}, {"text": "病院", "is_correct": false, "explanation": "病院で洗剤やトイレットペーパーを買うことはないので、この文の場所として合わない。"}, {"text": "図書館", "is_correct": false, "explanation": "図書館は本を借りる場所で、日用品を買う場所ではないので、この文脈に入らない。"}], "explanations": {"スーパー": "「洗剤やトイレットペーパーをまとめて買う」場所として、スーパーマーケットが自然に入る。", "電車": "電車は買い物をする場所ではないので、「電車でまとめて買っている」は成り立たない。", "病院": "病院で洗剤やトイレットペーパーを買うことはないので、この文の場所として合わない。", "図書館": "図書館は本を借りる場所で、日用品を買う場所ではないので、この文脈に入らない。"}, "sentence_index": 0, "correct_answer": "スーパー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新曲のお披露目で、スーパーのステージにバンドが立って演奏した。", "explanation": "ここは〈ライブ会場〉の意味。〈スーパー〉は食料品を売る店なので、演奏の舞台の意味では使わない。"}, {"text": "雨が上がったので、庭のスーパーに洗濯物を干した。", "explanation": "ここは〈物干し場〉の意味。〈スーパー〉は店を指すので、洗濯物を干す場所の意味には使わない。"}, {"text": "毎週日曜日、駅前の広場でスーパーが開かれる。", "explanation": "ここは〈市場〉の意味。〈スーパー〉は常設の店なので、臨時の催しとして開かれるものには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35495, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スーパー", "is_correct": true, "explanation": "「袋」の前に入り、買い物で得た袋を表す語として自然に入る。"}, {"text": "教室", "is_correct": false, "explanation": "教室の袋を持ち歩くという場面は文脈に合わず、この文の袋として不自然。"}, {"text": "消防車", "is_correct": false, "explanation": "乗り物で、買い物の袋として文脈に合わず「消防車の袋」は成り立たない。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱は持ち歩く袋とは結びつかず、買い物の文脈に合わないので「電柱の袋」は成り立たない。"}], "explanations": {"スーパー": "「袋」の前に入り、買い物で得た袋を表す語として自然に入る。", "教室": "教室の袋を持ち歩くという場面は文脈に合わず、この文の袋として不自然。", "消防車": "乗り物で、買い物の袋として文脈に合わず「消防車の袋」は成り立たない。", "電柱": "電柱は持ち歩く袋とは結びつかず、買い物の文脈に合わないので「電柱の袋」は成り立たない。"}, "sentence_index": 6, "correct_answer": "スーパー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝ぐせがひどかったので、スーパーで髪を切ってもらった。", "explanation": "ここは〈理髪店〉の意味。髪を切る店は〈スーパーマーケット〉ではないので、〈スーパー〉は合わない。"}, {"text": "古い新聞を調べるために、スーパーで縮刷版を借りた。", "explanation": "ここは〈図書館〉の意味。資料を借りられるのは図書館で、食料品を売る〈スーパーマーケット〉では借りられないので合わない。"}, {"text": "熱が出たので、スーパーで診察を受けた。", "explanation": "ここは〈病院〉の意味。診察を受けるのは医療機関で、食料品を売る〈スーパーマーケット〉の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35495, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は、スーパーに野菜を買って帰る。", "corrected_sentence": "週末は、スーパーで野菜を買って帰る。", "error_description": "買い物をする場所を表す「で」が正しいのに「に」になっている。「に」は行き先や到着点を表すので、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35495, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方、スーパーを牛乳を買った。", "corrected_sentence": "夕方、スーパーで牛乳を買った。", "error_description": "買い物をする場所を表す「で」が正しいのに「を」になっている。「を」は動作の対象を表すので、場所には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35500, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「買う」の目的語として「雑誌を」が自然。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を表すので、「雑誌で一冊買いました」は意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「雑誌に一冊買いました」では目的語が示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すので、「雑誌へ一冊買いました」は文に合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「買う」の目的語として「雑誌を」が自然。", "で": "場所や手段を表すので、「雑誌で一冊買いました」は意味が通らない。", "に": "「雑誌に一冊買いました」では目的語が示せず、文が成り立たない。", "へ": "方向を表すので、「雑誌へ一冊買いました」は文に合わない。"}, "error_tags": {"で": "場所・手段の格", "に": "与格・到達点の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35500, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "ばかり", "options": [{"text": "ばかり", "is_correct": true, "explanation": "正解。「雑誌ばかり読む」として、ひたすら雑誌を読む意味になる。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」で、「車の雑誌が読んでいます」では雑誌が読む主体になり不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同を表すので、「雑誌と読んでいます」は文の意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、「雑誌の読んでいます」は文が成り立たない。"}], "correct_answer": "ばかり", "explanations": {"ばかり": "正解。「雑誌ばかり読む」として、ひたすら雑誌を読む意味になる。", "が": "主格の「が」で、「車の雑誌が読んでいます」では雑誌が読む主体になり不自然。", "と": "共同を表すので、「雑誌と読んでいます」は文の意味が通らない。", "の": "連体修飾の「の」で、「雑誌の読んでいます」は文が成り立たない。"}, "error_tags": {"が": "主格", "と": "共同の格", "の": "連体修飾の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35500, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ざっしは、おはなしやしゃしんがのっているほんです。", "primary_collocate": null, "pronunciation": "ざっし", "ipa": "d͡zaɕːi", "syllable_count": 3, "sentences": [{"text": "私は毎月、料理の雑誌を買います。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "私[わたし]は毎月[まいつき]、料理[りょうり]の雑誌[ざっし]を買[か]います。", "sentence_source": "generated"}, {"text": "駅の本屋で雑誌を一冊買いました。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "駅[えき]の本屋[ほんや]で雑誌[ざっし]を一冊[いっさつ]買[か]いました。", "sentence_source": "generated"}, {"text": "この雑誌には、きれいな写真がたくさんのっています。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "この雑誌[ざっし]には、きれいな写真[しゃしん]がたくさんのっています。", "sentence_source": "generated"}, {"text": "病院で待つあいだ、雑誌を読んでいました。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "病院[びょういん]で待[ま]つあいだ、雑誌[ざっし]を読[よ]んでいました。", "sentence_source": "generated"}, {"text": "妹は好きな歌手が表紙の雑誌を集めています。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "妹[いもうと]は好[す]きな歌手[かしゅ]が表紙[ひょうし]の雑誌[ざっし]を集[あつ]めています。", "sentence_source": "generated"}, {"text": "図書館で古い雑誌を借りて、おもしろい話を読みました。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "図書館[としょかん]で古[ふる]い雑誌[ざっし]を借[か]りて、おもしろい話[はなし]を読[よ]みました。", "sentence_source": "generated"}, {"text": "雑誌の中の写真を見て、旅行に行きたくなりました。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "雑誌[ざっし]の中[なか]の写真[しゃしん]を見[み]て、旅行[りょこう]に行[い]きたくなりました。", "sentence_source": "generated"}, {"text": "兄は車の雑誌ばかり読んでいます。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "兄[あに]は車[くるま]の雑誌[ざっし]ばかり読[よ]んでいます。", "sentence_source": "generated"}, {"text": "この雑誌は軽いので、かばんに入れても重くありません。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "この雑誌[ざっし]は軽[かる]いので、かばんに入[い]れても重[おも]くありません。", "sentence_source": "generated"}, {"text": "机の上に雑誌が三冊おいてあります。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に雑誌[ざっし]が三冊[さんさつ]おいてあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雑誌", "label": "基本形"}], "register": "neutral (everyday spoken)", "sense_fingerprint": "magazine as a physical book with stories and photos, simple everyday sense", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35500, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雑誌", "is_correct": true, "explanation": "正解。「料理の雑誌を買う」として自然。"}, {"text": "切手", "is_correct": false, "explanation": "「料理の切手」は意味が通らず、文に合わない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "「料理の洗濯機を買う」は意味が通らず、文に合わない。"}, {"text": "電池", "is_correct": false, "explanation": "「料理の電池を買う」は意味が通らず、文に合わない。"}], "explanations": {"雑誌": "正解。「料理の雑誌を買う」として自然。", "切手": "「料理の切手」は意味が通らず、文に合わない。", "洗濯機": "「料理の洗濯機を買う」は意味が通らず、文に合わない。", "電池": "「料理の電池を買う」は意味が通らず、文に合わない。"}, "sentence_index": 0, "correct_answer": "雑誌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、雑誌に予定を書きます。", "explanation": "ここは〈手帳〉の意味。雑誌は印刷物で、予定を書き込む用途には使わないので合わない。"}, {"text": "暗い山道で、雑誌で足元を照らしました。", "explanation": "ここは〈懐中電灯〉の意味。雑誌は足元を照らす道具ではないので合わない。"}, {"text": "新しく入った人の名前を、雑誌に書きました。", "explanation": "ここは〈名簿〉の意味。雑誌には名前を登録しないので、名前を書く先としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35500, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雑誌", "is_correct": true, "explanation": "正解。「雑誌の中の写真」として自然で、旅行に行きたくなる文脈に合う。"}, {"text": "掃除機", "is_correct": false, "explanation": "家電で、「掃除機の中の写真」を見て旅行に行きたくなる文脈には合わない。"}, {"text": "体温計", "is_correct": false, "explanation": "測定器で、「体温計の中の写真」は文脈に合わない。"}, {"text": "卵", "is_correct": false, "explanation": "食材で、「卵の中の写真」は旅行の文脈に合わない。"}], "explanations": {"雑誌": "正解。「雑誌の中の写真」として自然で、旅行に行きたくなる文脈に合う。", "掃除機": "家電で、「掃除機の中の写真」を見て旅行に行きたくなる文脈には合わない。", "体温計": "測定器で、「体温計の中の写真」は文脈に合わない。", "卵": "食材で、「卵の中の写真」は旅行の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "雑誌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、新聞受けから雑誌を取って、一面の記事を読みます。", "explanation": "ここは〈新聞〉の意味。毎朝届いて一面に記事が載る紙面は新聞なので、定期的に発行される雑誌には合わない。"}, {"text": "知らない言葉に出会ったら、雑誌を引いて意味を調べます。", "explanation": "ここは〈辞書〉の意味。言葉の意味を調べるときに引くのは辞書で、雑誌は引く対象ではないので合わない。"}, {"text": "旅行先では、雑誌を広げて、道路の地図記号を確かめます。", "explanation": "ここは〈地図〉の意味。道路の記号を確かめるために広げるのは地図で、雑誌は道案内には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35500, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は毎週、駅前の雑誌で買います。", "corrected_sentence": "私は毎週、駅前の雑誌を買います。", "error_description": "「買う」の目的語には「を」が必要。「で」だと場所や手段になり、雑誌を買う意味にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35500, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は車の雑誌ばかり食べています。", "corrected_sentence": "妹は車の雑誌ばかり読んでいます。", "error_description": "雑誌は「読む」ものなので、「食べる」とは組み合わない。動詞の選び方が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35501, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "正解。「雑誌の記事」と所属を示す連体修飾の「の」。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」で、「雑誌が記事を読んで」は意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「雑誌に記事を読んで」では所属が示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「雑誌へ記事」は文に合わない。"}], "correct_answer": "の", "explanations": {"の": "正解。「雑誌の記事」と所属を示す連体修飾の「の」。", "が": "主格の「が」で、「雑誌が記事を読んで」は意味が通らない。", "に": "「雑誌に記事を読んで」では所属が示せず、文が成り立たない。", "へ": "方向を表す助詞で、「雑誌へ記事」は文に合わない。"}, "error_tags": {"が": "主格", "に": "与格・到達点の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35501, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「雑誌を見ました」の目的語として「を」。"}, {"text": "と", "is_correct": false, "explanation": "共同を表すので、「雑誌と、順番を待ちながら見ました」は意味が通りにくい。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、「雑誌の、順番を待ちながら」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、「雑誌より順番を待ちながら見ました」は文に合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「雑誌を見ました」の目的語として「を」。", "と": "共同を表すので、「雑誌と、順番を待ちながら見ました」は意味が通りにくい。", "の": "連体修飾の「の」で、「雑誌の、順番を待ちながら」は文が成り立たない。", "より": "比較の助詞で、「雑誌より順番を待ちながら見ました」は文に合わない。"}, "error_tags": {"と": "共同の格", "の": "連体修飾の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35501, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "雑誌とは、定期的に発行される、様々な記事や写真などを載せた出版物です。", "primary_collocate": null, "pronunciation": "ざっし", "ipa": "d͡zaɕːi", "syllable_count": 3, "sentences": [{"text": "この雑誌は毎週木曜日に発行されます。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "この雑誌[ざっし]は毎週[まいしゅう]木曜日[もくようび]に発行[はっこう]されます。", "sentence_source": "generated"}, {"text": "雑誌の記事を読んで、新しい店を知りました。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "雑誌[ざっし]の記事[きじ]を読[よ]んで、新[あたら]しい店[みせ]を知[し]りました。", "sentence_source": "generated"}, {"text": "彼女のインタビューが、有名な雑誌に載りました。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のインタビューが、有名[ゆうめい]な雑誌[ざっし]に載[の]りました。", "sentence_source": "generated"}, {"text": "雑誌には広告が多いので、値段が安く抑えられています。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "雑誌[ざっし]には広告[こうこく]が多[おお]いので、値段[ねだん]が安[やす]く抑[おさ]えられています。", "sentence_source": "generated"}, {"text": "先月の雑誌はもう売り切れてしまいました。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "先月[せんげつ]の雑誌[ざっし]はもう売[う]り切[き]れてしまいました。", "sentence_source": "generated"}, {"text": "母は定期的に雑誌を購読しています。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "母[はは]は定期的[ていきてき]に雑誌[ざっし]を購読[こうどく]しています。", "sentence_source": "generated"}, {"text": "写真家は、自分の作品が雑誌の表紙になって喜びました。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "写真家[しゃしんか]は、自分[じぶん]の作品[さくひん]が雑誌[ざっし]の表紙[ひょうし]になって喜[よろこ]びました。", "sentence_source": "generated"}, {"text": "美容院に置いてある雑誌を、順番を待ちながら見ました。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "美容院[びよういん]に置[お]いてある雑誌[ざっし]を、順番[じゅんばん]を待[ま]ちながら見[み]ました。", "sentence_source": "generated"}, {"text": "最近は紙の雑誌を買う人が減っています。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "最近[さいきん]は紙[かみ]の雑誌[ざっし]を買[か]う人[ひと]が減[へ]っています。", "sentence_source": "generated"}, {"text": "雑誌の編集者は、記事の内容を何度も確認します。", "target_word": "雑誌", "complexity_tier": "T3", "furigana": "雑誌[ざっし]の編集者[へんしゅうしゃ]は、記事[きじ]の内容[ないよう]を何度[なんど]も確認[かくにん]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "雑誌", "label": "基本形"}], "register": "neutral (slightly formal)", "sense_fingerprint": "magazine as a periodical publication issued regularly with various articles and photos", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35501, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雑誌", "is_correct": true, "explanation": "正解。定期的に発行される出版物として「この雑誌は毎週木曜日に発行されます」が自然。"}, {"text": "電池", "is_correct": false, "explanation": "「この電池は毎週木曜日に発行される」は意味が通らない。"}, {"text": "洗濯機", "is_correct": false, "explanation": "「この洗濯機は毎週木曜日に発行される」は意味が通らない。"}, {"text": "体温計", "is_correct": false, "explanation": "「この体温計は毎週木曜日に発行される」は意味が通らない。"}], "explanations": {"雑誌": "正解。定期的に発行される出版物として「この雑誌は毎週木曜日に発行されます」が自然。", "電池": "「この電池は毎週木曜日に発行される」は意味が通らない。", "洗濯機": "「この洗濯機は毎週木曜日に発行される」は意味が通らない。", "体温計": "「この体温計は毎週木曜日に発行される」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "雑誌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、玄関から雑誌を取ってきて、天気予報欄を読みます。", "explanation": "ここは〈新聞〉の意味。毎朝届いて天気予報欄がある紙は新聞なので、週刊や月刊の雑誌には合わない。"}, {"text": "改札で雑誌を見せて、電車に乗りました。", "explanation": "ここは〈切符〉の意味。改札で見せて乗車する紙は切符で、雑誌は乗車の証明にはならないので合わない。"}, {"text": "封筒に雑誌を貼って、郵便局から送りました。", "explanation": "ここは〈切手〉の意味。郵便料金として貼るのは切手で、雑誌を貼って料金にする用途はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35501, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雑誌", "is_correct": true, "explanation": "正解。作品が飾られる出版物として「雑誌の表紙」が自然。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、「冷蔵庫の表紙」とは言わないので文に合わない。"}, {"text": "郵便局", "is_correct": false, "explanation": "建物の名前で、表紙を持たないので文に合わない。"}, {"text": "教室", "is_correct": false, "explanation": "場所の名詞で、表紙を持たないので文に合わない。"}], "explanations": {"雑誌": "正解。作品が飾られる出版物として「雑誌の表紙」が自然。", "冷蔵庫": "家電で、「冷蔵庫の表紙」とは言わないので文に合わない。", "郵便局": "建物の名前で、表紙を持たないので文に合わない。", "教室": "場所の名詞で、表紙を持たないので文に合わない。"}, "sentence_index": 6, "correct_answer": "雑誌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、雑誌に作物の出来を書き込みます。", "explanation": "ここは〈日誌〉の意味。毎日の作業や作物の出来を書き残すのは日誌で、雑誌に書き込む用途ではないので合わない。"}, {"text": "柱の長さを、雑誌で測ります。", "explanation": "ここは〈定規〉の意味。長さを測るのは定規で、雑誌は長さを測る道具ではないので合わない。"}, {"text": "患者に雑誌を渡して、薬の飲み方を書き込みます。", "explanation": "ここは〈処方箋〉の意味。薬の飲み方を書いて患者に渡すのは処方箋で、雑誌は薬の指示には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35501, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雑誌を毎月第一月曜日に発行されます。", "corrected_sentence": "雑誌は毎月第一月曜日に発行されます。", "error_description": "受け身の「発行されます」の主語には「は」が必要。「を」だと目的語となり、受け身の文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35501, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人は、私の写真が雑誌を表紙に載ったと教えてくれました。", "corrected_sentence": "友人は、私の写真が雑誌の表紙に載ったと教えてくれました。", "error_description": "「雑誌の表紙」の「の」が正しいのに、「を」になっている。「雑誌を表紙に載った」では雑誌が目的語になり、表紙との関係が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35502, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「水を一杯」の「を」。飲むの目的語を示す格助詞で、文中に実際にある。"}, {"text": "が", "is_correct": false, "explanation": "「水が飲みます」では水が動作主になり、人が飲むという意味にならない。"}, {"text": "に", "is_correct": false, "explanation": "「水に飲みます」は意味が通らず、飲む対象として成立しない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は動詞の前に立たず、「水の一杯飲みます」は成立しない。"}], "correct_answer": "を", "explanations": {"を": "「水を一杯」の「を」。飲むの目的語を示す格助詞で、文中に実際にある。", "が": "「水が飲みます」では水が動作主になり、人が飲むという意味にならない。", "に": "「水に飲みます」は意味が通らず、飲む対象として成立しない。", "の": "連体修飾の「の」は動詞の前に立たず、「水の一杯飲みます」は成立しない。"}, "error_tags": {"が": "主語の格助詞の誤用", "に": "方向・相手の誤用", "の": "連体修飾の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35502, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「お茶を飲んで」の「を」。飲むの目的語を示す格助詞で、直前に実際にある。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は体言につくため、「お茶の飲んで」は文が成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は動詞の目的語にならず、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は飲む対象を示せず、「お茶へ飲んで」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「お茶を飲んで」の「を」。飲むの目的語を示す格助詞で、直前に実際にある。", "の": "連体修飾の「の」は体言につくため、「お茶の飲んで」は文が成立しない。", "より": "比較の「より」は動詞の目的語にならず、文が成立しない。", "へ": "方向を表す「へ」は飲む対象を示せず、「お茶へ飲んで」は不自然。"}, "error_tags": {"の": "連体修飾の誤用", "より": "比較の誤用", "へ": "方向の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35502, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "口から中に入れて、のどを通しておなかに入れること。", "primary_collocate": null, "pronunciation": "のむ", "ipa": "nomɯ", "syllable_count": 2, "sentences": [{"text": "熱が出たので、朝ごはんのあとに薬を飲みました。", "target_word": "飲みました", "complexity_tier": "T3", "furigana": "熱[ねつ]が出[で]たので、朝[あさ]ごはんのあとに薬[くすり]を飲[の]みました。", "sentence_source": "generated"}, {"text": "毎朝、起きてすぐに水を一杯飲みます。", "target_word": "飲みます", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、起[お]きてすぐに水[みず]を一杯[いっぱい]飲[の]みます。", "sentence_source": "generated"}, {"text": "薬を飲むとき、私はいつもコップの水を使います。", "target_word": "飲む", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]むとき、私[わたし]はいつもコップの水[みず]を使[つか]います。", "sentence_source": "generated"}, {"text": "のどがかわいたので、冷たい水を飲みたいです。", "target_word": "飲みたい", "complexity_tier": "T3", "furigana": "のどがかわいたので、冷[つめ]たい水[みず]を飲[の]みたいです。", "sentence_source": "generated"}, {"text": "寝る前に温かい牛乳を飲むと、よく眠れます。", "target_word": "飲む", "complexity_tier": "T3", "furigana": "寝[ね]る前[まえ]に温[あたた]かい牛乳[ぎゅうにゅう]を飲[の]むと、よく眠[ねむ]れます。", "sentence_source": "generated"}, {"text": "風邪をひいたときは、薬を飲んで早く寝ます。", "target_word": "飲んで", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいたときは、薬[くすり]を飲[の]んで早[はや]く寝[ね]ます。", "sentence_source": "generated"}, {"text": "錠剤が大きくて、子どもは飲めませんでした。", "target_word": "飲めませんでした", "complexity_tier": "T3", "furigana": "錠剤[じょうざい]が大[おお]きくて、子[こ]どもは飲[の]めませんでした。", "sentence_source": "generated"}, {"text": "食事のあとに、お茶を飲んでゆっくり休みました。", "target_word": "飲んで", "complexity_tier": "T3", "furigana": "食事[しょくじ]のあとに、お茶[ちゃ]を飲[の]んでゆっくり休[やす]みました。", "sentence_source": "generated"}, {"text": "母に言われて、まずい薬を我慢して飲みました。", "target_word": "飲みました", "complexity_tier": "T3", "furigana": "母[はは]に言[い]われて、まずい薬[くすり]を我慢[がまん]して飲[の]みました。", "sentence_source": "generated"}, {"text": "運動のあとは、水を飲まないと体に悪いです。", "target_word": "飲まない", "complexity_tier": "T3", "furigana": "運動[うんどう]のあとは、水[みず]を飲[の]まないと体[からだ]に悪[わる]いです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲む", "label": "辞書形"}, {"form": "飲みます", "label": "丁寧形"}, {"form": "飲んだ", "label": "過去形"}, {"form": "飲んで", "label": "て形"}, {"form": "飲まない", "label": "否定形"}, {"form": "飲めば", "label": "仮定形"}, {"form": "飲もう", "label": "意向形"}, {"form": "飲める", "label": "可能形"}], "register": "丁寧", "sense_fingerprint": "水や薬などを口に入れ、のどを通して胃に送る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa355574-9e18-4c72-a592-28e39dbf69ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35502, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飲みました", "is_correct": true, "explanation": "「薬を飲みました」で、体に薬を入れる行為として空欄に合う。"}, {"text": "歌いました", "is_correct": false, "explanation": "歌うは歌を対象とする動詞で、薬を目的語にできない。"}, {"text": "踊りました", "is_correct": false, "explanation": "踊るは自動詞で、薬を目的語に取れない。"}, {"text": "泳ぎました", "is_correct": false, "explanation": "泳ぐは移動を表す自動詞で、薬に続かない。"}], "explanations": {"飲みました": "「薬を飲みました」で、体に薬を入れる行為として空欄に合う。", "歌いました": "歌うは歌を対象とする動詞で、薬を目的語にできない。", "踊りました": "踊るは自動詞で、薬を目的語に取れない。", "泳ぎました": "泳ぐは移動を表す自動詞で、薬に続かない。"}, "sentence_index": 0, "correct_answer": "飲みました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "頭が痛いので、パンを飲みたいです。", "explanation": "ここは〈食べる〉の場面。パンは食べるもので、飲むとは言わない。"}, {"text": "お腹がすいたので、ご飯を飲みたいです。", "explanation": "ここは〈食べる〉の場面。ご飯は食べるもので、飲むとは言わない。"}, {"text": "ストレスがたまって、煙草を飲みたいです。", "explanation": "ここは〈吸う〉の場面。煙草は吸うもので、飲むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35502, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飲めませんでした", "is_correct": true, "explanation": "「子どもは飲めませんでした」で、大きな錠剤を飲めなかったという理由に合う。"}, {"text": "登れませんでした", "is_correct": false, "explanation": "登るは場所への移動を表し、錠剤に続かない。"}, {"text": "走れませんでした", "is_correct": false, "explanation": "走るは移動を表す自動詞で、錠剤を対象にできない。"}, {"text": "叫べませんでした", "is_correct": false, "explanation": "叫ぶは声を出す動作で、錠剤を目的語にできない。"}], "explanations": {"飲めませんでした": "「子どもは飲めませんでした」で、大きな錠剤を飲めなかったという理由に合う。", "登れませんでした": "登るは場所への移動を表し、錠剤に続かない。", "走れませんでした": "走るは移動を表す自動詞で、錠剤を対象にできない。", "叫べませんでした": "叫ぶは声を出す動作で、錠剤を目的語にできない。"}, "sentence_index": 6, "correct_answer": "飲めませんでした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テストの範囲を飲んで、覚えました。", "explanation": "ここは〈覚え込む〉の場面。範囲を覚えるのは飲むとは言わない。"}, {"text": "ガムをよく飲んで、口の中をさっぱりさせます。", "explanation": "ここは〈噛む〉の場面。ガムは噛むもので、飲むとは言わない。"}, {"text": "花の香りを飲んで、気持ちを落ち着けます。", "explanation": "ここは〈嗅ぐ〉の場面。香りは嗅ぐもので、飲むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35502, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝起きてから、お水が飲みました。", "corrected_sentence": "朝起きてから、お水を飲みました。", "error_description": "目的語の助詞が誤り。誤り：「お水が飲みました」、正しい形：「お水を飲みました」。「飲む」の目的語は「を」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "飲みます", "is_correct": true, "explanation": "丁寧形。毎朝の習慣を丁寧に述べる文に合う。"}, {"text": "飲んで", "is_correct": false, "explanation": "て形は文末にならず、「水を一杯飲んで。」では文が完結しない。"}, {"text": "飲んだら", "is_correct": false, "explanation": "条件の「たら」で終わり、文が完結しない。"}, {"text": "飲めば", "is_correct": false, "explanation": "仮定形で条件を表すが、ここは単なる習慣の叙述なので合わない。"}], "correct_form": "飲みます", "base_form": "飲む", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"飲みます": "丁寧形。毎朝の習慣を丁寧に述べる文に合う。", "飲んで": "て形は文末にならず、「水を一杯飲んで。」では文が完結しない。", "飲んだら": "条件の「たら」で終わり、文が完結しない。", "飲めば": "仮定形で条件を表すが、ここは単なる習慣の叙述なので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35502, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お酒を飲まなないで、早く寝ましょう。", "corrected_sentence": "お酒を飲まないで、早く寝ましょう。", "error_description": "否定の活用形が誤り。誤り：「飲まなない」（「な」の重複）、正しい形：「飲まないで」。「飲まない」の後に「で」を続けて、飲まないことを表す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "飲んで", "is_correct": true, "explanation": "て形。「お茶を飲んでゆっくり休みました」のように、動作を続けて述べる形になる。"}, {"text": "飲もう", "is_correct": false, "explanation": "意向形で意志を表すため、過去の出来事を述べる文に合わない。"}, {"text": "飲んだ", "is_correct": false, "explanation": "過去形の後に「ゆっくり休みました」が直接続かず、文が成立しない。"}, {"text": "飲みたい", "is_correct": false, "explanation": "希望を表す形で、実際に飲んだという出来事と合わない。"}], "correct_form": "飲んで", "base_form": "飲む", "form_label": "て形", "sentence_index": 7, "explanations": {"飲んで": "て形。「お茶を飲んでゆっくり休みました」のように、動作を続けて述べる形になる。", "飲もう": "意向形で意志を表すため、過去の出来事を述べる文に合わない。", "飲んだ": "過去形の後に「ゆっくり休みました」が直接続かず、文が成立しない。", "飲みたい": "希望を表す形で、実際に飲んだという出来事と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35503, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「冷たいジュースを飲みたい」で、飲みたい対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「ジュースに飲みたくなります」は成り立たず、相手や帰着点の意味にもならない。"}, {"text": "で", "is_correct": false, "explanation": "「ジュースで飲みたい」は手段の意味にもならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は飲む対象には使えず、「ジュースへ飲みたい」は不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。「冷たいジュースを飲みたい」で、飲みたい対象を示す。", "に": "「ジュースに飲みたくなります」は成り立たず、相手や帰着点の意味にもならない。", "で": "「ジュースで飲みたい」は手段の意味にもならず、不自然。", "へ": "方向を表す「へ」は飲む対象には使えず、「ジュースへ飲みたい」は不自然。"}, "error_tags": {"に": "相手・帰着点", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35503, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。「飲むといい」の条件を表す「と」で、飲むことが望ましいという意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「飲むにいいです」は成り立たず、動詞に続けられない。"}, {"text": "で", "is_correct": false, "explanation": "「飲むでいいです」は文法的に成り立たず、この位置では使えない。"}, {"text": "を", "is_correct": false, "explanation": "「飲むをいいです」は成り立たず、動詞に直接続けられない。"}], "correct_answer": "と", "explanations": {"と": "正解。「飲むといい」の条件を表す「と」で、飲むことが望ましいという意味になる。", "に": "「飲むにいいです」は成り立たず、動詞に続けられない。", "で": "「飲むでいいです」は文法的に成り立たず、この位置では使えない。", "を": "「飲むをいいです」は成り立たず、動詞に直接続けられない。"}, "error_tags": {"に": "場所・時点", "で": "手段・場所", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35503, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "液体を口に入れて、のどを通して体内に取り入れる。", "primary_collocate": null, "pronunciation": "のむ", "ipa": "nomɯ", "syllable_count": 2, "sentences": [{"text": "朝ごはんのとき、父はいつもコーヒーを飲みます。", "target_word": "飲みます", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんのとき、父[ちち]はいつもコーヒーを飲[の]みます。", "sentence_source": "generated"}, {"text": "暑い日は、冷たいジュースを飲みたくなります。", "target_word": "飲みたく", "complexity_tier": "T3", "furigana": "暑[あつ]い日[ひ]は、冷[つめ]たいジュースを飲[の]みたくなります。", "sentence_source": "generated"}, {"text": "友だちと喫茶店でお茶を飲みながら話しました。", "target_word": "飲みながら", "complexity_tier": "T3", "furigana": "友[とも]だちと喫茶店[きっさてん]でお茶[ちゃ]を飲[の]みながら話[はな]しました。", "sentence_source": "generated"}, {"text": "弟は牛乳が好きで、毎日二本飲みます。", "target_word": "飲みます", "complexity_tier": "T3", "furigana": "弟[おとうと]は牛乳[ぎゅうにゅう]が好[す]きで、毎日[まいにち]二本[にほん]飲[の]みます。", "sentence_source": "generated"}, {"text": "このスープは熱いので、ゆっくり飲んでください。", "target_word": "飲んで", "complexity_tier": "T3", "furigana": "このスープは熱[あつ]いので、ゆっくり飲[の]んでください。", "sentence_source": "generated"}, {"text": "昨日は夜にコーヒーを飲んだので、眠れませんでした。", "target_word": "飲んだ", "complexity_tier": "T3", "furigana": "昨日[きのう]は夜[よる]にコーヒーを飲[の]んだので、眠[ねむ]れませんでした。", "sentence_source": "generated"}, {"text": "赤ちゃんはミルクをたくさん飲んで、すぐに寝ました。", "target_word": "飲んで", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんはミルクをたくさん飲[の]んで、すぐに寝[ね]ました。", "sentence_source": "generated"}, {"text": "運動したあとは、スポーツドリンクを飲むといいです。", "target_word": "飲む", "complexity_tier": "T3", "furigana": "運動[うんどう]したあとは、スポーツドリンクを飲[の]むといいです。", "sentence_source": "generated"}, {"text": "水道の水は、そのまま飲めます。", "target_word": "飲めます", "complexity_tier": "T3", "furigana": "水道[すいどう]の水[みず]は、そのまま飲[の]めます。", "sentence_source": "generated"}, {"text": "ジュースを飲みすぎて、おなかが痛くなりました。", "target_word": "飲みすぎて", "complexity_tier": "T3", "furigana": "ジュースを飲[の]みすぎて、おなかが痛[いた]くなりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲む", "label": "辞書形"}, {"form": "飲みます", "label": "丁寧形"}, {"form": "飲んだ", "label": "過去形"}, {"form": "飲んで", "label": "て形"}, {"form": "飲まない", "label": "否定形"}, {"form": "飲めば", "label": "仮定形"}, {"form": "飲もう", "label": "意向形"}, {"form": "飲める", "label": "可能形"}], "register": "丁寧", "sense_fingerprint": "ジュースやお茶などの液体を口からとる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa355574-9e18-4c72-a592-28e39dbf69ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35503, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飲みます", "is_correct": true, "explanation": "正解。「父はいつもコーヒーを飲みます」で、習慣として飲み物を口に入れる意味が通る。"}, {"text": "読みます", "is_correct": false, "explanation": "「コーヒーを読みます」は、飲み物には使えない動詞なので文が成り立たない。"}, {"text": "洗います", "is_correct": false, "explanation": "「コーヒーを洗います」は意味が通らず、液体を口に入れる動作を表さない。"}, {"text": "切ります", "is_correct": false, "explanation": "「コーヒーを切ります」は飲み物に使わず、朝の習慣として成り立たない。"}], "explanations": {"飲みます": "正解。「父はいつもコーヒーを飲みます」で、習慣として飲み物を口に入れる意味が通る。", "読みます": "「コーヒーを読みます」は、飲み物には使えない動詞なので文が成り立たない。", "洗います": "「コーヒーを洗います」は意味が通らず、液体を口に入れる動作を表さない。", "切ります": "「コーヒーを切ります」は飲み物に使わず、朝の習慣として成り立たない。"}, "sentence_index": 0, "correct_answer": "飲みます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は急須のお茶を飲んで、湯のみに入れてくれた。", "explanation": "ここは〈注ぐ〉の意味。急須から器へ移す動作は〈飲む〉とは言わないので、定義には合わない。"}, {"text": "熱いうどんを、音を立てて飲んだ。", "explanation": "ここは〈すする〉の意味。麺を音を立てて口に入れる動作は〈すする〉で、〈飲む〉とは言わないので、定義には合わない。"}, {"text": "ケーキを丸ごと飲んで、おやつにした。", "explanation": "ここは〈食べる〉の意味。固形物には〈飲む〉を使わないので、〈食べる〉と混同した文になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35503, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飲んで", "is_correct": true, "explanation": "正解。「ミルクをたくさん飲んで、すぐに寝ました」で、飲んだ後に寝た順序が通る。"}, {"text": "読んで", "is_correct": false, "explanation": "「ミルクを読んで」は動詞が合わず、飲み物には使えない。"}, {"text": "洗って", "is_correct": false, "explanation": "「ミルクを洗って」は意味が通らず、飲む動作を表さない。"}, {"text": "切って", "is_correct": false, "explanation": "「ミルクを切って」は飲み物に使わず、文が成り立たない。"}], "explanations": {"飲んで": "正解。「ミルクをたくさん飲んで、すぐに寝ました」で、飲んだ後に寝た順序が通る。", "読んで": "「ミルクを読んで」は動詞が合わず、飲み物には使えない。", "洗って": "「ミルクを洗って」は意味が通らず、飲む動作を表さない。", "切って": "「ミルクを切って」は飲み物に使わず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "飲んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汗を流したくて、熱いシャワーを飲んだ。", "explanation": "ここは〈浴びる〉の意味。シャワーは体に浴びるもので、口から体内に入れる〈飲む〉とは違うので、定義には合わない。"}, {"text": "休憩のとき、たばこを飲んで一息ついた。", "explanation": "ここは〈吸う〉の意味。たばこは煙を吸うもので、〈飲む〉の定義には合わない。"}, {"text": "よく飲んで食べると、消化がよくなります。", "explanation": "ここは〈噛む〉の意味。食べ物は噛んでから食べるもので、噛む動作を〈飲む〉で言い換えるのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35503, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今朝は時間がなくて、コーヒーを飲むずに家を出ました。", "corrected_sentence": "今朝は時間がなくて、コーヒーを飲まずに家を出ました。", "error_description": "「飲む」の未然形は「飲ま」なので、「〜ずに」に続けるには「飲まずに」が正しい。「飲むずに」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "飲みたく", "is_correct": true, "explanation": "正解。「飲み」＋「たく」（〜たいの連用形）で、「飲みたくなります」の形になる。"}, {"text": "飲みます", "is_correct": false, "explanation": "丁寧形は「〜たくなります」の前に入らず、この文の形にならない。"}, {"text": "飲んだ", "is_correct": false, "explanation": "過去形で、希望を表す「〜たくなります」と続かない。"}, {"text": "飲まない", "is_correct": false, "explanation": "否定形で、希望の表現「〜たくなります」と組み合わせられない。"}], "correct_form": "飲みたく", "base_form": "飲む", "form_label": "〜たい（希望）の連用形", "sentence_index": 1, "explanations": {"飲みたく": "正解。「飲み」＋「たく」（〜たいの連用形）で、「飲みたくなります」の形になる。", "飲みます": "丁寧形は「〜たくなります」の前に入らず、この文の形にならない。", "飲んだ": "過去形で、希望を表す「〜たくなります」と続かない。", "飲まない": "否定形で、希望の表現「〜たくなります」と組み合わせられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35503, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "薬は、食後に水と一緒に飲んてください。", "corrected_sentence": "薬は、食後に水と一緒に飲んでください。", "error_description": "「飲んて」は「て」が誤り。「ん」の後では濁って「飲んで」となる（て形）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "飲む", "is_correct": true, "explanation": "正解。辞書形で、「〜といいです」に続く基本形。"}, {"text": "飲んで", "is_correct": false, "explanation": "て形は文末や「〜といいです」に直接つながらず、この文の形にならない。"}, {"text": "飲めば", "is_correct": false, "explanation": "仮定形は条件節を作るため、「〜といいです」に続けると文が成り立たない。"}, {"text": "飲もう", "is_correct": false, "explanation": "意向形は話し手の意志を表すので、相手への助言の「〜といいです」には続かない。"}], "correct_form": "飲む", "base_form": "飲む", "form_label": "辞書形（基本形）", "sentence_index": 7, "explanations": {"飲む": "正解。辞書形で、「〜といいです」に続く基本形。", "飲んで": "て形は文末や「〜といいです」に直接つながらず、この文の形にならない。", "飲めば": "仮定形は条件節を作るため、「〜といいです」に続けると文が成り立たない。", "飲もう": "意向形は話し手の意志を表すので、相手への助言の「〜といいです」には続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35504, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「消費が増える」で、増える主体を表す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「消費を増える」は、増える（自動詞）が目的語を取れないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「消費に増える」は、増加の対象を表す形として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「消費で増える」は手段や場所の意味になり、文の意図と合わない。"}], "correct_answer": "が", "explanations": {"が": "「消費が増える」で、増える主体を表す。正解。", "を": "「消費を増える」は、増える（自動詞）が目的語を取れないので不自然。", "に": "「消費に増える」は、増加の対象を表す形として成り立たない。", "で": "「消費で増える」は手段や場所の意味になり、文の意図と合わない。"}, "error_tags": {"を": "目的語の格", "に": "位置・帰着の格", "で": "場所・手段の格"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生産", "is_correct": true, "explanation": "消費の対義語。モノを作り出すことで、使ってなくす消費と対になる。正解。"}, {"text": "販売", "is_correct": false, "explanation": "売り渡すこと。消費の対義語ではない。"}, {"text": "収穫", "is_correct": false, "explanation": "作物を取り入れること。消費の対義語ではない。"}, {"text": "建設", "is_correct": false, "explanation": "建物などを造ること。消費の対義語ではない。"}], "correct_answer": "生産", "explanations": {"生産": "消費の対義語。モノを作り出すことで、使ってなくす消費と対になる。正解。", "販売": "売り渡すこと。消費の対義語ではない。", "収穫": "作物を取り入れること。消費の対義語ではない。", "建設": "建物などを造ること。消費の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35504, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生産", "is_correct": true, "explanation": "消費の対義語。作り出すことで、使ってなくす消費と対になる。正解。"}, {"text": "輸入", "is_correct": false, "explanation": "海外から買い入れること。消費の対義語ではない。"}, {"text": "栽培", "is_correct": false, "explanation": "植物を育てること。消費の対義語ではない。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出すこと。消費の対義語ではない。"}], "correct_answer": "生産", "explanations": {"生産": "消費の対義語。作り出すことで、使ってなくす消費と対になる。正解。", "輸入": "海外から買い入れること。消費の対義語ではない。", "栽培": "植物を育てること。消費の対義語ではない。", "採掘": "地下の資源を掘り出すこと。消費の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35504, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを使ったり、食べたりして、なくすこと。", "primary_collocate": null, "pronunciation": "しょうひ", "ipa": "ɕoːçi", "syllable_count": 3, "sentences": [{"text": "この車はガソリンの消費が少ないです。", "target_word": "消費", "complexity_tier": "T3", "furigana": "この車[くるま]はガソリンの消費[しょうひ]が少[すく]ないです。", "sentence_source": "generated"}, {"text": "運動をすると、エネルギーの消費が増えます。", "target_word": "消費", "complexity_tier": "T3", "furigana": "運動[うんどう]をすると、エネルギーの消費[しょうひ]が増[ふ]えます。", "sentence_source": "generated"}, {"text": "夏はエアコンを使うので、電気の消費が多くなります。", "target_word": "消費", "complexity_tier": "T3", "furigana": "夏[なつ]はエアコンを使[つか]うので、電気[でんき]の消費[しょうひ]が多[おお]くなります。", "sentence_source": "generated"}, {"text": "食べ物の消費を減らすために、買いすぎないようにしています。", "target_word": "消費", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]の消費[しょうひ]を減[へ]らすために、買[か]いすぎないようにしています。", "sentence_source": "generated"}, {"text": "日本では、お米の消費が年々少なくなっています。", "target_word": "消費", "complexity_tier": "T3", "furigana": "日本[にほん]では、お米[こめ]の消費[しょうひ]が年々[ねんねん]少[すく]なくなっています。", "sentence_source": "generated"}, {"text": "税金が上がると、人々の消費は減りやすいです。", "target_word": "消費", "complexity_tier": "T3", "furigana": "税金[ぜいきん]が上[あ]がると、人々[ひとびと]の消費[しょうひ]は減[へ]りやすいです。", "sentence_source": "generated"}, {"text": "水の消費を抑えるため、短いシャワーにしています。", "target_word": "消費", "complexity_tier": "T3", "furigana": "水[みず]の消費[しょうひ]を抑[おさ]えるため、短[みじか]いシャワーにしています。", "sentence_source": "generated"}, {"text": "子どもが三人いるので、牛乳の消費が多いです。", "target_word": "消費", "complexity_tier": "T3", "furigana": "子[こ]どもが三人[さんにん]いるので、牛乳[ぎゅうにゅう]の消費[しょうひ]が多[おお]いです。", "sentence_source": "generated"}, {"text": "このアプリは電池の消費が大きいです。", "target_word": "消費", "complexity_tier": "T3", "furigana": "このアプリは電池[でんち]の消費[しょうひ]が大[おお]きいです。", "sentence_source": "generated"}, {"text": "大きな車は小さな車より燃料の消費が多いです。", "target_word": "消費", "complexity_tier": "T3", "furigana": "大[おお]きな車[くるま]は小[ちい]さな車[くるま]より燃料[ねんりょう]の消費[しょうひ]が多[おお]いです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "消費", "label": "基本形"}, {"form": "消費する", "label": "サ変動詞 辞書形"}, {"form": "消費した", "label": "サ変動詞 過去形"}], "register": "neutral (written and spoken)", "sense_fingerprint": "consumption: using up goods, energy or food until it is gone", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35504, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消費", "is_correct": true, "explanation": "「ガソリンの消費が少ない」は使う量が少ないという意味で、文が成り立つ。正解。"}, {"text": "性格", "is_correct": false, "explanation": "「ガソリンの性格が少ない」は意味をなさない。"}, {"text": "天気", "is_correct": false, "explanation": "「ガソリンの天気が少ない」は意味をなさない。"}, {"text": "形", "is_correct": false, "explanation": "「ガソリンの形が少ない」は、量の話として成り立たない。"}], "explanations": {"消費": "「ガソリンの消費が少ない」は使う量が少ないという意味で、文が成り立つ。正解。", "性格": "「ガソリンの性格が少ない」は意味をなさない。", "天気": "「ガソリンの天気が少ない」は意味をなさない。", "形": "「ガソリンの形が少ない」は、量の話として成り立たない。"}, "sentence_index": 0, "correct_answer": "消費"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昔の習慣は、すっかり消費してしまった。", "explanation": "ここは〈消滅〉の意味。消費は使ってなくなることで、習慣のような形のないものには合わない。"}, {"text": "この部屋は毎週、サークルの活動で消費している。", "explanation": "ここは〈使用〉の意味。消費は使ってなくなることで、部屋のように残るものには合わない。"}, {"text": "期限切れの書類を消費した。", "explanation": "ここは〈処分〉の意味。消費は使い切ることで、書類を捨てる場合には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35504, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消費", "is_correct": true, "explanation": "「水の消費を抑える」で、使う量を減らすという意味。正解。"}, {"text": "味", "is_correct": false, "explanation": "「水の味を抑える」は意味をなさない。"}, {"text": "色", "is_correct": false, "explanation": "「水の色を抑える」は意味をなさない。"}, {"text": "手触り", "is_correct": false, "explanation": "「水の手触りを抑える」は意味をなさない。"}], "explanations": {"消費": "「水の消費を抑える」で、使う量を減らすという意味。正解。", "味": "「水の味を抑える」は意味をなさない。", "色": "「水の色を抑える」は意味をなさない。", "手触り": "「水の手触りを抑える」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "消費"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大切な鍵を消費してしまった。", "explanation": "ここは〈紛失〉の意味。消費は使ってなくなることで、鍵は使って減るものではないので合わない。"}, {"text": "財布を消費された。", "explanation": "ここは〈盗難〉の意味。財布は使ってなくなるものではないので、盗まれた場合には合わない。"}, {"text": "壊れたイスを消費して、教室に戻した。", "explanation": "ここは〈修理〉の意味。消費は使い切ることで、直して使い続けることには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35504, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この車はガソリンの消費を少ないので、遠くまで行けます。", "corrected_sentence": "この車はガソリンの消費が少ないので、遠くまで行けます。", "error_description": "正しくは「消費が少ない」。「少ない」の主語は消費なので「が」が必要。「を」は目的語を示す格助詞で、形容詞には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35504, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水の消費を抑えため、短いシャワーにしているそうだ。", "corrected_sentence": "水の消費を抑えるため、短いシャワーにしているそうだ。", "error_description": "正しくは「抑えるため」。「ため」は動詞の辞書形につくので、「抑えため」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35506, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「流れが止まる」で、止まる主体を表す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「流れを止まる」は、止まる（自動詞）が目的語を取れないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「流れに止まる」は、位置を示す形として文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を表すので、「人の流れと止まってしまいました」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「流れが止まる」で、止まる主体を表す。正解。", "を": "「流れを止まる」は、止まる（自動詞）が目的語を取れないので不自然。", "に": "「流れに止まる」は、位置を示す形として文が成り立たない。", "と": "並列・相手を表すので、「人の流れと止まってしまいました」は文が成り立たない。"}, "error_tags": {"を": "目的語の格", "に": "位置・帰着の格", "と": "並列・相手の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35506, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「流れが通っていく」で、通る主体を表す。正解。"}, {"text": "へ", "is_correct": false, "explanation": "「流れへ通っていく」は方向を示すので、通る主体にならない。"}, {"text": "から", "is_correct": false, "explanation": "「流れから通っていく」は起点を示すので、主語の役割を果たさない。"}, {"text": "と", "is_correct": false, "explanation": "「流れと通っていく」は並列の相手を示すので、主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「流れが通っていく」で、通る主体を表す。正解。", "へ": "「流れへ通っていく」は方向を示すので、通る主体にならない。", "から": "「流れから通っていく」は起点を示すので、主語の役割を果たさない。", "と": "「流れと通っていく」は並列の相手を示すので、主語にならない。"}, "error_tags": {"へ": "方向の格", "から": "起点の格", "と": "並列・相手の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35506, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水や人が、ある場所から別の場所へ動いていくこと。", "primary_collocate": null, "pronunciation": "ながれ", "ipa": "naɡaɾe", "syllable_count": 3, "sentences": [{"text": "川の流れはとても速いので、泳いではいけません。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "川[かわ]の流[なが]れはとても速[はや]いので、泳[およ]いではいけません。", "sentence_source": "generated"}, {"text": "駅の出口で、人の流れが止まってしまいました。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "駅[えき]の出口[でぐち]で、人[ひと]の流[なが]れが止[と]まってしまいました。", "sentence_source": "generated"}, {"text": "雨のあとで、川の流れが強くなりました。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "雨[あめ]のあとで、川[かわ]の流[なが]れが強[つよ]くなりました。", "sentence_source": "generated"}, {"text": "私は人の流れに乗って、改札を出ました。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "私[わたし]は人[ひと]の流[なが]れに乗[の]って、改札[かいさつ]を出[で]ました。", "sentence_source": "generated"}, {"text": "ゆっくりした流れの川で、子どもたちが遊んでいます。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "ゆっくりした流[なが]れの川[かわ]で、子[こ]どもたちが遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "朝の駅では、会社へ向かう人の流れができます。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "朝[あさ]の駅[えき]では、会社[かいしゃ]へ向[む]かう人[ひと]の流[なが]れができます。", "sentence_source": "generated"}, {"text": "水の流れを見ていると、心が落ち着きます。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "水[みず]の流[なが]れを見[み]ていると、心[こころ]が落[お]ち着[つ]きます。", "sentence_source": "generated"}, {"text": "雨で増えた水の流れが、橋の下を勢いよく通っていく。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "雨[あめ]で増[ふ]えた水[みず]の流[なが]れが、橋[はし]の下[した]を勢[いきお]いよく通[とお]っていく。", "sentence_source": "generated"}, {"text": "大きな岩のせいで、水の流れが変わりました。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "大[おお]きな岩[いわ]のせいで、水[みず]の流[なが]れが変[か]わりました。", "sentence_source": "generated"}, {"text": "祭りの日は、神社へ向かう人の流れが夜まで続きました。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]は、神社[じんじゃ]へ向[む]かう人[ひと]の流[なが]れが夜[よる]まで続[つづ]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流れ", "label": "基本形"}], "register": "neutral (everyday spoken)", "sense_fingerprint": "flow: movement of water or people from one place to another", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35506, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流れ", "is_correct": true, "explanation": "「川の流れは速い」で、水が移動する勢いを表す。正解。"}, {"text": "深さ", "is_correct": false, "explanation": "「川の深さは速い」は形容として成り立たない。"}, {"text": "色", "is_correct": false, "explanation": "「川の色は速い」は意味をなさない。"}, {"text": "重さ", "is_correct": false, "explanation": "「川の重さは速い」は意味をなさない。"}], "explanations": {"流れ": "「川の流れは速い」で、水が移動する勢いを表す。正解。", "深さ": "「川の深さは速い」は形容として成り立たない。", "色": "「川の色は速い」は意味をなさない。", "重さ": "「川の重さは速い」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "流れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は古い剣術の流れをくんでいる。", "explanation": "ここは〈流派〉の意味。流れは水や人の移動を指すので、剣術の流派には合わない。"}, {"text": "今この店では、流れの服が多い。", "explanation": "ここは〈流行〉の意味。流れは水や人の移動を指すので、服の人気には合わない。"}, {"text": "この小説は流れがしっかりしている。", "explanation": "ここは〈筋道〉の意味。流れは水や人の移動を指すので、物語の筋には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35506, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流れ", "is_correct": true, "explanation": "「水の流れを見ていると」で、動いていく水の様子を指す。正解。"}, {"text": "匂い", "is_correct": false, "explanation": "「水の匂いを見ていると」は、見るものとして成り立たない。"}, {"text": "硬さ", "is_correct": false, "explanation": "「水の硬さを見ていると」は意味をなさない。"}, {"text": "味", "is_correct": false, "explanation": "「水の味を見ていると」は、見るものとして成り立たない。"}], "explanations": {"流れ": "「水の流れを見ていると」で、動いていく水の様子を指す。正解。", "匂い": "「水の匂いを見ていると」は、見るものとして成り立たない。", "硬さ": "「水の硬さを見ていると」は意味をなさない。", "味": "「水の味を見ていると」は、見るものとして成り立たない。"}, "sentence_index": 6, "correct_answer": "流れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅で大きな流れを運ぶのを手伝った。", "explanation": "ここは〈荷物〉の意味。流れは水や人の動きで、物として運べないので合わない。"}, {"text": "川で拾った流れを、友だちにあげた。", "explanation": "ここは〈石〉の意味。流れは拾ったりあげたりできるものではないので合わない。"}, {"text": "風で流れが飛んだ。", "explanation": "ここは〈帽子〉の意味。流れは風に飛ばされる物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35506, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨のあとで、川の流れを急に強くなりました。", "corrected_sentence": "雨のあとで、川の流れが急に強くなりました。", "error_description": "正しくは「流れが強くなる」。「強くなる」の主語は流れなので「が」。「を」は目的語を示し、変化の動詞とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35506, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大きな岩のせいで、水の流れが変えてしまいました。", "corrected_sentence": "大きな岩のせいで、水の流れが変わってしまいました。", "error_description": "「流れが」には自動詞「変わる」が合う。他動詞「変える」を使うなら「流れを」が必要で、「流れが変える」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35507, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「流れが変わった」で、変わる主体を表す。正解。"}, {"text": "を", "is_correct": false, "explanation": "「流れを変わった」は、変わる（自動詞）が目的語を取れないので不自然。"}, {"text": "に", "is_correct": false, "explanation": "「流れに変わった」は変化の相手として不自然で、文の流れと合わない。"}, {"text": "と", "is_correct": false, "explanation": "「流れと変わった」は並列の相手を示すので、変わるの主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「流れが変わった」で、変わる主体を表す。正解。", "を": "「流れを変わった」は、変わる（自動詞）が目的語を取れないので不自然。", "に": "「流れに変わった」は変化の相手として不自然で、文の流れと合わない。", "と": "「流れと変わった」は並列の相手を示すので、変わるの主語にならない。"}, "error_tags": {"を": "目的語の格", "に": "変化の相手", "と": "並列・相手の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35507, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「流れが自然」で、自然であるものの主語を表す。正解。"}, {"text": "へ", "is_correct": false, "explanation": "「流れへ自然」は方向を示すので、形容詞の主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「流れから自然」は起点の意味になり、主語の役割を果たさない。"}, {"text": "に", "is_correct": false, "explanation": "「流れに自然」は位置・帰着を示すので、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「流れが自然」で、自然であるものの主語を表す。正解。", "へ": "「流れへ自然」は方向を示すので、形容詞の主語にならない。", "から": "「流れから自然」は起点の意味になり、主語の役割を果たさない。", "に": "「流れに自然」は位置・帰着を示すので、主語にはならない。"}, "error_tags": {"へ": "方向の格", "から": "起点の格", "に": "位置・帰着の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35507, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が進んでいく道筋や、連続した動き。", "primary_collocate": null, "pronunciation": "ながれ", "ipa": "naɡaɾe", "syllable_count": 3, "sentences": [{"text": "会議の流れを説明してから、質問を受け付けた。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "会議[かいぎ]の流[なが]れを説明[せつめい]してから、質問[しつもん]を受[う]け付[つ]けた。", "sentence_source": "generated"}, {"text": "話の流れが変わったので、私は意見を言うのをやめた。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "話[はなし]の流[なが]れが変[か]わったので、私[わたし]は意見[いけん]を言[い]うのをやめた。", "sentence_source": "generated"}, {"text": "今日の仕事の流れを紙に書いておくと、忘れずにすむ。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "今日[きょう]の仕事[しごと]の流[なが]れを紙[かみ]に書[か]いておくと、忘[わす]れずにすむ。", "sentence_source": "generated"}, {"text": "時代の流れとともに、人々の暮らしも大きく変わった。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "時代[じだい]の流[なが]れとともに、人々[ひとびと]の暮[く]らしも大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "試合の流れが相手に移り、私たちは続けて点を取られた。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "試合[しあい]の流[なが]れが相手[あいて]に移[うつ]り、私[わたし]たちは続[つづ]けて点[てん]を取[と]られた。", "sentence_source": "generated"}, {"text": "仕事の流れが一度止まると、取り戻すのに時間がかかる。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "仕事[しごと]の流[なが]れが一度[いちど]止[と]まると、取[と]り戻[もど]すのに時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "申し込みから受け取りまでの流れは、このページに書いてある。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "申[もう]し込[こ]みから受[う]け取[と]りまでの流[なが]れは、このページに書[か]いてある。", "sentence_source": "generated"}, {"text": "この映画は物語の流れが自然で、最後まで楽しく見られた。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "この映画[えいが]は物語[ものがたり]の流[なが]れが自然[しぜん]で、最後[さいご]まで楽[たの]しく見[み]られた。", "sentence_source": "generated"}, {"text": "話の流れを読んで、彼は黙っていることにした。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "話[はなし]の流[なが]れを読[よ]んで、彼[かれ]は黙[だま]っていることにした。", "sentence_source": "generated"}, {"text": "料理の流れを覚えれば、一人でも作れるようになる。", "target_word": "流れ", "complexity_tier": "T3", "furigana": "料理[りょうり]の流[なが]れを覚[おぼ]えれば、一人[ひとり]でも作[つく]れるようになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "流れ", "label": "基本形"}, {"form": "ながれ", "label": "ひらがな表記"}], "register": "普通体（中立）", "sense_fingerprint": "物事の進み方・順序・手順・時の移り変わりを表す「流れ」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35507, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流れ", "is_correct": true, "explanation": "「会議の流れ」は話し合いや手順の進み方のこと。説明の対象として自然。正解。"}, {"text": "色", "is_correct": false, "explanation": "「会議の色を説明」は意味をなさない。"}, {"text": "香り", "is_correct": false, "explanation": "「会議の香りを説明」は成り立たない。"}, {"text": "重さ", "is_correct": false, "explanation": "「会議の重さを説明」は意味をなさない。"}], "explanations": {"流れ": "「会議の流れ」は話し合いや手順の進み方のこと。説明の対象として自然。正解。", "色": "「会議の色を説明」は意味をなさない。", "香り": "「会議の香りを説明」は成り立たない。", "重さ": "「会議の重さを説明」は意味をなさない。"}, "sentence_index": 0, "correct_answer": "流れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "美容院で髪の流れを染めてもらった。", "explanation": "ここは〈色〉の意味。流れは物事の進み方を表すので、髪を染める対象にはならない。"}, {"text": "新しい靴の流れを測った。", "explanation": "ここは〈大きさ〉の意味。流れは進み方を表し、靴の寸法は測る対象ではないので合わない。"}, {"text": "この本の流れは千円だった。", "explanation": "ここは〈値段〉の意味。流れは物事の進み方なので、本の値段には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35507, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流れ", "is_correct": true, "explanation": "「申し込みから受け取りまでの流れ」は手続きの進み方を指す。正解。"}, {"text": "味", "is_correct": false, "explanation": "「申し込みから受け取りまでの味」は意味をなさない。"}, {"text": "匂い", "is_correct": false, "explanation": "「匂い」は手続きの進み方を説明する語として意味をなさない。"}, {"text": "色", "is_correct": false, "explanation": "「色」は手続きの説明には使わず、意味をなさない。"}], "explanations": {"流れ": "「申し込みから受け取りまでの流れ」は手続きの進み方を指す。正解。", "味": "「申し込みから受け取りまでの味」は意味をなさない。", "匂い": "「匂い」は手続きの進み方を説明する語として意味をなさない。", "色": "「色」は手続きの説明には使わず、意味をなさない。"}, "sentence_index": 6, "correct_answer": "流れ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店で服の流れを試着した。", "explanation": "ここは〈服〉の意味。流れは物事の進み方なので、試着できる服にはならない。"}, {"text": "古い服の流れを落とした。", "explanation": "ここは〈汚れ〉の意味。流れは落とせるものではないので合わない。"}, {"text": "指の流れが治った。", "explanation": "ここは〈傷〉の意味。流れは治るものではないので、傷には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35507, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日の仕事の流れが紙にまとめておくと、忘れずにすむ。", "corrected_sentence": "今日の仕事の流れを紙にまとめておくと、忘れずにすむ。", "error_description": "正しくは「流れを紙にまとめる」。「まとめる」の目的語は流れなので「を」。「が」は主語を示すため、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35507, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試合の流れを変わって、相手が勝った。", "corrected_sentence": "試合の流れを変えて、相手が勝った。", "error_description": "正しくは「流れを変える」。「変わる」は自動詞で目的語の「を」を取れないので、他動詞「変える」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
