INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35508, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示す。『商品でサプライ』では名詞をつながず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を示す。『商品からサプライ』では意味が通らない。"}, {"text": "の", "is_correct": true, "explanation": "『商品のサプライ』で名詞をつなぐ『の』。『まだ始まっていない』へ続く。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示す。『商品よりサプライ』では、サプライを修飾できない。"}], "correct_answer": "の", "explanations": {"で": "『で』は場所や手段を示す。『商品でサプライ』では名詞をつながず、文が成り立たない。", "から": "『から』は起点を示す。『商品からサプライ』では意味が通らない。", "の": "『商品のサプライ』で名詞をつなぐ『の』。『まだ始まっていない』へ続く。", "より": "『より』は比較を示す。『商品よりサプライ』では、サプライを修飾できない。"}, "error_tags": {"で": "手段・場所", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35508, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを必要なところに届けること。", "primary_collocate": null, "pronunciation": "さぷらい", "ipa": "sapɯɾai", "syllable_count": 4, "sentences": [{"text": "山小屋への食べ物のサプライは、ヘリコプターが毎週行っている。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "山小屋[やまごや]への食[た]べ物[もの]のサプライは、ヘリコプターが毎週[まいしゅう]行[おこな]っている。", "sentence_source": "generated"}, {"text": "雪で道が通れなくなり、村への薬のサプライが止まってしまった。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "雪[ゆき]で道[みち]が通[とお]れなくなり、村[むら]への薬[くすり]のサプライが止[と]まってしまった。", "sentence_source": "generated"}, {"text": "店は、毎朝きれいな水のサプライを業者に頼んでいる。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "店[みせ]は、毎朝[まいあさ]きれいな水[みず]のサプライを業者[ぎょうしゃ]に頼[たの]んでいる。", "sentence_source": "generated"}, {"text": "災害の現場へのサプライが早かったので、多くの人が助かった。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "災害[さいがい]の現場[げんば]へのサプライが早[はや]かったので、多[おお]くの人[ひと]が助[たす]かった。", "sentence_source": "generated"}, {"text": "工事現場では、材料のサプライが遅れると作業が進まない。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "工事[こうじ]現場[げんば]では、材料[ざいりょう]のサプライが遅[おく]れると作業[さぎょう]が進[すす]まない。", "sentence_source": "generated"}, {"text": "市は、病院へのマスクのサプライを増やすことを決めた。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "市[し]は、病院[びょういん]へのマスクのサプライを増[ふ]やすことを決[き]めた。", "sentence_source": "generated"}, {"text": "彼は毎日、事務所へのコピー用紙のサプライを担当している。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "彼[かれ]は毎日[まいにち]、事務所[じむしょ]へのコピー用紙[ようし]のサプライを担当[たんとう]している。", "sentence_source": "generated"}, {"text": "新しい店は商品のサプライがまだ始まっていないので、棚は空のままだ。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]は商品[しょうひん]のサプライがまだ始[はじ]まっていないので、棚[たな]は空[から]のままだ。", "sentence_source": "generated"}, {"text": "船によるサプライのおかげで、島の人々は冬も食料に困らなかった。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "船[ふね]によるサプライのおかげで、島[しま]の人々[ひとびと]は冬[ふゆ]も食料[しょくりょう]に困[こま]らなかった。", "sentence_source": "generated"}, {"text": "道路が直れば、被害を受けた町へのサプライも楽になる。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "道路[どうろ]が直[なお]れば、被害[ひがい]を受[う]けた町[まち]へのサプライも楽[らく]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サプライ", "label": "基本形"}, {"form": "サプライする", "label": "サ変動詞形"}, {"form": "サプライして", "label": "連用形（テ形）"}], "register": "neutral", "sense_fingerprint": "食べ物・薬・材料など必要なものを、必要としている場所や人のところへ届けること。外来語。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35508, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "修理は壊れたものを直すこと。食べ物の届け方を述べる文には合わない。"}, {"text": "サプライ", "is_correct": true, "explanation": "食べ物を必要な場所へ届ける意味のサプライ。ヘリコプターが毎週運ぶ文に合う。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は音楽を奏でること。食べ物を運ぶ文脈には入らない。"}, {"text": "登山", "is_correct": false, "explanation": "登山は山に登ること。ヘリコプターが食べ物を運ぶ話とは結びつかない。"}], "explanations": {"修理": "修理は壊れたものを直すこと。食べ物の届け方を述べる文には合わない。", "サプライ": "食べ物を必要な場所へ届ける意味のサプライ。ヘリコプターが毎週運ぶ文に合う。", "演奏": "演奏は音楽を奏でること。食べ物を運ぶ文脈には入らない。", "登山": "登山は山に登ること。ヘリコプターが食べ物を運ぶ話とは結びつかない。"}, "sentence_index": 0, "correct_answer": "サプライ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は大きな声でサプライした。", "explanation": "ここは〈笑う〉の意味。サプライは必要な場所へ物や助けを届けることで、声を出して笑う動作は表さない。"}, {"text": "急な出張に備えて、新幹線の切符をサプライした。", "explanation": "ここは〈手配〉の意味。サプライは食料や薬など必要な物資を届ける意味で、切符の確保には使わない。"}, {"text": "借りた本を、図書館にサプライした。", "explanation": "ここは〈返却〉の意味。サプライは必要な相手に物資を届けることで、借りた物を戻す行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35508, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻訳", "is_correct": false, "explanation": "翻訳は言葉を別の言語に置き換えること。コピー用紙の業務を表す文には結びつかない。"}, {"text": "誕生", "is_correct": false, "explanation": "誕生は生まれること。物資を届ける業務の文には合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩き回ること。担当する業務を表す文脈には入らない。"}, {"text": "サプライ", "is_correct": true, "explanation": "コピー用紙を事務所へ届ける意味のサプライ。担当する業務として文に合う。"}], "explanations": {"翻訳": "翻訳は言葉を別の言語に置き換えること。コピー用紙の業務を表す文には結びつかない。", "誕生": "誕生は生まれること。物資を届ける業務の文には合わない。", "散歩": "散歩は歩き回ること。担当する業務を表す文脈には入らない。", "サプライ": "コピー用紙を事務所へ届ける意味のサプライ。担当する業務として文に合う。"}, "sentence_index": 6, "correct_answer": "サプライ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁の穴を、板でサプライした。", "explanation": "ここは〈ふさぐ〉の意味。サプライは必要な場所へ物を届けることで、穴を埋めて塞ぐ作業には使わない。"}, {"text": "優勝者に記念の盾をサプライした。", "explanation": "ここは〈進呈〉の意味。サプライは必要とする相手に品を届ける業務で、表彰の贈呈には使わない。"}, {"text": "使い終わった瓶を、店がサプライした。", "explanation": "ここは〈回収〉の意味。サプライは必要な物を届ける意味で、使用済みの物を集めて引き取ることには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35508, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雪で道がふさがり、避難所への毛布をサプライが遅れた。", "corrected_sentence": "大雪で道がふさがり、避難所への毛布のサプライが遅れた。", "error_description": "誤『毛布をサプライが』→正『毛布のサプライ』。『サプライ』の前は『の』で名詞をつなぐ。『を』を使うと目的語になり、『サプライが遅れた』と噛み合わず成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35508, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、避難所へ毛布をサプライられ、夕方までに配り終えた。", "corrected_sentence": "市は、避難所へ毛布をサプライし、夕方までに配り終えた。", "error_description": "誤『サプライられ』は、サプライに受身の『られ』が続いた形で、サ変動詞の語幹として成り立たない。正しくは『サプライし』（サ変動詞『する』の連用形）で、後ろの『配り終えた』へつながる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35509, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『サプライが三日間止まった』で、止まった主語を示す『が』。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語。『止まった』は自動詞なので目的語を取れず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は帰着先を示す。『サプライに三日間止まった』では止まる場所として意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。『サプライへ止まった』では止まる先の方向として不自然で、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『サプライが三日間止まった』で、止まった主語を示す『が』。", "を": "『を』は目的語。『止まった』は自動詞なので目的語を取れず、文が成り立たない。", "に": "『に』は帰着先を示す。『サプライに三日間止まった』では止まる場所として意味が通らない。", "へ": "『へ』は方向を示す。『サプライへ止まった』では止まる先の方向として不自然で、文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "帰着先", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35509, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『軽食のサプライを毎朝早くから始める』で、始める対象を示す『を』。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語。『サプライが始める』では主語と動詞がつながらず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は相手や時点を示す。『サプライに始める』では始める対象の位置づけがなく、合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示す。『サプライへ始める』では始める対象を示せず、不自然。"}], "correct_answer": "を", "explanations": {"を": "『軽食のサプライを毎朝早くから始める』で、始める対象を示す『を』。", "が": "『が』は主語。『サプライが始める』では主語と動詞がつながらず、文が成り立たない。", "に": "『に』は相手や時点を示す。『サプライに始める』では始める対象の位置づけがなく、合わない。", "へ": "『へ』は方向を示す。『サプライへ始める』では始める対象を示せず、不自然。"}, "error_tags": {"が": "主語", "に": "相手・時点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35509, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "商品やサービスを、必要な人や場所に提供すること。", "primary_collocate": null, "pronunciation": "さぷらい", "ipa": "sapɯɾai", "syllable_count": 4, "sentences": [{"text": "工場では、部品のサプライが止まると生産がすぐに遅れる。", "target_word": "サプライ", "complexity_tier": "T5", "furigana": "工場[こうじょう]では、部品[ぶひん]のサプライが止[と]まると生産[せいさん]がすぐに遅[おく]れる。", "sentence_source": "generated"}, {"text": "台風の影響で、工場への部品のサプライが三日間止まった。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "台風[たいふう]の影響[えいきょう]で、工場[こうじょう]への部品[ぶひん]のサプライが三日間[みっかかん]止[と]まった。", "sentence_source": "generated"}, {"text": "医療品のサプライが遅れたため、病院は手術の予定を変えた。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "医療品[いりょうひん]のサプライが遅[おく]れたため、病院[びょういん]は手術[しゅじゅつ]の予定[よてい]を変[か]えた。", "sentence_source": "generated"}, {"text": "この会社は、全国のコンビニへの弁当のサプライを担当している。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、全国[ぜんこく]のコンビニへの弁当[べんとう]のサプライを担当[たんとう]している。", "sentence_source": "generated"}, {"text": "電力のサプライが安定しているので、夜も工場を動かせる。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "電力[でんりょく]のサプライが安定[あんてい]しているので、夜[よる]も工場[こうじょう]を動[うご]かせる。", "sentence_source": "generated"}, {"text": "災害の後は、水や食料のサプライを急いで整える必要がある。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "災害[さいがい]の後[あと]は、水[みず]や食料[しょくりょう]のサプライを急[いそ]いで整[ととの]える必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "原料のサプライが安定したので、新商品の発売日が決まった。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "原料[げんりょう]のサプライが安定[あんてい]したので、新商品[しんしょうひん]の発売日[はつばいび]が決[き]まった。", "sentence_source": "generated"}, {"text": "山の店では、観光客へのお茶と軽食のサプライを毎朝早くから始める。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "山[やま]の店[みせ]では、観光客[かんこうきゃく]へのお茶[ちゃ]と軽食[けいしょく]のサプライを毎朝[まいあさ]早[はや]くから始[はじ]める。", "sentence_source": "generated"}, {"text": "海外からのサプライに頼りすぎると、事情が変わったときに困る。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "海外[かいがい]からのサプライに頼[たよ]りすぎると、事情[じじょう]が変[か]わったときに困[こま]る。", "sentence_source": "generated"}, {"text": "学校へのパソコンのサプライは、来月から始まる予定だ。", "target_word": "サプライ", "complexity_tier": "T3", "furigana": "学校[がっこう]へのパソコンのサプライは、来月[らいげつ]から始[はじ]まる予定[よてい]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サプライ", "label": "基本形"}, {"form": "サプライする", "label": "サ変動詞形"}, {"form": "サプライして", "label": "連用形（テ形）"}], "register": "business", "sense_fingerprint": "部品・原料・電力などの商品やサービスを、必要とする相手や場所に提供すること。ビジネス場面で使う外来語。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '027810a5-82c1-4898-8f4c-3cbe5e1de1db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35509, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翻訳", "is_correct": false, "explanation": "翻訳は言葉を別の言語に置き換えること。部品の翻訳が止まる、という文では意味が通らない。"}, {"text": "サプライ", "is_correct": true, "explanation": "部品を必要な工場へ届ける意味のサプライ。止まると生産が遅れる文に合う。"}, {"text": "誕生", "is_correct": false, "explanation": "誕生は生まれること。部品の誕生が止まる、という文では意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩き回ること。部品の散歩が止まる、という文では意味が通らない。"}], "explanations": {"翻訳": "翻訳は言葉を別の言語に置き換えること。部品の翻訳が止まる、という文では意味が通らない。", "サプライ": "部品を必要な工場へ届ける意味のサプライ。止まると生産が遅れる文に合う。", "誕生": "誕生は生まれること。部品の誕生が止まる、という文では意味が通らない。", "散歩": "散歩は歩き回ること。部品の散歩が止まる、という文では意味が通らない。"}, "sentence_index": 0, "correct_answer": "サプライ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "野鳥の行動を、一日中サプライした。", "explanation": "ここは〈観察〉の意味。サプライは必要な人や場所に物やサービスを届けることで、生き物の様子を見て調べる行為には使わない。"}, {"text": "彼は夜通し、庭の雑草をサプライした。", "explanation": "ここは〈刈る〉の意味。サプライは必要な相手に物やサービスを提供することで、草を刈る作業には使わない。"}, {"text": "家臣は城の石垣を、夜のうちにサプライした。", "explanation": "ここは〈築く〉の意味。サプライは必要な相手に物やサービスを提供することで、石垣を積み上げる作業には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35509, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点検", "is_correct": false, "explanation": "点検は調べること。『原料の点検が安定した』では、届けられる状態を表せない。"}, {"text": "入学", "is_correct": false, "explanation": "入学は学校に入ること。原料には結びつかず、文が成り立たない。"}, {"text": "修理", "is_correct": false, "explanation": "修理は壊れたものを直すこと。『原料の修理が安定した』では意味が通らない。"}, {"text": "サプライ", "is_correct": true, "explanation": "原料を必要な場所へ届ける意味のサプライ。『原料のサプライが安定した』に合う。"}], "explanations": {"点検": "点検は調べること。『原料の点検が安定した』では、届けられる状態を表せない。", "入学": "入学は学校に入ること。原料には結びつかず、文が成り立たない。", "修理": "修理は壊れたものを直すこと。『原料の修理が安定した』では意味が通らない。", "サプライ": "原料を必要な場所へ届ける意味のサプライ。『原料のサプライが安定した』に合う。"}, "sentence_index": 6, "correct_answer": "サプライ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕暮れの空を、彼はそっとサプライした。", "explanation": "ここは〈眺める〉の意味。サプライは商品やサービスを必要な相手に提供することで、景色を眺める行為には使わない。"}, {"text": "週末に、汚れた事務所をサプライした。", "explanation": "ここは〈清掃〉の意味。サプライは必要な場所に物やサービスを届けることで、場所をきれいにする作業には使わない。"}, {"text": "使い終えた古い車を、庭でサプライした。", "explanation": "ここは〈解体〉の意味。サプライは必要な相手に物やサービスを提供することで、車を分解する作業には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35509, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "病院は医療品をサプライが遅れて、手術を延期した。", "corrected_sentence": "病院は医療品のサプライが遅れて、手術を延期した。", "error_description": "誤『医療品をサプライが』→正『医療品のサプライ』。『サプライ』の前は『の』で名詞をつなぐ。『を』を使うと目的語になり、『サプライが遅れた』と噛み合わず成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35509, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は、被災地へ毛布をサプライられる業者を探している。", "corrected_sentence": "市は、被災地へ毛布をサプライする業者を探している。", "error_description": "誤『サプライられる』→正『サプライする』。サ変名詞のサプライには『する』を付けて動詞にする。『られる』は受身の形で、サプライに直接付くと成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e4e5454-2efb-41b6-bfb9-5b0c9778d69d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35510, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『チェーンでつないで』の『で』で、道具を表す正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "『チェーンがつないで』は主語の形が合わず、つなぐ道具を示せない。"}, {"text": "より", "is_correct": false, "explanation": "『チェーンよりつないで』は比較の形で、道具を表せない。"}, {"text": "の", "is_correct": false, "explanation": "『チェーンのつないで』は所有の形になり、動作の道具を示せない。"}], "correct_answer": "で", "explanations": {"で": "『チェーンでつないで』の『で』で、道具を表す正しい助詞。", "が": "『チェーンがつないで』は主語の形が合わず、つなぐ道具を示せない。", "より": "『チェーンよりつないで』は比較の形で、道具を表せない。", "の": "『チェーンのつないで』は所有の形になり、動作の道具を示せない。"}, "error_tags": {"が": "主格", "より": "比較", "の": "所有・連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35510, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『チェーンに油を差す』の『に』で、油を差す対象を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "『チェーンを油を差す』は目的語が二つ重なり、対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "『チェーンで油を差す』は道具の意味になり、油を差す対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は向かう方向を表す助詞で、油を差す対象には使わない。"}], "correct_answer": "に", "explanations": {"に": "『チェーンに油を差す』の『に』で、油を差す対象を示す正しい助詞。", "を": "『チェーンを油を差す』は目的語が二つ重なり、対象を示せない。", "で": "『チェーンで油を差す』は道具の意味になり、油を差す対象を表せない。", "へ": "『へ』は向かう方向を表す助詞で、油を差す対象には使わない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35510, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いくつかをつなぐもの", "primary_collocate": null, "pronunciation": "ちぇーん", "ipa": "tɕeːɴ", "syllable_count": 3, "sentences": [{"text": "自転車のチェーンが外れて、坂の途中で止まった。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]のチェーンが外[はず]れて、坂[さか]の途中[とちゅう]で止[と]まった。", "sentence_source": "generated"}, {"text": "犬をチェーンでつないでおくのは、かわいそうだ。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "犬[いぬ]をチェーンでつないでおくのは、かわいそうだ。", "sentence_source": "generated"}, {"text": "雪道では、車のタイヤにチェーンを付けます。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "雪道[ゆきみち]では、車[くるま]のタイヤにチェーンを付[つ]けます。", "sentence_source": "generated"}, {"text": "門にチェーンをかけて、鍵を閉めた。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "門[もん]にチェーンをかけて、鍵[かぎ]を閉[し]めた。", "sentence_source": "generated"}, {"text": "このネックレスは、細いチェーンが美しい。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "このネックレスは、細[ほそ]いチェーンが美[うつく]しい。", "sentence_source": "generated"}, {"text": "自転車を電柱にチェーンで固定した。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]を電柱[でんちゅう]にチェーンで固定[こてい]した。", "sentence_source": "generated"}, {"text": "ドアにチェーンをかけたまま、相手と話した。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "ドアにチェーンをかけたまま、相手[あいて]と話[はな]した。", "sentence_source": "generated"}, {"text": "チェーンに油を差すと、音が静かになる。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "チェーンに油[あぶら]を差[さ]すと、音[おと]が静[しず]かになる。", "sentence_source": "generated"}, {"text": "古いチェーンは錆びていて、すぐに切れてしまった。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "古[ふる]いチェーンは錆[さ]びていて、すぐに切[き]れてしまった。", "sentence_source": "generated"}, {"text": "工事現場では、太いチェーンで重い荷物をつり上げる。", "target_word": "チェーン", "complexity_tier": "T4", "furigana": "工事現場[こうじげんば]では、太[ふと]いチェーンで重[おも]い荷物[にもつ]をつり上[あ]げる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チェーン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "金属の輪をつないだ鎖状の物（自転車・タイヤ・戸締まりなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: つり上げる (Zipf 1.63)']::text[], 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35510, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チェーン", "is_correct": true, "explanation": "『自転車のチェーンが外れた』と鎖状の部品を指し、外れて止まったという文脈に合う。"}, {"text": "ギター", "is_correct": false, "explanation": "『自転車のギター』は成り立たず、外れる部品としても合わない。"}, {"text": "カレー", "is_correct": false, "explanation": "『自転車のカレー』は意味をなさず、部品を表さない。"}, {"text": "ワイン", "is_correct": false, "explanation": "『自転車のワイン』は文脈に入らず、外れて止まる部品にはならない。"}], "explanations": {"チェーン": "『自転車のチェーンが外れた』と鎖状の部品を指し、外れて止まったという文脈に合う。", "ギター": "『自転車のギター』は成り立たず、外れる部品としても合わない。", "カレー": "『自転車のカレー』は意味をなさず、部品を表さない。", "ワイン": "『自転車のワイン』は文脈に入らず、外れて止まる部品にはならない。"}, "sentence_index": 0, "correct_answer": "チェーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玄関で靴ひもを、チェーンで縫いつけた。", "explanation": "ここは〈ひも〉の意味。チェーンは縫えず、靴ひもの代わりにもならない。"}, {"text": "ボタンのチェーンが取れてしまい、服が開いてしまった。", "explanation": "ここは〈ボタン〉の意味。チェーンはつなぐ鎖を指し、留め具としてのボタンは表せない。"}, {"text": "糸のチェーンでボタンを縫いつけた。", "explanation": "ここは〈糸〉の意味。チェーンは糸のように縫うことはできないので、縫いつける材料として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35510, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チェーン", "is_correct": true, "explanation": "『ドアにチェーンをかけたまま』と戸締まりの鎖を表し、話していた状況に合う。"}, {"text": "シャンプー", "is_correct": false, "explanation": "『ドアにシャンプーをかけたまま』は成り立たず、戸締まりを表さない。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "『ドアにヨーグルトをかけたまま』は不自然で、この文脈には入らない。"}, {"text": "ハンマー", "is_correct": false, "explanation": "『ドアにハンマーをかけたまま』は意味をなさず、戸締まりの語にならない。"}], "explanations": {"チェーン": "『ドアにチェーンをかけたまま』と戸締まりの鎖を表し、話していた状況に合う。", "シャンプー": "『ドアにシャンプーをかけたまま』は成り立たず、戸締まりを表さない。", "ヨーグルト": "『ドアにヨーグルトをかけたまま』は不自然で、この文脈には入らない。", "ハンマー": "『ドアにハンマーをかけたまま』は意味をなさず、戸締まりの語にならない。"}, "sentence_index": 6, "correct_answer": "チェーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工事現場では、チェーンで図面を描いた。", "explanation": "ここは〈線引き〉の意味。チェーンは図面を描く道具にならない。"}, {"text": "工事現場では、チェーンで扉を開けた。", "explanation": "ここは〈鍵〉の意味。チェーンでは扉を開けられず、施錠の鎖としての役割しかない。"}, {"text": "工事現場では、チェーンで板を貼った。", "explanation": "ここは〈のり〉の意味。チェーンでは板を貼り付けられず、貼る道具として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35510, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪道に備えて、タイヤにチェーンが付けた。", "corrected_sentence": "雪道に備えて、タイヤにチェーンを付けた。", "error_description": "正しくは『チェーンを付けた』。『付ける』の対象を示す『を』が必要で、『が』では動作の対象が示せず文が成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35510, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨で錆びたチェーンが取り替えた。", "corrected_sentence": "雨で錆びたチェーンを取り替えた。", "error_description": "正しくは『チェーンを取り替えた』。『取り替える』の対象は『を』で示す。『が』にすると、チェーンが主語になって動詞の目的語がなくなり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
