INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35511, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものが次々とつながった状態、またはそのつながり", "primary_collocate": null, "pronunciation": "ちぇーん", "ipa": "tɕeːɴ", "syllable_count": 3, "sentences": [{"text": "一社の判断が次々と取引先へ伝わるチェーンが、社会全体の流れを決めている。", "target_word": "チェーン", "complexity_tier": "T4", "furigana": "一社[いっしゃ]の判断[はんだん]が次々[つぎつぎ]と取引先[とりひきさき]へ伝[つた]わるチェーンが、社会全体[しゃかいぜんたい]の流[なが]れを決[き]めている。", "sentence_source": "generated"}, {"text": "小さなミスが次のミスを呼び、問題がチェーンのように広がった。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "小[ちい]さなミスが次[つぎ]のミスを呼[よ]び、問題[もんだい]がチェーンのように広[ひろ]がった。", "sentence_source": "generated"}, {"text": "人と人の信頼がチェーンのようにつながって、町を支えている。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "人[ひと]と人[ひと]の信頼[しんらい]がチェーンのようにつながって、町[まち]を支[ささ]えている。", "sentence_source": "generated"}, {"text": "原因と結果が長いチェーンになって、説明するのが難しい。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "原因[げんいん]と結果[けっか]が長[なが]いチェーンになって、説明[せつめい]するのが難[むずか]しい。", "sentence_source": "generated"}, {"text": "発注から配送までのチェーンのどこかが切れると、商品が届かない。", "target_word": "チェーン", "complexity_tier": "T4", "furigana": "発注[はっちゅう]から配送[はいそう]までのチェーンのどこかが切[き]れると、商品[しょうひん]が届[とど]かない。", "sentence_source": "generated"}, {"text": "親切がチェーンのように次の人へ伝わっていった。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "親切[しんせつ]がチェーンのように次[つぎ]の人[ひと]へ伝[つた]わっていった。", "sentence_source": "generated"}, {"text": "情報のチェーンが長いほど、話は変わりやすい。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "情報[じょうほう]のチェーンが長[なが]いほど、話[はなし]は変[か]わりやすい。", "sentence_source": "generated"}, {"text": "彼の話は、思いつきがチェーンのように続いて、終わらなかった。", "target_word": "チェーン", "complexity_tier": "T4", "furigana": "彼[かれ]の話[はなし]は、思[おも]いつきがチェーンのように続[つづ]いて、終[お]わらなかった。", "sentence_source": "generated"}, {"text": "この会社では、仕事のチェーンを見直して無駄をなくした。", "target_word": "チェーン", "complexity_tier": "T4", "furigana": "この会社[かいしゃ]では、仕事[しごと]のチェーンを見直[みなお]して無駄[むだ]をなくした。", "sentence_source": "generated"}, {"text": "事故は、小さな偶然のチェーンから起きた。", "target_word": "チェーン", "complexity_tier": "T3", "furigana": "事故[じこ]は、小[ちい]さな偶然[ぐうぜん]のチェーンから起[お]きた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "チェーン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事が次々につながった連なり・連鎖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1e5117e-6210-437d-8c4a-90abcde11eb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35511, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "チェーン", "is_correct": true, "explanation": "『伝わるチェーン』の『チェーン』が入り、次々と伝わる連なりを表す語として文が成立する。"}, {"text": "ピアノ", "is_correct": false, "explanation": "『伝わるピアノ』は成り立たず、次々と連なる意味を表さない。"}, {"text": "スプーン", "is_correct": false, "explanation": "『伝わるスプーン』は意味をなさず、ここに入る語ではない。"}, {"text": "カーテン", "is_correct": false, "explanation": "『伝わるカーテン』は不自然で、連なりの意味にならない。"}], "explanations": {"チェーン": "『伝わるチェーン』の『チェーン』が入り、次々と伝わる連なりを表す語として文が成立する。", "ピアノ": "『伝わるピアノ』は成り立たず、次々と連なる意味を表さない。", "スプーン": "『伝わるスプーン』は意味をなさず、ここに入る語ではない。", "カーテン": "『伝わるカーテン』は不自然で、連なりの意味にならない。"}, "sentence_index": 0, "correct_answer": "チェーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地図のチェーンが途切れていて、道がわからない。", "explanation": "ここは〈線〉の意味。チェーンは連なった鎖や連続を指し、地図上の線は表せないので、この文脈では使えない。"}, {"text": "駅までのチェーンを地図で確認した。", "explanation": "ここは〈経路〉の意味。チェーンは連なったものを指し、道順の経路という意味では使わない。"}, {"text": "雨の中、チケットを求める人のチェーンを、大きな鍋で煮た。", "explanation": "ここは〈料理〉の意味。チェーンは人の並びを煮る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35511, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "チェーン", "is_correct": true, "explanation": "『情報のチェーン』は情報が次々と伝わる連なりを表し、文脈に合う。"}, {"text": "バッグ", "is_correct": false, "explanation": "『情報のバッグ』は成り立たず、連なりを表す語ではない。"}, {"text": "マスク", "is_correct": false, "explanation": "『情報のマスク』は意味をなさず、この文には入らない。"}, {"text": "ラジオ", "is_correct": false, "explanation": "『情報のラジオ』は不自然で、情報の連なりの意味にならない。"}], "explanations": {"チェーン": "『情報のチェーン』は情報が次々と伝わる連なりを表し、文脈に合う。", "バッグ": "『情報のバッグ』は成り立たず、連なりを表す語ではない。", "マスク": "『情報のマスク』は意味をなさず、この文には入らない。", "ラジオ": "『情報のラジオ』は不自然で、情報の連なりの意味にならない。"}, "sentence_index": 6, "correct_answer": "チェーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電話のチェーンが切れて、声が聞こえなかった。", "explanation": "ここは〈回線〉の意味。チェーンは連なった鎖や連続を指し、通話の回線という意味では使わない。"}, {"text": "文章のチェーンが途中で切れて、読みにくかった。", "explanation": "ここは〈段落〉の意味。チェーンは連なりを指すが、文章の区切りを表す段落の意味では使わない。"}, {"text": "チームの作戦を、チェーンで立て直した。", "explanation": "ここは〈道具〉の意味。チェーンは作戦を立て直す手段として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35511, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不安がチェーンを社内に広がった。", "corrected_sentence": "不安がチェーンのように社内に広がった。", "error_description": "正しくは『チェーンのように』。比喩には『〜のように』が必要で、『を』は他動詞の目的語を示すため、自動詞『広がった』と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35511, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仕事のチェーンが途切れさせて、納期が遅れた。", "corrected_sentence": "仕事のチェーンが途切れて、納期が遅れた。", "error_description": "正しくは『途切れて』。『途切れる』は自動詞で、『途切れさせて』は誰かが切る使役になり、主語がチェーンのこの文には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6223e701-db4d-4fad-8ad6-90e467be2509') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
