INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35512, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人の名前や物の名前を言うこと。", "primary_collocate": null, "pronunciation": "よぶ", "ipa": "joβɯ", "syllable_count": 2, "sentences": [{"text": "友だちはみんな、私をあだ名で呼ぶ。", "target_word": "呼ぶ", "complexity_tier": "T3", "furigana": "友[とも]だちはみんな、私[わたし]をあだ名[な]で呼[よ]ぶ。", "sentence_source": "generated"}, {"text": "この花は、地方によって別の名前で呼ばれている。", "target_word": "呼ばれ", "complexity_tier": "T3", "furigana": "この花[はな]は、地方[ちほう]によって別[べつ]の名前[なまえ]で呼[よ]ばれている。", "sentence_source": "generated"}, {"text": "先生は出席を取るとき、一人ずつ名前を呼んだ。", "target_word": "呼んだ", "complexity_tier": "T3", "furigana": "先生[せんせい]は出席[しゅっせき]を取[と]るとき、一人[ひとり]ずつ名前[なまえ]を呼[よ]んだ。", "sentence_source": "generated"}, {"text": "日本では、この魚を「ぶり」と呼ぶ。", "target_word": "呼ぶ", "complexity_tier": "T3", "furigana": "日本[にほん]では、この魚[さかな]を「ぶり」と呼[よ]ぶ。", "sentence_source": "generated"}, {"text": "子どものころ、祖母のことを「ばあば」と呼んでいた。", "target_word": "呼んで", "complexity_tier": "T3", "furigana": "子[こ]どものころ、祖母[そぼ]のことを「ばあば」と呼[よ]んでいた。", "sentence_source": "generated"}, {"text": "初めて会った人を名前で呼ぶのは、少し恥ずかしい。", "target_word": "呼ぶ", "complexity_tier": "T3", "furigana": "初[はじ]めて会[あ]った人[ひと]を名前[なまえ]で呼[よ]ぶのは、少[すこ]し恥[は]ずかしい。", "sentence_source": "generated"}, {"text": "彼は自分の犬を「ココ」と呼んでかわいがっている。", "target_word": "呼んで", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の犬[いぬ]を「ココ」と呼[よ]んでかわいがっている。", "sentence_source": "generated"}, {"text": "私のことは、さんをつけずに下の名前で呼んでほしい。", "target_word": "呼んで", "complexity_tier": "T3", "furigana": "私[わたし]のことは、さんをつけずに下[した]の名前[なまえ]で呼[よ]んでほしい。", "sentence_source": "generated"}, {"text": "この小さな店を、町の人は「駅前の台所」と呼ぶ。", "target_word": "呼ぶ", "complexity_tier": "T3", "furigana": "この小[ちい]さな店[みせ]を、町[まち]の人[ひと]は「駅前[えきまえ]の台所[だいどころ]」と呼[よ]ぶ。", "sentence_source": "generated"}, {"text": "名前を呼ばれたら、大きな声で返事をしなさい。", "target_word": "呼ばれ", "complexity_tier": "T3", "furigana": "名前[なまえ]を呼[よ]ばれたら、大[おお]きな声[こえ]で返事[へんじ]をしなさい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "呼ぶ", "label": "辞書形"}, {"form": "呼びます", "label": "丁寧形"}, {"form": "呼んで", "label": "て形"}, {"form": "呼んだ", "label": "た形"}, {"form": "呼ばない", "label": "ない形"}, {"form": "呼べば", "label": "仮定形"}, {"form": "呼ばれる", "label": "受身形"}], "register": "普通体（中立）", "sense_fingerprint": "名前や呼び名を口に出して言う、「〜と呼ぶ」「名前を呼ぶ」の意味の「呼ぶ」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35512, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼ぶ", "is_correct": true, "explanation": "「あだ名で」と組み合わさり、「名前を言う」意味で文の述語として自然に入る。"}, {"text": "忘れる", "is_correct": false, "explanation": "「あだ名で忘れる」は意味が通らず、文の述語として合わない。"}, {"text": "直す", "is_correct": false, "explanation": "「私をあだ名で直す」は意味が通らず、この文脈に合わない。"}, {"text": "話す", "is_correct": false, "explanation": "「私をあだ名で話す」は意味が通らず、人を対象にした文として合わない。"}], "explanations": {"呼ぶ": "「あだ名で」と組み合わさり、「名前を言う」意味で文の述語として自然に入る。", "忘れる": "「あだ名で忘れる」は意味が通らず、文の述語として合わない。", "直す": "「私をあだ名で直す」は意味が通らず、この文脈に合わない。", "話す": "「私をあだ名で話す」は意味が通らず、人を対象にした文として合わない。"}, "sentence_index": 0, "correct_answer": "呼ぶ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寝る前に、本の表紙を呼んで一日を振り返る。", "explanation": "ここは〈読む〉の意味。〈呼ぶ〉は名前や物の名を言うことで、本の内容を読む動作には使わない。"}, {"text": "大雨だったので、駅の前で傘を呼んで買った。", "explanation": "ここは〈取り寄せる〉の意味。〈呼ぶ〉は名前を言うことや人を来させることで、物を届けさせる意味には使わない。"}, {"text": "雨が降ってきたので、私は空を呼んで傘を広げた。", "explanation": "ここは〈見上げる〉の意味。〈呼ぶ〉は名前を言うことで、空を見上げる動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35512, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼んで", "is_correct": true, "explanation": "「と呼んで」の形で「かわいがっている」につながり、文の形に合う。"}, {"text": "数えて", "is_correct": false, "explanation": "「と数えて」は意味が通らず、犬の名前を言う文脈に合わない。"}, {"text": "捨てて", "is_correct": false, "explanation": "「と捨てて」は意味が通らず、「かわいがっている」と矛盾する。"}, {"text": "叱って", "is_correct": false, "explanation": "「と叱って」は「かわいがっている」と矛盾し、名前を言う文脈に合わない。"}], "explanations": {"呼んで": "「と呼んで」の形で「かわいがっている」につながり、文の形に合う。", "数えて": "「と数えて」は意味が通らず、犬の名前を言う文脈に合わない。", "捨てて": "「と捨てて」は意味が通らず、「かわいがっている」と矛盾する。", "叱って": "「と叱って」は「かわいがっている」と矛盾し、名前を言う文脈に合わない。"}, "sentence_index": 6, "correct_answer": "呼んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末に友人を家に呼んで、一緒に食事をした。", "explanation": "ここは〈招く〉の意味。〈呼ぶ〉は名前を言うことで、人を家に来させる意味はこの義項に含まれない。"}, {"text": "店員に何を聞かれても、彼はいつも『いいえ』と呼ぶ。", "explanation": "ここは〈言う〉の意味。〈呼ぶ〉は名前を言うことなので、返事として言う場合は〈言う〉を使う。"}, {"text": "雨乞いの儀式で、村人たちは鐘を呼んだ。", "explanation": "ここは〈鳴らす〉の意味。〈呼ぶ〉は名前を言うことで、鐘を鳴らす動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35512, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生が生徒の名前を呼ばれて、出席を取った。", "corrected_sentence": "先生が生徒の名前を呼んで、出席を取った。", "error_description": "主語の先生が名前を言う側なので、能動の「呼んで」が正しいのに、受身の「呼ばれて」になっている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "呼ばれ", "is_correct": true, "explanation": "「呼ばれている」の形で、受身の語幹として文の形に合う。"}, {"text": "呼ぶ", "is_correct": false, "explanation": "辞書形の「呼ぶ」は「ている」が続かず、文の形に合わない。"}, {"text": "呼んだ", "is_correct": false, "explanation": "過去形の「呼んだ」は受身にならず、「別の名前で」の文の形に合わない。"}, {"text": "呼ばない", "is_correct": false, "explanation": "否定形の「呼ばない」は「ている」と続かず、文の意味も変わるので合わない。"}], "correct_form": "呼ばれ", "base_form": "呼ぶ", "form_label": "受身形", "sentence_index": 1, "explanations": {"呼ばれ": "「呼ばれている」の形で、受身の語幹として文の形に合う。", "呼ぶ": "辞書形の「呼ぶ」は「ている」が続かず、文の形に合わない。", "呼んだ": "過去形の「呼んだ」は受身にならず、「別の名前で」の文の形に合わない。", "呼ばない": "否定形の「呼ばない」は「ている」と続かず、文の意味も変わるので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35512, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔から友だちは、私を「ミキ」と呼んだ。", "corrected_sentence": "昔から友だちは、私を「ミキ」と呼んでいる。", "error_description": "「昔から」は今も続いている習慣を表すので、「呼んでいる」が正しい。過去形の「呼んだ」は終わった出来事を表すため、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "呼んで", "is_correct": true, "explanation": "「呼んでほしい」の形で、て形として文の形に合う。"}, {"text": "呼び", "is_correct": false, "explanation": "連用形の「呼び」は「ほしい」につながらず、この文の形に合わない。"}, {"text": "呼ばせ", "is_correct": false, "explanation": "使役形の「呼ばせ」は「ほしい」につながらず、文の意味も変わるので合わない。"}, {"text": "呼ばず", "is_correct": false, "explanation": "否定の連用形「呼ばず」は「ほしい」とつながらず、この文の形に合わない。"}], "correct_form": "呼んで", "base_form": "呼ぶ", "form_label": "て形", "sentence_index": 7, "explanations": {"呼んで": "「呼んでほしい」の形で、て形として文の形に合う。", "呼び": "連用形の「呼び」は「ほしい」につながらず、この文の形に合わない。", "呼ばせ": "使役形の「呼ばせ」は「ほしい」につながらず、文の意味も変わるので合わない。", "呼ばず": "否定の連用形「呼ばず」は「ほしい」とつながらず、この文の形に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35516, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「貿易で大きくなりました」で、貿易を理由とする意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「貿易を大きくなりました」は文が成り立たず、大きくなるの主体を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「貿易へ大きくなりました」は方向を表す語で、大きくなる理由にならない。"}, {"text": "の", "is_correct": false, "explanation": "「貿易の大きくなりました」は連体修飾の形で、文の述語として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "正解。「貿易で大きくなりました」で、貿易を理由とする意味になる。", "を": "「貿易を大きくなりました」は文が成り立たず、大きくなるの主体を示せない。", "へ": "「貿易へ大きくなりました」は方向を表す語で、大きくなる理由にならない。", "の": "「貿易の大きくなりました」は連体修飾の形で、文の述語として成り立たない。"}, "error_tags": {"を": "対象", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35516, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35516, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国と国の間で、物を売ったり買ったりすることです。", "primary_collocate": null, "pronunciation": "ぼうえき", "ipa": "boːeki", "syllable_count": 3, "sentences": [{"text": "日本は多くの国と貿易をしています。", "target_word": "貿易", "complexity_tier": "T3", "furigana": "日本[にほん]は多[おお]くの国[くに]と貿易[ぼうえき]をしています。", "sentence_source": "generated"}, {"text": "この会社は、アジアの国との貿易で大きくなりました。", "target_word": "貿易", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、アジアの国[くに]との貿易[ぼうえき]で大[おお]きくなりました。", "sentence_source": "generated"}, {"text": "貿易のおかげで、外国から安い果物を買うことができます。", "target_word": "貿易", "complexity_tier": "T3", "furigana": "貿易[ぼうえき]のおかげで、外国[がいこく]から安[やす]い果物[くだもの]を買[か]うことができます。", "sentence_source": "generated"}, {"text": "港には、貿易の船がたくさん集まります。", "target_word": "貿易", "complexity_tier": "T3", "furigana": "港[みなと]には、貿易[ぼうえき]の船[ふね]がたくさん集[あつ]まります。", "sentence_source": "generated"}, {"text": "二つの国の貿易が増えて、仕事を探す人も多くなりました。", "target_word": "貿易", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]の貿易[ぼうえき]が増[ふ]えて、仕事[しごと]を探[さが]す人[ひと]も多[おお]くなりました。", "sentence_source": "generated"}, {"text": "昔、長崎は外国との貿易で有名な町でした。", "target_word": "貿易", "complexity_tier": "T3", "furigana": "昔[むかし]、長崎[ながさき]は外国[がいこく]との貿易[ぼうえき]で有名[ゆうめい]な町[まち]でした。", "sentence_source": "generated"}, {"text": "兄は貿易の仕事をしていて、よく海外へ行きます。", "target_word": "貿易", "complexity_tier": "T3", "furigana": "兄[あに]は貿易[ぼうえき]の仕事[しごと]をしていて、よく海外[かいがい]へ行[い]きます。", "sentence_source": "generated"}, {"text": "戦争が始まって、両国の貿易が止まってしまいました。", "target_word": "貿易", "complexity_tier": "T3", "furigana": "戦争[せんそう]が始[はじ]まって、両国[りょうこく]の貿易[ぼうえき]が止[と]まってしまいました。", "sentence_source": "generated"}, {"text": "資源の少ない国は、貿易で石油を買っています。", "target_word": "貿易", "complexity_tier": "T3", "furigana": "資源[しげん]の少[すく]ない国[くに]は、貿易[ぼうえき]で石油[せきゆ]を買[か]っています。", "sentence_source": "generated"}, {"text": "貿易をすると、国の中にない物も手に入ります。", "target_word": "貿易", "complexity_tier": "T3", "furigana": "貿易[ぼうえき]をすると、国[くに]の中[なか]にない物[もの]も手[て]に入[はい]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "貿易", "label": "名詞"}, {"form": "貿易する", "label": "サ変動詞・辞書形"}, {"form": "貿易した", "label": "サ変動詞・過去形"}, {"form": "貿易して", "label": "サ変動詞・て形"}], "register": "丁寧", "sense_fingerprint": "国と国との間で商品を売買する経済活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa355574-9e18-4c72-a592-28e39dbf69ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35516, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "貿易", "is_correct": true, "explanation": "正解。「日本は多くの国と貿易をしています」で、国と国との売買を表す。"}, {"text": "掃除", "is_correct": false, "explanation": "「国と掃除をしています」は意味が通らず、文が成り立たない。"}, {"text": "散歩", "is_correct": false, "explanation": "「国と散歩をしています」は文脈に合わず、経済活動の意味にならない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「国と洗濯をしています」は成り立たず、文の意味が通らない。"}], "explanations": {"貿易": "正解。「日本は多くの国と貿易をしています」で、国と国との売買を表す。", "掃除": "「国と掃除をしています」は意味が通らず、文が成り立たない。", "散歩": "「国と散歩をしています」は文脈に合わず、経済活動の意味にならない。", "洗濯": "「国と洗濯をしています」は成り立たず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "貿易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町の八百屋は、近所の農家と貿易を続けている。", "explanation": "ここは〈取引〉の意味。貿易は国と国の間の売買なので、近所の相手との取引には使わない。"}, {"text": "学生たちは海外の学校と貿易を続けている。", "explanation": "ここは〈交流〉の意味。人や文化のやり取りを指すので、物の売買を表す〈貿易〉は合わない。"}, {"text": "友だちとお菓子を貿易した。", "explanation": "ここは〈交換〉の意味。個人同士の物のやり取りは〈交換〉で、国と国の売買を表す〈貿易〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35516, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "貿易", "is_correct": true, "explanation": "正解。「貿易の仕事をしていて」で、国際的な売買に関わる仕事を表す。"}, {"text": "天気", "is_correct": false, "explanation": "「天気の仕事」は意味が通らず、職業の説明にならない。"}, {"text": "眠気", "is_correct": false, "explanation": "「眠気の仕事」は成り立たず、職業を表せない。"}, {"text": "湿気", "is_correct": false, "explanation": "「湿気の仕事」は意味が通らず、職業にならない。"}], "explanations": {"貿易": "正解。「貿易の仕事をしていて」で、国際的な売買に関わる仕事を表す。", "天気": "「天気の仕事」は意味が通らず、職業の説明にならない。", "眠気": "「眠気の仕事」は成り立たず、職業を表せない。", "湿気": "「湿気の仕事」は意味が通らず、職業にならない。"}, "sentence_index": 6, "correct_answer": "貿易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は町の市場で小さな貿易をしている。", "explanation": "ここは〈商売〉の意味。貿易は国と国の間の売買なので、町の中の商いには使わない。"}, {"text": "会社は新しい靴を店で貿易している。", "explanation": "ここは〈販売〉の意味。国内の店での売り方なので、国境を越える〈貿易〉は合わない。"}, {"text": "祖父は孫に古い時計を貿易した。", "explanation": "ここは〈贈与〉の意味。無償で物を渡す場合は売買ではないので、〈貿易〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35516, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "日本は多くの国と貿易をかけていて、食料を輸入している。", "corrected_sentence": "日本は多くの国と貿易をしていて、食料を輸入している。", "error_description": "「貿易をする」が正しい。「貿易をかける」は貿易と結びつかない誤った連語。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35516, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "日本は外国との貿易に食品を売っています。", "corrected_sentence": "日本は外国との貿易で食品を売っています。", "error_description": "手段を表す「で」が正しい。「貿易に食品を売る」は助詞が誤りで、貿易の方法を示せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35518, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "正解。「外国へ輸出したい」で、輸出先の方向を示す。"}, {"text": "と", "is_correct": false, "explanation": "「外国と輸出したい」は「と」が動詞の前で成り立たず、不自然。"}, {"text": "で", "is_correct": false, "explanation": "「外国で輸出したい」は場所を表し、輸出先の方向にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「外国の輸出したい」は連体修飾の形で、文の述語が成り立たない。"}], "correct_answer": "へ", "explanations": {"へ": "正解。「外国へ輸出したい」で、輸出先の方向を示す。", "と": "「外国と輸出したい」は「と」が動詞の前で成り立たず、不自然。", "で": "「外国で輸出したい」は場所を表し、輸出先の方向にならず不自然。", "の": "「外国の輸出したい」は連体修飾の形で、文の述語が成り立たない。"}, "error_tags": {"を": "対象", "の": "連体修飾", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "輸入", "is_correct": true, "explanation": "正解。外国から品物を買い入れることで、輸出の対義語。"}, {"text": "散歩", "is_correct": false, "explanation": "対義語ではない。ただ歩くことで、輸出とは関係がない。"}, {"text": "掃除", "is_correct": false, "explanation": "対義語ではない。家の中を清める行為で、品物の売買とは関係がない。"}, {"text": "音楽", "is_correct": false, "explanation": "対義語ではない。音を楽しむ芸術で、品物の売買とは関係がない。"}], "correct_answer": "輸入", "explanations": {"輸入": "正解。外国から品物を買い入れることで、輸出の対義語。", "散歩": "対義語ではない。ただ歩くことで、輸出とは関係がない。", "掃除": "対義語ではない。家の中を清める行為で、品物の売買とは関係がない。", "音楽": "対義語ではない。音を楽しむ芸術で、品物の売買とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35518, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「お茶を輸出する仕事」で、輸出する品物を示す。"}, {"text": "に", "is_correct": false, "explanation": "「お茶に輸出する仕事」は品物を示す助詞として合わず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「お茶へ輸出する仕事」は方向の〈へ〉が品物には使えず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「お茶の輸出する仕事」は連体修飾の形として文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「お茶を輸出する仕事」で、輸出する品物を示す。", "に": "「お茶に輸出する仕事」は品物を示す助詞として合わず、不自然。", "へ": "「お茶へ輸出する仕事」は方向の〈へ〉が品物には使えず、不自然。", "の": "「お茶の輸出する仕事」は連体修飾の形として文が成り立たない。"}, "error_tags": {"に": "場所・相手", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "輸入", "is_correct": true, "explanation": "正解。外国から品物を買い入れることで、輸出の対義語。"}, {"text": "旅行", "is_correct": false, "explanation": "対義語ではない。目的地へ行く移動で、品物の売買とは反対の関係ではない。"}, {"text": "病気", "is_correct": false, "explanation": "対義語ではない。体の不調を指すもので、輸出との関係はない。"}, {"text": "手紙", "is_correct": false, "explanation": "対義語ではない。文章を送る物で、品物の売買とは反対の関係にはならない。"}], "correct_answer": "輸入", "explanations": {"輸入": "正解。外国から品物を買い入れることで、輸出の対義語。", "旅行": "対義語ではない。目的地へ行く移動で、品物の売買とは反対の関係ではない。", "病気": "対義語ではない。体の不調を指すもので、輸出との関係はない。", "手紙": "対義語ではない。文章を送る物で、品物の売買とは反対の関係にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35518, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "外国に品物を売ること。", "primary_collocate": null, "pronunciation": "ゆしゅつ", "ipa": "jɯɕɯtsɯ", "syllable_count": 3, "sentences": [{"text": "この国は車を輸出して、たくさんのお金を得ている。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "この国[くに]は車[くるま]を輸出[ゆしゅつ]して、たくさんのお金[かね]を得[え]ている。", "sentence_source": "generated"}, {"text": "農家は、育てた果物を外国へ輸出したいと考えている。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "農家[のうか]は、育[そだ]てた果物[くだもの]を外国[がいこく]へ輸出[ゆしゅつ]したいと考[かんが]えている。", "sentence_source": "generated"}, {"text": "台風の被害で、お米の輸出が一時止まった。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "台風[たいふう]の被害[ひがい]で、お米[こめ]の輸出[ゆしゅつ]が一時[いちじ]止[と]まった。", "sentence_source": "generated"}, {"text": "日本から輸出される物の中で、機械は特に多い。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "日本[にほん]から輸出[ゆしゅつ]される物[もの]の中[なか]で、機械[きかい]は特[とく]に多[おお]い。", "sentence_source": "generated"}, {"text": "円が安くなると、輸出が増えやすい。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "円[えん]が安[やす]くなると、輸出[ゆしゅつ]が増[ふ]えやすい。", "sentence_source": "generated"}, {"text": "工場で作った時計を、アメリカに輸出している。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "工場[こうじょう]で作[つく]った時計[とけい]を、アメリカに輸出[ゆしゅつ]している。", "sentence_source": "generated"}, {"text": "肉の輸出には、国の検査が必要だ。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "肉[にく]の輸出[ゆしゅつ]には、国[くに]の検査[けんさ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "その会社は、お茶を輸出する仕事を始めた。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は、お茶[ちゃ]を輸出[ゆしゅつ]する仕事[しごと]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "輸出が減ったため、工場の仕事も少なくなった。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "輸出[ゆしゅつ]が減[へ]ったため、工場[こうじょう]の仕事[しごと]も少[すく]なくなった。", "sentence_source": "generated"}, {"text": "彼は中古の自転車を東南アジアへ輸出して商売をしている。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "彼[かれ]は中古[ちゅうこ]の自転車[じてんしゃ]を東南[とうなん]アジアへ輸出[ゆしゅつ]して商売[しょうばい]をしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "輸出", "label": "基本形"}, {"form": "輸出する", "label": "動詞形"}, {"form": "輸出した", "label": "過去形"}, {"form": "輸出される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "品物を外国へ売って送り出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa355574-9e18-4c72-a592-28e39dbf69ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35518, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "輸出して", "is_correct": true, "explanation": "正解。「車を輸出して、たくさんのお金を得ている」で、外国へ売ってお金を得る意味になる。"}, {"text": "廃棄して", "is_correct": false, "explanation": "「車を廃棄して、お金を得ている」は廃棄に費用がかかり、お金を得る文脈に合わない。"}, {"text": "笑って", "is_correct": false, "explanation": "「車を笑って」は動詞が成り立たず、文の意味が通らない。"}, {"text": "眠って", "is_correct": false, "explanation": "「車を眠って」は意味が通らず、文が成り立たない。"}], "explanations": {"輸出して": "正解。「車を輸出して、たくさんのお金を得ている」で、外国へ売ってお金を得る意味になる。", "廃棄して": "「車を廃棄して、お金を得ている」は廃棄に費用がかかり、お金を得る文脈に合わない。", "笑って": "「車を笑って」は動詞が成り立たず、文の意味が通らない。", "眠って": "「車を眠って」は意味が通らず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "輸出して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "うちの会社は海外から部品を輸出している。", "explanation": "ここは〈輸入〉の意味。外国から買う方向なのに、〈輸出〉は外国へ売る方向を表すので合わない。"}, {"text": "店は地元の人に野菜を輸出している。", "explanation": "ここは〈販売〉の意味。国内の人に売ることは〈輸出〉ではないので、外国へ売る定義と合わない。"}, {"text": "工場は製品を県内の店へ輸出した。", "explanation": "ここは〈出荷〉の意味。県内へ送ることは外国へ売ることではないので、〈輸出〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35518, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "輸出", "is_correct": true, "explanation": "正解。「肉の輸出には、国の検査が必要だ」で、外国へ売る際の規則を表す。"}, {"text": "掃除", "is_correct": false, "explanation": "「肉の掃除には、国の検査が必要だ」は意味が通らず、検査の文にならない。"}, {"text": "散歩", "is_correct": false, "explanation": "「肉の散歩」は成り立たず、文が意味を持たない。"}, {"text": "睡眠", "is_correct": false, "explanation": "「肉の睡眠」は意味が通らず、文の主題にならない。"}], "explanations": {"輸出": "正解。「肉の輸出には、国の検査が必要だ」で、外国へ売る際の規則を表す。", "掃除": "「肉の掃除には、国の検査が必要だ」は意味が通らず、検査の文にならない。", "散歩": "「肉の散歩」は成り立たず、文が意味を持たない。", "睡眠": "「肉の睡眠」は意味が通らず、文の主題にならない。"}, "sentence_index": 6, "correct_answer": "輸出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は孫に手作りの服を輸出した。", "explanation": "ここは〈送る〉の意味。無償で贈るので、外国へ売る〈輸出〉とは合わない。"}, {"text": "私は町のお店で新しい本を輸出した。", "explanation": "ここは〈購入〉の意味。国内で買うことは〈輸出〉ではないので、定義には合わない。"}, {"text": "トラックで荷物を隣町へ輸出した。", "explanation": "ここは〈運ぶ〉の意味。隣町へ運ぶのは外国へ売ることではないので、〈輸出〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35518, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工場は製品の輸出を作っていて、利益が増えた。", "corrected_sentence": "この工場は製品の輸出を行っていて、利益が増えた。", "error_description": "「輸出を行う」が正しい。「輸出を作る」は輸出と結びつかない誤った連語。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35518, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この国のお米は海外へたくさん輸出れている。", "corrected_sentence": "この国のお米は海外へたくさん輸出されている。", "error_description": "「輸出される」が正しい。「輸出する」はサ変なので受身は「される」。「輸出れる」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35519, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「世界中に輸出される」で、輸出の行き先を示す。輸出の直前に付く正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "「世界中が輸出される」は主語にしても意味が通らず、受身文の主体にもならない。"}, {"text": "を", "is_correct": false, "explanation": "「世界中を輸出される」は、受身文で場所を目的語として取れず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「世界中と輸出される」は相手や並列を表すが、輸出の行き先としては成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「世界中に輸出される」で、輸出の行き先を示す。輸出の直前に付く正しい助詞。", "が": "「世界中が輸出される」は主語にしても意味が通らず、受身文の主体にもならない。", "を": "「世界中を輸出される」は、受身文で場所を目的語として取れず不自然。", "と": "「世界中と輸出される」は相手や並列を表すが、輸出の行き先としては成り立たない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "相手・並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "輸入", "is_correct": true, "explanation": "対義語。輸出（国内から外国へ売る）と輸入（外国から買い入れる）は向きが反対で、国語辞典でも対になる。"}, {"text": "生産", "is_correct": false, "explanation": "対義語ではない。生産は物を作ることで、輸出の反対語にはならない。"}, {"text": "寄付", "is_correct": false, "explanation": "対義語ではない。寄付は無償で物を渡す行為で、輸出と向きが反対という関係にはない。"}, {"text": "修理", "is_correct": false, "explanation": "対義語ではない。修理は壊れた物を直す行為で、輸出とは反対の関係にならない。"}], "correct_answer": "輸入", "explanations": {"輸入": "対義語。輸出（国内から外国へ売る）と輸入（外国から買い入れる）は向きが反対で、国語辞典でも対になる。", "生産": "対義語ではない。生産は物を作ることで、輸出の反対語にはならない。", "寄付": "対義語ではない。寄付は無償で物を渡す行為で、輸出と向きが反対という関係にはない。", "修理": "対義語ではない。修理は壊れた物を直す行為で、輸出とは反対の関係にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35519, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「輸出で利益を出す」の手段を示す正しい助詞。輸出という手段で利益を得る意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「輸出を利益を出す」は目的語が二つ重なり、文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「輸出と利益を出す」は並列にしても、利益を出す手段として合わず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「輸出へ利益を出す」は方向を示すが、利益を出す手段にはならない。"}], "correct_answer": "で", "explanations": {"で": "「輸出で利益を出す」の手段を示す正しい助詞。輸出という手段で利益を得る意味になる。", "を": "「輸出を利益を出す」は目的語が二つ重なり、文として成り立たない。", "と": "「輸出と利益を出す」は並列にしても、利益を出す手段として合わず不自然。", "へ": "「輸出へ利益を出す」は方向を示すが、利益を出す手段にはならない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "輸入", "is_correct": true, "explanation": "対義語。輸出（国内から外国へ売る）と輸入（外国から買い入れる）は向きが反対で、国語辞典でも対になる。"}, {"text": "購入", "is_correct": false, "explanation": "対義語ではない。購入は買うことで、輸出（売る方向）の反対語として対になる関係ではない。"}, {"text": "製造", "is_correct": false, "explanation": "対義語ではない。製造は物を作る行為で、輸出の反対語にはならない。"}, {"text": "開発", "is_correct": false, "explanation": "対義語ではない。開発は新しく生み出すことで、輸出と向きが反対という関係にはない。"}], "correct_answer": "輸入", "explanations": {"輸入": "対義語。輸出（国内から外国へ売る）と輸入（外国から買い入れる）は向きが反対で、国語辞典でも対になる。", "購入": "対義語ではない。購入は買うことで、輸出（売る方向）の反対語として対になる関係ではない。", "製造": "対義語ではない。製造は物を作る行為で、輸出の反対語にはならない。", "開発": "対義語ではない。開発は新しく生み出すことで、輸出と向きが反対という関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35519, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自国で生産した商品やサービスを、外国に販売すること。", "primary_collocate": null, "pronunciation": "ゆしゅつ", "ipa": "jɯɕɯtsɯ", "syllable_count": 3, "sentences": [{"text": "政府は、国内の技術を海外へ輸出する計画を発表した。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "政府[せいふ]は、国内[こくない]の技術[ぎじゅつ]を海外[かいがい]へ輸出[ゆしゅつ]する計画[けいかく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "日本のアニメは、世界中に輸出される人気の商品になった。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "日本[にほん]のアニメは、世界中[せかいじゅう]に輸出[ゆしゅつ]される人気[にんき]の商品[しょうひん]になった。", "sentence_source": "generated"}, {"text": "この国は、ソフトウェアの輸出で経済を伸ばしている。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "この国[くに]は、ソフトウェアの輸出[ゆしゅつ]で経済[けいざい]を伸[の]ばしている。", "sentence_source": "generated"}, {"text": "地元で作った日本酒を輸出するために、会社は英語の説明書を作った。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "地元[じもと]で作[つく]った日本酒[にほんしゅ]を輸出[ゆしゅつ]するために、会社[かいしゃ]は英語[えいご]の説明書[せつめいしょ]を作[つく]った。", "sentence_source": "generated"}, {"text": "輸出の売り上げが、去年より二割増えた。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "輸出[ゆしゅつ]の売[う]り上[あ]げが、去年[きょねん]より二割[にわり]増[ふ]えた。", "sentence_source": "generated"}, {"text": "鉄道の技術を輸出する話が、ほかの国と進んでいる。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "鉄道[てつどう]の技術[ぎじゅつ]を輸出[ゆしゅつ]する話[はなし]が、ほかの国[くに]と進[すす]んでいる。", "sentence_source": "generated"}, {"text": "国内で売れなくなった商品を、海外に輸出して在庫を減らした。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "国内[こくない]で売[う]れなくなった商品[しょうひん]を、海外[かいがい]に輸出[ゆしゅつ]して在庫[ざいこ]を減[へ]らした。", "sentence_source": "generated"}, {"text": "輸出で利益を出すには、品質の高さが欠かせない。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "輸出[ゆしゅつ]で利益[りえき]を出[だ]すには、品質[ひんしつ]の高[たか]さが欠[か]かせない。", "sentence_source": "generated"}, {"text": "自動車の輸出が好調で、会社の利益が大きく伸びた。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "自動車[じどうしゃ]の輸出[ゆしゅつ]が好調[こうちょう]で、会社[かいしゃ]の利益[りえき]が大[おお]きく伸[の]びた。", "sentence_source": "generated"}, {"text": "小さな会社でも、インターネットを使って商品を輸出できる時代だ。", "target_word": "輸出", "complexity_tier": "T3", "furigana": "小[ちい]さな会社[かいしゃ]でも、インターネットを使[つか]って商品[しょうひん]を輸出[ゆしゅつ]できる時代[じだい]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "輸出", "label": "基本形"}, {"form": "輸出する", "label": "動詞形"}, {"form": "輸出した", "label": "過去形"}, {"form": "輸出される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "自国で作った商品や技術を外国に販売すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa355574-9e18-4c72-a592-28e39dbf69ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35519, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "輸出", "is_correct": true, "explanation": "「海外へ〜する計画」に入る名詞で、国内の技術を外国へ売り出すという意味に合う。"}, {"text": "削除", "is_correct": false, "explanation": "「技術を海外へ削除する計画」は意味が通らない。削除はデータなどを消す行為で、海外への提供とは結びつかない。"}, {"text": "中止", "is_correct": false, "explanation": "「海外へ中止する計画」は動作の向きが成り立たず、計画を発表する文脈にも合わない。"}, {"text": "修理", "is_correct": false, "explanation": "「技術を海外へ修理する」は意味が通らない。修理は壊れた物を直す行為で、海外へ送る計画とは合わない。"}], "explanations": {"輸出": "「海外へ〜する計画」に入る名詞で、国内の技術を外国へ売り出すという意味に合う。", "削除": "「技術を海外へ削除する計画」は意味が通らない。削除はデータなどを消す行為で、海外への提供とは結びつかない。", "中止": "「海外へ中止する計画」は動作の向きが成り立たず、計画を発表する文脈にも合わない。", "修理": "「技術を海外へ修理する」は意味が通らない。修理は壊れた物を直す行為で、海外へ送る計画とは合わない。"}, "sentence_index": 0, "correct_answer": "輸出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "トラックで商品を隣の市まで輸出した。", "explanation": "ここは〈輸送〉の意味。輸出は外国へ売ることなので、国内の隣の市へ運ぶ場合には使わない。"}, {"text": "海外から部品を輸出して、工場で組み立てた。", "explanation": "ここは〈輸入〉の意味。外国から買って国内に入れる動きで、輸出は向きが逆になるので合わない。"}, {"text": "国内の店で、商品を輸出して売った。", "explanation": "ここは〈販売〉の意味。国内の店で売る場合は輸出とは言わず、輸出は外国向けに売ることを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35519, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "輸出", "is_correct": true, "explanation": "「海外に輸出して在庫を減らした」で、売れない商品を外国へ売って減らすという意味に合う。"}, {"text": "点検", "is_correct": false, "explanation": "「海外に点検して在庫を減らした」は意味が通らない。点検は調べる行為で、在庫を減らす手段にならない。"}, {"text": "解約", "is_correct": false, "explanation": "「海外に解約して在庫を減らした」は意味が通らない。解約は契約を打ち切ることで、商品の在庫とは関係がない。"}, {"text": "清掃", "is_correct": false, "explanation": "「海外に清掃して在庫を減らした」は意味が通らない。清掃は場所をきれいにすることで、商品を減らす文には合わない。"}], "explanations": {"輸出": "「海外に輸出して在庫を減らした」で、売れない商品を外国へ売って減らすという意味に合う。", "点検": "「海外に点検して在庫を減らした」は意味が通らない。点検は調べる行為で、在庫を減らす手段にならない。", "解約": "「海外に解約して在庫を減らした」は意味が通らない。解約は契約を打ち切ることで、商品の在庫とは関係がない。", "清掃": "「海外に清掃して在庫を減らした」は意味が通らない。清掃は場所をきれいにすることで、商品を減らす文には合わない。"}, "sentence_index": 6, "correct_answer": "輸出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は毎年、地元の施設に古い本を輸出している。", "explanation": "ここは〈寄付〉の意味。無償で地元の施設に渡す場合は寄付と言い、輸出は外国へ売ることを指す。"}, {"text": "ピザ屋が注文の品を、お客さんの家まで輸出した。", "explanation": "ここは〈配達〉の意味。近所の家へ届けることは配達で、輸出とは言わない。"}, {"text": "図書館で借りた本を、輸出して返した。", "explanation": "ここは〈返却〉の意味。借りた本を図書館に戻すのは返却で、輸出とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35519, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海外への輸出を、現地の法律を調べることから始まる。", "corrected_sentence": "海外への輸出は、現地の法律を調べることから始まる。", "error_description": "「輸出」に付いた「を」が誤り。主題を示すので「は」が正しい。「海外への輸出は〜から始まる」が自然な形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35519, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新製品を海外へ輸出を最中だ。", "corrected_sentence": "新製品を海外へ輸出の最中だ。", "error_description": "「輸出」と「最中」の間の「を」が誤り。「輸出の最中だ」のように「の」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35520, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「輸入が止まる」で、止まるものの主語を示す正しい助詞。輸入の直後に付く。"}, {"text": "を", "is_correct": false, "explanation": "「輸入を止まる」は、自動詞「止まる」に目的語を付けられず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「輸入に止まる」は、止まる先を示す形として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「輸入と止まる」は並列にしても、止まる主体として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「輸入が止まる」で、止まるものの主語を示す正しい助詞。輸入の直後に付く。", "を": "「輸入を止まる」は、自動詞「止まる」に目的語を付けられず不自然。", "に": "「輸入に止まる」は、止まる先を示す形として成り立たない。", "と": "「輸入と止まる」は並列にしても、止まる主体として成り立たない。"}, "error_tags": {"を": "目的語", "に": "方向", "と": "相手・並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "輸出", "is_correct": true, "explanation": "対義語。輸入（外国から買い入れる）と輸出（国内から外国へ売る）は向きが反対で、国語辞典でも対になる。"}, {"text": "寄付", "is_correct": false, "explanation": "対義語ではない。寄付は無償で物を渡す行為で、輸入と向きが反対という関係ではない。"}, {"text": "修理", "is_correct": false, "explanation": "対義語ではない。修理は壊れた物を直す行為で、輸入とは反対の関係にならない。"}, {"text": "製造", "is_correct": false, "explanation": "対義語ではない。製造は物を作る行為で、輸入の反対語にはならない。"}], "correct_answer": "輸出", "explanations": {"輸出": "対義語。輸入（外国から買い入れる）と輸出（国内から外国へ売る）は向きが反対で、国語辞典でも対になる。", "寄付": "対義語ではない。寄付は無償で物を渡す行為で、輸入と向きが反対という関係ではない。", "修理": "対義語ではない。修理は壊れた物を直す行為で、輸入とは反対の関係にならない。", "製造": "対義語ではない。製造は物を作る行為で、輸入の反対語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35520, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「ワインを輸入する」で、輸入の対象であるワインに付く目的語の助詞。"}, {"text": "が", "is_correct": false, "explanation": "「ワインが輸入する会社」では、ワインが輸入する主体になり、会社との関係が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「ワインに輸入する」は、輸入の対象として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「ワインと輸入する」は並列にしても、輸入の目的語として成り立たず不自然。"}], "correct_answer": "を", "explanations": {"を": "「ワインを輸入する」で、輸入の対象であるワインに付く目的語の助詞。", "が": "「ワインが輸入する会社」では、ワインが輸入する主体になり、会社との関係が通らない。", "に": "「ワインに輸入する」は、輸入の対象として成り立たない。", "と": "「ワインと輸入する」は並列にしても、輸入の目的語として成り立たず不自然。"}, "error_tags": {"が": "主語", "に": "方向", "と": "相手・並列"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "輸出", "is_correct": true, "explanation": "対義語。輸入（外国から買い入れる）と輸出（国内から外国へ売る）は向きが反対で、国語辞典でも対になる。"}, {"text": "購入", "is_correct": false, "explanation": "対義語ではない。購入は買うことで、輸入の反対語にはならない。"}, {"text": "生産", "is_correct": false, "explanation": "対義語ではない。生産は物を作ることで、輸入の反対語にはならない。"}, {"text": "開発", "is_correct": false, "explanation": "対義語ではない。開発は新しく生み出すことで、輸入と向きが反対という関係にはない。"}], "correct_answer": "輸出", "explanations": {"輸出": "対義語。輸入（外国から買い入れる）と輸出（国内から外国へ売る）は向きが反対で、国語辞典でも対になる。", "購入": "対義語ではない。購入は買うことで、輸入の反対語にはならない。", "生産": "対義語ではない。生産は物を作ることで、輸入の反対語にはならない。", "開発": "対義語ではない。開発は新しく生み出すことで、輸入と向きが反対という関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35520, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "外国から物を買って、国の中に入れること。", "primary_collocate": null, "pronunciation": "ゆにゅう", "ipa": "jɯɲɯː", "syllable_count": 3, "sentences": [{"text": "日本は食べ物の多くを外国から輸入している。", "target_word": "輸入", "complexity_tier": "T3", "furigana": "日本[にほん]は食[た]べ物[もの]の多[おお]くを外国[がいこく]から輸入[ゆにゅう]している。", "sentence_source": "generated"}, {"text": "石油の輸入が止まると、車も工場も動かなくなる。", "target_word": "輸入", "complexity_tier": "T3", "furigana": "石油[せきゆ]の輸入[ゆにゅう]が止[と]まると、車[くるま]も工場[こうじょう]も動[うご]かなくなる。", "sentence_source": "generated"}, {"text": "店では、イタリアから輸入したチーズを売っている。", "target_word": "輸入", "complexity_tier": "T3", "furigana": "店[みせ]では、イタリアから輸入[ゆにゅう]したチーズを売[う]っている。", "sentence_source": "generated"}, {"text": "小麦の値段が上がったので、輸入にかかるお金が増えた。", "target_word": "輸入", "complexity_tier": "T3", "furigana": "小麦[こむぎ]の値段[ねだん]が上[あ]がったので、輸入[ゆにゅう]にかかるお金[かね]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "この家具は北欧から輸入されたもので、とても丈夫だ。", "target_word": "輸入", "complexity_tier": "T3", "furigana": "この家具[かぐ]は北欧[ほくおう]から輸入[ゆにゅう]されたもので、とても丈夫[じょうぶ]だ。", "sentence_source": "generated"}, {"text": "国内で作るより、輸入するほうが安い野菜もある。", "target_word": "輸入", "complexity_tier": "T3", "furigana": "国内[こくない]で作[つく]るより、輸入[ゆにゅう]するほうが安[やす]い野菜[やさい]もある。", "sentence_source": "generated"}, {"text": "輸入した品物は、港で検査を受けてから店に届く。", "target_word": "輸入", "complexity_tier": "T3", "furigana": "輸入[ゆにゅう]した品物[しなもの]は、港[みなと]で検査[けんさ]を受[う]けてから店[みせ]に届[とど]く。", "sentence_source": "generated"}, {"text": "父は海外からワインを輸入する会社で働いている。", "target_word": "輸入", "complexity_tier": "T3", "furigana": "父[ちち]は海外[かいがい]からワインを輸入[ゆにゅう]する会社[かいしゃ]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "円が高くなると、輸入が増えやすい。", "target_word": "輸入", "complexity_tier": "T3", "furigana": "円[えん]が高[たか]くなると、輸入[ゆにゅう]が増[ふ]えやすい。", "sentence_source": "generated"}, {"text": "木材を輸入に頼っているので、外国の値段が上がると家の費用も上がる。", "target_word": "輸入", "complexity_tier": "T3", "furigana": "木材[もくざい]を輸入[ゆにゅう]に頼[たよ]っているので、外国[がいこく]の値段[ねだん]が上[あ]がると家[いえ]の費用[ひよう]も上[あ]がる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "輸入", "label": "基本形"}, {"form": "輸入する", "label": "動詞形"}, {"form": "輸入した", "label": "過去形"}, {"form": "輸入される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "外国から物を買って国内に入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa355574-9e18-4c72-a592-28e39dbf69ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35520, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "輸入", "is_correct": true, "explanation": "「食べ物の多くを外国から輸入している」で、外国から買い入れる意味に合う。"}, {"text": "点検", "is_correct": false, "explanation": "「外国から点検している」は、食べ物を買い入れる文に合わない。点検は調べる行為である。"}, {"text": "修理", "is_correct": false, "explanation": "「外国から修理している」は、食べ物には修理の対象にならず意味が通らない。"}, {"text": "削除", "is_correct": false, "explanation": "「外国から削除している」は、食べ物には意味が通らない。削除は情報などを消す行為である。"}], "explanations": {"輸入": "「食べ物の多くを外国から輸入している」で、外国から買い入れる意味に合う。", "点検": "「外国から点検している」は、食べ物を買い入れる文に合わない。点検は調べる行為である。", "修理": "「外国から修理している」は、食べ物には修理の対象にならず意味が通らない。", "削除": "「外国から削除している」は、食べ物には意味が通らない。削除は情報などを消す行為である。"}, "sentence_index": 0, "correct_answer": "輸入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国内で作った車を、海外へ輸入して売った。", "explanation": "ここは〈輸出〉の意味。国内の商品を外国へ送る場合は輸出で、輸入は外国から入れる方向を表す。"}, {"text": "店は毎朝、近所の農家から野菜を輸入している。", "explanation": "ここは〈仕入れ〉の意味。国内の農家から買う場合は仕入れと言い、輸入は外国から買い入れる時に使う。"}, {"text": "港から倉庫まで、トラックで部品を輸入した。", "explanation": "ここは〈輸送〉の意味。国内で物を運ぶことで、外国から買い入れる輸入とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35520, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "輸入", "is_correct": true, "explanation": "「輸入した品物は、港で検査を受けてから店に届く」で、外国から入れた品物という意味に合う。"}, {"text": "解約", "is_correct": false, "explanation": "「解約した品物」は契約を打ち切った品物という意味になり、港で検査を受けて店に届く流れと合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "「清掃した品物」は掃除した物の意味で、港の検査から店に届く流れと合わない。"}, {"text": "撤去", "is_correct": false, "explanation": "「撤去した品物」は取り除いた物の意味で、店に届く文脈に合わない。"}], "explanations": {"輸入": "「輸入した品物は、港で検査を受けてから店に届く」で、外国から入れた品物という意味に合う。", "解約": "「解約した品物」は契約を打ち切った品物という意味になり、港で検査を受けて店に届く流れと合わない。", "清掃": "「清掃した品物」は掃除した物の意味で、港の検査から店に届く流れと合わない。", "撤去": "「撤去した品物」は取り除いた物の意味で、店に届く文脈に合わない。"}, "sentence_index": 6, "correct_answer": "輸入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社は、来年から新しい社員を輸入する予定だ。", "explanation": "ここは〈採用〉の意味。人を雇う場合は採用と言い、輸入は外国から物を買い入れることに使う。"}, {"text": "市民が、古い家具を市役所に輸入した。", "explanation": "ここは〈寄贈〉の意味。国内の市役所へ無償で渡す場合は寄贈で、輸入とは言わない。"}, {"text": "工場は、不良品を店から輸入して引き取った。", "explanation": "ここは〈回収〉の意味。国内の店から戻す場合は回収で、外国から入れる輸入とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35520, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海外からの輸入を、税関の手続きが必要だ。", "corrected_sentence": "海外からの輸入には、税関の手続きが必要だ。", "error_description": "「輸入」の後に「を」を付けたのが誤り。「必要だ」の主題は「には」で示すので「輸入には」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35520, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "輸入し品物は、税関で検査を受ける。", "corrected_sentence": "輸入した品物は、税関で検査を受ける。", "error_description": "「輸入」に続く動詞の過去形「した」が抜けている。「輸入し」では品物を修飾できないので、「輸入した品物」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35522, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「は」は主題を示し、「第一ステップは〜ことです」の形で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、ここでは主題になるので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐだけで、「です」の文の主題にはならないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、主題を示す形にはならないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「は」は主題を示し、「第一ステップは〜ことです」の形で正しい。", "を": "「を」は目的語を示すが、ここでは主題になるので合わない。", "の": "「の」は名詞どうしをつなぐだけで、「です」の文の主題にはならないので合わない。", "から": "「から」は起点を示すが、主題を示す形にはならないので合わない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35522, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「覚える」の目的語を示す「を」で、正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すが、覚える対象には合わないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、覚えることには使えないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、ここで覚える対象を示すことはできないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「覚える」の目的語を示す「を」で、正しい。", "に": "「に」は相手や場所を示すが、覚える対象には合わないので合わない。", "へ": "「へ」は方向を示すが、覚えることには使えないので合わない。", "が": "「が」は主語を示すが、ここで覚える対象を示すことはできないので合わない。"}, "error_tags": {"に": "相手・場所", "へ": "方向", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35522, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "することや場所が、一つずつ順番に進んでいくこと。", "primary_collocate": null, "pronunciation": "すてっぷ", "ipa": "sɯteppɯ", "syllable_count": 4, "sentences": [{"text": "手順をまちがえないように、ステップを一つずつ進めましょう。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "手順[てじゅん]をまちがえないように、ステップを一[ひと]つずつ進[すす]めましょう。", "sentence_source": "generated"}, {"text": "新しい仕事の第一ステップは、道具をそろえることです。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]の第一[だいいち]ステップは、道具[どうぐ]をそろえることです。", "sentence_source": "generated"}, {"text": "日本語の勉強は、やさしいステップから始めます。", "target_word": "ステップ", "complexity_tier": "T2", "furigana": "日本語[にほんご]の勉強[べんきょう]は、やさしいステップから始[はじ]めます。", "sentence_source": "generated"}, {"text": "小さなステップでも、続ければ大きな進歩になります。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "小[ちい]さなステップでも、続[つづ]ければ大[おお]きな進歩[しんぽ]になります。", "sentence_source": "generated"}, {"text": "次のステップに進む前に、宿題を確認します。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "次[つぎ]のステップに進[すす]む前[まえ]に、宿題[しゅくだい]を確認[かくにん]します。", "sentence_source": "generated"}, {"text": "計画は三つのステップに分けて進めます。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "計画[けいかく]は三[みっ]つのステップに分[わ]けて進[すす]めます。", "sentence_source": "generated"}, {"text": "先生は、ステップの順番を黒板に書いて説明しました。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ステップの順番[じゅんばん]を黒板[こくばん]に書[か]いて説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "彼は、仕事のステップを順番に覚えました。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "彼[かれ]は、仕事[しごと]のステップを順番[じゅんばん]に覚[おぼ]えました。", "sentence_source": "generated"}, {"text": "夢をかなえる最初のステップは、毎日練習することです。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "夢[ゆめ]をかなえる最初[さいしょ]のステップは、毎日[まいにち]練習[れんしゅう]することです。", "sentence_source": "generated"}, {"text": "この本は、料理の方法をステップごとに説明しています。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "この本[ほん]は、料理[りょうり]の方法[ほうほう]をステップごとに説明[せつめい]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ステップ", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "物事を一つずつ順番に進めていくときの一つ一つの歩み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35522, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ステップ", "is_correct": true, "explanation": "「ステップを一つずつ進める」は順番に進む段階を指すので正しい。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、順番に進むものではないので合わない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所で、一つずつ進めるものではないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様で、進めるものではないので合わない。"}], "explanations": {"ステップ": "「ステップを一つずつ進める」は順番に進む段階を指すので正しい。", "冷蔵庫": "冷蔵庫は家電で、順番に進むものではないので合わない。", "教室": "教室は場所で、一つずつ進めるものではないので合わない。", "天気": "天気は空模様で、進めるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "ステップ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "車はステップを上げて走りました。", "explanation": "ここは〈スピード〉の意味。ステップは順番に進む段階を指すので、速さの調整には使わない。"}, {"text": "私のステップが三キロ増えました。", "explanation": "ここは〈体重〉の意味。ステップは段階を指すので、重さが増えるという話には合わない。"}, {"text": "この服は、ステップが明るいです。", "explanation": "ここは〈色〉の意味。ステップは段階を指すので、服の色の明るさには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35522, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ステップ", "is_correct": true, "explanation": "「ステップの順番」は進める段階の並びを指すので、黒板に書く文に合う。"}, {"text": "毛布", "is_correct": false, "explanation": "毛布は寝具で、「毛布の順番」は意味が通らないので合わない。"}, {"text": "花束", "is_correct": false, "explanation": "花束は贈り物で、「花束の順番」は意味が通らないので合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は器で、「花瓶の順番」は意味が通らないので合わない。"}], "explanations": {"ステップ": "「ステップの順番」は進める段階の並びを指すので、黒板に書く文に合う。", "毛布": "毛布は寝具で、「毛布の順番」は意味が通らないので合わない。", "花束": "花束は贈り物で、「花束の順番」は意味が通らないので合わない。", "花瓶": "花瓶は器で、「花瓶の順番」は意味が通らないので合わない。"}, "sentence_index": 6, "correct_answer": "ステップ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ステップで寝ました。", "explanation": "ここは〈ベッド〉の意味。ステップは段階を指すので、寝る場所には使えない。"}, {"text": "ステップが咲きました。", "explanation": "ここは〈花〉の意味。ステップは段階を指すので、咲く植物にはならない。"}, {"text": "ステップを回してドアを開けました。", "explanation": "ここは〈鍵〉の意味。ステップは段階を指すので、回してドアを開ける道具にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35522, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "次のステップを進みましょう。", "corrected_sentence": "次のステップに進みましょう。", "error_description": "「ステップに進む」が正しい形。「進む」は「～に」で進む先を示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35522, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三人のステップで作業が完了しました。", "corrected_sentence": "三つのステップで作業が完了しました。", "error_description": "段階は「つ」で数えるので「三つ」が正しい。「三人」は人を数える言い方なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
