INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35523, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "段階。物事が進むときの、一つ一つの段階や手順。", "primary_collocate": null, "pronunciation": "すてっぷ", "ipa": "sɯteppɯ", "syllable_count": 4, "sentences": [{"text": "手続きは、四つのステップで完了します。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "手続[てつづ]きは、四[よっ]つのステップで完了[かんりょう]します。", "sentence_source": "generated"}, {"text": "目標に近づくために、まず最初のステップを決めましょう。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "目標[もくひょう]に近[ちか]づくために、まず最初[さいしょ]のステップを決[き]めましょう。", "sentence_source": "generated"}, {"text": "成功への第一ステップは、現状を知ることです。", "target_word": "ステップ", "complexity_tier": "T4", "furigana": "成功[せいこう]への第一[だいいち]ステップは、現状[げんじょう]を知[し]ることです。", "sentence_source": "generated"}, {"text": "このマニュアルには、各ステップの注意点が書かれています。", "target_word": "ステップ", "complexity_tier": "T4", "furigana": "このマニュアルには、各[かく]ステップの注意点[ちゅういてん]が書[か]かれています。", "sentence_source": "generated"}, {"text": "彼女は、昇進という次のステップを目指しています。", "target_word": "ステップ", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は、昇進[しょうしん]という次[つぎ]のステップを目指[めざ]しています。", "sentence_source": "generated"}, {"text": "実験は、準備、測定、確認の三ステップで行います。", "target_word": "ステップ", "complexity_tier": "T4", "furigana": "実験[じっけん]は、準備[じゅんび]、測定[そくてい]、確認[かくにん]の三[さん]ステップで行[おこな]います。", "sentence_source": "generated"}, {"text": "問題を解決するには、原因を調べるステップが欠かせません。", "target_word": "ステップ", "complexity_tier": "T4", "furigana": "問題[もんだい]を解決[かいけつ]するには、原因[げんいん]を調[しら]べるステップが欠[か]かせません。", "sentence_source": "generated"}, {"text": "留学は、私の将来にとって大切なステップです。", "target_word": "ステップ", "complexity_tier": "T3", "furigana": "留学[りゅうがく]は、私[わたし]の将来[しょうらい]にとって大切[たいせつ]なステップです。", "sentence_source": "generated"}, {"text": "次のステップへ進むには、試験に合格する必要があります。", "target_word": "ステップ", "complexity_tier": "T4", "furigana": "次[つぎ]のステップへ進[すす]むには、試験[しけん]に合格[ごうかく]する必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "作業のステップを図にすると、全体が分かりやすくなります。", "target_word": "ステップ", "complexity_tier": "T4", "furigana": "作業[さぎょう]のステップを図[ず]にすると、全体[ぜんたい]が分[わ]かりやすくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ステップ", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "物事が進むときの一つ一つの段階や手順", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35523, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ステップ", "is_correct": true, "explanation": "「四つのステップで完了する」は手続きの段階を指すので正しい。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建具で、手続きを完了させる段階にはならないので合わない。"}, {"text": "雑誌", "is_correct": false, "explanation": "雑誌は印刷物で、手続きの段階にはならないので合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は文房具で、手続きの段階にはならないので合わない。"}], "explanations": {"ステップ": "「四つのステップで完了する」は手続きの段階を指すので正しい。", "窓": "窓は建具で、手続きを完了させる段階にはならないので合わない。", "雑誌": "雑誌は印刷物で、手続きの段階にはならないので合わない。", "鉛筆": "鉛筆は文房具で、手続きの段階にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "ステップ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ステップを開けて、中の水を飲みました。", "explanation": "ここは〈ボトル〉の意味。ステップは段階で、開けて中身を出す容器にはならないので合わない。"}, {"text": "ステップを割ってかき混ぜました。", "explanation": "ここは〈卵〉の意味。ステップは段階で、割って使う食材ではないので合わない。"}, {"text": "ステップでノートに書きました。", "explanation": "ここは〈ペン〉の意味。ステップは段階で、書く道具にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35523, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ステップ", "is_correct": true, "explanation": "「原因を調べるステップ」は問題を解決する段階を指すので、欠かせない文に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、原因を調べる段階にはならないので合わない。"}, {"text": "毛布", "is_correct": false, "explanation": "毛布は寝具で、「原因を調べる毛布」は意味が通らないので合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は器で、「原因を調べる花瓶」は意味が通らないので合わない。"}], "explanations": {"ステップ": "「原因を調べるステップ」は問題を解決する段階を指すので、欠かせない文に合う。", "冷蔵庫": "冷蔵庫は家電で、原因を調べる段階にはならないので合わない。", "毛布": "毛布は寝具で、「原因を調べる毛布」は意味が通らないので合わない。", "花瓶": "花瓶は器で、「原因を調べる花瓶」は意味が通らないので合わない。"}, "sentence_index": 6, "correct_answer": "ステップ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓の外を見ると、ステップが晴れていました。", "explanation": "ここは〈空〉の意味。ステップは段階を指すので、晴れるという天気の話には使えない。"}, {"text": "このお菓子は、ステップがとても甘いです。", "explanation": "ここは〈味〉の意味。ステップは段階を指すので、お菓子の甘さを表す主語にはならない。"}, {"text": "その犬は、長いステップを振りました。", "explanation": "ここは〈尻尾〉の意味。ステップは段階を指すので、犬の体の部位として振ることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35523, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "手続きは、三つのステップに完了します。", "corrected_sentence": "手続きは、三つのステップで完了します。", "error_description": "「完了する」は手段を示す「で」を使う。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35523, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実験は、三人のステップで行います。", "corrected_sentence": "実験は、三つのステップで行います。", "error_description": "段階は「つ」で数える。「三人」は人を数える助数詞なので、段階には使えず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
