INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35524, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "何かをする前に、最初にすること。", "primary_collocate": null, "pronunciation": "まず", "ipa": "mazɯ", "syllable_count": 2, "sentences": [{"text": "料理を始める前に、先ず手をよく洗ってください。", "target_word": "先ず", "complexity_tier": "T3", "furigana": "料理[りょうり]を始[はじ]める前[まえ]に、先ず[まず]手[て]をよく洗[あら]ってください。", "sentence_source": "generated"}, {"text": "先ず自分で考えてから、先生に質問しなさい。", "target_word": "先ず", "complexity_tier": "T3", "furigana": "先ず[まず]自分[じぶん]で考[かんが]えてから、先生[せんせい]に質問[しつもん]しなさい。", "sentence_source": "generated"}, {"text": "家に着いたら、先ず荷物を置いて休もう。", "target_word": "先ず", "complexity_tier": "T3", "furigana": "家[いえ]に着[つ]いたら、先ず[まず]荷物[にもつ]を置[お]いて休[やす]もう。", "sentence_source": "generated"}, {"text": "旅行の計画は、先ず行き先を決めることから始まる。", "target_word": "先ず", "complexity_tier": "T3", "furigana": "旅行[りょこう]の計画[けいかく]は、先ず[まず]行[い]き先[さき]を決[き]めることから始[はじ]まる。", "sentence_source": "generated"}, {"text": "先ず謝ってから、理由を説明したほうがいい。", "target_word": "先ず", "complexity_tier": "T3", "furigana": "先ず[まず]謝[あやま]ってから、理由[りゆう]を説明[せつめい]したほうがいい。", "sentence_source": "generated"}, {"text": "病院では、先ず受付で名前を書いてください。", "target_word": "先ず", "complexity_tier": "T3", "furigana": "病院[びょういん]では、先ず[まず]受付[うけつけ]で名前[なまえ]を書[か]いてください。", "sentence_source": "generated"}, {"text": "難しい問題は、先ず簡単な部分から解くとよい。", "target_word": "先ず", "complexity_tier": "T3", "furigana": "難[むずか]しい問題[もんだい]は、先ず[まず]簡単[かんたん]な部分[ぶぶん]から解[と]くとよい。", "sentence_source": "generated"}, {"text": "先ず結果を見てから、次にどうするか話し合おう。", "target_word": "先ず", "complexity_tier": "T3", "furigana": "先ず[まず]結果[けっか]を見[み]てから、次[つぎ]にどうするか話[はな]し合[あ]おう。", "sentence_source": "generated"}, {"text": "買い物の前に、先ず冷蔵庫の中を確かめた。", "target_word": "先ず", "complexity_tier": "T3", "furigana": "買[か]い物[もの]の前[まえ]に、先ず[まず]冷蔵庫[れいぞうこ]の中[なか]を確[たし]かめた。", "sentence_source": "generated"}, {"text": "新しい町に引っ越したら、先ず近所の人にあいさつしたい。", "target_word": "先ず", "complexity_tier": "T3", "furigana": "新[あたら]しい町[まち]に引[ひ]っ越[こ]したら、先ず[まず]近所[きんじょ]の人[ひと]にあいさつしたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "先ず", "label": "基本形"}, {"form": "まず", "label": "ひらがな表記"}, {"form": "先ずは", "label": "強調形"}], "register": "neutral", "sense_fingerprint": "いくつかの動作の中で、最初にするという順序を示す副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa355574-9e18-4c72-a592-28e39dbf69ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35524, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "先ず", "is_correct": true, "explanation": "「料理を始める前に、先ず手を洗う」で、最初にする動作を示す副詞として合う。"}, {"text": "最後に", "is_correct": false, "explanation": "「料理を始める前に、最後に手を洗う」は、料理の後に来る順序を示す語で、前提の文脈と矛盾する。"}, {"text": "結局", "is_correct": false, "explanation": "「結局手をよく洗ってください」は結果を表す副詞で、料理を始める前の順序を示す文脈に合わない。"}, {"text": "たまに", "is_correct": false, "explanation": "「たまに手をよく洗ってください」は頻度を表し、料理の前の最初の動作の指示としては合わない。"}], "explanations": {"先ず": "「料理を始める前に、先ず手を洗う」で、最初にする動作を示す副詞として合う。", "最後に": "「料理を始める前に、最後に手を洗う」は、料理の後に来る順序を示す語で、前提の文脈と矛盾する。", "結局": "「結局手をよく洗ってください」は結果を表す副詞で、料理を始める前の順序を示す文脈に合わない。", "たまに": "「たまに手をよく洗ってください」は頻度を表し、料理の前の最初の動作の指示としては合わない。"}, "sentence_index": 0, "correct_answer": "先ず"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は私より先ず会場に着いていた。", "explanation": "ここは〈先に〉の意味。ほかの人より前に着いていたという比較は「先に」で表し、先ずは最初にする行動の順序を示すので合わない。"}, {"text": "食事を済ませた後で、先ず料理を作った。", "explanation": "ここは〈最後に〉の意味。食後に料理を作るのは最後の順序で、先ずは最初の行動を示すので合わない。"}, {"text": "何度も話し合ったが、先ず計画は中止になった。", "explanation": "ここは〈結局〉の意味。話し合いの末の結果は「結局」で表し、先ずは順序を示すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35524, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先ず", "is_correct": true, "explanation": "「難しい問題は、先ず簡単な部分から解くとよい」で、最初に取り組む順序を示す副詞として合う。"}, {"text": "ついに", "is_correct": false, "explanation": "「ついに簡単な部分から解くとよい」は、長い時間を経た到達を表し、解き方の順序の指示には合わない。"}, {"text": "ふと", "is_correct": false, "explanation": "「ふと簡単な部分から解くとよい」は思いがけない動作を表し、解き方の指示として不自然。"}, {"text": "けっして", "is_correct": false, "explanation": "「けっして〜とよい」は打ち消しと勧めが合わず、文が成り立たない。"}], "explanations": {"先ず": "「難しい問題は、先ず簡単な部分から解くとよい」で、最初に取り組む順序を示す副詞として合う。", "ついに": "「ついに簡単な部分から解くとよい」は、長い時間を経た到達を表し、解き方の順序の指示には合わない。", "ふと": "「ふと簡単な部分から解くとよい」は思いがけない動作を表し、解き方の指示として不自然。", "けっして": "「けっして〜とよい」は打ち消しと勧めが合わず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "先ず"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "失敗したので、先ず挑戦した。", "explanation": "ここは〈再び〉の意味。失敗の後のやり直しは「再び」で表し、先ずは最初の動作を示すので合わない。"}, {"text": "長い時間をかけて、先ず完成した。", "explanation": "ここは〈やっと〉の意味。苦労の末の到達は「やっと」で表し、先ずは順序を示すので合わない。"}, {"text": "長い議論の末、先ず結論が出た。", "explanation": "ここは〈ついに〉の意味。長い過程の末に到達した場面は「ついに」で表し、先ずは最初の順序を示すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35524, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "説明会では、先ずの自己紹介をしてください。", "corrected_sentence": "説明会では、先ず自己紹介をしてください。", "error_description": "「先ず」は副詞なので、直後に「の」を付けて名詞を修飾することはできない。「先ず自己紹介をしてください」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35524, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議の資料は、先ずを課長に確認してもらう。", "corrected_sentence": "会議の資料は、先ず課長に確認してもらう。", "error_description": "「先ず」は副詞なので、直後に「を」は付かない。「先ず課長に確認してもらう」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a509a714-fc16-4962-af58-8de3aed1b6b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35526, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寒冷", "is_correct": true, "explanation": "温暖の対義語として類語・対義語辞典に並ぶ。気候が寒いことを表す。"}, {"text": "穏やか", "is_correct": false, "explanation": "気候の落ち着きを表す語で、温暖と近い意味を持つ。対義語ではない。"}, {"text": "快適", "is_correct": false, "explanation": "過ごしやすさを表す語で、気候の性質の対義語ではない。"}, {"text": "清潔", "is_correct": false, "explanation": "衛生状態を表す語で、気候の対義語にはならない。"}], "correct_answer": "寒冷", "explanations": {"寒冷": "温暖の対義語として類語・対義語辞典に並ぶ。気候が寒いことを表す。", "穏やか": "気候の落ち着きを表す語で、温暖と近い意味を持つ。対義語ではない。", "快適": "過ごしやすさを表す語で、気候の性質の対義語ではない。", "清潔": "衛生状態を表す語で、気候の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35526, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寒冷", "is_correct": true, "explanation": "温暖の対義語として類語・対義語辞典に並ぶ。気候が寒いことを表す。"}, {"text": "素朴", "is_correct": false, "explanation": "飾り気のない様子を表す語で、気候の性質の対義語ではない。"}, {"text": "上品", "is_correct": false, "explanation": "品のよさを表す語で、気候の対義語にはならない。"}, {"text": "健康", "is_correct": false, "explanation": "心身の状態を表す語で、気候の性質の対義語ではない。"}], "correct_answer": "寒冷", "explanations": {"寒冷": "温暖の対義語として類語・対義語辞典に並ぶ。気候が寒いことを表す。", "素朴": "飾り気のない様子を表す語で、気候の性質の対義語ではない。", "上品": "品のよさを表す語で、気候の対義語にはならない。", "健康": "心身の状態を表す語で、気候の性質の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35526, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "気温が高くて、寒くないこと。", "primary_collocate": null, "pronunciation": "おんだん", "ipa": "oɴdaɴ", "syllable_count": 4, "sentences": [{"text": "沖縄は温暖な気候なので、冬でも厚いコートはいりません。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "沖縄[おきなわ]は温暖[おんだん]な気候[きこう]なので、冬[ふゆ]でも厚[あつ]いコートはいりません。", "sentence_source": "generated"}, {"text": "この地方は一年を通して温暖で、みかんがよく育ちます。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "この地方[ちほう]は一年[いちねん]を通[とお]して温暖[おんだん]で、みかんがよく育[そだ]ちます。", "sentence_source": "generated"}, {"text": "北海道に比べて、九州は冬でも温暖です。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "北海道[ほっかいどう]に比[くら]べて、九州[きゅうしゅう]は冬[ふゆ]でも温暖[おんだん]です。", "sentence_source": "generated"}, {"text": "温暖な場所に住みたくて、南の町へ引っ越しました。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "温暖[おんだん]な場所[ばしょ]に住[す]みたくて、南[みなみ]の町[まち]へ引[ひ]っ越[こ]しました。", "sentence_source": "generated"}, {"text": "冬なのに今日は温暖な一日で、上着を脱いで歩きました。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "冬[ふゆ]なのに今日[きょう]は温暖[おんだん]な一日[いちにち]で、上着[うわぎ]を脱[ぬ]いで歩[ある]きました。", "sentence_source": "generated"}, {"text": "温暖な海辺の町では、一月でも花が咲いています。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "温暖[おんだん]な海辺[うみべ]の町[まち]では、一月[いちがつ]でも花[はな]が咲[さ]いています。", "sentence_source": "generated"}, {"text": "寒い国から来た彼女は、温暖な日本の冬に驚きました。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "寒[さむ]い国[くに]から来[き]た彼女[かのじょ]は、温暖[おんだん]な日本[にほん]の冬[ふゆ]に驚[おどろ]きました。", "sentence_source": "generated"}, {"text": "温暖な地域では、冬の暖房費があまりかかりません。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "温暖[おんだん]な地域[ちいき]では、冬[ふゆ]の暖房費[だんぼうひ]があまりかかりません。", "sentence_source": "generated"}, {"text": "母は体が弱いので、冬は温暖な土地で過ごしています。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "母[はは]は体[からだ]が弱[よわ]いので、冬[ふゆ]は温暖[おんだん]な土地[とち]で過[す]ごしています。", "sentence_source": "generated"}, {"text": "今年の春は温暖で、桜がいつもより早く咲きました。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "今年[ことし]の春[はる]は温暖[おんだん]で、桜[さくら]がいつもより早[はや]く咲[さ]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "温暖だ", "label": "終止形"}, {"form": "温暖な", "label": "連体形"}, {"form": "温暖で", "label": "連用形（で）"}, {"form": "温暖に", "label": "連用形（に）"}, {"form": "温暖です", "label": "丁寧形"}], "register": "標準語（やや書き言葉的）", "sense_fingerprint": "気温が高く、寒さを感じないこと。気温の面から見た暖かさ。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76303e4f-8772-4b0c-a318-4b641521f4da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35526, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温暖", "is_correct": true, "explanation": "「沖縄は温暖な気候」となり、暖かい気候を表して、冬でも厚いコートがいらない理由になる。"}, {"text": "寒冷", "is_correct": false, "explanation": "寒い気候を表すので、「寒冷な気候なので厚いコートはいりません」は文の意味が矛盾する。"}, {"text": "暑い", "is_correct": false, "explanation": "形容詞なので「暑いな気候」と続けられず、「な」の形に合わない。"}, {"text": "猛吹雪", "is_correct": false, "explanation": "吹雪の激しさを表す名詞で、「〜な気候」とは続かず、文脈とも合わない。"}], "explanations": {"温暖": "「沖縄は温暖な気候」となり、暖かい気候を表して、冬でも厚いコートがいらない理由になる。", "寒冷": "寒い気候を表すので、「寒冷な気候なので厚いコートはいりません」は文の意味が矛盾する。", "暑い": "形容詞なので「暑いな気候」と続けられず、「な」の形に合わない。", "猛吹雪": "吹雪の激しさを表す名詞で、「〜な気候」とは続かず、文脈とも合わない。"}, "sentence_index": 0, "correct_answer": "温暖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は温暖な性格で、誰にでも優しく接します。", "explanation": "ここは〈温厚〉の意味。温暖は気候・天候に使う語で、人の性格には〈温厚〉を使う。"}, {"text": "温暖なお湯で手を洗いました。", "explanation": "ここは〈温かい〉の意味。温暖は気候に使う語で、お湯の温度には〈温かい〉を使う。"}, {"text": "この部屋は温暖な色の壁紙で、落ち着きます。", "explanation": "ここは〈暖色〉の意味。温暖は気候の語で、色の暖かさには〈暖色〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35526, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温暖", "is_correct": true, "explanation": "寒い国との対比で、暖かい日本の冬に驚く文になり、文脈に合う。"}, {"text": "冷涼", "is_correct": false, "explanation": "涼しく冷たい気候を表し、寒い国から来た人が驚く理由として文脈と合わない。"}, {"text": "猛暑", "is_correct": false, "explanation": "夏の厳しい暑さを表す語で、冬の描写には使えない。"}, {"text": "豪雨", "is_correct": false, "explanation": "大雨を表す名詞で、「〜な冬」とは続かず、冬の描写にも合わない。"}], "explanations": {"温暖": "寒い国との対比で、暖かい日本の冬に驚く文になり、文脈に合う。", "冷涼": "涼しく冷たい気候を表し、寒い国から来た人が驚く理由として文脈と合わない。", "猛暑": "夏の厳しい暑さを表す語で、冬の描写には使えない。", "豪雨": "大雨を表す名詞で、「〜な冬」とは続かず、冬の描写にも合わない。"}, "sentence_index": 6, "correct_answer": "温暖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は温暖な話し方で、落ち着いて説明してくれた。", "explanation": "ここは〈穏やか〉の意味。温暖は気候・天候に使う語で、話し方の落ち着きには〈穏やか〉を使う。"}, {"text": "二人は温暖な関係を築いて、仕事を続けています。", "explanation": "ここは〈良好〉の意味。温暖は気候に使う語で、人間関係の良し悪しには〈良好〉を使う。"}, {"text": "この布団は温暖で、寒い夜でもよく眠れます。", "explanation": "ここは〈保温〉の意味。温暖は気候の語で、寝具の暖かさを言うには〈保温〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35526, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この島は温暖に気候で、一年中、花が咲いています。", "corrected_sentence": "この島は温暖な気候で、一年中、花が咲いています。", "error_description": "誤りは「温暖に」。温暖は形状詞なので、名詞「気候」を修飾するには「温暖な」が正しい。「に」は連用形で、名詞の前には置けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "温暖で", "is_correct": true, "explanation": "連用形「で」で文を中止し、後半の「みかんがよく育つ」へ続けている。"}, {"text": "温暖な", "is_correct": false, "explanation": "連体形なので名詞の前にしか置けず、「、」で続く文中では使えない。"}, {"text": "温暖です", "is_correct": false, "explanation": "丁寧な文末形なので「、」で続けられず、後半の「みかんがよく育つ」ともつながらない。"}, {"text": "温暖だ", "is_correct": false, "explanation": "終止形なので「、」で続けられず、後半の「みかんがよく育つ」とつながらない。"}], "correct_form": "温暖で", "base_form": "温暖だ", "form_label": "連用形（で）", "sentence_index": 1, "explanations": {"温暖で": "連用形「で」で文を中止し、後半の「みかんがよく育つ」へ続けている。", "温暖な": "連体形なので名詞の前にしか置けず、「、」で続く文中では使えない。", "温暖です": "丁寧な文末形なので「、」で続けられず、後半の「みかんがよく育つ」ともつながらない。", "温暖だ": "終止形なので「、」で続けられず、後半の「みかんがよく育つ」とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35526, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来週は温暖の天気が続くので、薄着で出かけましょう。", "corrected_sentence": "来週は温暖な天気が続くので、薄着で出かけましょう。", "error_description": "誤りは「温暖の」の「の」。温暖は形状詞なので、名詞「天気」を修飾するには「な」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "温暖な", "is_correct": true, "explanation": "連体形で、後の名詞「地域」を修飾し、「〜な地域では」となる。"}, {"text": "温暖で", "is_correct": false, "explanation": "連用形「で」は名詞の前に置けず、「温暖で地域」は成り立たない。"}, {"text": "温暖です", "is_correct": false, "explanation": "丁寧な文末形で、名詞「地域」の前には置けない。"}, {"text": "温暖でした", "is_correct": false, "explanation": "過去の丁寧な文末形で、名詞の前には置けない。"}], "correct_form": "温暖な", "base_form": "温暖だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"温暖な": "連体形で、後の名詞「地域」を修飾し、「〜な地域では」となる。", "温暖で": "連用形「で」は名詞の前に置けず、「温暖で地域」は成り立たない。", "温暖です": "丁寧な文末形で、名詞「地域」の前には置けない。", "温暖でした": "過去の丁寧な文末形で、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35527, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寒冷", "is_correct": true, "explanation": "温暖の対義語として類語・対義語辞典に並ぶ。気候が寒いことを表す。"}, {"text": "静か", "is_correct": false, "explanation": "物音や雰囲気が穏やかな様子を表し、気候の対義語ではない。"}, {"text": "清潔", "is_correct": false, "explanation": "衛生状態を表す語で、気候の性質の対義語にはならない。"}, {"text": "健康", "is_correct": false, "explanation": "心身の状態を表す語で、気候の対義語ではない。"}], "correct_answer": "寒冷", "explanations": {"寒冷": "温暖の対義語として類語・対義語辞典に並ぶ。気候が寒いことを表す。", "静か": "物音や雰囲気が穏やかな様子を表し、気候の対義語ではない。", "清潔": "衛生状態を表す語で、気候の性質の対義語にはならない。", "健康": "心身の状態を表す語で、気候の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35527, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "寒冷", "is_correct": true, "explanation": "温暖の対義語として類語・対義語辞典に並ぶ。気候が寒いことを表す。"}, {"text": "素朴", "is_correct": false, "explanation": "飾り気のない様子を表す語で、気候の性質の対義語ではない。"}, {"text": "上品", "is_correct": false, "explanation": "品のよさを表す語で、気候の対義語にはならない。"}, {"text": "平穏", "is_correct": false, "explanation": "穏やかで静かな様子を表し、気候の対義語ではない。"}], "correct_answer": "寒冷", "explanations": {"寒冷": "温暖の対義語として類語・対義語辞典に並ぶ。気候が寒いことを表す。", "素朴": "飾り気のない様子を表す語で、気候の性質の対義語ではない。", "上品": "品のよさを表す語で、気候の対義語にはならない。", "平穏": "穏やかで静かな様子を表し、気候の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35527, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "気候が冷たくなく、過ごしやすい状態であること。", "primary_collocate": null, "pronunciation": "おんだん", "ipa": "oɴdaɴ", "syllable_count": 4, "sentences": [{"text": "地中海沿岸は温暖で、夏も冬も過ごしやすい土地です。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "地中海[ちちゅうかい]沿岸[えんがん]は温暖[おんだん]で、夏[なつ]も冬[ふゆ]も過[す]ごしやすい土地[とち]です。", "sentence_source": "generated"}, {"text": "温暖な気候のおかげで、一年中外で運動ができます。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "温暖[おんだん]な気候[きこう]のおかげで、一年中[いちねんじゅう]外[そと]で運動[うんどう]ができます。", "sentence_source": "generated"}, {"text": "祖父は温暖な海辺の町で、のんびり暮らしています。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "祖父[そふ]は温暖[おんだん]な海辺[うみべ]の町[まち]で、のんびり暮[く]らしています。", "sentence_source": "generated"}, {"text": "この島は温暖なので、観光客が一年中訪れます。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "この島[しま]は温暖[おんだん]なので、観光客[かんこうきゃく]が一年中[いちねんじゅう]訪[おとず]れます。", "sentence_source": "generated"}, {"text": "寒さが苦手な私には、温暖な場所が合っています。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "寒[さむ]さが苦手[にがて]な私[わたし]には、温暖[おんだん]な場所[ばしょ]が合[あ]っています。", "sentence_source": "generated"}, {"text": "温暖な土地では、冬でも畑で野菜が作れます。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "温暖[おんだん]な土地[とち]では、冬[ふゆ]でも畑[はたけ]で野菜[やさい]が作[つく]れます。", "sentence_source": "generated"}, {"text": "日本は北と南で気候が違い、南のほうが温暖です。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "日本[にほん]は北[きた]と南[みなみ]で気候[きこう]が違[ちが]い、南[みなみ]のほうが温暖[おんだん]です。", "sentence_source": "generated"}, {"text": "温暖な地域に建てられた家は、窓が大きいことが多いです。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "温暖[おんだん]な地域[ちいき]に建[た]てられた家[いえ]は、窓[まど]が大[おお]きいことが多[おお]いです。", "sentence_source": "generated"}, {"text": "仕事を引退したら、温暖で静かな町に住むのが夢です。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "仕事[しごと]を引退[いんたい]したら、温暖[おんだん]で静[しず]かな町[まち]に住[す]むのが夢[ゆめ]です。", "sentence_source": "generated"}, {"text": "温暖な気候の国では、冬の服をあまり持っていない人もいます。", "target_word": "温暖", "complexity_tier": "T3", "furigana": "温暖[おんだん]な気候[きこう]の国[くに]では、冬[ふゆ]の服[ふく]をあまり持[も]っていない人[ひと]もいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "温暖だ", "label": "終止形"}, {"form": "温暖な", "label": "連体形"}, {"form": "温暖で", "label": "連用形（で）"}, {"form": "温暖に", "label": "連用形（に）"}, {"form": "温暖です", "label": "丁寧形"}], "register": "標準語（やや書き言葉的）", "sense_fingerprint": "気候が厳しくなく、人が暮らしやすい穏やかな状態。土地の住みやすさに重点がある。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76303e4f-8772-4b0c-a318-4b641521f4da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35527, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温暖", "is_correct": true, "explanation": "気候が冷たくなく過ごしやすいという意味で、「過ごしやすい土地」と続く。"}, {"text": "寒冷", "is_correct": false, "explanation": "寒い気候を表し、「夏も冬も過ごしやすい」と矛盾する。"}, {"text": "猛暑", "is_correct": false, "explanation": "厳しい暑さを表し、「夏も過ごしやすい」と矛盾する。"}, {"text": "豪雪", "is_correct": false, "explanation": "大雪を表し、過ごしやすい土地という文脈と合わない。"}], "explanations": {"温暖": "気候が冷たくなく過ごしやすいという意味で、「過ごしやすい土地」と続く。", "寒冷": "寒い気候を表し、「夏も冬も過ごしやすい」と矛盾する。", "猛暑": "厳しい暑さを表し、「夏も過ごしやすい」と矛盾する。", "豪雪": "大雪を表し、過ごしやすい土地という文脈と合わない。"}, "sentence_index": 0, "correct_answer": "温暖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は温暖な笑顔で、いつも周りの人を安心させます。", "explanation": "ここは〈温和〉の意味。温暖は気候に使う語で、人の表情や態度には〈温和〉を使う。"}, {"text": "温暖な光の中で、静かに本を読みました。", "explanation": "ここは〈穏やか〉の意味。温暖は気候の語で、光のやわらかさには〈穏やか〉を使う。"}, {"text": "温暖な飲み物で、体の芯まで温まりました。", "explanation": "ここは〈温かい〉の意味。温暖は気候に使う語で、飲み物の温度には〈温かい〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35527, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温暖", "is_correct": true, "explanation": "南のほうは北より暖かいという比べ方になり、文の意味が通る。"}, {"text": "厳寒", "is_correct": false, "explanation": "極端な寒さを表し、南のほうが優れているという文脈と矛盾する。"}, {"text": "寒帯", "is_correct": false, "explanation": "寒帯は極寒の気候帯を表すので、「南のほうが寒帯です」は南のほうが温暖だという文脈と矛盾する。"}, {"text": "乾燥", "is_correct": false, "explanation": "湿度の状態を表す語で、北と南の気温の違いを述べる文に合わない。"}], "explanations": {"温暖": "南のほうは北より暖かいという比べ方になり、文の意味が通る。", "厳寒": "極端な寒さを表し、南のほうが優れているという文脈と矛盾する。", "寒帯": "寒帯は極寒の気候帯を表すので、「南のほうが寒帯です」は南のほうが温暖だという文脈と矛盾する。", "乾燥": "湿度の状態を表す語で、北と南の気温の違いを述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "温暖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は温暖な気質で、誰とでもすぐ打ち解けます。", "explanation": "ここは〈温厚〉の意味。温暖は気候・天候に使う語で、性格には〈温厚〉を使う。"}, {"text": "この部屋は温暖なので、ストーブがいりません。", "explanation": "ここは〈暖かい〉の意味。温暖は気候の語で、室内の暖かさには〈暖かい〉を使う。"}, {"text": "彼女の温暖な声に、みんなが安心しました。", "explanation": "ここは〈優しい〉の意味。温暖は気候に使う語で、声の印象には〈優しい〉を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35527, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町は温暖を気候で、一年中過ごしやすいです。", "corrected_sentence": "この町は温暖な気候で、一年中過ごしやすいです。", "error_description": "誤りは「温暖を」の「を」。温暖は形状詞なので、名詞「気候」を修飾するには「な」が必要で、「を」は目的語を示す助詞として合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "温暖な", "is_correct": true, "explanation": "連体形で、後の名詞「気候」を修飾し、「温暖な気候のおかげで」となる。"}, {"text": "温暖で", "is_correct": false, "explanation": "連用形「で」は名詞の前に置けず、「温暖で気候」は成り立たない。"}, {"text": "温暖だ", "is_correct": false, "explanation": "終止形なので名詞を修飾できず、「温暖だ気候」は成り立たない。"}, {"text": "温暖です", "is_correct": false, "explanation": "丁寧な文末形で、名詞の前には置けない。"}], "correct_form": "温暖な", "base_form": "温暖だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"温暖な": "連体形で、後の名詞「気候」を修飾し、「温暖な気候のおかげで」となる。", "温暖で": "連用形「で」は名詞の前に置けず、「温暖で気候」は成り立たない。", "温暖だ": "終止形なので名詞を修飾できず、「温暖だ気候」は成り立たない。", "温暖です": "丁寧な文末形で、名詞の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35527, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域は温暖で気候で、一年中花が咲きます。", "corrected_sentence": "この地域は温暖な気候で、一年中花が咲きます。", "error_description": "誤りは「温暖で気候」の「で」。名詞「気候」を修飾するには連体形の「な」が必要で、連用形の「で」では名詞を修飾できない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "温暖な", "is_correct": true, "explanation": "連体形で、後の名詞「地域」を修飾し、「温暖な地域に建てられた家」となる。"}, {"text": "温暖に", "is_correct": false, "explanation": "連用形「に」は動詞を修飾する形で、名詞「地域」を直接修飾できない。"}, {"text": "温暖でした", "is_correct": false, "explanation": "過去の丁寧な文末形で、名詞の前には置けない。"}, {"text": "温暖ではありません", "is_correct": false, "explanation": "否定の丁寧な文末形で、名詞の前には置けず、「地域」とは続かない。"}], "correct_form": "温暖な", "base_form": "温暖だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"温暖な": "連体形で、後の名詞「地域」を修飾し、「温暖な地域に建てられた家」となる。", "温暖に": "連用形「に」は動詞を修飾する形で、名詞「地域」を直接修飾できない。", "温暖でした": "過去の丁寧な文末形で、名詞の前には置けない。", "温暖ではありません": "否定の丁寧な文末形で、名詞の前には置けず、「地域」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35530, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「旅行する」の対象を示す「を」。ヨーロッパの国々を訪れる文になる。"}, {"text": "が", "is_correct": false, "explanation": "「国々が旅行する」となり、国々が主語になって私の夢の話と文意が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「国々と旅行する」は同行の意味になり、訪問先を表せない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す「より」で、旅行の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「旅行する」の対象を示す「を」。ヨーロッパの国々を訪れる文になる。", "が": "「国々が旅行する」となり、国々が主語になって私の夢の話と文意が通らない。", "と": "「国々と旅行する」は同行の意味になり、訪問先を表せない。", "より": "比較の基準を示す「より」で、旅行の対象にはならない。"}, "error_tags": {"が": "主語化の誤り", "と": "同行の意味", "より": "比較の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35530, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「国々の名前」と名詞をつなぐ連体修飾の「の」で、国々に属する名前を表す。"}, {"text": "を", "is_correct": false, "explanation": "「国々を名前を覚えました」は「を」が二つ並んで目的語が重複し、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「国々に名前を覚える」では対象が合わず、名前の所属を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「国々へ名前」は方向を表す助詞で、名前とつながらない。"}], "correct_answer": "の", "explanations": {"の": "「国々の名前」と名詞をつなぐ連体修飾の「の」で、国々に属する名前を表す。", "を": "「国々を名前を覚えました」は「を」が二つ並んで目的語が重複し、不自然。", "に": "「国々に名前を覚える」では対象が合わず、名前の所属を表せない。", "へ": "「国々へ名前」は方向を表す助詞で、名前とつながらない。"}, "error_tags": {"を": "目的語の重複", "に": "対象の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35530, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いくつもの国のこと。", "primary_collocate": null, "pronunciation": "くにぐに", "ipa": "kɯniɡɯni", "syllable_count": 4, "sentences": [{"text": "世界の国々は、環境を守るために協力しています。", "target_word": "国々", "complexity_tier": "T3", "furigana": "世界[せかい]の国々[くにぐに]は、環境[かんきょう]を守[まも]るために協力[きょうりょく]しています。", "sentence_source": "generated"}, {"text": "ヨーロッパの国々を旅行するのが、私の夢です。", "target_word": "国々", "complexity_tier": "T3", "furigana": "ヨーロッパの国々[くにぐに]を旅行[りょこう]するのが、私[わたし]の夢[ゆめ]です。", "sentence_source": "generated"}, {"text": "近くの国々と仲よくすることは大切です。", "target_word": "国々", "complexity_tier": "T3", "furigana": "近[ちか]くの国々[くにぐに]と仲[なか]よくすることは大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "国々によって、食べ物も習慣もちがいます。", "target_word": "国々", "complexity_tier": "T3", "furigana": "国々[くにぐに]によって、食[た]べ物[もの]も習慣[しゅうかん]もちがいます。", "sentence_source": "generated"}, {"text": "アジアの国々から、たくさんの留学生が来ています。", "target_word": "国々", "complexity_tier": "T3", "furigana": "アジアの国々[くにぐに]から、たくさんの留学生[りゅうがくせい]が来[き]ています。", "sentence_source": "generated"}, {"text": "冬のオリンピックには、寒い国々の選手が多く参加します。", "target_word": "国々", "complexity_tier": "T3", "furigana": "冬[ふゆ]のオリンピックには、寒[さむ]い国々[くにぐに]の選手[せんしゅ]が多[おお]く参加[さんか]します。", "sentence_source": "generated"}, {"text": "豊かな国々が、貧しい国々を助ける活動を続けています。", "target_word": "国々", "complexity_tier": "T3", "furigana": "豊[ゆた]かな国々[くにぐに]が、貧[まず]しい国々[くにぐに]を助[たす]ける活動[かつどう]を続[つづ]けています。", "sentence_source": "generated"}, {"text": "地図を見ながら、南にある国々の名前を覚えました。", "target_word": "国々", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ながら、南[みなみ]にある国々[くにぐに]の名前[なまえ]を覚[おぼ]えました。", "sentence_source": "generated"}, {"text": "多くの国々が、新しい条約に賛成しました。", "target_word": "国々", "complexity_tier": "T3", "furigana": "多[おお]くの国々[くにぐに]が、新[あたら]しい条約[じょうやく]に賛成[さんせい]しました。", "sentence_source": "generated"}, {"text": "海外にいる友達のおかげで、いろいろな国々の文化を知りました。", "target_word": "国々", "complexity_tier": "T3", "furigana": "海外[かいがい]にいる友達[ともだち]のおかげで、いろいろな国々[くにぐに]の文化[ぶんか]を知[し]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国々", "label": "基本形"}, {"form": "国々の", "label": "連体形（の）"}, {"form": "国々で", "label": "場所を表す形（で）"}, {"form": "国々に", "label": "対象を表す形（に）"}], "register": "標準語", "sense_fingerprint": "一つではなく、いくつもある国をまとめて指す言い方。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76303e4f-8772-4b0c-a318-4b641521f4da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35530, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国々", "is_correct": true, "explanation": "いくつもの国をまとめて指し、国どうしで協力する主語として文が成り立つ。"}, {"text": "星々", "is_correct": false, "explanation": "星の複数形で、環境を守るために協力する主語にはならない。"}, {"text": "花々", "is_correct": false, "explanation": "花の複数形で、協力の主語として文脈に合わない。"}, {"text": "機械", "is_correct": false, "explanation": "物を指す名詞で、複数の協力主体を表せない。"}], "explanations": {"国々": "いくつもの国をまとめて指し、国どうしで協力する主語として文が成り立つ。", "星々": "星の複数形で、環境を守るために協力する主語にはならない。", "花々": "花の複数形で、協力の主語として文脈に合わない。", "機械": "物を指す名詞で、複数の協力主体を表せない。"}, "sentence_index": 0, "correct_answer": "国々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この国々は、私が生まれた小さな村です。", "explanation": "ここは〈集落〉の意味。国々は複数の国をまとめる語で、一つの集落は指せない。"}, {"text": "私の国々では、お正月にもちを食べます。", "explanation": "ここは〈祖国〉の意味。国々は複数形なので、自分一人の祖国を指すには合わない。"}, {"text": "東京の国々では、朝から電車が混みます。", "explanation": "ここは〈都市〉の意味。国々は複数の国を指すので、一つの都市には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35530, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国々", "is_correct": true, "explanation": "豊かな国々が主語となり、貧しい国々を助ける文として意味が通る。"}, {"text": "木々", "is_correct": false, "explanation": "植物の集まりで、国を助ける主語にはならない。"}, {"text": "玩具", "is_correct": false, "explanation": "遊び道具で、支援の主体として文脈に合わない。"}, {"text": "宝石", "is_correct": false, "explanation": "高価な品を表し、支援を行う主体にはならない。"}], "explanations": {"国々": "豊かな国々が主語となり、貧しい国々を助ける文として意味が通る。", "木々": "植物の集まりで、国を助ける主語にはならない。", "玩具": "遊び道具で、支援の主体として文脈に合わない。", "宝石": "高価な品を表し、支援を行う主体にはならない。"}, "sentence_index": 6, "correct_answer": "国々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この国々は、山と川に囲まれた静かな地方です。", "explanation": "ここは〈地域〉の意味。国々は複数の国を指す語で、一つの地域には使わない。"}, {"text": "私たちの国々では、お正月に家族でもちを食べます。", "explanation": "ここは〈祖国〉の意味。国々は複数形で、自分たちの祖国には使わない。"}, {"text": "この校庭の国々では、毎朝みんなで体操をします。", "explanation": "ここは〈運動場〉の意味。国々は国の複数形で、学校の敷地には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35530, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会議は、多くの国々を参加しています。", "corrected_sentence": "この会議は、多くの国々が参加しています。", "error_description": "誤りは「国々を参加」の「を」。「参加する」は「〜が参加する」の形で、対象を「を」で示さないので、主語の「が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35530, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一つの国々が、環境を守る活動を支えています。", "corrected_sentence": "多くの国々が、環境を守る活動を支えています。", "error_description": "誤りは「一つの」。国々は複数の国を指すので単数を表す「一つの」とは合わず、「多くの」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35532, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「農家で」は場所や立場を示す「で」。祖父が農家として米を作る、の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。農家は作るものではないので「農家を作る」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、後ろの動詞とつながらず文が途中で止まってしまう。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、米を作る場所としては不自然で、農家へ向かうという意味になってしまう。"}], "correct_answer": "で", "explanations": {"で": "「農家で」は場所や立場を示す「で」。祖父が農家として米を作る、の意味に合う。", "を": "「を」は動作の対象を示す。農家は作るものではないので「農家を作る」は成り立たない。", "の": "「の」は名詞をつなぐ助詞で、後ろの動詞とつながらず文が途中で止まってしまう。", "へ": "「へ」は方向を示すが、米を作る場所としては不自然で、農家へ向かうという意味になってしまう。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35532, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「農家が」は主語を示す。「減っている」の主語として自然に成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すが、「農家に減っている」は動詞と合わず成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「農家で減っている」では減る主体にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、「農家と減っている」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「農家が」は主語を示す。「減っている」の主語として自然に成り立つ。", "に": "「に」は位置や相手を示すが、「農家に減っている」は動詞と合わず成り立たない。", "で": "「で」は場所や手段を示すが、「農家で減っている」では減る主体にならず不自然。", "と": "「と」は並列や相手を示すが、「農家と減っている」は文として成り立たない。"}, "error_tags": {"に": "位置", "で": "手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35532, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お米や野菜を作る人のこと。", "primary_collocate": null, "pronunciation": "のうか", "ipa": "noːka", "syllable_count": 3, "sentences": [{"text": "農家の人が、朝早くから畑で野菜を収穫しています。", "target_word": "農家", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]が、朝早[あさはや]くから畑[はたけ]で野菜[やさい]を収穫[しゅうかく]しています。", "sentence_source": "generated"}, {"text": "祖父は農家で、毎年おいしい米を作っています。", "target_word": "農家", "complexity_tier": "T3", "furigana": "祖父[そふ]は農家[のうか]で、毎年[まいとし]おいしい米[こめ]を作[つく]っています。", "sentence_source": "generated"}, {"text": "台風で、多くの農家が大きな被害を受けました。", "target_word": "農家", "complexity_tier": "T3", "furigana": "台風[たいふう]で、多[おお]くの農家[のうか]が大[おお]きな被害[ひがい]を受[う]けました。", "sentence_source": "generated"}, {"text": "私は農家から直接、新鮮なトマトを買っています。", "target_word": "農家", "complexity_tier": "T3", "furigana": "私[わたし]は農家[のうか]から直接[ちょくせつ]、新鮮[しんせん]なトマトを買[か]っています。", "sentence_source": "generated"}, {"text": "農家の仕事は、天気に大きく左右されます。", "target_word": "農家", "complexity_tier": "T3", "furigana": "農家[のうか]の仕事[しごと]は、天気[てんき]に大[おお]きく左右[さゆう]されます。", "sentence_source": "generated"}, {"text": "兄は会社をやめて、農家になる決心をしました。", "target_word": "農家", "complexity_tier": "T3", "furigana": "兄[あに]は会社[かいしゃ]をやめて、農家[のうか]になる決心[けっしん]をしました。", "sentence_source": "generated"}, {"text": "夏休みに農家の方の家に泊まって、田植えを体験しました。", "target_word": "農家", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに農家[のうか]の方[かた]の家[いえ]に泊[と]まって、田植[たう]えを体験[たいけん]しました。", "sentence_source": "generated"}, {"text": "農家が減っているので、国は支援を始めました。", "target_word": "農家", "complexity_tier": "T3", "furigana": "農家[のうか]が減[へ]っているので、国[くに]は支援[しえん]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "父の実家は農家で、秋になると新米を送ってくれます。", "target_word": "農家", "complexity_tier": "T3", "furigana": "父[ちち]の実家[じっか]は農家[のうか]で、秋[あき]になると新米[しんまい]を送[おく]ってくれます。", "sentence_source": "generated"}, {"text": "近所の農家が、余った野菜を安く売ってくれました。", "target_word": "農家", "complexity_tier": "T3", "furigana": "近所[きんじょ]の農家[のうか]が、余[あま]った野菜[やさい]を安[やす]く売[う]ってくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農家", "label": "基本形"}, {"form": "農家の", "label": "連体形（の）"}, {"form": "農家が", "label": "主語を表す形（が）"}, {"form": "農家から", "label": "起点を表す形（から）"}], "register": "標準語", "sense_fingerprint": "田畑で米や野菜などの作物を育てて暮らす人、またはその家。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76303e4f-8772-4b0c-a318-4b641521f4da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35532, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "農家", "is_correct": true, "explanation": "正解。田畑で作物を育てる人を指すので、「農家の人が畑で野菜を収穫する」が成り立つ。"}, {"text": "肥料", "is_correct": false, "explanation": "肥料は作物に与えるものであり人を指さないため、「肥料の人」は収穫する主体として成り立たない。"}, {"text": "農薬", "is_correct": false, "explanation": "農薬は害虫を防ぐ薬で人ではないため、「農薬の人が収穫する」は不自然で主語にならない。"}, {"text": "田植え", "is_correct": false, "explanation": "田植えは稲を植える作業を表し人を指さないため、「田植えの人」は成り立たない。"}], "explanations": {"農家": "正解。田畑で作物を育てる人を指すので、「農家の人が畑で野菜を収穫する」が成り立つ。", "肥料": "肥料は作物に与えるものであり人を指さないため、「肥料の人」は収穫する主体として成り立たない。", "農薬": "農薬は害虫を防ぐ薬で人ではないため、「農薬の人が収穫する」は不自然で主語にならない。", "田植え": "田植えは稲を植える作業を表し人を指さないため、「田植えの人」は成り立たない。"}, "sentence_index": 0, "correct_answer": "農家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は大学で農家を専攻し、作物の品種改良を研究している。", "explanation": "ここは〈農学〉の意味。農家は人や家を指し、学問の分野にはならないので合わない。"}, {"text": "この店では、地元の農家を豊富に並べて販売している。", "explanation": "ここは〈農産物〉の意味。店で並べて売るのは作物であり、農家は人や家なので合わない。"}, {"text": "この国の農家の市場規模は、十年で二倍になった。", "explanation": "ここは〈農業〉の意味。市場規模は産業について言う言葉で、農家は人や家を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35532, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "農家", "is_correct": true, "explanation": "正解。夏休みに農家の方の家に泊まる、という文で、農家の人を指すので合う。"}, {"text": "田畑", "is_correct": false, "explanation": "田畑は土地を指すので、「田畑の方の家」は成り立たない。"}, {"text": "農機具", "is_correct": false, "explanation": "農機具は道具で人ではないため、「農機具の方の家」は意味をなさない。"}, {"text": "野菜", "is_correct": false, "explanation": "野菜は作物で人を指さないため、「野菜の方の家」は不自然で成り立たない。"}], "explanations": {"農家": "正解。夏休みに農家の方の家に泊まる、という文で、農家の人を指すので合う。", "田畑": "田畑は土地を指すので、「田畑の方の家」は成り立たない。", "農機具": "農機具は道具で人ではないため、「農機具の方の家」は意味をなさない。", "野菜": "野菜は作物で人を指さないため、「野菜の方の家」は不自然で成り立たない。"}, "sentence_index": 6, "correct_answer": "農家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝早く、農家に水を入れてから出勤した。", "explanation": "ここは〈田んぼ〉の意味。水を入れるのは田んぼなどの土地で、農家は人や家を指すので合わない。"}, {"text": "強い風の日は、農家を散布しないようにしている。", "explanation": "ここは〈農薬〉の意味。散布するのは薬であり、農家は人や家なので合わない。"}, {"text": "この農家は旬が冬で、春には収穫が少ない。", "explanation": "ここは〈野菜〉の意味。旬があるのは野菜などの作物で、農家は人や家を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35532, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は農家を働いている。", "corrected_sentence": "父は農家で働いている。", "error_description": "「働く」の場所は「で」で示す。「を」は目的語の助詞なので誤りで、正しくは「農家で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35532, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近所の農家へ、新鮮な卵をもらった。", "corrected_sentence": "近所の農家から、新鮮な卵をもらった。", "error_description": "「もらう」の起点は「から」で示す。「へ」は方向を表すので、ここでは誤り。正しくは「農家から」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35534, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「木に登って」の「に」は、登る先（着点）を表します。"}, {"text": "が", "is_correct": false, "explanation": "「猫は木が登って」は主語が重なり、登る先を示せません。"}, {"text": "で", "is_correct": false, "explanation": "「木で登って」は手段・場所の「で」になり、登る先を示せません。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」になり、登る場所を示せません。"}], "correct_answer": "に", "explanations": {"に": "正解。「木に登って」の「に」は、登る先（着点）を表します。", "が": "「猫は木が登って」は主語が重なり、登る先を示せません。", "で": "「木で登って」は手段・場所の「で」になり、登る先を示せません。", "より": "比較の「より」になり、登る場所を示せません。"}, "error_tags": {"が": "主語", "で": "手段・場所", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35534, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「高い木が」は、後ろの「たくさんある」の主語を表す「が」です。"}, {"text": "の", "is_correct": false, "explanation": "「高い木のたくさんあって」は成り立たず、存在するものの主語を示せません。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」になり、存在する物を示す働きがありません。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」になり、存在するものの主語を示せません。"}], "correct_answer": "が", "explanations": {"が": "正解。「高い木が」は、後ろの「たくさんある」の主語を表す「が」です。", "の": "「高い木のたくさんあって」は成り立たず、存在するものの主語を示せません。", "へ": "方向の「へ」になり、存在する物を示す働きがありません。", "から": "起点の「から」になり、存在するものの主語を示せません。"}, "error_tags": {"の": "所属・修飾", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35534, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面からまっすぐにのびて、上に枝や葉がある、大きい植物です。", "primary_collocate": null, "pronunciation": "き", "ipa": "ki", "syllable_count": 1, "sentences": [{"text": "学校の前に、大きな木が一本立っている。", "target_word": "木", "complexity_tier": "T3", "furigana": "学校[がっこう]の前[まえ]に、大[おお]きな木[き]が一本[いっぽん]立[た]っている。", "sentence_source": "generated"}, {"text": "猫は木に登って、下を見ておびえていた。", "target_word": "木", "complexity_tier": "T3", "furigana": "猫[ねこ]は木[き]に登[のぼ]って、下[した]を見[み]ておびえていた。", "sentence_source": "generated"}, {"text": "木の枝に、赤い実がたくさんなっている。", "target_word": "木", "complexity_tier": "T3", "furigana": "木[き]の枝[えだ]に、赤[あか]い実[み]がたくさんなっている。", "sentence_source": "generated"}, {"text": "川のそばの木の下で、お弁当を食べた。", "target_word": "木", "complexity_tier": "T3", "furigana": "川[かわ]のそばの木[き]の下[した]で、お弁当[べんとう]を食[た]べた。", "sentence_source": "generated"}, {"text": "冬の木は葉が落ちて、さびしい感じがする。", "target_word": "木", "complexity_tier": "T3", "furigana": "冬[ふゆ]の木[き]は葉[は]が落[お]ちて、さびしい感[かん]じがする。", "sentence_source": "generated"}, {"text": "木は根から水を吸って、少しずつ大きくなる。", "target_word": "木", "complexity_tier": "T3", "furigana": "木[き]は根[ね]から水[みず]を吸[す]って、少[すこ]しずつ大[おお]きくなる。", "sentence_source": "generated"}, {"text": "風が強くて、木が大きくゆれている。", "target_word": "木", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]くて、木[き]が大[おお]きくゆれている。", "sentence_source": "generated"}, {"text": "森には高い木がたくさんあって、昼でも暗い。", "target_word": "木", "complexity_tier": "T3", "furigana": "森[もり]には高[たか]い木[き]がたくさんあって、昼[ひる]でも暗[くら]い。", "sentence_source": "generated"}, {"text": "庭の木に水をやらないと、夏には枯れてしまう。", "target_word": "木", "complexity_tier": "T3", "furigana": "庭[にわ]の木[き]に水[みず]をやらないと、夏[なつ]には枯[か]れてしまう。", "sentence_source": "generated"}, {"text": "木の幹にさわると、ざらざらしていた。", "target_word": "木", "complexity_tier": "T3", "furigana": "木[き]の幹[みき]にさわると、ざらざらしていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "木", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "地面からのびて上に枝や葉がある大きな植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: 根から (Zipf 2.23)','sentence 9 above tier T1: contains vocabulary far above tier T1: ざらざら (Zipf 2.37)']::text[], '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35534, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木", "is_correct": true, "explanation": "正解。「大きな〜が一本立っている」の空所には、立っている植物の「木」が入ります。"}, {"text": "声", "is_correct": false, "explanation": "「大きな声が一本立っている」は意味が通りません。声は立つものではありません。"}, {"text": "月", "is_correct": false, "explanation": "「大きな月が一本立っている」は不自然です。月は空にあるもので、地面に立つものではありません。"}, {"text": "歌", "is_correct": false, "explanation": "「大きな歌が一本立っている」は成り立ちません。歌は立っている物として描けるものではありません。"}], "explanations": {"木": "正解。「大きな〜が一本立っている」の空所には、立っている植物の「木」が入ります。", "声": "「大きな声が一本立っている」は意味が通りません。声は立つものではありません。", "月": "「大きな月が一本立っている」は不自然です。月は空にあるもので、地面に立つものではありません。", "歌": "「大きな歌が一本立っている」は成り立ちません。歌は立っている物として描けるものではありません。"}, "sentence_index": 0, "correct_answer": "木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春になると、野原一面に木が咲く。", "explanation": "ここは〈花〉の意味。野原一面に咲くのは花で、幹と枝のある木が一面に咲くとは言いません。"}, {"text": "雨上がりに、木をむしって庭をきれいにした。", "explanation": "ここは〈草〉の意味。むしって抜くのは草で、幹と枝のある木はむしって抜く対象になりません。"}, {"text": "石段の木を踏まないように、そっと上った。", "explanation": "ここは〈苔〉の意味。石段に生える苔を指し、木を踏むとは言いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35534, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木", "is_correct": true, "explanation": "正解。「風が強くて、〜が大きくゆれている」の空所には、風に揺れる植物の「木」が入ります。"}, {"text": "祖父", "is_correct": false, "explanation": "「祖父が大きくゆれている」は意味が通りません。人は風に揺れる物ではありません。"}, {"text": "数字", "is_correct": false, "explanation": "「数字が大きくゆれている」は不自然です。数字は揺れて動く物ではありません。"}, {"text": "辞書", "is_correct": false, "explanation": "「辞書が大きくゆれている」は成り立ちません。辞書は風で大きく揺れるものではありません。"}], "explanations": {"木": "正解。「風が強くて、〜が大きくゆれている」の空所には、風に揺れる植物の「木」が入ります。", "祖父": "「祖父が大きくゆれている」は意味が通りません。人は風に揺れる物ではありません。", "数字": "「数字が大きくゆれている」は不自然です。数字は揺れて動く物ではありません。", "辞書": "「辞書が大きくゆれている」は成り立ちません。辞書は風で大きく揺れるものではありません。"}, "sentence_index": 6, "correct_answer": "木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空の木がゆっくり動いていく。", "explanation": "ここは〈雲〉の意味。空をゆっくり動いていくのは雲で、地面に立つ木は空を動きません。"}, {"text": "夜空の木を眺めながら散歩した。", "explanation": "ここは〈星〉の意味。夜空に見えて眺めるのは星で、木を夜空に眺めるとは言いません。"}, {"text": "木をすくって、バケツに入れた。", "explanation": "ここは〈砂〉の意味。すくって入れるのは砂で、幹と枝のある木をすくって入れるとは言いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35534, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い木が風に泳いでいる。", "corrected_sentence": "古い木が風に揺れている。", "error_description": "誤りは動詞の選択。木は風に「揺れる」もので、「泳ぐ」は魚などに使うため、木には誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35534, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公園の木を雷が落ちた。", "corrected_sentence": "公園の木に雷が落ちた。", "error_description": "誤りは助詞「を」。雷が落ちる先は「に」で示すので「木に雷が落ちた」が正しく、「木を雷が落ちた」は誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35535, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「庭の木に」は、鳥が止まる着地点を表す「に」です。"}, {"text": "が", "is_correct": false, "explanation": "「庭の木が小さな鳥が止まって」は主語が重なり、止まる場所を示せません。"}, {"text": "で", "is_correct": false, "explanation": "「庭の木で止まって」は手段・場所の「で」になり、止まる先を示せません。"}, {"text": "を", "is_correct": false, "explanation": "「庭の木を」は対象を示すが、「止まる」は目的語を取らず、止まる場所は「に」で示すので成り立たない"}], "correct_answer": "に", "explanations": {"に": "正解。「庭の木に」は、鳥が止まる着地点を表す「に」です。", "が": "「庭の木が小さな鳥が止まって」は主語が重なり、止まる場所を示せません。", "で": "「庭の木で止まって」は手段・場所の「で」になり、止まる先を示せません。", "を": "「庭の木を」は対象を示すが、「止まる」は目的語を取らず、止まる場所は「に」で示すので成り立たない"}, "error_tags": {"が": "主語", "で": "手段・場所", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35535, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「木を植えて」の「を」は、植える対象を表します。"}, {"text": "へ", "is_correct": false, "explanation": "「庭に木へ植えて」は方向の「へ」になり、植える対象を示せません。"}, {"text": "より", "is_correct": false, "explanation": "「庭に木より植えて」は比較の意味になり、植える対象として成り立ちません。"}, {"text": "から", "is_correct": false, "explanation": "「庭に木から植えて」は起点の意味になり、植える対象を示せません。"}], "correct_answer": "を", "explanations": {"を": "正解。「木を植えて」の「を」は、植える対象を表します。", "へ": "「庭に木へ植えて」は方向の「へ」になり、植える対象を示せません。", "より": "「庭に木より植えて」は比較の意味になり、植える対象として成り立ちません。", "から": "「庭に木から植えて」は起点の意味になり、植える対象を示せません。"}, "error_tags": {"へ": "方向", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35535, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の一種で、幹と枝があり、高く成長するもの。", "primary_collocate": null, "pronunciation": "き", "ipa": "ki", "syllable_count": 1, "sentences": [{"text": "夏の午後、公園の大きな木の陰で本を読んだ。", "target_word": "木", "complexity_tier": "T3", "furigana": "夏[なつ]の午後[ごご]、公園[こうえん]の大[おお]きな木[き]の陰[かげ]で本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "庭の木に小さな鳥が止まって、きれいな声で鳴いている。", "target_word": "木", "complexity_tier": "T3", "furigana": "庭[にわ]の木[き]に小[ちい]さな鳥[とり]が止[と]まって、きれいな声[こえ]で鳴[な]いている。", "sentence_source": "generated"}, {"text": "夏は大きな木の下に入ると、すずしくて気持ちがいい。", "target_word": "木", "complexity_tier": "T3", "furigana": "夏[なつ]は大[おお]きな木[き]の下[した]に入[はい]ると、すずしくて気持[きも]ちがいい。", "sentence_source": "generated"}, {"text": "台風で木が倒れ、道がふさがってしまった。", "target_word": "木", "complexity_tier": "T3", "furigana": "台風[たいふう]で木[き]が倒[たお]れ、道[みち]がふさがってしまった。", "sentence_source": "generated"}, {"text": "春になると、公園の木にピンクの花が咲く。", "target_word": "木", "complexity_tier": "T3", "furigana": "春[はる]になると、公園[こうえん]の木[き]にピンクの花[はな]が咲[さ]く。", "sentence_source": "generated"}, {"text": "秋になると、木から葉が落ちて道が黄色くなる。", "target_word": "木", "complexity_tier": "T3", "furigana": "秋[あき]になると、木[き]から葉[は]が落[お]ちて道[みち]が黄色[きいろ]くなる。", "sentence_source": "generated"}, {"text": "弟は高い木に登って、降りられなくなった。", "target_word": "木", "complexity_tier": "T3", "furigana": "弟[おとうと]は高[たか]い木[き]に登[のぼ]って、降[お]りられなくなった。", "sentence_source": "generated"}, {"text": "祖父は庭に木を植えて、毎日水をやっている。", "target_word": "木", "complexity_tier": "T3", "furigana": "祖父[そふ]は庭[にわ]に木[き]を植[う]えて、毎日[まいにち]水[みず]をやっている。", "sentence_source": "generated"}, {"text": "この木は百年以上前からここに立っているそうだ。", "target_word": "木", "complexity_tier": "T3", "furigana": "この木[き]は百年以上前[ひゃくねんいじょうまえ]からここに立[た]っているそうだ。", "sentence_source": "generated"}, {"text": "木の上に家を作る遊びは、子どもに人気がある。", "target_word": "木", "complexity_tier": "T3", "furigana": "木[き]の上[うえ]に家[いえ]を作[つく]る遊[あそ]びは、子[こ]どもに人気[にんき]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "木", "label": "基本形"}], "register": "標準（中立）", "sense_fingerprint": "幹と枝があり高く成長する植物としての樹木", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: すずしく (Zipf 1.49)']::text[], '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35535, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木", "is_correct": true, "explanation": "正解。「大きな木の陰で本を読んだ」の空所には、陰をつくる植物の「木」が入ります。"}, {"text": "夜", "is_correct": false, "explanation": "「大きな夜の陰で」は、夜は陰をつくる物ではないので成り立ちません。"}, {"text": "海", "is_correct": false, "explanation": "「大きな海の陰で」は、海は陰をつくる物ではないので不自然です。"}, {"text": "雨", "is_correct": false, "explanation": "「大きな雨の陰で」は、雨は陰をつくる物ではないので成り立ちません。"}], "explanations": {"木": "正解。「大きな木の陰で本を読んだ」の空所には、陰をつくる植物の「木」が入ります。", "夜": "「大きな夜の陰で」は、夜は陰をつくる物ではないので成り立ちません。", "海": "「大きな海の陰で」は、海は陰をつくる物ではないので不自然です。", "雨": "「大きな雨の陰で」は、雨は陰をつくる物ではないので成り立ちません。"}, "sentence_index": 0, "correct_answer": "木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭一面に木が生えて、ふかふかになった。", "explanation": "ここは〈草〉の意味。庭一面を覆ってふかふかにするのは草で、幹と枝のある木とは合いません。"}, {"text": "湿った石段に木がびっしり生えていた。", "explanation": "ここは〈苔〉の意味。石段を覆う苔を指し、幹と枝のある木がびっしり生えるとは言いません。"}, {"text": "雨上がりの森に、木が一晩でぽつぽつ顔を出した。", "explanation": "ここは〈きのこ〉の意味。雨のあとに一晩で顔を出すのはきのこで、幹と枝のある木は一晩では生えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35535, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木", "is_correct": true, "explanation": "正解。「高い〜に登って」の空所には、登れる対象の「木」が入ります。"}, {"text": "風", "is_correct": false, "explanation": "「高い風に登って」は意味が通りません。風は登れる対象ではありません。"}, {"text": "霧", "is_correct": false, "explanation": "「高い霧に登って」は成り立ちません。霧は漂うもので、登る対象にはなりません。"}, {"text": "星", "is_correct": false, "explanation": "「高い星に登って」は不自然です。星は遠くにあり、登ることはできません。"}], "explanations": {"木": "正解。「高い〜に登って」の空所には、登れる対象の「木」が入ります。", "風": "「高い風に登って」は意味が通りません。風は登れる対象ではありません。", "霧": "「高い霧に登って」は成り立ちません。霧は漂うもので、登る対象にはなりません。", "星": "「高い星に登って」は不自然です。星は遠くにあり、登ることはできません。"}, "sentence_index": 6, "correct_answer": "木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "畑に木をまいて、毎朝水をやった。", "explanation": "ここは〈種〉の意味。まいて芽を出させるのは種で、幹と枝のある木はまきません。"}, {"text": "空に白い木が浮かんでいる。", "explanation": "ここは〈雲〉の意味。空に浮かぶのは雲で、地面に生える木は空に浮かびません。"}, {"text": "夜空に木がたくさん光っていた。", "explanation": "ここは〈星〉の意味。夜空で光るのは星で、木は光りません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35535, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の木を鳥が止まっている。", "corrected_sentence": "庭の木に鳥が止まっている。", "error_description": "誤りは助詞「を」。「止まる」は止まる場所を「に」で示すので「木に止まる」が正しく、「木を止まる」は誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35535, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の木が大きく育てた。", "corrected_sentence": "庭の木が大きく育った。", "error_description": "誤りは動詞の選択。「育つ」は自動詞で木が主語になるので「育った」が正しく、「育てる」は人が植物を育てる他動詞なので、木が主語では誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
