INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35538, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木になる果物のこと。", "primary_collocate": null, "pronunciation": "み", "ipa": "mi", "syllable_count": 1, "sentences": [{"text": "木に実がある。", "target_word": "実", "complexity_tier": "T1", "furigana": "木[き]に実[み]がある。", "sentence_source": "generated"}, {"text": "赤い実を見つけた。", "target_word": "実", "complexity_tier": "T1", "furigana": "赤[あか]い実[み]を見[み]つけた。", "sentence_source": "generated"}, {"text": "猿が木の実を食べました。", "target_word": "実", "complexity_tier": "T2", "furigana": "猿[さる]が木[き]の実[み]を食[た]べました。", "sentence_source": "generated"}, {"text": "この木の実は食べられますか。", "target_word": "実", "complexity_tier": "T2", "furigana": "この木[き]の実[み]は食[た]べられますか。", "sentence_source": "generated"}, {"text": "実がなる季節が待ち遠しいです。", "target_word": "実", "complexity_tier": "T2", "furigana": "実[み]がなる季節[きせつ]が待[ま]ち遠[どお]しいです。", "sentence_source": "generated"}, {"text": "庭のレモンの木に、黄色い実がなっている。", "target_word": "実", "complexity_tier": "T3", "furigana": "庭[にわ]のレモンの木[き]に、黄色[きいろ]い実[み]がなっている。", "sentence_source": "generated"}, {"text": "子どもたちは山で拾った実を集めた。", "target_word": "実", "complexity_tier": "T3", "furigana": "子[こ]どもたちは山[やま]で拾[ひろ]った実[み]を集[あつ]めた。", "sentence_source": "generated"}, {"text": "実を取ろうとして、木から落ちてしまった。", "target_word": "実", "complexity_tier": "T3", "furigana": "実[み]を取[と]ろうとして、木[き]から落[お]ちてしまった。", "sentence_source": "generated"}, {"text": "熟した実ほど、甘くておいしいと言われる。", "target_word": "実", "complexity_tier": "T4", "furigana": "熟[じゅく]した実[み]ほど、甘[あま]くておいしいと言[い]われる。", "sentence_source": "generated"}, {"text": "冬、鳥たちは残った実をついばんで暮らす。", "target_word": "実", "complexity_tier": "T3", "furigana": "冬[ふゆ]、鳥[とり]たちは残[のこ]った実[み]をついばんで暮[く]らす。", "sentence_source": "generated"}], "morphological_forms": [{"form": "木の実", "label": "派生"}, {"form": "実る", "label": "派生"}, {"form": "実り", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 木になる果物や木の実のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: ついばん (Zipf 1.54)']::text[], '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35538, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "実", "is_correct": true, "explanation": "見出し語「実(み)」。"}, {"text": "目", "is_correct": false, "explanation": "「め」で、「み」と1音だけ違う別の語。"}, {"text": "木", "is_correct": false, "explanation": "「き」で、「み」と1音だけ違う別の語。"}, {"text": "手", "is_correct": false, "explanation": "「て」で、「み」と1音だけ違う別の語。"}, {"text": "葉", "is_correct": false, "explanation": "「は」で、「み」と1音だけ違う別の語。"}], "explanations": {"実": "見出し語「実(み)」。", "目": "「め」で、「み」と1音だけ違う別の語。", "木": "「き」で、「み」と1音だけ違う別の語。", "手": "「て」で、「み」と1音だけ違う別の語。", "葉": "「は」で、「み」と1音だけ違う別の語。"}, "sentence_index": null, "correct_answer": "実"}, "level_3": {"options": [{"text": "実", "is_correct": true, "explanation": "「木に実がある」で、木になる果物を表す。"}, {"text": "海", "is_correct": false, "explanation": "形は合うが、「木に海がある」は意味が合わない。"}, {"text": "雲", "is_correct": false, "explanation": "形は合うが、「木に雲がある」は意味が合わない。"}, {"text": "橋", "is_correct": false, "explanation": "形は合うが、「木に橋がある」は意味が合わない。"}], "explanations": {"実": "「木に実がある」で、木になる果物を表す。", "海": "形は合うが、「木に海がある」は意味が合わない。", "雲": "形は合うが、「木に雲がある」は意味が合わない。", "橋": "形は合うが、「木に橋がある」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "実"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は実を運転して、友だちの家へ行った。", "explanation": "「実」は木になる果物で、運転する乗り物の意味はない。"}, {"text": "実を読んで、とてもおもしろかった。", "explanation": "「実」は木になる果物で、読み物の意味はない。"}, {"text": "彼は店で実を買って、足にはいた。", "explanation": "「実」は木になる果物で、履き物の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35538, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "実", "is_correct": true, "explanation": "見出し語「実(み)」。"}, {"text": "根", "is_correct": false, "explanation": "「ね」で、「み」と1音だけ違う別の語。"}, {"text": "日", "is_correct": false, "explanation": "「ひ」で、「み」と1音だけ違う別の語。"}, {"text": "巣", "is_correct": false, "explanation": "「す」で、「み」と1音だけ違う別の語。"}, {"text": "血", "is_correct": false, "explanation": "「ち」で、「み」と1音だけ違う別の語。"}], "explanations": {"実": "見出し語「実(み)」。", "根": "「ね」で、「み」と1音だけ違う別の語。", "日": "「ひ」で、「み」と1音だけ違う別の語。", "巣": "「す」で、「み」と1音だけ違う別の語。", "血": "「ち」で、「み」と1音だけ違う別の語。"}, "sentence_index": null, "correct_answer": "実"}, "level_3": {"options": [{"text": "実", "is_correct": true, "explanation": "「山で拾った実を集めた」で、拾って集める木の実を表す。"}, {"text": "星", "is_correct": false, "explanation": "形は合うが、山で星を拾って集めることは意味が合わない。"}, {"text": "雨", "is_correct": false, "explanation": "形は合うが、雨を拾って集めることは意味が合わない。"}, {"text": "影", "is_correct": false, "explanation": "形は合うが、影を拾って集めることは意味が合わない。"}], "explanations": {"実": "「山で拾った実を集めた」で、拾って集める木の実を表す。", "星": "形は合うが、山で星を拾って集めることは意味が合わない。", "雨": "形は合うが、雨を拾って集めることは意味が合わない。", "影": "形は合うが、影を拾って集めることは意味が合わない。"}, "sentence_index": 6, "correct_answer": "実"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅の前に大きな実が建っていて、遠くからでもよく見えた。", "explanation": "「実」は木になる果物で、建物の意味はない。"}, {"text": "兄は部屋で実を弾いて、みんなで歌った。", "explanation": "「実」は木になる果物で、楽器の意味はない。"}, {"text": "私は実を着て、すぐに出かけた。", "explanation": "「実」は木になる果物で、服の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
