INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35542, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の全体のうちの、一つのところ。", "primary_collocate": null, "pronunciation": "ぶぶん", "ipa": "bɯbɯɴ", "syllable_count": 3, "sentences": [{"text": "この文章は、後ろの部分が難しくて、何度読んでも意味が分からない。", "target_word": "部分", "complexity_tier": "T3", "furigana": "この文章[ぶんしょう]は、後[うし]ろの部分[ぶぶん]が難[むずか]しくて、何度[なんど]読[よ]んでも意味[いみ]が分[わ]からない。", "sentence_source": "generated"}, {"text": "服の汚れた部分だけを、洗剤で丁寧に洗った。", "target_word": "部分", "complexity_tier": "T3", "furigana": "服[ふく]の汚[よご]れた部分[ぶぶん]だけを、洗剤[せんざい]で丁寧[ていねい]に洗[あら]った。", "sentence_source": "generated"}, {"text": "彼の意見には、賛成できる部分もあれば、できない部分もある。", "target_word": "部分", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]には、賛成[さんせい]できる部分[ぶぶん]もあれば、できない部分[ぶぶん]もある。", "sentence_source": "generated"}, {"text": "絵の暗い部分を明るくすると、作品の印象が変わる。", "target_word": "部分", "complexity_tier": "T3", "furigana": "絵[え]の暗[くら]い部分[ぶぶん]を明[あか]るくすると、作品[さくひん]の印象[いんしょう]が変[か]わる。", "sentence_source": "generated"}, {"text": "映画の最後の部分は感動的だったが、前半は退屈だった。", "target_word": "部分", "complexity_tier": "T3", "furigana": "映画[えいが]の最後[さいご]の部分[ぶぶん]は感動的[かんどうてき]だったが、前半[ぜんはん]は退屈[たいくつ]だった。", "sentence_source": "generated"}, {"text": "魚の骨の部分は取りのぞいて、身だけを食べた。", "target_word": "部分", "complexity_tier": "T3", "furigana": "魚[さかな]の骨[ほね]の部分[ぶぶん]は取[と]りのぞいて、身[み]だけを食[た]べた。", "sentence_source": "generated"}, {"text": "計画のうち、お金に関する部分は私が担当します。", "target_word": "部分", "complexity_tier": "T3", "furigana": "計画[けいかく]のうち、お金[かね]に関[かん]する部分[ぶぶん]は私[わたし]が担当[たんとう]します。", "sentence_source": "generated"}, {"text": "壁の古くなった部分だけを、新しい板に取りかえた。", "target_word": "部分", "complexity_tier": "T3", "furigana": "壁[かべ]の古[ふる]くなった部分[ぶぶん]だけを、新[あたら]しい板[いた]に取[と]りかえた。", "sentence_source": "generated"}, {"text": "話の中でいちばん面白い部分を、友だちに先に教えてしまった。", "target_word": "部分", "complexity_tier": "T3", "furigana": "話[はなし]の中[なか]でいちばん面白[おもしろ]い部分[ぶぶん]を、友[とも]だちに先[さき]に教[おし]えてしまった。", "sentence_source": "generated"}, {"text": "地図の青い部分は海を表している。", "target_word": "部分", "complexity_tier": "T3", "furigana": "地図[ちず]の青[あお]い部分[ぶぶん]は海[うみ]を表[あらわ]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "部分", "label": "基本形"}, {"form": "部分的", "label": "派生形"}], "register": "標準", "sense_fingerprint": "全体の中の一つの箇所やところ。汚れた部分、難しい部分など", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: contains vocabulary far above tier T1: 取りかえ (Zipf 1.48)']::text[], '76303e4f-8772-4b0c-a318-4b641521f4da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35542, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部分", "is_correct": true, "explanation": "正解。「後ろの部分」は文章の一つの箇所を指すので、「難しくて」と自然に続く。"}, {"text": "色", "is_correct": false, "explanation": "「後ろの色が難しい」は意味をなさず、文章の箇所を表せない。"}, {"text": "重さ", "is_correct": false, "explanation": "「後ろの重さが難しい」は不自然で、文章の一部を表す語にはならない。"}, {"text": "味", "is_correct": false, "explanation": "「後ろの味が難しい」は成り立たず、文章の箇所の意味にならない。"}], "explanations": {"部分": "正解。「後ろの部分」は文章の一つの箇所を指すので、「難しくて」と自然に続く。", "色": "「後ろの色が難しい」は意味をなさず、文章の箇所を表せない。", "重さ": "「後ろの重さが難しい」は不自然で、文章の一部を表す語にはならない。", "味": "「後ろの味が難しい」は成り立たず、文章の箇所の意味にならない。"}, "sentence_index": 0, "correct_answer": "部分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部分の人が反対したので、話し合いを続けることにした。", "explanation": "「部分の人」は不自然。「部分」は物事の一つの箇所を指し、人の集まりを表す語としては使わないので合わない。"}, {"text": "上司は、ミスをした部分を厳しく叱った。", "explanation": "ここは〈部下〉の意味。叱る相手は人なので、「部分」は物事の一つの箇所を指す言葉として合わない。"}, {"text": "部分をかけて、丁寧に練習しよう。", "explanation": "ここは〈時間〉の意味。「時間をかける」は時間の長さを表す言い方で、「部分」には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35542, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部分", "is_correct": true, "explanation": "正解。「お金に関する部分」は計画の一つの箇所を指し、「は私が担当します」と自然に続く。"}, {"text": "形", "is_correct": false, "explanation": "「お金に関する形」は意味をなさず、計画の一部を表す語にはならない。"}, {"text": "匂い", "is_correct": false, "explanation": "「お金に関する匂い」は成り立たず、計画の箇所を表せない。"}, {"text": "温度", "is_correct": false, "explanation": "「お金に関する温度」は意味をなさず、計画の一部を表す語にはならない。"}], "explanations": {"部分": "正解。「お金に関する部分」は計画の一つの箇所を指し、「は私が担当します」と自然に続く。", "形": "「お金に関する形」は意味をなさず、計画の一部を表す語にはならない。", "匂い": "「お金に関する匂い」は成り立たず、計画の箇所を表せない。", "温度": "「お金に関する温度」は意味をなさず、計画の一部を表す語にはならない。"}, "sentence_index": 6, "correct_answer": "部分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日、駅で部分に会う約束をした。", "explanation": "ここは〈恋人〉の意味。会う相手は人で、「部分」は物事の一つの箇所を指すので合わない。"}, {"text": "うちでは部分を飼っている。", "explanation": "ここは〈生き物〉の意味。飼うのは生き物で、「部分」は物事の一つの箇所を指すので合わない。"}, {"text": "バスの部分を待つ間に、本を読んだ。", "explanation": "ここは〈順番〉の意味。待つのは順番で、「部分」は全体の一つの箇所なので、待つ対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35542, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この機械の故障した部分に直した。", "corrected_sentence": "この機械の故障した部分を直した。", "error_description": "「直す」の対象は「を」で示す。「に」は誤りで、正しくは「部分を直した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35542, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "記事の難しい部分が、わかりやすく書き直した。", "corrected_sentence": "記事の難しい部分を、わかりやすく書き直した。", "error_description": "「書き直す」の対象は「を」で示す。「が」は主語になるため、「部分が書き直した」は誤り。正しくは「部分を書き直した」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35543, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「分ける」の結果を示す「に」。「三つの部分に分けて」で自然な形になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は分けられる対象に付くが、ここは分けた先の区分なので「部分を分けて」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。ここは分けた結果を示す位置なので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」。分けた結果の区分は「と」では表せない。"}], "correct_answer": "に", "explanations": {"に": "「分ける」の結果を示す「に」。「三つの部分に分けて」で自然な形になる。", "を": "「を」は分けられる対象に付くが、ここは分けた先の区分なので「部分を分けて」は成り立たない。", "が": "主語を示す「が」。ここは分けた結果を示す位置なので合わない。", "と": "並列や相手を示す「と」。分けた結果の区分は「と」では表せない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全体", "is_correct": true, "explanation": "「部分」の対義語。全体をいくつかに分けたうちの一つが部分なので、全体と部分は対になる。"}, {"text": "感想", "is_correct": false, "explanation": "名詞だが、部分と対になる語ではない。"}, {"text": "温度", "is_correct": false, "explanation": "名詞だが、部分と対になる語ではない。"}, {"text": "重さ", "is_correct": false, "explanation": "名詞だが、部分と対になる語ではない。"}], "correct_answer": "全体", "explanations": {"全体": "「部分」の対義語。全体をいくつかに分けたうちの一つが部分なので、全体と部分は対になる。", "感想": "名詞だが、部分と対になる語ではない。", "温度": "名詞だが、部分と対になる語ではない。", "重さ": "名詞だが、部分と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
