INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35543, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "全体をいくつかに分けたうちの一つ。", "primary_collocate": null, "pronunciation": "ぶぶん", "ipa": "bɯbɯɴ", "syllable_count": 3, "sentences": [{"text": "この本は三つの部分に分かれていて、第一の部分は歴史の話だ。", "target_word": "部分", "complexity_tier": "T3", "furigana": "この本[ほん]は三[みっ]つの部分[ぶぶん]に分[わ]かれていて、第一[だいいち]の部分[ぶぶん]は歴史[れきし]の話[はなし]だ。", "sentence_source": "generated"}, {"text": "ケーキを同じ大きさの四つの部分に分けて、家族で食べた。", "target_word": "部分", "complexity_tier": "T3", "furigana": "ケーキを同[おな]じ大[おお]きさの四[よっ]つの部分[ぶぶん]に分[わ]けて、家族[かぞく]で食[た]べた。", "sentence_source": "generated"}, {"text": "論文は、序論と本論と結論の三つの部分から成る。", "target_word": "部分", "complexity_tier": "T3", "furigana": "論文[ろんぶん]は、序論[じょろん]と本論[ほんろん]と結論[けつろん]の三[みっ]つの部分[ぶぶん]から成[な]る。", "sentence_source": "generated"}, {"text": "この機械は、上と下の二つの部分に分けて運べる。", "target_word": "部分", "complexity_tier": "T3", "furigana": "この機械[きかい]は、上[うえ]と下[した]の二[ふた]つの部分[ぶぶん]に分[わ]けて運[はこ]べる。", "sentence_source": "generated"}, {"text": "この曲は、静かな部分と速い部分に分かれている。", "target_word": "部分", "complexity_tier": "T3", "furigana": "この 曲[きょく]は、静[しず]かな 部分[ぶぶん]と 速[はや]い 部分[ぶぶん]に 分[わ]かれている。", "sentence_source": "generated"}, {"text": "町は川を境に、東の部分と西の部分に分かれている。", "target_word": "部分", "complexity_tier": "T3", "furigana": "町[まち]は川[かわ]を境[さかい]に、東[ひがし]の部分[ぶぶん]と西[にし]の部分[ぶぶん]に分[わ]かれている。", "sentence_source": "generated"}, {"text": "試験は、読む部分と聞く部分の二つに分かれている。", "target_word": "部分", "complexity_tier": "T3", "furigana": "試験[しけん]は、読[よ]む部分[ぶぶん]と聞[き]く部分[ぶぶん]の二[ふた]つに分[わ]かれている。", "sentence_source": "generated"}, {"text": "この本棚は、いくつかの部分に分けて箱に入っている。", "target_word": "部分", "complexity_tier": "T3", "furigana": "この本棚[ほんだな]は、いくつかの部分[ぶぶん]に分[わ]けて箱[はこ]に入[はい]っている。", "sentence_source": "generated"}, {"text": "長い物語を五つの部分に分けて、一週間かけて読んだ。", "target_word": "部分", "complexity_tier": "T3", "furigana": "長[なが]い物語[ものがたり]を五[いつ]つの部分[ぶぶん]に分[わ]けて、一週間[いっしゅうかん]かけて読[よ]んだ。", "sentence_source": "generated"}, {"text": "授業は、説明の部分と練習の部分で構成されている。", "target_word": "部分", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]は、説明[せつめい]の部分[ぶぶん]と練習[れんしゅう]の部分[ぶぶん]で構成[こうせい]されている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "部分", "label": "基本形"}, {"form": "部分的", "label": "派生形"}], "register": "標準", "sense_fingerprint": "全体を区切って分けたときの、その一区分。三つの部分に分けるなど", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: 序論 (Zipf 1.99), 本論 (Zipf 2.07)']::text[], '76303e4f-8772-4b0c-a318-4b641521f4da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35543, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部分", "is_correct": true, "explanation": "「三つの部分に分かれていて」に入る語で、全体を区切った一区分を表す。文に合う唯一の語。"}, {"text": "全体", "is_correct": false, "explanation": "全体は分ける前のまとまりを指すので、「三つの全体に分かれて」とは言えない。"}, {"text": "感想", "is_correct": false, "explanation": "感想は読んだ後の気持ちで、本を分ける単位にはならない。「三つの感想に分かれて」は不自然。"}, {"text": "温度", "is_correct": false, "explanation": "温度は物の熱さを表すので、本を三つに分けるという文脈には入らない。"}], "explanations": {"部分": "「三つの部分に分かれていて」に入る語で、全体を区切った一区分を表す。文に合う唯一の語。", "全体": "全体は分ける前のまとまりを指すので、「三つの全体に分かれて」とは言えない。", "感想": "感想は読んだ後の気持ちで、本を分ける単位にはならない。「三つの感想に分かれて」は不自然。", "温度": "温度は物の熱さを表すので、本を三つに分けるという文脈には入らない。"}, "sentence_index": 0, "correct_answer": "部分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全国に三十の部分があり、どの店もほぼ独立して運営している。", "explanation": "ここは〈支部〉の意味。部分は全体を区切った一区分を指し、独立して運営する組織は表せないので合わない。"}, {"text": "彼はチームの部分として、最後まで全力で戦った。", "explanation": "ここは〈一員〉の意味。部分は人を指さないので、チームの構成員の一人には使えない。"}, {"text": "彼は社長の部分に就任した。", "explanation": "ここは〈地位〉の意味。部分は全体を区切った一区分で、役職という立場は表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35543, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部分", "is_correct": true, "explanation": "「読む部分と聞く部分の二つ」に入る語で、試験を区切った一区分を表す。文に合う唯一の語。"}, {"text": "値段", "is_correct": false, "explanation": "値段は品物の代金なので、試験を読む・聞くに分けた文には入らない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は一年の区分で、試験の内容を分けるという文脈には合わない。"}, {"text": "時刻", "is_correct": false, "explanation": "時刻は時の一点を表すので、「読む時刻と聞く時刻」とは言えない。"}], "explanations": {"部分": "「読む部分と聞く部分の二つ」に入る語で、試験を区切った一区分を表す。文に合う唯一の語。", "値段": "値段は品物の代金なので、試験を読む・聞くに分けた文には入らない。", "季節": "季節は一年の区分で、試験の内容を分けるという文脈には合わない。", "時刻": "時刻は時の一点を表すので、「読む時刻と聞く時刻」とは言えない。"}, "sentence_index": 6, "correct_answer": "部分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この物語には、主役の部分が三人登場する。", "explanation": "ここは〈登場人物〉の意味。部分は全体の一区分で、人を数えて登場させる言い方には使えないので合わない。"}, {"text": "彼の言葉には、深い部分がこもっている。", "explanation": "ここは〈感情〉の意味。部分は全体を区切った一区分で、気持ちの深さは表せないので合わない。"}, {"text": "今日の部分は晴れだ。", "explanation": "ここは〈天気〉の意味。部分は全体の区切りを指すので、晴れや雨という天候の状態には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35543, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この布を三つの部分を分けて、袋を作った。", "corrected_sentence": "この布を三つの部分に分けて、袋を作った。", "error_description": "「部分」に付く格助詞が誤り。「分ける」は分けた結果を「に」で示すので、「部分を」ではなく「部分に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35543, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この試験は、読む部分を書く部分の二つから成る。", "corrected_sentence": "この試験は、読む部分と書く部分の二つから成る。", "error_description": "「部分」に続く格助詞が誤り。二つの部分を並べるには並列の「と」が必要で、目的格の「を」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f89250-6203-44cb-bec4-c146eade3c07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35546, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『出す』の目的語（豆を出して）。豆を直接取り出すので、対象を示す『を』が正しい。"}, {"text": "に", "is_correct": false, "explanation": "帰着点や場所を示す。『豆に出して』では何を出すのか文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。『豆へ出して』は豆を目的語にできず不自然。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す。『豆と出して』は『出す』の対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『出す』の目的語（豆を出して）。豆を直接取り出すので、対象を示す『を』が正しい。", "に": "帰着点や場所を示す。『豆に出して』では何を出すのか文が成り立たない。", "へ": "方向を示す。『豆へ出して』は豆を目的語にできず不自然。", "と": "並列や相手を示す。『豆と出して』は『出す』の対象として成り立たない。"}, "error_tags": {"に": "帰着点・場所", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35546, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "転がっている主語（豆が）。転がる動作の主体を示すので『が』が正しい。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す。『豆で転がっている』では転がる主体が立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。『豆から転がっている』では主語が立たず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す。ここに比べる対象はなく、『豆より転がっている』は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "転がっている主語（豆が）。転がる動作の主体を示すので『が』が正しい。", "で": "場所や手段を示す。『豆で転がっている』では転がる主体が立たない。", "から": "起点を示す。『豆から転がっている』では主語が立たず不自然。", "より": "比較の基準を示す。ここに比べる対象はなく、『豆より転がっている』は成り立たない。"}, "error_tags": {"で": "場所・手段", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35546, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べ物の一つ。小さくて、くだものややさいの中にあるもの。", "primary_collocate": null, "pronunciation": "まめ", "ipa": "mame", "syllable_count": 2, "sentences": [{"text": "さやを開けると、緑色の豆が五つ並んでいた。", "target_word": "豆", "complexity_tier": "T3", "furigana": "さやを開[あ]けると、緑色[みどりいろ]の豆[まめ]が五[いつ]つ並[なら]んでいた。", "sentence_source": "generated"}, {"text": "母はさやから豆を出して、ご飯といっしょに炊いた。", "target_word": "豆", "complexity_tier": "T3", "furigana": "母[はは]はさやから豆[まめ]を出[だ]して、ご飯[はん]といっしょに炊[た]いた。", "sentence_source": "generated"}, {"text": "豆は小さいので、スプーンですくって食べる。", "target_word": "豆", "complexity_tier": "T3", "furigana": "豆[まめ]は小[ちい]さいので、スプーンですくって食[た]べる。", "sentence_source": "generated"}, {"text": "弟は豆が苦手で、スープに入っているとよけてしまう。", "target_word": "豆", "complexity_tier": "T3", "furigana": "弟[おとうと]は豆[まめ]が苦手[にがて]で、スープに入[はい]っているとよけてしまう。", "sentence_source": "generated"}, {"text": "畑で取ったばかりの豆は、あまくておいしい。", "target_word": "豆", "complexity_tier": "T3", "furigana": "畑[はたけ]で取[と]ったばかりの豆[まめ]は、あまくておいしい。", "sentence_source": "generated"}, {"text": "子どもたちは、さやをむいて豆をざるに入れた。", "target_word": "豆", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、さやをむいて豆[まめ]をざるに入[い]れた。", "sentence_source": "generated"}, {"text": "豆をひとつぶ落としてしまい、机の下をさがした。", "target_word": "豆", "complexity_tier": "T3", "furigana": "豆[まめ]をひとつぶ落[お]としてしまい、机[つくえ]の下[した]をさがした。", "sentence_source": "generated"}, {"text": "皿の上に、丸くて小さな豆がころがっている。", "target_word": "豆", "complexity_tier": "T3", "furigana": "皿[さら]の上[うえ]に、丸[まる]くて小[ちい]さな豆[まめ]がころがっている。", "sentence_source": "generated"}, {"text": "この豆は、さやの中でゆっくり大きくなる。", "target_word": "豆", "complexity_tier": "T3", "furigana": "この豆[まめ]は、さやの中[なか]でゆっくり大[おお]きくなる。", "sentence_source": "generated"}, {"text": "給食に、豆の入ったサラダが出た。", "target_word": "豆", "complexity_tier": "T3", "furigana": "給食[きゅうしょく]に、豆[まめ]の入[はい]ったサラダが出[で]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "豆", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "small round food grain found inside a pod of a vegetable, such as peas", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: ひとつぶ (Zipf 2.01)','sentence 7 above tier T2: contains vocabulary far above tier T2: ころがっ (Zipf 2.17)']::text[], '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35546, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "豆", "is_correct": true, "explanation": "さやの中に入る食べ物の豆。さやを開けて緑色の豆が並ぶ文に合う。"}, {"text": "釘", "is_correct": false, "explanation": "金属の細い棒で、さやの中から出てくるものではないので文に合わない。"}, {"text": "針", "is_correct": false, "explanation": "縫い針などの細い道具で、さやを開けると出てくるものとしては不自然。"}, {"text": "錠", "is_correct": false, "explanation": "錠前や錠剤を指し、さやの中に並んでいるものとは言えないので合わない。"}], "explanations": {"豆": "さやの中に入る食べ物の豆。さやを開けて緑色の豆が並ぶ文に合う。", "釘": "金属の細い棒で、さやの中から出てくるものではないので文に合わない。", "針": "縫い針などの細い道具で、さやを開けると出てくるものとしては不自然。", "錠": "錠前や錠剤を指し、さやの中に並んでいるものとは言えないので合わない。"}, "sentence_index": 0, "correct_answer": "豆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "りんごの豆を一つずつ切って、皿に並べた。", "explanation": "ここは〈種〉の意味。りんごの種は豆とは言わないので、食べ物の豆の意味では合わない。"}, {"text": "机の上に、ほこりの豆が一つ落ちていた。", "explanation": "ここは〈粒〉の意味。ほこりの小さな粒を豆とは言わないので合わない。"}, {"text": "公園でどんぐりの豆を拾って、ポケットに入れた。", "explanation": "ここは〈実〉の意味。どんぐりの実を豆とは言わないので、食べ物の豆の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35546, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "豆", "is_correct": true, "explanation": "『ひとつぶ』と数える小さな食べ物の豆。ひとつぶ落とした、という文に合う。"}, {"text": "鍵", "is_correct": false, "explanation": "『一本』『一つ』で数える道具で、『ひとつぶ』とは数えないので合わない。"}, {"text": "指輪", "is_correct": false, "explanation": "『ひとつぶ』で数えるものではなく、指輪を粒の単位で言うことはないので合わない。"}, {"text": "切手", "is_correct": false, "explanation": "紙の切手は『一枚』で数えるので、『ひとつぶ』とは言わず文に合わない。"}], "explanations": {"豆": "『ひとつぶ』と数える小さな食べ物の豆。ひとつぶ落とした、という文に合う。", "鍵": "『一本』『一つ』で数える道具で、『ひとつぶ』とは数えないので合わない。", "指輪": "『ひとつぶ』で数えるものではなく、指輪を粒の単位で言うことはないので合わない。", "切手": "紙の切手は『一枚』で数えるので、『ひとつぶ』とは言わず文に合わない。"}, "sentence_index": 6, "correct_answer": "豆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ほうれんそうの豆を買って、庭にまいた。", "explanation": "ここは〈種〉の意味。豆は食べるために収穫する実で、ほうれんそうの種には使わないので合わない。"}, {"text": "春になると、庭の豆が鼻の奥まで飛んでくる。", "explanation": "ここは〈花粉〉の意味。花粉は風で飛んで鼻に入るもので、食べ物の豆とは言わないので合わない。"}, {"text": "窓ガラスに、雨の豆がいくつもついていた。", "explanation": "ここは〈水滴〉の意味。窓につく水のつぶを豆とは言わないので、食べ物の豆の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35546, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は夜のうちに豆に水につけておいた。", "corrected_sentence": "母は夜のうちに豆を水につけておいた。", "error_description": "誤: 豆に / 正: 豆を。『つける』の対象は豆なので、目的語を示す『を』が必要。『に』では豆が対象にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35546, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "豆を一晩水につかると、やわらかくなる。", "corrected_sentence": "豆を一晩水につけると、やわらかくなる。", "error_description": "誤: つかる / 正: つける。『つける』は豆を目的語に取る他動詞。『つかる』は自動詞で、『豆を』と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35547, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「豆を甘く煮る」の目的語を示す「を」。煮る対象が豆であることを表す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「豆が甘く煮る」は豆が煮る主体になり、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「豆に甘く煮る」は煮る対象を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「豆へ甘く煮る」は方向を示し、煮る対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「豆を甘く煮る」の目的語を示す「を」。煮る対象が豆であることを表す。正解。", "が": "「豆が甘く煮る」は豆が煮る主体になり、不自然。", "に": "「豆に甘く煮る」は煮る対象を示せず、不自然。", "へ": "「豆へ甘く煮る」は方向を示し、煮る対象にはならない。"}, "error_tags": {"が": "主語を示す助詞", "に": "対象・相手を示す助詞", "へ": "方向を示す助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35547, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「豆をお皿いっぱいに出す」の目的語を示す「を」。出す対象が豆であることを表す。正解。"}, {"text": "で", "is_correct": false, "explanation": "「豆でお皿いっぱいに出した」は手段の意味になり、出す対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「豆とお皿いっぱいに出した」は並列の意味になり、出す対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「豆からお皿いっぱいに出した」は起点を示すが、出す対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「豆をお皿いっぱいに出す」の目的語を示す「を」。出す対象が豆であることを表す。正解。", "で": "「豆でお皿いっぱいに出した」は手段の意味になり、出す対象を示せない。", "と": "「豆とお皿いっぱいに出した」は並列の意味になり、出す対象を示せない。", "から": "「豆からお皿いっぱいに出した」は起点を示すが、出す対象にはならない。"}, "error_tags": {"で": "手段を示す助詞", "と": "並列を示す助詞", "から": "起点を示す助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35547, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の種子のうち、特に食用になる小さいもの。大豆や小豆など、いろいろな種類がある。", "primary_collocate": null, "pronunciation": "まめ", "ipa": "mame", "syllable_count": 2, "sentences": [{"text": "店で、乾燥した豆を袋に入れて買った。", "target_word": "豆", "complexity_tier": "T3", "furigana": "店[みせ]で、乾燥[かんそう]した豆[まめ]を袋[ふくろ]に入[い]れて買[か]った。", "sentence_source": "generated"}, {"text": "祖母は毎年、黒い豆を甘く煮ておせち料理に入れる。", "target_word": "豆", "complexity_tier": "T3", "furigana": "祖母[そぼ]は毎年[まいとし]、黒[くろ]い豆[まめ]を甘[あま]く煮[に]ておせち料理[りょうり]に入[い]れる。", "sentence_source": "generated"}, {"text": "農家の人は五月に畑に豆をまいて、秋に収穫する。", "target_word": "豆", "complexity_tier": "T3", "furigana": "農家[のうか]の人[ひと]は五月[ごがつ]に畑[はたけ]に豆[まめ]をまいて、秋[あき]に収穫[しゅうかく]する。", "sentence_source": "generated"}, {"text": "肉を食べない人は、豆からたんぱく質をとることが多い。", "target_word": "豆", "complexity_tier": "T3", "furigana": "肉[にく]を食[た]べない人[ひと]は、豆[まめ]からたんぱく質[しつ]をとることが多[おお]い。", "sentence_source": "generated"}, {"text": "節分の日には、鬼を追い払うために豆をまく。", "target_word": "豆", "complexity_tier": "T3", "furigana": "節分[せつぶん]の日[ひ]には、鬼[おに]を追[お]い払[はら]うために豆[まめ]をまく。", "sentence_source": "generated"}, {"text": "この店のカレーは、野菜と豆がたっぷり入っていて体によい。", "target_word": "豆", "complexity_tier": "T3", "furigana": "この店[みせ]のカレーは、野菜[やさい]と豆[まめ]がたっぷり入[はい]っていて体[からだ]によい。", "sentence_source": "generated"}, {"text": "乾燥した豆は、一晩水につけておくと柔らかくなる。", "target_word": "豆", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した豆[まめ]は、一晩[ひとばん]水[みず]につけておくと柔[やわ]らかくなる。", "sentence_source": "generated"}, {"text": "夕食に、塩ゆでした豆をお皿いっぱいに出した。", "target_word": "豆", "complexity_tier": "T3", "furigana": "夕食[ゆうしょく]に、塩[しお]ゆでした豆[まめ]をお皿[さら]いっぱいに出[だ]した。", "sentence_source": "generated"}, {"text": "豆を煮るときは、あくをこまめに取るときれいに仕上がる。", "target_word": "豆", "complexity_tier": "T3", "furigana": "豆[まめ]を煮[に]るときは、あくをこまめに取[と]るときれいに仕上[しあ]がる。", "sentence_source": "generated"}, {"text": "缶に入った豆を買えば、すぐ料理に使える。", "target_word": "豆", "complexity_tier": "T3", "furigana": "缶[かん]に入[はい]った豆[まめ]を買[か]えば、すぐ料理[りょうり]に使[つか]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "豆", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "edible small plant seed such as soybean or azuki bean, used as food", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 塩ゆで (Zipf 1.67)','sentence 8 above tier T2: 4 words above tier T2 (max 3): 煮る (Zipf 3.12), あく (Zipf 3.6), こまめ (Zipf 3.47), 仕上がる (Zipf 2.69)']::text[], '93e79adc-4d42-49ba-a89a-201c237b3d59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35547, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "豆", "is_correct": true, "explanation": "乾燥させた食用の豆を袋に入れて買う文に合う。正解。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は食品ではないので、乾燥させて袋に入れて買う対象にならない。"}, {"text": "電池", "is_correct": false, "explanation": "電池は食品ではないので、乾燥した状態で袋に入れて買うものとしては合わない。"}, {"text": "紙幣", "is_correct": false, "explanation": "紙幣は食品ではないので、豆の代わりに買う対象にはならない。"}], "explanations": {"豆": "乾燥させた食用の豆を袋に入れて買う文に合う。正解。", "鍵": "鍵は食品ではないので、乾燥させて袋に入れて買う対象にならない。", "電池": "電池は食品ではないので、乾燥した状態で袋に入れて買うものとしては合わない。", "紙幣": "紙幣は食品ではないので、豆の代わりに買う対象にはならない。"}, "sentence_index": 0, "correct_answer": "豆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭のりんごの豆が熟した。", "explanation": "ここは〈実〉の意味。りんごの果実は実と言い、食用の豆とは言わないので不自然。"}, {"text": "柿の豆を木からもいだ。", "explanation": "ここは〈実〉の意味。柿の果実は実と言い、食用の豆とは言わないので合わない。"}, {"text": "梨の豆をむいた。", "explanation": "ここは〈実〉の意味。梨の果実は実と言い、食用の豆とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35547, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "豆", "is_correct": true, "explanation": "ここは食用の豆の意味。乾燥させた豆を水につけて柔らかくするという文で正解。"}, {"text": "窓", "is_correct": false, "explanation": "「乾燥した窓は、一晩水につけておくと柔らかくなる」は意味が通らない。"}, {"text": "鍋", "is_correct": false, "explanation": "「乾燥した鍋は、一晩水につけておくと柔らかくなる」は成り立たない。"}, {"text": "帽子", "is_correct": false, "explanation": "「乾燥した帽子は、一晩水につけておくと柔らかくなる」は不自然。帽子は食品ではない。"}], "explanations": {"豆": "ここは食用の豆の意味。乾燥させた豆を水につけて柔らかくするという文で正解。", "窓": "「乾燥した窓は、一晩水につけておくと柔らかくなる」は意味が通らない。", "鍋": "「乾燥した鍋は、一晩水につけておくと柔らかくなる」は成り立たない。", "帽子": "「乾燥した帽子は、一晩水につけておくと柔らかくなる」は不自然。帽子は食品ではない。"}, "sentence_index": 6, "correct_answer": "豆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桃の豆を取り除いてから、ジャムを作る。", "explanation": "ここは〈核〉の意味。桃の硬い中心の種は核と言い、食用の豆とは言わないので合わない。"}, {"text": "砂糖の豆が溶けた。", "explanation": "ここは〈粒〉の意味。砂糖などの小さな粒は粒と言い、食用の豆とは言わない。"}, {"text": "草の豆をまく。", "explanation": "ここは〈種〉の意味。草の種は種と言い、食用の豆とは言わないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35547, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "豆がゆでて、サラダに入れる。", "corrected_sentence": "豆をゆでて、サラダに入れる。", "error_description": "ゆでる対象の豆は「を」で示す。「が」は主語の助詞で、ゆでる動作の目的語にはならないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35547, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "乾いた豆が収穫した。", "corrected_sentence": "乾いた豆が収穫された。", "error_description": "豆は収穫されるものなので、受け身の「収穫された」が正しい。能動の「収穫した」は豆を主語にできず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0e2cf23-569e-4808-a1bc-9c97e1af7f7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
