INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35548, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「あこがれる」は「に」を取るので、飛行に続く「に」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すが、「あこがれる」の対象には使わないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すが、「あこがれる」は「を」を取らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すが、「あこがれる」の対象にはならないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「あこがれる」は「に」を取るので、飛行に続く「に」が正しい。", "が": "「が」は主語を表すが、「あこがれる」の対象には使わないので合わない。", "を": "「を」は目的語を表すが、「あこがれる」は「を」を取らないので合わない。", "で": "「で」は手段や場所を表すが、「あこがれる」の対象にはならないので合わない。"}, "error_tags": {"に": "target", "が": "subject", "を": "object", "で": "means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35548, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "空を飛ぶこと。", "primary_collocate": null, "pronunciation": "ひこう", "ipa": "çikoː", "syllable_count": 3, "sentences": [{"text": "鳥の飛行を見ていると、空を自由に飛びたくなる。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "鳥[とり]の飛行[ひこう]を見[み]ていると、空[そら]を自由[じゆう]に飛[と]びたくなる。", "sentence_source": "generated"}, {"text": "霧がひどくて、今日の飛行は取りやめになった。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "霧[きり]がひどくて、今日[きょう]の飛行[ひこう]は取[と]りやめになった。", "sentence_source": "generated"}, {"text": "模型の飛行を見て、子どもたちは大きな声で喜んだ。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "模型[もけい]の飛行[ひこう]を見[み]て、子[こ]どもたちは大[おお]きな声[こえ]で喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "ツバメは水の上を低く飛行しながら、すばやく進んだ。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "ツバメは水[みず]の上[うえ]を低[ひく]く飛行[ひこう]しながら、すばやく進[すす]んだ。", "sentence_source": "generated"}, {"text": "風が強いと、小さな鳥は安全に飛行できない。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]いと、小[ちい]さな鳥[とり]は安全[あんぜん]に飛行[ひこう]できない。", "sentence_source": "generated"}, {"text": "この鳥は、海の上を何時間も飛行する。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "この鳥[とり]は、海[うみ]の上[うえ]を何時間[なんじかん]も飛行[ひこう]する。", "sentence_source": "generated"}, {"text": "夜の飛行は景色が見えにくいので、注意が必要だ。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "夜[よる]の飛行[ひこう]は景色[けしき]が見[み]えにくいので、注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "彼は空の飛行にあこがれて、パイロットを目指した。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "彼[かれ]は空[そら]の飛行[ひこう]にあこがれて、パイロットを目指[めざ]した。", "sentence_source": "generated"}, {"text": "虫の飛行は音が小さいが、羽は一秒に何百回も動く。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "虫[むし]の飛行[ひこう]は音[おと]が小[ちい]さいが、羽[はね]は一秒[いちびょう]に何百回[なんびゃくかい]も動[うご]く。", "sentence_source": "generated"}, {"text": "初めての飛行は不安だったが、窓の外の雲を見て落ち着いた。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "初[はじ]めての飛行[ひこう]は不安[ふあん]だったが、窓[まど]の外[そと]の雲[くも]を見[み]て落[お]ち着[つ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛行", "label": "基本形"}, {"form": "飛行する", "label": "する動詞形"}, {"form": "飛行した", "label": "た形"}, {"form": "飛行できない", "label": "可能の否定形"}], "register": "普通体（やや硬い中立）", "sense_fingerprint": "鳥・虫・乗り物などが空を飛ぶこと、またはその様子としての「飛行」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35548, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飛行", "is_correct": true, "explanation": "「鳥の飛行を見ている」と、鳥が空を飛ぶ様子を表す語として自然に入る。"}, {"text": "宿題", "is_correct": false, "explanation": "「鳥の宿題」は意味が通らず、空を飛ぶ様子を見る文に合わない。"}, {"text": "財布", "is_correct": false, "explanation": "「鳥の財布」は意味が通らず、空を飛ぶ場面と結びつかない。"}, {"text": "天気", "is_correct": false, "explanation": "「鳥の天気を見ている」は意味が通らず、この文脈に入らない。"}], "explanations": {"飛行": "「鳥の飛行を見ている」と、鳥が空を飛ぶ様子を表す語として自然に入る。", "宿題": "「鳥の宿題」は意味が通らず、空を飛ぶ様子を見る文に合わない。", "財布": "「鳥の財布」は意味が通らず、空を飛ぶ場面と結びつかない。", "天気": "「鳥の天気を見ている」は意味が通らず、この文脈に入らない。"}, "sentence_index": 0, "correct_answer": "飛行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちの誘いで、夜の街を飛行して回るようになった。", "explanation": "ここは〈出歩く〉の意味。〈飛行〉は空中を飛んで進むことで、地上を歩き回る動作には使わない。"}, {"text": "選手がバーを越えて、高く飛行した。", "explanation": "ここは〈跳躍〉の意味。高く跳ぶ動作は〈跳躍〉で、空中を飛び続ける〈飛行〉とは言わない。"}, {"text": "割れたガラスの破片が、部屋中に飛行した。", "explanation": "ここは〈飛散〉の意味。物が四方に散らばる様子には〈飛行〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35548, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飛行", "is_correct": true, "explanation": "「夜の飛行は景色が見えにくい」と、夜に空を飛ぶことを表す語として自然に入る。"}, {"text": "料理", "is_correct": false, "explanation": "「夜の料理は景色が見えにくい」は意味が通らず、この文の主語として合わない。"}, {"text": "試験", "is_correct": false, "explanation": "「夜の試験は景色が見えにくい」は意味が通らず、注意が必要という文脈に合わない。"}, {"text": "作文", "is_correct": false, "explanation": "「夜の作文は景色が見えにくい」は意味が通らず、この文脈に入らない。"}], "explanations": {"飛行": "「夜の飛行は景色が見えにくい」と、夜に空を飛ぶことを表す語として自然に入る。", "料理": "「夜の料理は景色が見えにくい」は意味が通らず、この文の主語として合わない。", "試験": "「夜の試験は景色が見えにくい」は意味が通らず、注意が必要という文脈に合わない。", "作文": "「夜の作文は景色が見えにくい」は意味が通らず、この文脈に入らない。"}, "sentence_index": 6, "correct_answer": "飛行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その大きな貨物船は、霧の中をゆっくり飛行していた。", "explanation": "ここは〈航行〉の意味。水上を進む船には〈航行〉を使い、〈飛行〉は空中を飛ぶ鳥や飛行機に使う。"}, {"text": "嵐の中で小舟が三日間、海を飛行して流されていた。", "explanation": "ここは〈漂流〉の意味。流されて動く様子を表すので、自分で空を飛ぶ〈飛行〉とは合わない。"}, {"text": "子どもたちが夏の海へ次々と飛行した。", "explanation": "ここは〈飛び込む〉の意味。水中へ入る動作を〈飛行〉とは言わないので、この文の意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35548, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ハトは毎朝、屋根の上を飛行へ続けた。", "corrected_sentence": "ハトは毎朝、屋根の上を飛行を続けた。", "error_description": "「続ける」の対象は「を」で示すので、「へ」は使えない。正しくは「飛行を続けた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35548, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の空で、ふくろうが飛行に続けていた。", "corrected_sentence": "夜の空で、ふくろうが飛行を続けていた。", "error_description": "「続ける」の対象を表す「を」が正しいのに、「に」になっている。「続ける」は「を」を取るので、「に」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35549, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「飛行の道筋」のように、飛行と道筋をつなぐ「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を表すが、「飛行を道筋」は名詞をつなぐ形にならないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すが、「飛行が道筋」は名詞の関係として不自然なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や方向を表すが、「飛行に道筋」は名詞の関係を表せないので合わない。"}], "correct_answer": "の", "explanations": {"の": "「飛行の道筋」のように、飛行と道筋をつなぐ「の」が正しい。", "を": "「を」は目的語を表すが、「飛行を道筋」は名詞をつなぐ形にならないので合わない。", "が": "「が」は主語を表すが、「飛行が道筋」は名詞の関係として不自然なので合わない。", "に": "「に」は場所や方向を表すが、「飛行に道筋」は名詞の関係を表せないので合わない。"}, "error_tags": {"の": "modifier", "を": "object", "が": "subject", "に": "target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
