INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35549, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "空中を飛んで進むこと。", "primary_collocate": null, "pronunciation": "ひこう", "ipa": "çikoː", "syllable_count": 3, "sentences": [{"text": "飛行は順調で、予定より早く目的地に着いた。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "飛行[ひこう]は順調[じゅんちょう]で、予定[よてい]より早[はや]く目的地[もくてきち]に着[つ]いた。", "sentence_source": "generated"}, {"text": "雨雲を避けるため、飛行の道筋を少し変えた。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "雨雲[あまぐも]を避[さ]けるため、飛行[ひこう]の道筋[みちすじ]を少[すこ]し変[か]えた。", "sentence_source": "generated"}, {"text": "長時間の飛行で疲れたので、着いてすぐに眠った。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "長時間[ちょうじかん]の飛行[ひこう]で疲[つか]れたので、着[つ]いてすぐに眠[ねむ]った。", "sentence_source": "generated"}, {"text": "荷物を運ぶ小型の機械が、町の上を飛行している。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "荷物[にもつ]を運[はこ]ぶ小型[こがた]の機械[きかい]が、町[まち]の上[うえ]を飛行[ひこう]している。", "sentence_source": "generated"}, {"text": "この鳥は渡りの季節に、一日で数百キロを飛行する。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "この鳥[とり]は渡[わた]りの季節[きせつ]に、一日[いちにち]で数百[すうひゃく]キロを飛行[ひこう]する。", "sentence_source": "generated"}, {"text": "強い風のせいで、飛行の途中で機体が何度も揺れた。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "強[つよ]い風[かぜ]のせいで、飛行[ひこう]の途中[とちゅう]で機体[きたい]が何度[なんど]も揺[ゆ]れた。", "sentence_source": "generated"}, {"text": "事故のあと、その会社は飛行を一週間取りやめた。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、その会社[かいしゃ]は飛行[ひこう]を一週間[いっしゅうかん]取[と]りやめた。", "sentence_source": "generated"}, {"text": "雪の日は視界が悪く、安全な飛行が難しい。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は視界[しかい]が悪[わる]く、安全[あんぜん]な飛行[ひこう]が難[むずか]しい。", "sentence_source": "generated"}, {"text": "二時間の飛行を終えると、機内に拍手が起こった。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "二時間[にじかん]の飛行[ひこう]を終[お]えると、機内[きない]に拍手[はくしゅ]が起[お]こった。", "sentence_source": "generated"}, {"text": "新しい機械の飛行を、研究者たちが地上から見守った。", "target_word": "飛行", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]の飛行[ひこう]を、研究者[けんきゅうしゃ]たちが地上[ちじょう]から見守[みまも]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "飛行", "label": "基本形"}, {"form": "飛行する", "label": "する動詞形"}, {"form": "飛行している", "label": "ている形"}, {"form": "飛行した", "label": "た形"}], "register": "普通体（やや硬い中立）", "sense_fingerprint": "空中を飛びながら目的地へ進むこと、その行程としての「飛行」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f6a9da0-592a-4780-9395-b52cb518f54e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35549, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飛行", "is_correct": true, "explanation": "「飛行は順調で、目的地に着いた」と、空の移動の行程を表す語として自然に入る。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題は順調で、目的地に着いた」は意味が通らず、移動の文脈に合わない。"}, {"text": "財布", "is_correct": false, "explanation": "「財布は順調で」は意味が通らず、目的地に着いた文脈と結びつかない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気は順調で」は意味が通らず、移動が順調だったという文脈に合わない。"}], "explanations": {"飛行": "「飛行は順調で、目的地に着いた」と、空の移動の行程を表す語として自然に入る。", "宿題": "「宿題は順調で、目的地に着いた」は意味が通らず、移動の文脈に合わない。", "財布": "「財布は順調で」は意味が通らず、目的地に着いた文脈と結びつかない。", "天気": "「天気は順調で」は意味が通らず、移動が順調だったという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "飛行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちに誘われて、夕方に公園まで飛行した。", "explanation": "ここは〈散歩〉の意味。〈飛行〉は空中を飛んで進むことで、歩いて出かける動作には使わない。"}, {"text": "夏休みに家族と川辺で、バーベキューを飛行した。", "explanation": "ここは〈行う〉の意味。〈飛行〉は空中を飛んで進むことで、料理や食事には使わない。"}, {"text": "事故のため、電車が飛行を停止した。", "explanation": "ここは〈運行〉の意味。電車やバスの定期的な運転には〈運行〉を使い、〈飛行〉は空を飛ぶ乗り物に限る。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35549, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飛行", "is_correct": true, "explanation": "「飛行を一週間取りやめた」と、空の移動の予定を表す語として自然に入る。"}, {"text": "写真", "is_correct": false, "explanation": "「写真を一週間取りやめた」は意味が通らず、航空の文脈に合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙を一週間取りやめた」は意味が通らず、事故後の運航停止の文脈に合わない。"}, {"text": "絵画", "is_correct": false, "explanation": "「絵画を一週間取りやめた」は意味が通らず、航空会社の予定の文脈に合わない。"}], "explanations": {"飛行": "「飛行を一週間取りやめた」と、空の移動の予定を表す語として自然に入る。", "写真": "「写真を一週間取りやめた」は意味が通らず、航空の文脈に合わない。", "手紙": "「手紙を一週間取りやめた」は意味が通らず、事故後の運航停止の文脈に合わない。", "絵画": "「絵画を一週間取りやめた」は意味が通らず、航空会社の予定の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "飛行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大型客船が、一か月かけて世界を飛行した。", "explanation": "ここは〈航行〉の意味。水上を進む船には〈航行〉を使い、〈飛行〉は空の移動に使う。"}, {"text": "雪のため、バスが飛行を休んでいる。", "explanation": "ここは〈運転〉の意味。地上を走るバスには〈運転〉を使い、〈飛行〉は空を飛ぶ乗り物に限る。"}, {"text": "彼は池の中で大きな飛行をして、観客を驚かせた。", "explanation": "ここは〈潜る・泳ぐ〉の意味。水中で動く様子を〈飛行〉とは言わないので、この文の意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35549, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "長時間の飛行の、体に負担をかける。", "corrected_sentence": "長時間の飛行が、体に負担をかける。", "error_description": "「体に負担をかける」の主語を表す「が」が正しいのに、「の」になっている。「の」は名詞をつなぐ働きなので、主語にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35549, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪の影響で、飛行に延期した。", "corrected_sentence": "雪の影響で、飛行を延期した。", "error_description": "「延期する」の対象を表す「を」が正しいのに、「に」になっている。「に」では「延期」と結びつかず、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '223029e3-b7e0-4449-838c-e5ce6756289a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35552, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「商品が多い」と、多いものを示す。"}, {"text": "を", "is_correct": false, "explanation": "「多い」は目的語を取らないので不適切。"}, {"text": "で", "is_correct": false, "explanation": "「商品で多い」は意味が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「商品へ多い」は文として不自然。"}], "correct_answer": "が", "explanations": {"が": "「商品が多い」と、多いものを示す。", "を": "「多い」は目的語を取らないので不適切。", "で": "「商品で多い」は意味が成り立たない。", "へ": "「商品へ多い」は文として不自然。"}, "error_tags": {"を": "object_marker", "で": "means_marker", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35552, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「商品が壊れていた」と、壊れたものを示す主語の助詞。"}, {"text": "を", "is_correct": false, "explanation": "「壊れる」は自動詞で目的語を取らない。"}, {"text": "と", "is_correct": false, "explanation": "「商品と壊れていた」は文として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「商品から壊れていた」は主語の意味にならず不自然。"}], "correct_answer": "が", "explanations": {"が": "「商品が壊れていた」と、壊れたものを示す主語の助詞。", "を": "「壊れる」は自動詞で目的語を取らない。", "と": "「商品と壊れていた」は文として不自然。", "から": "「商品から壊れていた」は主語の意味にならず不自然。"}, "error_tags": {"を": "object_marker", "と": "comitative", "から": "source_marker"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35552, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "売ったり買ったりするもののことです。", "primary_collocate": null, "pronunciation": "しょうひん", "ipa": "ɕoːhiɴ", "syllable_count": 4, "sentences": [{"text": "商品を売る。", "target_word": "商品", "complexity_tier": "T1", "furigana": "商品[しょうひん]を売[う]る。", "sentence_source": "generated"}, {"text": "店には商品が多い。", "target_word": "商品", "complexity_tier": "T1", "furigana": "店[みせ]には商品[しょうひん]が多[おお]い。", "sentence_source": "generated"}, {"text": "この商品は安いです。", "target_word": "商品", "complexity_tier": "T2", "furigana": "この商品[しょうひん]は安[やす]いです。", "sentence_source": "generated"}, {"text": "商品を箱に入れました。", "target_word": "商品", "complexity_tier": "T2", "furigana": "商品[しょうひん]を箱[はこ]に入[い]れました。", "sentence_source": "generated"}, {"text": "新しい商品を見に行きます。", "target_word": "商品", "complexity_tier": "T2", "furigana": "新[あたら]しい商品[しょうひん]を見[み]に行[い]きます。", "sentence_source": "generated"}, {"text": "売れない商品は、棚から外される。", "target_word": "商品", "complexity_tier": "T4", "furigana": "売[う]れない商品[しょうひん]は、棚[たな]から外[はず]される。", "sentence_source": "generated"}, {"text": "店員が商品の場所を教えてくれた。", "target_word": "商品", "complexity_tier": "T3", "furigana": "店員[てんいん]が商品[しょうひん]の場所[ばしょ]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "商品が壊れていたので、店に電話した。", "target_word": "商品", "complexity_tier": "T3", "furigana": "商品[しょうひん]が壊[こわ]れていたので、店[みせ]に電話[でんわ]した。", "sentence_source": "generated"}, {"text": "もし商品に問題があれば、交換できます。", "target_word": "商品", "complexity_tier": "T4", "furigana": "もし商品[しょうひん]に問題[もんだい]があれば、交換[こうかん]できます。", "sentence_source": "generated"}, {"text": "お客さんが何を求めているかを考えて、商品を作ることが大切だ。", "target_word": "商品", "complexity_tier": "T4", "furigana": "お客[きゃく]さんが何[なに]を求[もと]めているかを考[かんが]えて、商品[しょうひん]を作[つく]ることが大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "商品名", "label": "派生"