INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35553, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店員は商品で棚に並べている。", "corrected_sentence": "店員は商品を棚に並べている。", "error_description": "並べる対象を示す助詞は「を」で、「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35554, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「牛乳を売っている」で、牛乳が動作の対象であることを示すので正解。"}, {"text": "に", "is_correct": false, "explanation": "「牛乳に売っている」は対象を示せず、不自然な文になる。"}, {"text": "で", "is_correct": false, "explanation": "「牛乳で売っている」は手段の意味になり、対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「牛乳へ売っている」は方向を示すが、売る対象を示す文型に合わない。"}], "correct_answer": "を", "explanations": {"を": "「牛乳を売っている」で、牛乳が動作の対象であることを示すので正解。", "に": "「牛乳に売っている」は対象を示せず、不自然な文になる。", "で": "「牛乳で売っている」は手段の意味になり、対象を示せない。", "へ": "「牛乳へ売っている」は方向を示すが、売る対象を示す文型に合わない。"}, "error_tags": {"に": "相手・位置", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "買う", "is_correct": true, "explanation": "売るの対義語。代金を払って品物を受け取る行為で、この意味の売るに対応する。"}, {"text": "書く", "is_correct": false, "explanation": "売るとは対義関係にない動詞。文字を記す意味で、取引の反対の行為ではない。"}, {"text": "食べる", "is_correct": false, "explanation": "売るとは対義関係にない動詞。飲食の動作で、商品の売買とは関係がない。"}, {"text": "歩く", "is_correct": false, "explanation": "売るとは対義関係にない動詞。移動の動作で、取引の反対の行為ではない。"}], "correct_answer": "買う", "explanations": {"買う": "売るの対義語。代金を払って品物を受け取る行為で、この意味の売るに対応する。", "書く": "売るとは対義関係にない動詞。文字を記す意味で、取引の反対の行為ではない。", "食べる": "売るとは対義関係にない動詞。飲食の動作で、商品の売買とは関係がない。", "歩く": "売るとは対義関係にない動詞。移動の動作で、取引の反対の行為ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35554, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "受身文で、売られる魚が主語になるため「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "受身文では「魚を売られている」とは言えず、不自然な文になる。"}, {"text": "の", "is_correct": false, "explanation": "「魚の毎朝売られている」は文として成立せず、主語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「魚と売られている」は並列や共同の意味になり、受身の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "受身文で、売られる魚が主語になるため「が」が入る。", "を": "受身文では「魚を売られている」とは言えず、不自然な文になる。", "の": "「魚の毎朝売られている」は文として成立せず、主語を示せない。", "と": "「魚と売られている」は並列や共同の意味になり、受身の主語を示せない。"}, "error_tags": {"を": "目的語", "の": "所有・修飾", "と": "並列"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "買う", "is_correct": true, "explanation": "売るの対義語。代金を払って品物を受け取る行為で、この意味の売るに対応する。"}, {"text": "眠る", "is_correct": false, "explanation": "売るとは対義関係にない動詞。休息の動作で、取引の反対の行為ではない。"}, {"text": "歌う", "is_correct": false, "explanation": "売るとは対義関係にない動詞。声を出す行為で、商品の売買とは関係がない。"}, {"text": "走る", "is_correct": false, "explanation": "売るとは対義関係にない動詞。移動の動作で、取引の反対の行為ではない。"}], "correct_answer": "買う", "explanations": {"買う": "売るの対義語。代金を払って品物を受け取る行為で、この意味の売るに対応する。", "眠る": "売るとは対義関係にない動詞。休息の動作で、取引の反対の行為ではない。", "歌う": "売るとは対義関係にない動詞。声を出す行為で、商品の売買とは関係がない。", "走る": "売るとは対義関係にない動詞。移動の動作で、取引の反対の行為ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35554, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "お金をもらって、ものを他の人にわたすこと。", "primary_collocate": null, "pronunciation": "うる", "ipa": "ɯɾɯ", "syllable_count": 2, "sentences": [{"text": "古い本を店で売ることにした。", "target_word": "売る", "complexity_tier": "T3", "furigana": "古(ふる)い本(ほん)を店(みせ)で売(う)ることにした。", "sentence_source": "generated"}, {"text": "この店ではパンと牛乳を売っている。", "target_word": "売って", "complexity_tier": "T3", "furigana": "この店(みせ)ではパンと牛乳(ぎゅうにゅう)を売(う)っている。", "sentence_source": "generated"}, {"text": "弟は読み終えた漫画を友達に売った。", "target_word": "売った", "complexity_tier": "T3", "furigana": "弟(おとうと)は読(よ)み終(お)えた漫画(まんが)を友達(ともだち)に売(う)った。", "sentence_source": "generated"}, {"text": "安く売れば、すぐに全部なくなるだろう。", "target_word": "売れば", "complexity_tier": "T3", "furigana": "安(やす)く売(う)れば、すぐに全部(ぜんぶ)なくなるだろう。", "sentence_source": "generated"}, {"text": "祖母は野菜を売り、そのお金で孫に本を買った。", "target_word": "売り", "complexity_tier": "T3", "furigana": "祖母(そぼ)は野菜(やさい)を売(う)り、そのお金(かね)で孫(まご)に本(ほん)を買(か)った。", "sentence_source": "generated"}, {"text": "この古い自転車は売らないで、妹に使わせる。", "target_word": "売らないで", "complexity_tier": "T3", "furigana": "この古(ふる)い自転車(じてんしゃ)は売(う)らないで、妹(いもうと)に使(つか)わせる。", "sentence_source": "generated"}, {"text": "要らなくなった服をフリマアプリで売ろうと思っている。", "target_word": "売ろう", "complexity_tier": "T3", "furigana": "要(い)らなくなった服(ふく)をフリマアプリで売(う)ろうと思(おも)っている。", "sentence_source": "generated"}, {"text": "駅の前では、新鮮な魚が毎朝売られている。", "target_word": "売られて", "complexity_tier": "T3", "furigana": "駅(えき)の前(まえ)では、新鮮(しんせん)な魚(さかな)が毎朝(まいあさ)売(う)られている。", "sentence_source": "generated"}, {"text": "彼は買った値段より高く売ってもうけた。", "target_word": "売って", "complexity_tier": "T3", "furigana": "彼(かれ)は買(か)った値段(ねだん)より高(たか)く売(う)ってもうけた。", "sentence_source": "generated"}, {"text": "店員は客に、この傘は千円で売ると言った。", "target_word": "売る", "complexity_tier": "T3", "furigana": "店員(てんいん)は客(きゃく)に、この傘(かさ)は千円(せんえん)で売(う)ると言(い)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "売る", "label": "終止形・連体形"}, {"form": "売り", "label": "連用形"}, {"form": "売って", "label": "て形"}, {"form": "売った", "label": "た形"}, {"form": "売らない", "label": "ない形"}, {"form": "売れば", "label": "仮定形"}, {"form": "売ろう", "label": "意志形"}, {"form": "売られる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "日常の売り買いで、お金と引き換えに品物を他人に渡す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35554, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "売る", "is_correct": true, "explanation": "「売ることにした」の形で、古い本を店に渡す行為を表すので正解。"}, {"text": "売って", "is_correct": false, "explanation": "て形は「売ってことにした」と続かず、文の形が合わない。"}, {"text": "売り", "is_correct": false, "explanation": "連用形は「売りことにした」と続かず、文法的に成立しない。"}, {"text": "売ろう", "is_correct": false, "explanation": "意志形は「売ろうことにした」と続かず、文法的に成立しない。"}], "explanations": {"売る": "「売ることにした」の形で、古い本を店に渡す行為を表すので正解。", "売って": "て形は「売ってことにした」と続かず、文の形が合わない。", "売り": "連用形は「売りことにした」と続かず、文法的に成立しない。", "売ろう": "意志形は「売ろうことにした」と続かず、文法的に成立しない。"}, "sentence_index": 0, "correct_answer": "売る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は使わなくなった自転車を、お金は取らずに孫に売ってあげた。", "explanation": "ここは〈譲る〉の意味。売るは代金を受け取ることが前提なので、「お金は取らず」とは合わない。"}, {"text": "会社は社員に交通費を売った。", "explanation": "ここは〈支給する〉の意味。売るは相手からお金を受け取る行為で、会社が社員にお金を渡す場面には合わない。"}, {"text": "友達に本を一週間だけ売った。", "explanation": "ここは〈貸す〉の意味。売るは所有権ごと渡すので、「一週間だけ」という期間限定とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35554, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "売ろう", "is_correct": true, "explanation": "意志形で「売ろうと思っている」と続き、売る意志を表すので正解。"}, {"text": "売れば", "is_correct": false, "explanation": "仮定形は「売ればと思っている」と続かず、文法的に成立しない。"}, {"text": "売り", "is_correct": false, "explanation": "連用形は「売りと思っている」と続かず、文法的に成立しない。"}, {"text": "売らず", "is_correct": false, "explanation": "連用中止の形は「売らずと思っている」と続かず、文法的に成立しない。"}], "explanations": {"売ろう": "意志形で「売ろうと思っている」と続き、売る意志を表すので正解。", "売れば": "仮定形は「売ればと思っている」と続かず、文法的に成立しない。", "売り": "連用形は「売りと思っている」と続かず、文法的に成立しない。", "売らず": "連用中止の形は「売らずと思っている」と続かず、文法的に成立しない。"}, "sentence_index": 6, "correct_answer": "売ろう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行の間、飼い犬をペットホテルに売っておいた。", "explanation": "ここは〈預ける〉の意味。売るは手放すことなので、いずれ返ってくる前提の預ける状況とは合わない。"}, {"text": "業者は不要になった家具を無料で売って引き取った。", "explanation": "ここは〈処分する〉の意味。売るは代金を受け取る行為なので、「無料で」というのは合わない。"}, {"text": "彼は誕生日に、友達に古い本を売った。", "explanation": "ここは〈贈る〉の意味。売るは代金を受け取る行為なので、誕生日の贈り物とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35554, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は使わなくなったゲームを友達に売らた。", "corrected_sentence": "父は使わなくなったゲームを友達に売った。", "error_description": "活用の誤り。売るの過去形は「売った」。「売らた」は五段動詞の活用形として成立しない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "売って", "is_correct": true, "explanation": "「売っている」の形で、て形に〈いる〉が続いた正しい形。"}, {"text": "売り", "is_correct": false, "explanation": "連用形は「売りいる」と続かず、〈ている〉の形にならない。"}, {"text": "売れば", "is_correct": false, "explanation": "仮定形は「売ればいる」と続かず、現在の動作を表せない。"}, {"text": "売らない", "is_correct": false, "explanation": "ない形は否定の意味になり、「売らないいる」は成立せず、文の意味も変わる。"}], "correct_form": "売って", "base_form": "売る", "form_label": "て形", "sentence_index": 1, "explanations": {"売って": "「売っている」の形で、て形に〈いる〉が続いた正しい形。", "売り": "連用形は「売りいる」と続かず、〈ている〉の形にならない。", "売れば": "仮定形は「売ればいる」と続かず、現在の動作を表せない。", "売らない": "ない形は否定の意味になり、「売らないいる」は成立せず、文の意味も変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35554, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は着なくなった服を古着屋から売った。", "corrected_sentence": "姉は着なくなった服を古着屋に売った。", "error_description": "助詞の誤り。売る相手は「に」で示す。「から」は出どころを示すため、売り先が逆の意味になってしまう。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "売られて", "is_correct": true, "explanation": "受身のて形で、「売られている」の形として文に合う。"}, {"text": "売った", "is_correct": false, "explanation": "た形は過去を表し、「売ったいる」と続かず、受身の〈ている〉の形にならない。"}, {"text": "売ろう", "is_correct": false, "explanation": "意志形は「売ろういる」と続かず、受身の文を作れない。"}, {"text": "売る", "is_correct": false, "explanation": "終止形・連体形は「売るいる」と続かず、受身の〈ている〉の形にならない。"}], "correct_form": "売られて", "base_form": "売る", "form_label": "受身のて形", "sentence_index": 7, "explanations": {"売られて": "受身のて形で、「売られている」の形として文に合う。", "売った": "た形は過去を表し、「売ったいる」と続かず、受身の〈ている〉の形にならない。", "売ろう": "意志形は「売ろういる」と続かず、受身の文を作れない。", "売る": "終止形・連体形は「売るいる」と続かず、受身の〈ている〉の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35555, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「土地を売る」で、土地が売る対象であることを示すので正解。"}, {"text": "に", "is_correct": false, "explanation": "「土地に売る」は対象を示せず、不自然な文になる。"}, {"text": "で", "is_correct": false, "explanation": "「土地で売る」は場所や手段の意味になり、売る対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「土地へ売る」は方向の意味になり、売る対象を示す文型に合わない。"}], "correct_answer": "を", "explanations": {"を": "「土地を売る」で、土地が売る対象であることを示すので正解。", "に": "「土地に売る」は対象を示せず、不自然な文になる。", "で": "「土地で売る」は場所や手段の意味になり、売る対象を示せない。", "へ": "「土地へ売る」は方向の意味になり、売る対象を示す文型に合わない。"}, "error_tags": {"に": "相手・位置", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "買う", "is_correct": true, "explanation": "売るの対義語。代金を払って品物を受け取る行為で、この意味の売るに対応する。"}, {"text": "書く", "is_correct": false, "explanation": "売るとは対義関係にない動詞。文字を記す意味で、取引の反対の行為ではない。"}, {"text": "食べる", "is_correct": false, "explanation": "売るとは対義関係にない動詞。飲食の動作で、商品の売買とは関係がない。"}, {"text": "歩く", "is_correct": false, "explanation": "売るとは対義関係にない動詞。移動の動作で、取引の反対の行為ではない。"}], "correct_answer": "買う", "explanations": {"買う": "売るの対義語。代金を払って品物を受け取る行為で、この意味の売るに対応する。", "書く": "売るとは対義関係にない動詞。文字を記す意味で、取引の反対の行為ではない。", "食べる": "売るとは対義関係にない動詞。飲食の動作で、商品の売買とは関係がない。", "歩く": "売るとは対義関係にない動詞。移動の動作で、取引の反対の行為ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35555, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「楽器を売り」で、楽器が売る対象であることを示すので正解。"}, {"text": "が", "is_correct": false, "explanation": "「楽器が売り」は主語の意味になり、売る対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「楽器と売り」は並列の意味になり、売る対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「楽器に売り」は相手や位置の意味になり、売る対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「楽器を売り」で、楽器が売る対象であることを示すので正解。", "が": "「楽器が売り」は主語の意味になり、売る対象を示せない。", "と": "「楽器と売り」は並列の意味になり、売る対象を示せない。", "に": "「楽器に売り」は相手や位置の意味になり、売る対象を示せない。"}, "error_tags": {"が": "主語", "と": "並列", "に": "相手・位置"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "買う", "is_correct": true, "explanation": "売るの対義語。代金を払って品物を受け取る行為で、この意味の売るに対応する。"}, {"text": "眠る", "is_correct": false, "explanation": "売るとは対義関係にない動詞。休息の動作で、取引の反対の行為ではない。"}, {"text": "歌う", "is_correct": false, "explanation": "売るとは対義関係にない動詞。声を出す行為で、商品の売買とは関係がない。"}, {"text": "走る", "is_correct": false, "explanation": "売るとは対義関係にない動詞。移動の動作で、取引の反対の行為ではない。"}], "correct_answer": "買う", "explanations": {"買う": "売るの対義語。代金を払って品物を受け取る行為で、この意味の売るに対応する。", "眠る": "売るとは対義関係にない動詞。休息の動作で、取引の反対の行為ではない。", "歌う": "売るとは対義関係にない動詞。声を出す行為で、商品の売買とは関係がない。", "走る": "売るとは対義関係にない動詞。移動の動作で、取引の反対の行為ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35555, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "代金と引き換えに、自分の所有する品物などを相手に渡す。", "primary_collocate": null, "pronunciation": "うる", "ipa": "ɯɾɯ", "syllable_count": 2, "sentences": [{"text": "父は古い家と土地を売って、小さな部屋に引っ越した。", "target_word": "売って", "complexity_tier": "T3", "furigana": "父(ちち)は古(ふる)い家(いえ)と土地(とち)を売(う)って、小(ちい)さな部屋(へや)に引(ひ)っ越(こ)した。", "sentence_source": "generated"}, {"text": "会社は使っていない土地を売ることに決めた。", "target_word": "売る", "complexity_tier": "T3", "furigana": "会社(かいしゃ)は使(つか)っていない土地(とち)を売(う)ることに決(き)めた。", "sentence_source": "generated"}, {"text": "車を売った代金で、新しいパソコンを買った。", "target_word": "売った", "complexity_tier": "T3", "furigana": "車(くるま)を売(う)った代金(だいきん)で、新(あたら)しいパソコンを買(か)った。", "sentence_source": "generated"}, {"text": "彼は持っていた株を全部売ってしまった。", "target_word": "売って", "complexity_tier": "T3", "furigana": "彼(かれ)は持(も)っていた株(かぶ)を全部(ぜんぶ)売(う)ってしまった。", "sentence_source": "generated"}, {"text": "家を高く売りたいなら、先に部屋をきれいにしたほうがいい。", "target_word": "売りたい", "complexity_tier": "T3", "furigana": "家(いえ)を高(たか)く売(う)りたいなら、先(さき)に部屋(へや)をきれいにしたほうがいい。", "sentence_source": "generated"}, {"text": "建物が古いので、持ち主は売らずに人に貸すことにした。", "target_word": "売らず", "complexity_tier": "T3", "furigana": "建物(たてもの)が古(ふる)いので、持(も)ち主(ぬし)は売(う)らずに人(ひと)に貸(か)すことにした。", "sentence_source": "generated"}, {"text": "借金を返すために、祖父は大切な絵を売らなければならなかった。", "target_word": "売らなければ", "complexity_tier": "T3", "furigana": "借金(しゃっきん)を返(かえ)すために、祖父(そふ)は大切(たいせつ)な絵(え)を売(う)らなければならなかった。", "sentence_source": "generated"}, {"text": "私は店に自分の楽器を売り、旅行の費用にした。", "target_word": "売り", "complexity_tier": "T3", "furigana": "私(わたし)は店(みせ)に自分(じぶん)の楽器(がっき)を売(う)り、旅行(りょこう)の費用(ひよう)にした。", "sentence_source": "generated"}, {"text": "持っている畑を売れば、新しい店を開くお金ができる。", "target_word": "売れば", "complexity_tier": "T3", "furigana": "持(も)っている畑(はたけ)を売(う)れば、新(あたら)しい店(みせ)を開(ひら)くお金(かね)ができる。", "sentence_source": "generated"}, {"text": "買う人がいなければ、古い土地は売ることもできない。", "target_word": "売る", "complexity_tier": "T3", "furigana": "買(か)う人(ひと)がいなければ、古(ふる)い土地(とち)は売(う)ることもできない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "売る", "label": "終止形・連体形"}, {"form": "売り", "label": "連用形"}, {"form": "売って", "label": "て形"}, {"form": "売った", "label": "た形"}, {"form": "売らない", "label": "ない形"}, {"form": "売れば", "label": "仮定形"}, {"form": "売りたい", "label": "たい形"}, {"form": "売られる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "自分の持ち物(家・土地・車・株など)の所有を代金と引き換えに相手へ移す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35555, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "売って", "is_correct": true, "explanation": "て形で、「売って、引っ越した」と続き、家と土地を売った後に引っ越した流れに合う。"}, {"text": "売り", "is_correct": false, "explanation": "連用形は「売り、引っ越した」と続かず、文が成立しない。"}, {"text": "売れば", "is_correct": false, "explanation": "仮定形は「売れば、引っ越した」となり、過去の出来事として文が合わない。"}, {"text": "売ろう", "is_correct": false, "explanation": "意志形は「売ろう、引っ越した」と続かず、文法的に成立しない。"}], "explanations": {"売って": "て形で、「売って、引っ越した」と続き、家と土地を売った後に引っ越した流れに合う。", "売り": "連用形は「売り、引っ越した」と続かず、文が成立しない。", "売れば": "仮定形は「売れば、引っ越した」となり、過去の出来事として文が合わない。", "売ろう": "意志形は「売ろう、引っ越した」と続かず、文法的に成立しない。"}, "sentence_index": 0, "correct_answer": "売って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は大切にしていた着物を、代金は取らずに娘に売った。", "explanation": "ここは〈譲る〉の意味。売るは代金を受け取ることが前提なので、「代金は取らず」とは合わない。"}, {"text": "旅行の間、持ち家の鍵を管理人に売っておいた。", "explanation": "ここは〈預ける〉の意味。売るは相手に所有を移すことなので、旅行中だけ任せる預けるとは合わない。"}, {"text": "大事な指輪を、質屋に一週間だけ売った。", "explanation": "ここは〈質入れ〉の意味。売るは手放すことなので、一週間で取り戻す前提とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35555, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "売らなければ", "is_correct": true, "explanation": "「売らなければならなかった」の形で、祖父が絵を手放す必要があった文に合う。"}, {"text": "売って", "is_correct": false, "explanation": "て形は「売ってならなかった」と続かず、文が成立しない。"}, {"text": "売ろう", "is_correct": false, "explanation": "意志形は「売ろうならなかった」と続かず、文が成立しない。"}, {"text": "売らず", "is_correct": false, "explanation": "連用中止の形は「売らずならなかった」と続かず、文が成立しない。"}], "explanations": {"売らなければ": "「売らなければならなかった」の形で、祖父が絵を手放す必要があった文に合う。", "売って": "て形は「売ってならなかった」と続かず、文が成立しない。", "売ろう": "意志形は「売ろうならなかった」と続かず、文が成立しない。", "売らず": "連用中止の形は「売らずならなかった」と続かず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "売らなければ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い土地を、町に寄付して売った。", "explanation": "ここは〈寄贈する〉の意味。売るは代金を受け取る行為なので、無償で贈る寄贈とは合わない。"}, {"text": "不要になった家具を、ごみ置き場に売った。", "explanation": "ここは〈捨てる〉の意味。売るは代金を受け取る行為なので、ごみ置き場に出す場面には合わない。"}, {"text": "大切な指輪を、質屋に戻る前提で売った。", "explanation": "ここは〈質入れ〉の意味。売るは手放すことなので、戻ってくる前提とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35555, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は使わなくなった車を友達に売らて、お金を受け取った。", "corrected_sentence": "祖父は使わなくなった車を友達に売って、お金を受け取った。", "error_description": "活用の誤り。売るのて形は「売って」。「売らて」は五段動詞の活用形として成立しない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "売る", "is_correct": true, "explanation": "連体形で、「売ることに決めた」と続き、土地を売る行為を表すので正解。"}, {"text": "売って", "is_correct": false, "explanation": "て形は「売ってことに決めた」と続かず、文法的に成立しない。"}, {"text": "売り", "is_correct": false, "explanation": "連用形は「売りことに決めた」と続かず、文法的に成立しない。"}, {"text": "売れば", "is_correct": false, "explanation": "仮定形は「売ればことに決めた」と続かず、文法的に成立しない。"}], "correct_form": "売る", "base_form": "売る", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"売る": "連体形で、「売ることに決めた」と続き、土地を売る行為を表すので正解。", "売って": "て形は「売ってことに決めた」と続かず、文法的に成立しない。", "売り": "連用形は「売りことに決めた」と続かず、文法的に成立しない。", "売れば": "仮定形は「売ればことに決めた」と続かず、文法的に成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35555, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔父は山の土地が売った代金で、大きな家を建てた。", "corrected_sentence": "叔父は山の土地を売った代金で、大きな家を建てた。", "error_description": "助詞の誤り。「売る」の対象は「を」で示す。「が」だと土地が売る主体になり、文として不自然になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "売り", "is_correct": true, "explanation": "連用形で、「売り、旅行の費用にした」と続き、楽器を売った行為を表すので正解。"}, {"text": "売ろう", "is_correct": false, "explanation": "意志形は「売ろう、旅行の費用にした」と続かず、文法的に成立しない。"}, {"text": "売れば", "is_correct": false, "explanation": "仮定形は「売れば、旅行の費用にした」と続かず、文の意味も合わない。"}, {"text": "売らない", "is_correct": false, "explanation": "ない形は「売らない、旅行の費用にした」と続かず、文が成立しない。"}], "correct_form": "売り", "base_form": "売る", "form_label": "連用形", "sentence_index": 7, "explanations": {"売り": "連用形で、「売り、旅行の費用にした」と続き、楽器を売った行為を表すので正解。", "売ろう": "意志形は「売ろう、旅行の費用にした」と続かず、文法的に成立しない。", "売れば": "仮定形は「売れば、旅行の費用にした」と続かず、文の意味も合わない。", "売らない": "ない形は「売らない、旅行の費用にした」と続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
