INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35557, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "順序や向きなどが反対であることを示す。物事の位置や関係が反対側にあるさま。", "primary_collocate": null, "pronunciation": "ぎゃく", "ipa": "ɡjakɯ", "syllable_count": 2, "sentences": [{"text": "地図が逆になっていたので、道に迷ってしまった。", "target_word": "逆", "complexity_tier": "T3", "furigana": "地図(ちず)が逆(ぎゃく)になっていたので、道(みち)に迷(まよ)ってしまった。", "sentence_source": "generated"}, {"text": "姓と名を逆に書いたので、先生に直された。", "target_word": "逆", "complexity_tier": "T3", "furigana": "姓(せい)と名(めい)を逆(ぎゃく)に書(か)いたので、先生(せんせい)に直(なお)された。", "sentence_source": "generated"}, {"text": "靴を左右逆にはいてしまい、歩きにくかった。", "target_word": "逆", "complexity_tier": "T3", "furigana": "靴(くつ)を左右(さゆう)逆(ぎゃく)にはいてしまい、歩(ある)きにくかった。", "sentence_source": "generated"}, {"text": "数字を逆の順番に並べると、百から一になる。", "target_word": "逆", "complexity_tier": "T3", "furigana": "数字(すうじ)を逆(ぎゃく)の順番(じゅんばん)に並(なら)べると、百(ひゃく)から一(いち)になる。", "sentence_source": "generated"}, {"text": "乗った電車が逆で、会社から遠くなってしまった。", "target_word": "逆", "complexity_tier": "T3", "furigana": "乗(の)った電車(でんしゃ)が逆(ぎゃく)で、会社(かいしゃ)から遠(とお)くなってしまった。", "sentence_source": "generated"}, {"text": "順番が逆だと、この計算は答えが変わってしまう。", "target_word": "逆", "complexity_tier": "T3", "furigana": "順番(じゅんばん)が逆(ぎゃく)だと、この計算(けいさん)は答(こた)えが変(か)わってしまう。", "sentence_source": "generated"}, {"text": "上下が逆のまま写真を飾ってしまった。", "target_word": "逆", "complexity_tier": "T3", "furigana": "上下(じょうげ)が逆(ぎゃく)のまま写真(しゃしん)を飾(かざ)ってしまった。", "sentence_source": "generated"}, {"text": "このシャツは前と後ろが逆になっている。", "target_word": "逆", "complexity_tier": "T3", "furigana": "このシャツは前(まえ)と後(うし)ろが逆(ぎゃく)になっている。", "sentence_source": "generated"}, {"text": "鏡に映すと、文字の左右が逆になる。", "target_word": "逆", "complexity_tier": "T3", "furigana": "鏡(かがみ)に映(うつ)すと、文字(もじ)の左右(さゆう)が逆(ぎゃく)になる。", "sentence_source": "generated"}, {"text": "勝ち負けが逆になって、チームの順位は大きく変わった。", "target_word": "逆", "complexity_tier": "T3", "furigana": "勝(か)ち負(ま)けが逆(ぎゃく)になって、チームの順位(じゅんい)は大(おお)きく変(か)わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "逆", "label": "基本形"}, {"form": "逆の", "label": "連体形"}, {"form": "逆に", "label": "連用形"}, {"form": "逆だ", "label": "断定形"}], "register": "neutral", "sense_fingerprint": "順序・向き・位置が本来と反対になっている状態(逆になる・逆だ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35557, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逆", "is_correct": true, "explanation": "「逆になっていた」で、地図の向きや順序が反対だった状態を表すので正解。"}, {"text": "完成", "is_correct": false, "explanation": "「地図が完成になっていた」は意味が成立せず、向きの状態を表せない。"}, {"text": "夕方", "is_correct": false, "explanation": "「地図が夕方になっていた」は意味が成立せず、向きの状態を表せない。"}, {"text": "活気", "is_correct": false, "explanation": "「地図が活気になっていた」は意味が成立せず、向きの状態を表せない。"}], "explanations": {"逆": "「逆になっていた」で、地図の向きや順序が反対だった状態を表すので正解。", "完成": "「地図が完成になっていた」は意味が成立せず、向きの状態を表せない。", "夕方": "「地図が夕方になっていた」は意味が成立せず、向きの状態を表せない。", "活気": "「地図が活気になっていた」は意味が成立せず、向きの状態を表せない。"}, "sentence_index": 0, "correct_answer": "逆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の日は、傘の骨を逆の数だけ折ってしまった。", "explanation": "ここは〈同じ数〉の意味。〈逆〉は向きや順序の反対を表すので、数を同じだけ折るという意味では使えない。"}, {"text": "この歌は、テンポが逆の速さで進む。", "explanation": "ここは〈程度の差〉の意味。〈逆〉は向きや順序の反対を表すので、速さの程度の違いには使わない。"}, {"text": "私は身長が逆に、東の方角へ伸びた。", "explanation": "ここは〈成長〉の意味。〈逆〉は向きや順序の反対を表すので、身長が伸びるという成長の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35557, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逆", "is_correct": true, "explanation": "「上下が逆のまま」で、上下の向きが反対のままという意味に合うので正解。"}, {"text": "静寂", "is_correct": false, "explanation": "「上下が静寂のまま」は意味が成立せず、向きの状態を表せない。"}, {"text": "活気", "is_correct": false, "explanation": "「上下が活気のまま」は意味が成立せず、向きの状態を表せない。"}, {"text": "完璧", "is_correct": false, "explanation": "「上下が完璧のまま」は意味が成立せず、向きが反対であることを表せない。"}], "explanations": {"逆": "「上下が逆のまま」で、上下の向きが反対のままという意味に合うので正解。", "静寂": "「上下が静寂のまま」は意味が成立せず、向きの状態を表せない。", "活気": "「上下が活気のまま」は意味が成立せず、向きの状態を表せない。", "完璧": "「上下が完璧のまま」は意味が成立せず、向きが反対であることを表せない。"}, "sentence_index": 6, "correct_answer": "逆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私の意見は、先生と逆に一致した。", "explanation": "ここは〈同調する〉の意味。〈逆〉は向きや順序が反対になることで、意見が同じになる意味では使わない。"}, {"text": "彼女は身長が逆のまま、大きくなった。", "explanation": "ここは〈増加〉の意味。〈逆〉は向きや順序の反対を表すので、数や大きさが増えるという意味では使わない。"}, {"text": "列車の時間が逆になって、ホームで二時間待った。", "explanation": "ここは〈遅延〉の意味。〈逆〉は向きや順序の反対を表す語で、列車の遅れを言う場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35557, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "靴を逆になっていて、歩きにくかった。", "corrected_sentence": "靴が逆になっていて、歩きにくかった。", "error_description": "助詞の誤り。〈なる〉の主語は「が」で示す。「を」は他動詞の目的語に使うので、自動詞〈なる〉には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35557, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "勝ち負けを逆になって、順位が変わった。", "corrected_sentence": "勝ち負けが逆になって、順位が変わった。", "error_description": "助詞の誤り。〈なる〉の主語は「が」で示す。「を」は他動詞の目的語に使うので、自動詞〈なる〉には合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35560, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "売る", "is_correct": true, "explanation": "「買う」の対義語。代金を受け取って品物を手放す意味で、買うと対になる。"}, {"text": "作る", "is_correct": false, "explanation": "品物を生み出す動詞で、「買う」の対義語ではない。"}, {"text": "食べる", "is_correct": false, "explanation": "品物を口にする動詞で、「買う」と対になる関係にはない。"}, {"text": "借りる", "is_correct": false, "explanation": "一時的に使う意味で、「買う」の対義語ではない（借りるの対義語は貸す）。"}], "correct_answer": "売る", "explanations": {"売る": "「買う」の対義語。代金を受け取って品物を手放す意味で、買うと対になる。", "作る": "品物を生み出す動詞で、「買う」の対義語ではない。", "食べる": "品物を口にする動詞で、「買う」と対になる関係にはない。", "借りる": "一時的に使う意味で、「買う」の対義語ではない（借りるの対義語は貸す）。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35560, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "売る", "is_correct": true, "explanation": "「買う」の対義語。代金を受け取って品物を手放す意味で、買うと対になる。"}, {"text": "払う", "is_correct": false, "explanation": "代金を支払う意味で、買うと同じ側の動作であり、対義語ではない。"}, {"text": "壊す", "is_correct": false, "explanation": "品物を壊す意味で、「買う」とは対になる関係ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "品物を移動させる意味で、「買う」の対義語ではない。"}], "correct_answer": "売る", "explanations": {"売る": "「買う」の対義語。代金を受け取って品物を手放す意味で、買うと対になる。", "払う": "代金を支払う意味で、買うと同じ側の動作であり、対義語ではない。", "壊す": "品物を壊す意味で、「買う」とは対になる関係ではない。", "運ぶ": "品物を移動させる意味で、「買う」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35560, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "お金を出して、自分のものにする。", "primary_collocate": null, "pronunciation": "かう", "ipa": "kaɯ", "syllable_count": 2, "sentences": [{"text": "スーパーで牛乳とパンを買った。", "target_word": "買った", "complexity_tier": "T3", "furigana": "スーパーで牛乳(ぎゅうにゅう)とパンを買(か)った。", "sentence_source": "generated"}, {"text": "新しいくつを買うために、駅前の店へ行った。", "target_word": "買う", "complexity_tier": "T3", "furigana": "新(あたら)しいくつを買(か)うために、駅前(えきまえ)の店(みせ)へ行(い)った。", "sentence_source": "generated"}, {"text": "母は毎週土曜日に、市場で魚を買っている。", "target_word": "買って", "complexity_tier": "T3", "furigana": "母(はは)は毎週(まいしゅう)土曜日(どようび)に、市場(いちば)で魚(さかな)を買(か)っている。", "sentence_source": "generated"}, {"text": "お金がないので、その本は買わないことにした。", "target_word": "買わない", "complexity_tier": "T3", "furigana": "お金(かね)がないので、その本(ほん)は買(か)わないことにした。", "sentence_source": "generated"}, {"text": "安ければ、私はこのかばんを買いたい。", "target_word": "買いたい", "complexity_tier": "T3", "furigana": "安(やす)ければ、私(わたし)はこのかばんを買(か)いたい。", "sentence_source": "generated"}, {"text": "妹の誕生日に、花を買って持っていった。", "target_word": "買って", "complexity_tier": "T3", "furigana": "妹(いもうと)の誕生日(たんじょうび)に、花(はな)を買(か)って持(も)っていった。", "sentence_source": "generated"}, {"text": "買う前に、値段をよく見たほうがいい。", "target_word": "買う", "complexity_tier": "T3", "furigana": "買(か)う前(まえ)に、値段(ねだん)をよく見(み)たほうがいい。", "sentence_source": "generated"}, {"text": "一つ百円のお菓子を十個買えば、千円になる。", "target_word": "買えば", "complexity_tier": "T3", "furigana": "一(ひと)つ百円(ひゃくえん)のお菓子(かし)を十個(じゅっこ)買(か)えば、千円(せんえん)になる。", "sentence_source": "generated"}, {"text": "父は新しい自転車を買ってくれた。", "target_word": "買って", "complexity_tier": "T3", "furigana": "父(ちち)は新(あたら)しい自転車(じてんしゃ)を買(か)ってくれた。", "sentence_source": "generated"}, {"text": "昨日、デパートで帽子を買ったが、少し大きかった。", "target_word": "買った", "complexity_tier": "T3", "furigana": "昨日(きのう)、デパートで帽子(ぼうし)を買(か)ったが、少(すこ)し大(おお)きかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "買う", "label": "終止形・連体形"}, {"form": "買い", "label": "連用形"}, {"form": "買って", "label": "て形"}, {"form": "買った", "label": "た形"}, {"form": "買わない", "label": "ない形"}, {"form": "買えば", "label": "仮定形"}, {"form": "買おう", "label": "意志形"}, {"form": "買いたい", "label": "たい形"}], "register": "neutral", "sense_fingerprint": "日常の買い物で、お金を払って品物を自分のものにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35560, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "買った", "is_correct": true, "explanation": "「スーパーで牛乳とパンを」に続く、過去の購入を表す動詞の形で、文に合う。"}, {"text": "読んだ", "is_correct": false, "explanation": "牛乳やパンは読めないので、「読んだ」では文の意味が通らない。"}, {"text": "弾いた", "is_correct": false, "explanation": "弾くのは楽器などで、食品には使えないので文に合わない。"}, {"text": "書いた", "is_correct": false, "explanation": "食品は書けないので、この文脈では「書いた」は成り立たない。"}], "explanations": {"買った": "「スーパーで牛乳とパンを」に続く、過去の購入を表す動詞の形で、文に合う。", "読んだ": "牛乳やパンは読めないので、「読んだ」では文の意味が通らない。", "弾いた": "弾くのは楽器などで、食品には使えないので文に合わない。", "書いた": "食品は書けないので、この文脈では「書いた」は成り立たない。"}, "sentence_index": 0, "correct_answer": "買った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "危険な仕事を、誰も嫌がらずに買った。", "explanation": "ここは〈引き受ける〉の意味。〈買う〉は代金を払って手に入れる意味なので、仕事を引き受ける場面には合わない。"}, {"text": "レジで代金を買った。", "explanation": "ここは〈払う〉の意味。〈買う〉は品物を手に入れることで、代金そのものは買う対象にならないので合わない。"}, {"text": "友達からお金を買った。", "explanation": "ここは〈借りる〉の意味。〈買う〉は品物を代金で手に入れることで、お金を借りる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35560, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "買う", "is_correct": true, "explanation": "「買う前に」は辞書形で、動作の前後関係を示す「前に」と合う。"}, {"text": "買って", "is_correct": false, "explanation": "て形は「前に」に続かず、文が途中で切れてしまう。"}, {"text": "買えば", "is_correct": false, "explanation": "仮定形は「前に」の前に置けず、文が成り立たない。"}, {"text": "買い", "is_correct": false, "explanation": "連用形だけでは「前に」に続かず、名詞句としても成り立たない。"}], "explanations": {"買う": "「買う前に」は辞書形で、動作の前後関係を示す「前に」と合う。", "買って": "て形は「前に」に続かず、文が途中で切れてしまう。", "買えば": "仮定形は「前に」の前に置けず、文が成り立たない。", "買い": "連用形だけでは「前に」に続かず、名詞句としても成り立たない。"}, "sentence_index": 6, "correct_answer": "買う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "努力して、良い成績を買った。", "explanation": "ここは〈得る〉の意味。成績は代金を払って手に入れるものではないので、〈買う〉は合わない。"}, {"text": "社員に特別ボーナスを買った。", "explanation": "ここは〈支給する〉の意味。ボーナスは代金を払って手に入れるものではないので、〈買う〉は合わない。"}, {"text": "大勢の笑顔を買った。", "explanation": "ここは〈もらう〉の意味。笑顔は代金を払って手に入れるものではないので、〈買う〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35560, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日、新しいくつを買えために、駅前の店へ行く。", "corrected_sentence": "明日、新しいくつを買うために、駅前の店へ行く。", "error_description": "誤りは「買えために」の部分。「ために」の前には辞書形の「買う」を置く。「買え」は命令形で、「ために」の前には入らないので誤り。正しくは「買うために」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "買う", "is_correct": true, "explanation": "「ために」の前は辞書形（終止形・連体形）。目的を表す文に合う。"}, {"text": "買い", "is_correct": false, "explanation": "連用形は「ために」の前に直接置けず、この文の形ではない。"}, {"text": "買って", "is_correct": false, "explanation": "て形は文を続ける形で、「ために」の前には使えない。"}, {"text": "買った", "is_correct": false, "explanation": "た形は過去の動作を表すので、目的を表す「ために」の前には入らない。"}], "correct_form": "買う", "base_form": "買う", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"買う": "「ために」の前は辞書形（終止形・連体形）。目的を表す文に合う。", "買い": "連用形は「ために」の前に直接置けず、この文の形ではない。", "買って": "て形は文を続ける形で、「ために」の前には使えない。", "買った": "た形は過去の動作を表すので、目的を表す「ために」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35560, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一つ百円のお菓子を五個買うば、五百円になる。", "corrected_sentence": "一つ百円のお菓子を五個買えば、五百円になる。", "error_description": "誤りは「買うば」の部分。条件の仮定形は「買えば」で、「買うば」という形は成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "買えば", "is_correct": true, "explanation": "仮定形で「～ば」に続き、条件を表す文に合う。"}, {"text": "買わない", "is_correct": false, "explanation": "ない形は否定になり、「十個買わない、千円になる」では条件の文として成り立たない。"}, {"text": "買おう", "is_correct": false, "explanation": "意志形は「買おう、千円になる」と意志を述べる形になり、条件を表す文には合わない。"}, {"text": "買いたい", "is_correct": false, "explanation": "願望の形は「十個買いたい、千円になる」と希望の文になり、条件の文には合わない。"}], "correct_form": "買えば", "base_form": "買う", "form_label": "仮定形", "sentence_index": 7, "explanations": {"買えば": "仮定形で「～ば」に続き、条件を表す文に合う。", "買わない": "ない形は否定になり、「十個買わない、千円になる」では条件の文として成り立たない。", "買おう": "意志形は「買おう、千円になる」と意志を述べる形になり、条件を表す文には合わない。", "買いたい": "願望の形は「十個買いたい、千円になる」と希望の文になり、条件の文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35561, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "売る", "is_correct": true, "explanation": "「買う」の対義語。代金を受け取って品物を手放す意味で、買うと対になる。"}, {"text": "貸す", "is_correct": false, "explanation": "「借りる」の対義語で、「買う」とは対にならない。"}, {"text": "書く", "is_correct": false, "explanation": "文字を記す動作で、「買う」の対義語ではない。"}, {"text": "開ける", "is_correct": false, "explanation": "閉じたものを開く意味で、「買う」の対義語ではない。"}], "correct_answer": "売る", "explanations": {"売る": "「買う」の対義語。代金を受け取って品物を手放す意味で、買うと対になる。", "貸す": "「借りる」の対義語で、「買う」とは対にならない。", "書く": "文字を記す動作で、「買う」の対義語ではない。", "開ける": "閉じたものを開く意味で、「買う」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35561, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「買いたいと強く望んでいる」の「と」で、望みの内容を引用する。"}, {"text": "が", "is_correct": false, "explanation": "「買いたいが強く望んでいる」では主語にも逆接にもならず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「買いたいに強く望んでいる」は不自然で、方向や相手を示す「に」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「買いたいで強く望んでいる」は手段や場所を示す「で」で、文に合わない。"}], "correct_answer": "と", "explanations": {"と": "「買いたいと強く望んでいる」の「と」で、望みの内容を引用する。", "が": "「買いたいが強く望んでいる」では主語にも逆接にもならず、文が成り立たない。", "に": "「買いたいに強く望んでいる」は不自然で、方向や相手を示す「に」は合わない。", "で": "「買いたいで強く望んでいる」は手段や場所を示す「で」で、文に合わない。"}, "error_tags": {"が": "主語", "に": "方向", "で": "手段"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "売る", "is_correct": true, "explanation": "「買う」の対義語。代金を受け取って品物を手放す意味で、買うと対になる。"}, {"text": "預ける", "is_correct": false, "explanation": "一時的に保管を任せる意味で、「買う」とは対義の関係にない。"}, {"text": "直す", "is_correct": false, "explanation": "壊れたものを元に戻す意味で、「買う」の対義語ではない。"}, {"text": "渡す", "is_correct": false, "explanation": "相手に手渡す意味で、「買う」の対義語ではない。"}], "correct_answer": "売る", "explanations": {"売る": "「買う」の対義語。代金を受け取って品物を手放す意味で、買うと対になる。", "預ける": "一時的に保管を任せる意味で、「買う」とは対義の関係にない。", "直す": "壊れたものを元に戻す意味で、「買う」の対義語ではない。", "渡す": "相手に手渡す意味で、「買う」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35561, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "代金を支払って、品物や権利などを自分のものにする。", "primary_collocate": null, "pronunciation": "かう", "ipa": "kaɯ", "syllable_count": 2, "sentences": [{"text": "来月のコンサートのチケットをインターネットで買った。", "target_word": "買った", "complexity_tier": "T3", "furigana": "来月(らいげつ)のコンサートのチケットをインターネットで買(か)った。", "sentence_source": "generated"}, {"text": "兄は貯金で小さな土地を買うつもりだ。", "target_word": "買う", "complexity_tier": "T3", "furigana": "兄(あに)は貯金(ちょきん)で小(ちい)さな土地(とち)を買(か)うつもりだ。", "sentence_source": "generated"}, {"text": "駅の窓口で、新幹線の切符を買ってください。", "target_word": "買って", "complexity_tier": "T3", "furigana": "駅(えき)の窓口(まどぐち)で、新幹線(しんかんせん)の切符(きっぷ)を買(か)ってください。", "sentence_source": "generated"}, {"text": "彼は会社の株を買い、数年後に高く売った。", "target_word": "買い", "complexity_tier": "T3", "furigana": "彼(かれ)は会社(かいしゃ)の株(かぶ)を買(か)い、数年後(すうねんご)に高(たか)く売(う)った。", "sentence_source": "generated"}, {"text": "母は電車の定期券を買うために、窓口に並んだ。", "target_word": "買う", "complexity_tier": "T3", "furigana": "母(はは)は電車(でんしゃ)の定期券(ていきけん)を買(か)うために、窓口(まどぐち)に並(なら)んだ。", "sentence_source": "generated"}, {"text": "その美術館は人気で、入館券を買わないと中に入れない。", "target_word": "買わない", "complexity_tier": "T3", "furigana": "その美術館[びじゅつかん]は人気[にんき]で、入館券[にゅうかんけん]を買[か]わないと中[なか]に入[い]れない。", "sentence_source": "generated"}, {"text": "家を買えば、毎月の家賃は払わなくてよくなる。", "target_word": "買えば", "complexity_tier": "T3", "furigana": "家(いえ)を買(か)えば、毎月(まいつき)の家賃(やちん)は払(はら)わなくてよくなる。", "sentence_source": "generated"}, {"text": "彼女は貯金して、中古の車を買いたいと言っている。", "target_word": "買いたい", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は貯金(ちょきん)して、中古(ちゅうこ)の車(くるま)を買(か)いたいと言(い)っている。", "sentence_source": "generated"}, {"text": "入場券を買って中に入ると、広い庭があった。", "target_word": "買って", "complexity_tier": "T3", "furigana": "入場券(にゅうじょうけん)を買(か)って中(なか)に入(はい)ると、広(ひろ)い庭(にわ)があった。", "sentence_source": "generated"}, {"text": "会社は、あの小説の映画化の権利を二億円で買った。", "target_word": "買った", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、あの小説[しょうせつ]の映画化[えいがか]の権利[けんり]を二億円[におくえん]で買[か]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "買う", "label": "終止形・連体形"}, {"form": "買い", "label": "連用形"}, {"form": "買って", "label": "て形"}, {"form": "買った", "label": "た形"}, {"form": "買わない", "label": "ない形"}, {"form": "買えば", "label": "仮定形"}, {"form": "買いたい", "label": "たい形"}], "register": "neutral", "sense_fingerprint": "代金を払って、チケット・土地・株・権利など形のあるなしを問わず自分の所有にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35561, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "買った", "is_correct": true, "explanation": "「インターネットで」を受けて、購入した過去を表す形で文に合う。"}, {"text": "読んだ", "is_correct": false, "explanation": "チケットは読むものではないので、文の意味が通らない。"}, {"text": "歌った", "is_correct": false, "explanation": "チケットは歌えないので、この文脈では成り立たない。"}, {"text": "描いた", "is_correct": false, "explanation": "チケットは描くものではなく、文に合わない。"}], "explanations": {"買った": "「インターネットで」を受けて、購入した過去を表す形で文に合う。", "読んだ": "チケットは読むものではないので、文の意味が通らない。", "歌った": "チケットは歌えないので、この文脈では成り立たない。", "描いた": "チケットは描くものではなく、文に合わない。"}, "sentence_index": 0, "correct_answer": "買った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼を信頼して、大きな仕事を買った。", "explanation": "ここは〈任せる〉の意味。仕事は代金を払って手に入れるものではないので、〈買う〉は合わない。"}, {"text": "彼は大会で賞金を買った。", "explanation": "ここは〈受け取る〉の意味。賞金は代金を払って手に入れるものではないので、〈買う〉は合わない。"}, {"text": "被災地に寄付を買った。", "explanation": "ここは〈贈る〉の意味。寄付は代金を払って手に入れるものではないので、〈買う〉の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35561, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "買えば", "is_correct": true, "explanation": "仮定形で、「家を買えば、家賃は払わなくてよくなる」という条件の文に合う。"}, {"text": "買おう", "is_correct": false, "explanation": "意志形は「買おう、～」と意志を言い切る形で、条件の文には合わない。"}, {"text": "買わない", "is_correct": false, "explanation": "否定形で続けると条件の意味が通らず、「家賃は払わなくてよい」と結びつかない。"}, {"text": "買いたい", "is_correct": false, "explanation": "願望の形は「家を買いたい、～」では条件にならず、文の意味が成り立たない。"}], "explanations": {"買えば": "仮定形で、「家を買えば、家賃は払わなくてよくなる」という条件の文に合う。", "買おう": "意志形は「買おう、～」と意志を言い切る形で、条件の文には合わない。", "買わない": "否定形で続けると条件の意味が通らず、「家賃は払わなくてよい」と結びつかない。", "買いたい": "願望の形は「家を買いたい、～」では条件にならず、文の意味が成り立たない。"}, "sentence_index": 6, "correct_answer": "買えば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先輩から厳しい注意を買った。", "explanation": "ここは〈受ける〉の意味。注意は代金を払って手に入れるものではないので、〈買う〉は合わない。"}, {"text": "毎月の家賃を買っている。", "explanation": "ここは〈支払う〉の意味。家賃は買うものではなく、〈買う〉は品物を手に入れる意味なので合わない。"}, {"text": "新入社員に新しい権限を買った。", "explanation": "ここは〈与える〉の意味。権限は代金で取引するものではないので、〈買う〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35561, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日までに、チケットを買いてください。", "corrected_sentence": "明日までに、チケットを買ってください。", "error_description": "誤りは「買いて」。「買う」のて形は「買って」で、「買いて」は形が誤っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "買う", "is_correct": true, "explanation": "「つもり」の前は辞書形。意図を表す文に合う。"}, {"text": "買い", "is_correct": false, "explanation": "連用形は「つもり」の前に直接置けず、この文の形ではない。"}, {"text": "買って", "is_correct": false, "explanation": "て形は文を続ける形で、「つもり」に続かない。"}, {"text": "買えば", "is_correct": false, "explanation": "仮定形は「つもり」の前には置けず、文が成り立たない。"}], "correct_form": "買う", "base_form": "買う", "form_label": "終止形・連体形", "sentence_index": 1, "explanations": {"買う": "「つもり」の前は辞書形。意図を表す文に合う。", "買い": "連用形は「つもり」の前に直接置けず、この文の形ではない。", "買って": "て形は文を続ける形で、「つもり」に続かない。", "買えば": "仮定形は「つもり」の前には置けず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35561, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は貯金して、新しい自転車を買いたいが言っている。", "corrected_sentence": "彼は貯金して、新しい自転車を買いたいと言っている。", "error_description": "誤りは「買いたいが」の「が」。引用を表す「と言っている」の「と」が正しい。「が」は主語や逆接を表すので、ここでは文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "買った", "is_correct": false, "explanation": "た形は既に買った事実を表し、「買ったと強く望んでいる」は望みの文として不自然。"}, {"text": "買えば", "is_correct": false, "explanation": "仮定形は条件を表す形で、「買えばと強く望んでいる」は文として成り立たない。"}, {"text": "買おう", "is_correct": false, "explanation": "意志形は決意を言う形で、「買おうと強く望んでいる」は望みの文として不自然。"}, {"text": "買いたい", "is_correct": true, "explanation": "「～たい」の希望の形で、「買いたいと強く望んでいる」の文に合う。"}], "correct_form": "買いたい", "base_form": "買う", "form_label": "たい形", "sentence_index": 7, "explanations": {"買った": "た形は既に買った事実を表し、「買ったと強く望んでいる」は望みの文として不自然。", "買えば": "仮定形は条件を表す形で、「買えばと強く望んでいる」は文として成り立たない。", "買おう": "意志形は決意を言う形で、「買おうと強く望んでいる」は望みの文として不自然。", "買いたい": "「～たい」の希望の形で、「買いたいと強く望んでいる」の文に合う。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
