INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35562, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が集まって、ものを売ったり買ったりする仕事をするところです。", "primary_collocate": null, "pronunciation": "かいしゃ", "ipa": "kaiɕa", "syllable_count": 3, "sentences": [{"text": "父は駅の近くの会社で働いています。", "target_word": "会社", "complexity_tier": "T3", "furigana": "父[ちち]は駅[えき]の近[ちか]くの会社[かいしゃ]で働[はたら]いています。", "sentence_source": "generated"}, {"text": "この会社には、毎朝たくさんの人が集まります。", "target_word": "会社", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]には、毎朝[まいあさ]たくさんの人[ひと]が集[あつ]まります。", "sentence_source": "generated"}, {"text": "会社が休みなので、今日は家で本を読みます。", "target_word": "会社", "complexity_tier": "T3", "furigana": "会社[かいしゃ]が休[やす]みなので、今日[きょう]は家[いえ]で本[ほん]を読[よ]みます。", "sentence_source": "generated"}, {"text": "私は会社まで電車で三十分かかります。", "target_word": "会社", "complexity_tier": "T3", "furigana": "私[わたし]は会社[かいしゃ]まで電車[でんしゃ]で三十分[さんじゅっぷん]かかります。", "sentence_source": "generated"}, {"text": "兄は大きい会社に入るために、毎日勉強しています。", "target_word": "会社", "complexity_tier": "T3", "furigana": "兄[あに]は大[おお]きい会社[かいしゃ]に入[はい]るために、毎日[まいにち]勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "会社の人と昼ご飯を食べに行きました。", "target_word": "会社", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の人[ひと]と昼[ひる]ご飯[はん]を食[た]べに行[い]きました。", "sentence_source": "generated"}, {"text": "雨がひどかったので、会社に遅れてしまいました。", "target_word": "会社", "complexity_tier": "T3", "furigana": "雨[あめ]がひどかったので、会社[かいしゃ]に遅[おく]れてしまいました。", "sentence_source": "generated"}, {"text": "母の会社は、安い服を作って売っています。", "target_word": "会社", "complexity_tier": "T3", "furigana": "母[はは]の会社[かいしゃ]は、安[やす]い服[ふく]を作[つく]って売[う]っています。", "sentence_source": "generated"}, {"text": "会社を早く出たから、友達と映画を見られました。", "target_word": "会社", "complexity_tier": "T3", "furigana": "会社[かいしゃ]を早[はや]く出[で]たから、友達[ともだち]と映画[えいが]を見[み]られました。", "sentence_source": "generated"}, {"text": "将来は自分の会社を作りたいです。", "target_word": "会社", "complexity_tier": "T3", "furigana": "将来[しょうらい]は自分[じぶん]の会社[かいしゃ]を作[つく]りたいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "会社", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "人が集まって働く職場としての会社", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35562, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会社", "is_correct": true, "explanation": "人が集まって働く場所を表し、「で働いています」の場所として合う。"}, {"text": "電車", "is_correct": false, "explanation": "電車は乗るものなので、「で働いています」の場所にはならない。"}, {"text": "花", "is_correct": false, "explanation": "花は働く場所にはならず、文が成り立たない。"}, {"text": "本", "is_correct": false, "explanation": "本は読むものなので、働く場所としては不自然。"}], "explanations": {"会社": "人が集まって働く場所を表し、「で働いています」の場所として合う。", "電車": "電車は乗るものなので、「で働いています」の場所にはならない。", "花": "花は働く場所にはならず、文が成り立たない。", "本": "本は読むものなので、働く場所としては不自然。"}, "sentence_index": 0, "correct_answer": "会社"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父の会社は、毎年夏に大きな花を咲かせる。", "explanation": "ここは〈植物〉の意味。会社は花を咲かせないので、〈会社〉は合わない。"}, {"text": "会社が朝から晴れている。", "explanation": "ここは〈天気〉の意味。会社は空模様ではないので、〈会社〉は合わない。"}, {"text": "会社を焼いて、おいしく食べた。", "explanation": "ここは〈食べ物〉の意味。会社は食べられるものではないので、〈会社〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35562, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会社", "is_correct": true, "explanation": "「遅れてしまいました」の相手として、会社が文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "雨に遅れることは成り立たず、文が通らない。"}, {"text": "傘", "is_correct": false, "explanation": "傘に遅れるという意味にはならず、文が成り立たない。"}, {"text": "紅茶", "is_correct": false, "explanation": "紅茶に遅れることは成り立たず、不自然。"}], "explanations": {"会社": "「遅れてしまいました」の相手として、会社が文に合う。", "雨": "雨に遅れることは成り立たず、文が通らない。", "傘": "傘に遅れるという意味にはならず、文が成り立たない。", "紅茶": "紅茶に遅れることは成り立たず、不自然。"}, "sentence_index": 6, "correct_answer": "会社"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社は、私の隣で大きないびきをかいた。", "explanation": "ここは〈人〉の意味。会社はいびきをかく人ではないので、〈会社〉は合わない。"}, {"text": "会社に乗って、駅まで行った。", "explanation": "ここは〈乗り物〉の意味。会社は乗って移動するものではないので、〈会社〉は合わない。"}, {"text": "会社が、庭で元気に鳴いている。", "explanation": "ここは〈動物〉の意味。会社は鳴く生き物ではないので、〈会社〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35562, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は駅の近くの会社を働いています。", "corrected_sentence": "母は駅の近くの会社で働いています。", "error_description": "誤りは「会社を」。働く場所は「で」で示すので、「を」は誤り。正しくは「会社で働いています」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35562, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車が止まったので、会社を遅れてしまいました。", "corrected_sentence": "電車が止まったので、会社に遅れてしまいました。", "error_description": "誤りは「会社を」。「遅れる」は遅れる先を「に」で示すので、「を」は誤り。正しくは「会社に遅れて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
